For convenience throughout this appendix,
we will let $F: \Rz \tms \uVals \tms \dVals \to \Rz$ and $H: \Rz \tms \Rz \to \R$ be given by
\begin{align*}
    &F(\zVal,\uVal,\dVal) = f(\zVal,\uVal,\dVal) - M(\zVal) g(\zVal,\uVal,\dVal),\\
    &H(\zVal, \lm) = \min_{\uVal \in \uVals} \max_{\dVal \in \dVals} \lm^\top F(\zVal, \uVal, \dVal) = \max_{\dVal \in \dVals} \min_{\uVal \in \uVals}  \lm^\top F(\zVal, \uVal, \dVal).
\end{align*}

Given $t_0,\dots,t_n \in \R$ such that $t_0 < \dots < t_n$, and given functions $\aSig_1:[t_0,t_1) \to \R^m, \dots, \aSig_n: [t_{n-1},t_n) \to \R^m$, we define the function $[\aSig_1,\dots,\aSig_n):[t_0,t_n) \to \R^m$ such that
$[\aSig_1,\dots,\aSig_n)(s) =  \aSig_j(s)$ whenever $s \in [t_{j-1},t_j)$.
For each $[t,s) \ssbs \R$, we also let $\uSigsts$ $(\dSigsts)$ be the set of measurable functions from $[\tVal,s)$ to $\uVals$ $([\tVal,s)$ to $\dVals)$.

\subsection{Boundary Layer Model}
For each $\zVal \in \Rz$, we consider the following ``boundary-layer'' model:
\begin{equation}\label{eqn:blm}
    \dot{\ySig} = f(\zVal, \uSig, \dSig) + A(\zVal, \uSig, \dSig) \ySig.
\end{equation}

For each $\tVal < 0$, $\yVal \in \Ry$, $\zVal \in \Rz$, $\uSig \in \uSigs$, and $\dSig \in \dSigs$, we let $\trajBLM:[\tVal,0] \to \Ry$ be the unique Carath\'{e}odory solution of \eqref{eqn:blm} satisfying $\trajBLM(\tVal) = \yVal$.

For each $\tVal < 0$, $\yVal \in \Ry$, $\zVal \in \Rz$, and $\lm \in \Rz$, we define the payoff functional $\payoffBLM: \uSigs \tms \dSigs \to \R$ by
\begin{align*}
    \payoffBLM(\uSig,\dSig) = \frac{1}{|t|} \int_t^0 \lm^\top [ &f(\zVal, \uSig(\ta), \dSig(\ta)) +\\
    &M(\zVal)A(\zVal, \uSig(\ta), \dSig(\ta)) \trajBLM(\ta)] \dee \ta.
\end{align*}

Moreover, for each $\tVal < 0$, $\yVal \in \Ry$, $\zVal \in \Rz$, and $\lm \in \Rz$, and for each partition $P$ of the interval $[t,0)$ into the subintervals $[t_0,t_1),\dots,[t_{r-1},t_r)$ (where $t_0 = \tVal$ and $t_{r} = 0$), we define the following upper and lower value functions for the boundary-layer model:
\begin{align}
    \valBLMdiscretePlus(\tVal, \yVal) = \inf_{\uSig_1 \in \uSigsi{1}}  &\sup_{\dSig_1 \in \dSigsi{1}} \dots \inf_{\uSig_r \in \uSigsi{r}} \sup_{\dSig_r \in \dSigsi{r}} \nonumber\\
    &\payoffBLM([\uSig_1,\dots,\uSig_r), [\dSig_1,\dots,\dSig_r)), \label{eqn:af-game-value-plus}\\
    \valBLMdiscreteMinus(\tVal, \yVal) =   \sup_{\dSig_1 \in \dSigsi{1}} &\inf_{\uSig_1 \in \uSigsi{1}} \dots \sup_{\dSig_r \in \dSigsi{r}} \inf_{\uSig_r \in \uSigsi{r}} \nonumber\\
    &\payoffBLM([\uSig_1,\dots,\uSig_r), [\dSig_1,\dots,\dSig_r)), \label{eqn:af-game-value-minus}
    \end{align}
    where $\uSigsi{j} = \uSigsii{j-1}{j}$ and $\dSigsi{j} = \dSigsii{j-1}{j}$ for each $j$.

\subsection{Intermediate Lemmas}

\begin{lemma} \label{lemma:exponential-bounding}
    Let $\zVal \in \Rz$.
    There are constants $\al,\kp > 0$ such that for each $\tVal < 0$ and each $\uSig \in \uSigs$ and each $\dSig \in \dSigs$,
    \begin{equation}
        \lf\| e^{\int_\tVal^0 A(z,\uSig(r),\dSig(r)) \dee r} \rg\| \le \al e^{\kp \tVal}.
    \end{equation}
\end{lemma}
\begin{proof}
    Let $\Lm: \uVals \tms \dVals \to \R$ be such that $\Lm(\uVal,\dVal)$ is the largest eigenvalue of $A(\zVal,\uVal,\dVal)^\top P + P A(\zVal,\uVal,\dVal)$, where $P$ is as in Assumption \ref{assumption:stability}.
    Then $\Lm$ is continuous, so by Assumption \ref{assumption:stability}, there is some $\nu > 0$ such that $\Lm(\uVal,\dVal) \le -\nu$ for each $\uVal \in \uVals$ and $\dVal \in \dVals$.

    Fix some $\tVal < 0$, $\uSig \in \uSigs$, and $\dSig \in \dSigs$.
    Let $\wSig:[\tVal,0] \to \Ry$ be the Carath\'{e}odory solution to 
    $$\dot{\wSig} = A(\zVal,\uSig, \dSig) \wSig, \quad \wSig(t) = \wVal.$$
    A standard argument (see e.g. the proof of Theorem 4.10 in \cite{Khalil}) using the Lyapunov function $V(\wVal) = \wVal^\top P \wVal$ shows
    \begin{equation*}
        \frac{\dee}{\dee \ta} [V(\wSig(\ta))] = - 2 \kp V(\wSig(\ta)) - \mu(\ta)
    \end{equation*}
    for a.e. $\ta \in (t,0)$, where $\kp := \frac{\nu}{2\lm_{\max}(P)}$ and $\mu(\cdot) \ge 0$.

    Since $\wSig$ is absolutely continuous with a compact domain, and since $V$ is locally Lipschitz, then $V \circ \wSig$ is absolutely continuous, so that
    $$V(\wSig(0)) = V(\wVal) e^{2 \kp \tVal} - \int_\tVal^0 \mu(s) e^{2 \kp s} \dee s \le V(\wVal) e^{2 \kp \tVal},$$
    and thus $\|\wSig(\tVal)\| \le \|\wVal\| \al e^{\kp \tVal}$,
    where $\al = \sqrt{\frac{\lm_{\max}(P)}{\lm_{\min}(P)}}$ (again see the proof of Theorem 4.10 in \cite{Khalil} for details).
    But since $\wVal \in \Ry$ was arbitrary and
    $\wSig(\tVal) = e^{\int_\tVal^0 A(\zVal,\uSig(r),\dSig(r))} \wVal$,
    the result follows.

\end{proof}

\begin{lemma} \label{lemma:bounding-payoff-error}
    Let $\yVal \in \Ry$, $\zVal \in \Rz$, and $\lm \in \Rz$.
    There is some $\bt > 0$ such that for all $\tVal < 0$ and for each $\uSig \in \uSigs$ and $\dSig \in \dSigs$,
    \begin{align*}
        \lf|\payoffBLM(\uSig,\dSig) - \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(\zVal,\uSig(\ta),\dSig(\ta)) \dee \ta\rg| \le \frac{\bt}{|\tVal|}.
    \end{align*}
\end{lemma}
\begin{proof}
    Fix some $\tVal < 0$ and some $\uSig \in \uSigs$ and $\dSig \in \dSigs$.
    Then $\payoffBLM(\uSig,\dSig) = I_1 + I_2 + I_3$, where
    \begin{alignat}{2}
        I_1 &= \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top &&f(\zVal,\uSig(\ta),\dSig(\ta)) \dee \ta,\\
        I_2 &= \frac{1}{|\tVal|} \int_\tVal^0 \int_\tVal^\ta &&\lm^\top M(\zVal)A(\zVal,\uSig(\ta), \dSig(\ta)) e^{\int_\ta^0 A(\zVal,\uSig(r),\dSig(r)) \dee r}\nonumber \label{proof:lemma-bounding-payoff-I2}\\
        & &&g(\zVal,\uSig(s),\dSig(s)) \dee s \dee \ta,\\
        I_3 &= \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top  && e^{\int_\ta^0 A(\zVal,\uSig(r),\dSig(r)) \dee r} \yVal \dee \ta.
    \end{alignat}
    Choose $\al > 0$ and $\kp > 0$ as in Lemma \ref{lemma:exponential-bounding}.
    Then
    \begin{equation*}
        |I_3| \le \frac{\al \|\lm\|\|\yVal\|}{|\tVal|} \int_\tVal^0 e^{\kp \ta} \dee \ta 
        = \frac{\al \|\lm\|\|\yVal\|}{\kp |\tVal|} \lf(1- e^{\kp \tVal} \rg).
    \end{equation*}
    By The Fundamental Theorem of Calculus for Lebesgue Integrals (see Theorem 3.35 in \cite{Folland}), for a.e. $\ta \in (\tVal,0)$,
    $$\frac{\dee}{\dee \tau} \int_\ta^0 A(\zVal,\uSig(r),\dSig(r)) \dee r = -A(\zVal,\uSig(\ta),\dSig(\ta)),$$
    so that
    $$\frac{\dee}{\dee \ta} e^{\int_\ta^0 A(\zVal,\uSig(r),\dSig(r)) \dee r} = -A(\zVal,\uSig(\ta),\dSig(\ta)) e^{\int_\ta^0 A(\zVal,\uSig(r),\dSig(r))}.$$
    Since $\int_\ta^0 A(\zVal,\uSig(r),\dSig(r)) \dee r$ is absolutely continuous as a function of $\ta$ on $[\tVal,0]$, and since the exponential of an absolutely continuous function on a compact interval is absolutely continuous, then $e^{\int_\ta^0 A(\zVal,\uSig(r),\dSig(r))}$ is also absolutely continuous as a function of $\ta$ on the interval $[\tVal,0]$. 
    Again by the The Fundamental Theorem of Calculus for Lebesgue Integrals, for each $s \in [\tVal,0]$
    \begin{align*}
        &e^{\int_s^0 A(\zVal,\uSig(r),\dSig(r)) \dee r} - I =\\
        &\int_s^0 A(\zVal,\uSig(\ta), \dSig(\ta)) e^{\int_\ta^0 A(\zVal,\uSig(r),\dSig(r)) \dee r} \dee \ta,
    \end{align*}
    where $I$ is the identity matrix in $\Ryy$.
    By changing the order of integration in \eqref{proof:lemma-bounding-payoff-I2},
    \begin{alignat*}{2}
        I_2 &= \frac{1}{|\tVal|} \int_\tVal^0 \int_s^0 &&\lm^\top M(\zVal)A(\zVal,\uSig(\ta), \dSig(\ta)) e^{\int_\ta^0 A(\zVal,\uSig(r),\dSig(r)) \dee r}\\
        & && g(\zVal,\uSig(\ta),\dSig(\ta)) \dee \ta \dee s\\
        &= \frac{1}{|\tVal|} \int_t^0 \lm^\top && M(\zVal) \lf[e^{\int_s^0 A(\zVal,\uSig(r),\dSig(r)) \dee r} - I\rg]\\
        & && g(\zVal,\uSig(s),\dSig(s)) \dee s.
    \end{alignat*}
    Note that
    \begin{align*}
        &\lf|\frac{1}{|\tVal|} \int_\tVal^0 \lm^\top M(\zVal) e^{\int_s^0 A(\zVal,\uSig(r),\dSig(r)) \dee r} g(\zVal,\uSig(s),\dSig(s)) \dee s \rg| \le \\
        &\quad\frac{\al \|\lm\| \|M(z)\| B}{|\tVal|} \int_\tVal^0 e^{\kp s} \dee s = \frac{\al \|\lm\| \|M(z)\| B}{\kp |\tVal|} \lf(1 - e^{\kp \tVal} \rg),
    \end{align*}
    where $B := \max_{\uVal \in \uVals}  \max_{\dVal \in \dVals} \|g(\zVal, \uVal, \dVal)\|.$
    The lemma then follows with
    $\bt := \frac{\al \|\lm\|}{\kp} \lf(\|\yVal\| + B\|M(z)\| \rg).$
\end{proof}

\begin{lemma} \label{lemma:payoff-limit}
Given $\lm,z \in \Rz$ and $\tVal < 0$,
\begin{align*}
    &\inf_{\uSig \in \uSigs} \sup_{\dSig \in \dSigs} \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(z,\uSig(\ta),\dSig(\ta)) \dee \ta\\
    &= \sup_{\dSig \in \dSigs} \inf_{\uSig \in \uSigs} \frac{1}{|\tVal|}\int_\tVal^0 \lm^\top F(z,\uSig(\ta),\dSig(\ta)) \dee \ta = H(\zVal,\lm).
\end{align*}
\end{lemma}
\begin{proof}
    Let $\uVal^* \in \argmin_{\uVal \in \uVals}\max_{\dVal \in \dVals} \lm^\top F(\zVal,\uVal,\dVal)$, and let $\dVal^* \in \argmax_{\dVal \in \dVals}\min_{\uVal \in \uVals} \lm^\top F(\zVal,\uVal,\dVal)$.
    Then
    \begin{equation}\label{proof:lemma-payoff-limit-1}
      H(\zVal, \lm) = \max_{\dVal \in \dVals} \lm^\top F(\zVal, \uVal^*, \dVal) = \min_{\uVal \in \uVals}  \lm^\top F(\zVal, \uVal, \dVal^*)  
    \end{equation}
     by Assumption \ref{assumption:saddle-point}. Observe that
    \begin{align*}
        \inf_{\uSig \in \uSigs} &\sup_{\dSig \in \dSigs} \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(\zVal,\uSig(\ta),\dSig(\ta)) \dee \ta \\
        &\le \sup_{\dSig \in \dSigs} \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(\zVal, \uVal^*,\dSig(\ta)) \dee \ta \\
        &= H(\zVal,\lm) = \inf_{\uSig \in \uSigs} \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(\zVal,\uSig(\ta),\dVal^*) \dee \ta \\
        &\le \sup_{\dSig \in \dSigs} \inf_{\uSig \in \uSigs} \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(z,\uSig(\ta),\dSig(\ta)) \dee \ta \\
        &\le \inf_{\uSig \in \uSigs} \sup_{\dSig \in \dSigs} \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(z,\uSig(\ta),\dSig(\ta)) \dee \ta
    \end{align*}
    where both equalities are justified by \eqref{proof:lemma-payoff-limit-1}, and where the final inequality is justified by the standard minimax inequality.
\end{proof}

\begin{lemma} \label{lemma:bounding-value-error}
Let $\yVal \in \Ry$, $\zVal \in \Rz$, and $\lm \in \Rz$.
    There is some $\bt > 0$ such that for all $\tVal < 0$ and for each partition $P$ of the interval $[\tVal,0)$,
    \begin{equation*}
    \lf|\valBLMdiscretePlusMinus(\tVal,\yVal) - H(\zVal,\lm) \rg| \le \bt/|\tVal|.
    \end{equation*}
\end{lemma}
\begin{proof}
    Let $\uSigsi{1},\dots,\uSigsi{r}$ and $\dSigsi{1},\dots,\dSigsi{r}$ be as in the definitions of $\valBLMdiscretePlusMinus$.
    First note that it follows from repeated use of the standard minimax inequality that
    \begin{align*}
    &\sup_{\dSig \in \dSigs} \inf_{\uSig \in \uSigs} \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(\zVal,\uSig(\ta),\dSig(\ta)) \dee \ta \\
    &= \sup_{\dSig_1 \in \dSigsi{1}} \dots \sup_{\dSig_r \in \dSigsi{r}}\inf_{\uSig_1 \in \uSigsi{1}} \dots \inf_{\uSig_r \in \uSigsi{r}}\\
    &\quad\quad \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(\zVal,[\uSig_1,\dots,\uSig_r)(\ta),[\dSig_1,\dots,\dSig_r)(\ta)) \dee \ta\\
    &\le \inf_{\uSig_1 \in \uSigsi{1}} \sup_{\dSig_1 \in \dSigsi{1}} \dots \inf_{\uSig_r \in \uSigsi{r}} \sup_{\dSig_r \in \dSigsi{r}} \\
    &\quad\quad \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(\zVal,[\uSig_1,\dots,\uSig_r)(\ta),[\dSig_1,\dots,\dSig_r)(\ta)) \dee \ta\\
    &\le \sup_{\dSig_1 \in \dSigsi{1}} \dots \sup_{\dSig_r \in \dSigsi{r}} \inf_{\uSig_1 \in \uSigsi{1}} \dots \inf_{\uSig_r \in \uSigsi{r}} \\
    &\quad\quad \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(z,[\uSig_1,\dots,\uSig_r)(\ta),[\dSig_1,\dots,\dSig_r)(\ta)) \dee \ta\\
    &= \inf_{\uSig \in \uSigs} \sup_{\dSig \in \dSigs} \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(\zVal,\uSig(\ta),\dSig(\ta)) \dee \ta.
    \end{align*}
    It then follows from Lemma \ref{lemma:payoff-limit} that
    \begin{align}\label{proof:value-error-1}
        &H(\zVal,\lm) = \\
        &\quad\inf_{\uSig_1 \in \uSigsi{1}} \sup_{\dSig_1 \in \dSigsi{1}} \dots \inf_{\uSig_r \in \uSigsi{r}} \sup_{\dSig_r \in \dSigsi{r}} \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(\zVal,\uSig(\ta),\dSig(\ta)) \dee \ta. \nonumber
    \end{align}
    Then by \eqref{eqn:af-game-value-plus} and \eqref{proof:value-error-1} together with repeated use of the standard inequality for the absolute difference of suprema/infima
    \begin{align*}
        &|\valBLMdiscretePlusMinus(\tVal,\yVal) - H(\zVal,\lm)| \le \\
        &\sup_{\uSig_1 \in \uSigsi{1}} \sup_{\dSig_1 \in \dSigsi{1}} \dots \sup_{\uSig_r \in \uSigsi{r}} \sup_{\dSig_r \in \dSigsi{r}} \Big|\payoffBLM([\uSig_1, \dots \uSig_r),[\dSig_1,\dots,\dSig_r))\\ 
        &\quad- \frac{1}{|\tVal|} \int_\tVal^0 \lm^\top F(\zVal,[\uSig_1, \dots \uSig_r)(\ta),[\dSig_1,\dots,\dSig_r)(\ta)) \dee \ta\Big|
    \end{align*}
    The result follows from Lemma \ref{lemma:bounding-payoff-error} (the result for $\valBLMdiscreteMinus$ follows similarly).
\end{proof}

\subsection{Proof of Lemma \ref{lemma:main-lemma}}

Having shown Lemma \ref{lemma:bounding-value-error}, Lemma \ref{lemma:main-lemma} is now a mostly straightforward consequence of the main result in \cite{gaitsgory}:

\begin{proof}[Proof of Lemma \ref{lemma:main-lemma}]
    Applying the main result (Theorem 4.2) in \cite{gaitsgory} to our setting requires verifying a number of assumptions, which we do now (unfortunately the assumptions are too extensive to reproduce in this text).
    We note that Assumption 1 in \cite{gaitsgory} follows from Lemma \ref{lemma:bounding-value-error} in this text;
    Assumptions (A1)-(A3) in \cite{gaitsgory} follow from Assumption \ref{assumption:regularity} in this text; Assumptions (B1)-(B3) in \cite{gaitsgory} follow from Theorem 6.2, 7.1, and 7.2 in \cite{gaitsgory} together with Assumption \ref{assumption:stability} in this text (as this assumption justifies Assumptions (C1) and (C2) in \cite{gaitsgory}, which are needed in Theorems 6.1, 7.1, and 7.2).
    [Also note that by Lemma \ref{lemma:bounding-value-error}, the quantities $R_\dl^{up}$, $R_\dl^{lo}$, and $R$ in the hypotheses of Theorem 4.2 are all equal to the quantity $-H$ defined in this text.]

    By \cite{Evans-Diff-Games} and \cite{Ishii-uniqueness}, $\valRM$ is the unique continuous viscosity solution (in the sense described in Remark 4.1 of \cite{gaitsgory}) of the Hamilton-Jacobi PDE
    \begin{equation*}
        \begin{cases}
        -\partial_\tVal v(\tVal,\zVal) + H(\zVal, \nabla_\zVal v(\tVal, \zVal)) = 0, & (\tVal,\zVal) \in (-\ii,0) \tms \Rz,\\
        v(0,\zVal) = \ell(\zVal), & \zVal \in \Rz.
        \end{cases}
    \end{equation*}
    Having verified the above assumptions, Theorem 4.2 in \cite{gaitsgory} then implies that $\valSP(t,z,y) \to \valRM(t,z)$ as $\ep \to 0^+$, with the convergence being uniform on compact sets in $(-\ii,0] \tms \Rz \tms \Ry$, which is our desired result.
\end{proof}

\begin{remark}
    We note two nuances in this proof which may catch the attention of the careful reader.
    First, the theory in \cite{gaitsgory} uses the Friedman definition of the value function (see \cite{Friedman}), whereas we use the Elliot-Kalton definitions for $\valSP$ and $\valRM$.
    These definitions are indeed equivalent in our setting, because they are both the unique viscosity solutions to a corresponding Hamilton-Jacobi-Isaacs PDE by \cite{Evans-Diff-Games}, \cite{Barron-Evans-Jensen}, \cite{Ishii-uniqueness}.
    Second, the assumptions made in \cite{Evans-Diff-Games} and \cite{Barron-Evans-Jensen} on boundedness of the system dynamics virtually never hold for systems \eqref{eqn:sp-system-slow}-\eqref{eqn:sp-system-fast} and \eqref{eqn:reduced-system}. Moreover, the definition of a viscosity solution used in these two early works postulates boundedness and uniform continuity of the solution, whereas the definition in \cite{gaitsgory} merely postulates continuity.
    It is known (and in fact even stated in \cite{Evans-Diff-Games}) that such strong assumptions are not required to characterize the value function as the unique viscosity solution of a Hamilton-Jacobi PDE.
    Indeed the ``existence'' proofs from \cite{Evans-Diff-Games} and \cite{Barron-Evans-Jensen} (i.e. that the value functions of a differential game is a [possibly unbounded and continuous but not uniformly so] viscosity solution of the corresponding Hamilton-Jacobi-Isaacs PDE) follow similarly under only Assumption \ref{assumption:regularity} and continuity of the terminal payoff function $\ell$.
    On the other hand, the uniqueness result follows under these weaker assumptions and less restrictive definition of a viscosity solution from Theorem 2.5 in \cite{Ishii-uniqueness}.
    Both these observations are not new (c.f. Sections III.3.2, VIII.1, and the end of VIII in the classic text \cite{Bardi}).
\end{remark}

