\subsection{Link between the Meyer--Zheng and the pointwise convergence metircs}

\begin{lemma}
\label{lemm:appx_mz}
Let $(B^n)_{n=1}^\infty$ be measurable stochastic processes with paths from $\cV$. Let $B^n \to B$ a.s. in $\cD_{d, MZ}$. Then there are a dense countable set $I \subset [0, T]$ with $T \in I$ and a subsequence $n_k$ satisfying $B^{n_k}_t \to B_t$ a.s. for all $t \in I$.
\end{lemma} 
\begin{proof}
By the Fubini theorem,
\begin{equation*}
\int_{[0, T)} \E |B^n_s - B_s| \wedge 1 \, ds + \E |B^n_T - B_T| \wedge 1 \to 0, 
\end{equation*}
hence the integrand converges a.e. and there is  dense countable set $I \subset [0, T]$ with $T \in I$ that enjoys the following property:
\begin{equation*}
\E |B^n_t - B_t| \wedge 1 \to 0, \quad \forall t \in I.
\end{equation*}
By the Riesz theorem and the diagonalization argument, there exists a subsequence $n_k$ such that $B^{n_k}_t \to B_t$ a.s. for all $t \in I$. 

\end{proof}

