\centering
% \includegraphics[width = 0.482\textwidth]{fig_pre/unit_distribution_extr_update_ver4_fig9.png}
\includegraphics[width = 0.482\textwidth]{fig_pre_low/unit_distribution_extr_update_ver4_fig9.png}
