% and are given by 
% \begin{align*}
% I(0) & = \int_0^{\infty} \left[ i_0(0,a) + i_p(0,a) \right] \d a = \int_0^{\infty} \left[ f_{i_0}(a) + f_{i_p}(a) \right] \d a, \\
% R(0) &  = \int_0^{\infty}  \left[ r_0(0,a)i_0(0,a) + r_p(0,a)i_p(0,a) \right] \d a = \int_0^{\infty} \left[ f_{r_0}(a)f_{i_0}(a) + f_{r_p}(a)f_{i_p}(a) \right] \d a.
% \end{align*} 
Now, if $b(t)$ is chosen so that hepatocytes undergo logistic growth with a carrying capacity $T_{max}$ and growth rate $\gamma$, as in \citep{Dahari2007,Dahari2007a,Iwanami2020,Reluga2009}, we obtain
\begin{equation} \label{Eq:LogisticProliferationEquivalentODE}
\left \{
\begin{aligned}
\TimeDeriv T(t) & = \gamma \left(1-\frac{T(t)+I(t)}{T_{max}} \right) T(t) -\beta V(t) T(t), \\
\TimeDeriv I(t) & = \beta V(t)T(t) +  \eta   \gamma \left(1-\frac{T(t)+I(t)}{T_{max}} \right)  I(t)  - \delta I(t), \\
\TimeDeriv R(t) & = \zeta \beta V(t) T(t) +  \alpha I(t)  - (\rho+\mu+\delta)R(t), \\
\TimeDeriv V(t) & =  \rho R(t)  - cV(t).
\end{aligned}
\right. 
\end{equation}
We compare Eq.~\eqref{Eq:LogisticProliferationEquivalentODE} against the \citet{Elkaranshawy2024} model in the Appendix and show that the \citet{Elkaranshawy2024} model predicts non-realistic production of intracellular vRNA due to infected cell proliferation.

\subsection{Generation tracking of infected hepatocytes}\label{Sec:GenerationTracking}
% \citep{Calogero1968}
In the development of Eq.~\eqref{Eq:ProliferationMultiScale}, we distinguished between cells that arise from new infections, $i_0(t,a)$, and cells that arise from infected cell proliferation, $i_p(t,a)$. In this setting, the boundary condition that defines the amount of intracellular vRNA inherited by newly proliferated daughter cells corresponds to the average amount of vRNA within all proliferating infected cells. However, the amount of vRNA at proliferation of the mother cell determines the amount of intracellular vRNA inherited by the resulting daughter cells. As we expect intracellular vRNA to be produced by infected  cells, and thus accumulate from birth until mitosis, the daughter cells in generation $n$ will have more intracellular vRNA upon mitosis than daughter cells in generation $n-1$. 

However, the resulting generational accumulation of intracellular vRNA is not reflected in the boundary conditions of Eq.~\eqref{Eq:ProliferationMultiScale}, where all daughter cells inherit half the average amount of vRNA of all proliferating mother cells, regardless of their generation. We now show how to account for these generational dynamics via an infinite system of PDEs that tracks the dynamics of each generation of infected hepatocytes. In what follows, the dynamics of newly infected cells, $i_0$, are unchanged from Eq.~\eqref{Eq:ProliferationMultiScale}.

\subsubsection*{Infinite systems of differential equations to model generational inheritance}

We begin by developing a mathematical model for each generation of infected hepatocyte. For $n \geq 1,$ let $i_n(t,a)$ denote the concentration of infected hepatocytes in the $n-$th generation, and let $I(t)$ denote the total concentration of infected hepatocytes. As before, the proliferation rate $b$ may depend on the concentration of uninfected and infected hepatocytes, $T(t)$ and $I(t)$. Then, using the same reasoning as for Eq.~\eqref{Eq:ProliferationMultiScale}, $i_n(t,a)$ satisfies
\begin{align*}
(\partial_t+ \partial_a)i_n(t,a) & =  - [\delta_n +b(t,I(t),T(t))h_n(a)] i_n(t,a).
\end{align*}
In what follows, we assume that the per capita death rate $\delta_n$ and likelihood of proliferation $h_n$ are independent of generation, so $\delta_n = \delta$ and $h_n(a) = h(a)$. For notational simplicity, we suppress the explicit dependence of $b$ on the total concentration of hepatocytes and instead write $ b(t, I(t),T(t)) = b(t).$  The boundary condition of $i_n(t,a)$ corresponds to proliferation of cells in the preceding generation, so the production of infected hepatocytes in generation $n$ is given by
\begin{align*}
i_n(t,0) = 2 \int_{0}^{\infty} b(t)h(a)i_{n-1}(t,a)\d a.
\end{align*}
In this framework, $a$ represents the time-since infection for $i_0(t,a)$ and the time since mitosis for $i_n(t,a)$ with $n = 1,2,...$.
% As we would expect from the biological interpretation of $i_n(t,a)$, the total concentration of infected hepatocytes that have arisen from proliferation is
% \begin{align*}
% i_p(t,a) = \displaystyle \sum_{n=1}^{\infty} i_n(t,a).
% \end{align*}
Similarly, let $r_n(t,a)$ denote the amount of intracellular vRNA within infected cells of age $a$ in generation $n$. Once again assuming that the dynamics of intracelluar vRNA are independent of generation and using the same reasoning as in Eq.~\eqref{Eq:ProliferationMultiScale}, we obtain
\begin{align*}
(\partial_t+ \partial_a)r_n(t,a) & = \alpha  - [\mu+\rho] r_n(t,a).
\end{align*}
Then, the boundary condition of $r_n(t,a)$ corresponds to the amount of vRNA inherited by infected cells in generation $n$ following mitosis of the mother cell in generation $n-1$. The total amount of vRNA within these proliferating cells is given by 
\begin{align*}
 \int_{0}^{\infty} b(t)h(a)i_{n-1}(t,a)r_{n-1}(t,a)\; \d a,
\end{align*}
and this vRNA is equally divided among the resulting daughter cells, now in the $n$-th generation, which determines the boundary condition $i_n(t,0)$. Consequently, each infected cell in generation $n$ inherits 
\begin{align*}
r_n(t,0) = \frac{\int_{0}^{\infty} b(t)h(a)i_{n-1}(t,a)r_{n-1}(t,a) \; \d a }{2 \int_{0}^{\infty} b(t)h(a)i_{n-1}(t,a) \; \d a},
\end{align*}
copies of vRNA. As we are not \textit{a priori} imposing an upper limit on the number of generations, $n$, the resulting model is a coupled infinite system of PDEs for the generational dynamics of $i_n(t,a)$ and $r_n(t,a)$ with $n = 1,2,3,...$. As in Section~\ref{Sec:MultiscaleProliferation}, the total concentration of infected cells in the $n-$th generation is given by  
\begin{align*}
I_n(t) = \int_0^{\infty} i_n(t,a) \d a.
\end{align*}
 Then, using the same approach as for Eq.~\eqref{Eq:ProliferationEquivalentODE}, we calculate
 \begin{align*}
 \TimeDeriv I_n(t) = 2 b(t) \int_0^{\infty} h(a) i_{n-1}(t,a)\d a - \delta I_n(t) - b(t) \int_0^{\infty} h(a) i_{n}(t,a)\d a .
 \end{align*}
Under the assumption that $h(a) = \eta$, this differential equation for $I_n(t)$ becomes
\begin{align*}
 \TimeDeriv I_n(t) = 2 b(t)\eta I_{n-1}(t)  - \delta I_n(t) - b(t)\eta I_n(t),
 \end{align*}
where we clearly see the distinction between the loss of cells in generation $n$ due to mitosis and the appearance of cells in this generation due to proliferation of cells in generation $n-1$. In this way, we obtain an infinite system of ODEs for $\{ I_n(t) \}_{n=1}^{\infty}$. Assuming that $I_m(0) \geq 0$ for all $m$, it is simple to show by induction and using Gronwall's lemma that $I_m(t) \geq 0 $ for all $m$ \citep{Reid1930}. Returning to the intracellular vRNA concentration, the total amount of vRNA within each generation is given by
\begin{align*}
R_n(t) = \int_0^{\infty} i_n(t,a)r_n(t,a) \d a,
\end{align*}
and using the same approach as in Section~\ref{Sec:MultiscaleProliferation}, we calculate
\begin{align*}
\TimeDeriv R_n(t) = \alpha I_n(t)  - (\delta + \mu+ \rho)R_n(t) .
\end{align*}
As with the concentration of infected hepatocytes in the $n$-th generation, assuming that $R_m(0) \geq 0$ for all $m$ implies that $R_m(t) \geq 0$. We thus obtain the infinite system of ODEs
\begin{equation}\label{Eq:InfiniteSystemODE}
\left \{
\begin{aligned}
\TimeDeriv T(t) & =b(t) T(t) -\beta T(t) V(t), \\
\TimeDeriv I_0(t) &  =  \beta T(t) V(t)  - \eta b(t) I_0(t)-\delta I_0(t), \\
\TimeDeriv I_n(t) & =    2\eta b(t) I_{n-1}(t) -  \eta b(t) I_n(t)  - \delta I_{n}(t) , \  \textrm{for} \  n \geq 1,  \\
% =   2 \eta \gamma \left( 1 - \frac{T(t)+  \sum_{n=0}^{\infty} I_n(t) }{T_{max}}  \right) I_{n-1}(t) -  \eta \gamma \left( 1 - \frac{T(t)+  \sum_{n=0}^{\infty} I_n(t) }{T_{max}}  \right) I_{n}(t) - \delta I_{n}(t) , \  \textrm{for} \  n = 1,2,3,... \\
\TimeDeriv R_0(t) &  = \zeta \beta T(t) V(t) + \alpha I_0(t)  - (\delta + \mu+ \rho)R_0(t), \\
\TimeDeriv R_n(t) & = \alpha I_n(t)  - (\delta + \mu+ \rho)R_n(t), \  \textrm{for} \  n \geq 1,  \\
\TimeDeriv V(t) & = \rho \sum_{n=0}^{\infty} R_n(t) - cV(t).
\end{aligned}
\right.
\end{equation}

\subsubsection*{Tracking generational dynamics does not influence infection dynamics}

We now show that the dynamics of the infinite system of ODEs in Eq.~\eqref{Eq:InfiniteSystemODE} are precisely the same as those of the multiscale model with proliferation that did not track the generational inheritance. To do so, we remark that, if we could interchange infinite summation and differentiation, so that
\begin{align*}
\TimeDeriv  \displaystyle \sum_{n=0}^{\infty} I_n(t) =  \displaystyle  \sum_{n=0}^{\infty} \TimeDeriv I_n(t),
\end{align*}
then the resulting infinite series would telescope to exactly the ODE for $I(t)$ in Eq.~\eqref{Eq:LogisticProliferationEquivalentODE}. In Appendix~\ref{Sec:InfiniteODEProof}, we utilize the results on infinite systems of differential equations from \citet{McClure1976}, where they considered the generic infinite system of ODEs
\begin{align}\label{Eq:McClureODE}
\TimeDeriv y_i(t) = \displaystyle \sum_{j=1}^{\infty} a_{i,j}(t)y_j(t) + f_j(\tilde{y}(t)), \quad \textrm{for} \quad i = 1,2,...,
\end{align}
with $\tilde{y} = (y_1(t), y_2(t),...)$, to show that we can exchange differentiation and summation. \citet{McClure1976} demonstrated that a unique solution of Eq.~\eqref{Eq:McClureODE} exists and is a \textit{strongly continuous function}.  
\sloppy
\begin{definition} [Strongly continuous function]
The sequence $\tilde{y}(t) = (y_1(t), y_2(t),...)$ is a strongly continuous function on the domain $\mathcal{I} \subset \mathbb{R}$ if each $y_i(t)$ is continuous and
\begin{align*}
\|\tilde{y}(t) \| = \displaystyle \sum_{i=1}^{\infty} |y_i(t)|
\end{align*}
is uniformly convergent on compact subsets of $\mathcal{I}$.
\end{definition}

In Appendix~\ref{Sec:InfiniteODEProof}, we prove 
% that the infinite system Eq.~\eqref{Eq:InfiniteSystemODE} has a strongly continuous solution. 
\begin{proposition}\label{Prop:StronglyContinuousSolution}
Assume that the parameters in Eq.~\eqref{Eq:InfiniteSystemODE} are strictly positive, the proliferation function $b(t)$ is continuous and bounded, and that the initial conditions are non-negative. Then, the infinite system of ODEs~Eq.~\eqref{Eq:InfiniteSystemODE} has a strongly continuous solution. 
\end{proposition}

Now, let $\tilde{I}(t) = (I_1(t), I_2(t), ...)$ and $\tilde{R}(t) = (R_1(t), R_2(t),...),$ be the strongly continuous solution of Eq.~\eqref{Eq:InfiniteSystemODE} and define
\begin{align*}
J_N(t) = I_0(t) + \displaystyle \sum_{n=1}^N I_n(t) \quad \textrm{and} \quad P_N(t) = R_0(t) + \displaystyle \sum_{n=1}^N R_n(t).
\end{align*}
Proposition~\ref{Prop:StronglyContinuousSolution} ensures that $J_N$ and $P_N$ converge uniformly, so it is natural to define the total concentration of infected cells, $I(t)$, and intracellular vRNA, $R(t)$, as
\begin{align*}
I(t) = \lim_{N \to \infty} J_N(t)  \quad \textrm{and} \quad R(t) =  \lim_{N \to \infty} P_N(t). 
\end{align*}
Then, by adding and subtracting the term $\eta b(t) I_N(t)$ in the ODE for $J_N$, we calculate
\begin{align*}
\TimeDeriv J_N(t) & = \beta V(t)T(t) +   \eta b(t) J_{N}(t)  - \delta  J_{N}(t)  - 2\eta b(t) I_{N}(t), \\
\TimeDeriv P_N(t) & = \zeta \beta V(t) T(t) +  \alpha J_N(t)  - (\delta + \mu+ \rho)P_N(t).
\end{align*}
Since $J_N$ and $P_N$ converge uniformly and $I_N\to 0$ as $N \to \infty$, the sequences $J'_N$ and $P'_N$ converge uniformly, so after interchanging differentiation and summation, we find 
\begin{align*}
\TimeDeriv I(t)  & = \beta V(t)T(t) +  \eta b(t) I(t)  - \delta I(t), \ \textrm{and}  \\
\TimeDeriv R(t)  & = \zeta \beta V(t) T(t) +  \alpha I(t)  - (\rho+\mu+\delta)R(t), 
\end{align*}   
 which are precisely what we obtained in Eq.~\eqref{Eq:ProliferationEquivalentODE}.  Consequently, the dynamics of the total concentration of infected hepatocytes and intracellular vRNA in the infinite ODE that tracks generation inheritance Eq.~\eqref{Eq:InfiniteSystemODE} are exactly those of Eq.~\eqref{Eq:ProliferationEquivalentODE}, where we only considered infected hepatocytes arising from new infections or from proliferation of infected mother cells. We therefore do not need to account for the generational dynamics of intracellular vRNA, as the inheritance balances over all generations. Further, for non-negative parameters, the existence, uniqueness, and non-negativity of solutions to Eq.~\eqref{Eq:InfiniteSystemODE} is immediate.

