\subsection{Gradient and Hessian of the \gls{rdp}} \label{appendix:rdp}

For completeness, we present here the first and second derivatives of the \gls{rdp} \eqref{eqn:rdp}, i.e., the gradient and the diagonal of the Hessian. Both of these are used in our proposed solution.

Let $d_{i,j} = \image_i - \image_j$, $s_{i,j} = \image_i + \image_j$ and $\phi_{i,j} = s_{i,j} + \gamma |d_{i,j}| + \varepsilon$. Then the first derivative is given by 
\begin{align*}
    \partial_{\image_i} \smoothness(\image) = \sum_{j \in N_i} w_{i,j} \kappa_i \kappa_j \frac{d_{i,j} (2 \phi_{i,j} - (d_{i,j} + \gamma |d_{i,j}|))}{\phi_{i,j}^2},
\end{align*}
and the second by
\begin{align*}
    \partial^2_{\image_i} \smoothness(\image) = 2 \sum_{j \in N_i} w_{i,j} \kappa_i \kappa_j \frac{(s_{i,j} - d_{i,j} + \varepsilon)^2}{\phi_{i,j}^3}.
\end{align*}


\subsection{Pseudocode for submitted preconditioned \gls{svrg} algorithm
\label{sec:app_alg}}

\begin{algorithm}
  \caption{Preconditioned \gls{svrg} Algorithm}
  \label{alg:svrg}
  \begin{algorithmic}[1]
    \Require initial image: \(\image\), number of subsets: \(\nsubsets\), 
    stepsize rule: \texttt{stepsize}, 
    sampling rule: \texttt{subset}, 
    diagonal preconditioner rule: \texttt{preconditioner},
    list of iterations to update the preconditioner: \texttt{update\_pc\_iters},
    update gradient at anchor point every $\omega$ epochs (default=2)
    \For{\(k = 0,1,\dots\)}
        \If{\(k \in \text{\texttt{update\_pc\_iters}}\)}
        \State \(\precond \gets \text{\texttt{preconditioner}}(\image)\) \Comment{update preconditioner via \eqref{eqn:preconditioner}}
      \EndIf

      \If{\(k \bmod (\omega \nsubsets) = 0\)}
        \For{\(i=1\) \textbf{to} \(\nsubsets\)} 
          \State \(\svrghist{i} \gets \nabla \objective_i(\image)\) \Comment{calculate all subset gradients at snapshot image}
        \EndFor
        \State \(\svrghist{} \gets \sum_{i=1}^\nsubsets \svrghist{i}\)
        \State \(\tilde \nabla \gets \svrghist{}\)
      \Else
        \State \(i \gets \text{\texttt{subset}} (k)\) 
        \State \(\tilde \nabla \gets \nsubsets \bigl(\nabla \objective_i(\image) - \svrghist{i}\bigr) + \svrghist{}\)
      \EndIf
        \State \(\tau \gets \text{\texttt{stepsize}} (k)\) 
      \State \(\image \gets \image -\tau\precond\tilde \nabla\)
      \If{stopping criterion is reached} 
        \Return{$\image$}
       \EndIf
       \EndFor
  \end{algorithmic}
\end{algorithm}


