\centering 
\includegraphics[width=0.8\columnwidth]{C-Figure-C1-filling.pdf}
\caption{Apparent (black) and intrinsic (red) thickness of the continuum emission at 230 GHz as a function of radius;  in blue, intrinsic thickness at 345 GHz.  The dash-dotted line indicates the width due to the best fit scale height,
the dashed line the expected width due to the disk inclination of $\sim 86^\circ$, and the solid line the resulting total width.}
\label{fig:filling}%
