 \Longrightarrow  c^2  \ \mathbf{B}(\mathrm{Sz}(q))^3 \le   {\mathbf{B}(\mathrm{Sz}(q))}^2  \ {( \mathbf{B}(\mathrm{Sz}(q))+1)}^2
 \end{equation}   
and so
