\title{\LARGE \bf
First experimental demonstration of plasma shape control in a tokamak through Model Predictive Control
}

\author{Adriano Mele$^{1}$, 
Maria A. Topalova$^{1,2}$, 
Cristian Galperti$^{1}$, Stefano Coda$^{1}$, \\
the TCV team$^{3}$ and the Eurofusion Tokamak Exploitation team$^4$% 
