    \qquad
    \infer[{\ket 1}]
    {\vdash\ket 1:\B}
    {}
    \qquad
    \infer[{\ket{+}}]
    {\vdash\ket{+}:\X}
    {}
    \qquad
    \infer[{\ket{-}}]
    {\vdash\ket{-}:\X}
    {}
  \]
