\section{Subject reduction}

\subsection{Generation lemma}\label{app:generation}
We write $\fT(\Gamma)$ for the set of types in the context $\Gamma$, that is,
$\fT(\Gamma) = \Set{\gB \mid x^\gB \in \Gamma}$.


\begin{lemma}[Generation]
  \label{generation}
  If $\Gamma \vdash t : A$, then:
  \begin{enumerate}
    \item\label{generation_1} If $t = x$, then $x^\gB \in \Gamma$, $\gB \preceq A$, and $\fT(\Gamma
      \setminus \{x^\gB\}) \subseteq \bqtypes$.

    \item\label{generation_2} If $t = \z$, then there exists $C$ such that $\Gamma \vdash \z :
      S(C)$, $S(C) \preceq A$, and $\fT(\Gamma) \subseteq \bqtypes$.

    \item\label{generation_3} If $t = \ket{0}$ or $t = \ket{1}$, then $\B \preceq A$ and
      $\fT(\Gamma) \subseteq \bqtypes$.

    \item\label{generation_5} If $t = \ket{+}$ or $t = \ket{-}$, then $\X \preceq A$ and
      $\fT(\Gamma) \subseteq \bqtypes$.

    \item\label{generation_7} If $t = \lambda x^{\gB}.r$, then $\Gamma, x^\gB \vdash r : C$ and
      $\gB \Rightarrow C \preceq A$.

    \item\label{generation_8} If $t = rs$, then either:
      \begin{itemize}
	\item $\Gamma = \Gamma_1, \Gamma_2, \Xi$, with $\fT(\Xi) \subseteq
	  \bqtypes$, $\Gamma_1, \Xi \vdash r : \gB \Rightarrow A$, and
	  $\Gamma_2, \Xi \vdash s : \gB$, or
	\item $\Gamma_1, \Xi \vdash r : S(\gB \Rightarrow C)$, $\Gamma_2, \Xi
	  \vdash s : S(\gB)$, and $S(C) \preceq A$.
      \end{itemize}

    \item\label{generation_9} If $t = r + s$, then $\Gamma = \Gamma_1, \Gamma_2, \Xi$, with $\Xi,
      \Gamma_1 \vdash r : C$, $\Xi, \Gamma_2 \vdash s : C$, $\fT(\Xi) \subseteq
      \bqtypes$, and $S(C) \preceq A$.

    \item\label{generation_10} If $t = \alpha.r$, then $\Gamma \vdash r : C$ and $S(C) \preceq A$.

    \item\label{generation_11} If $t = r \otimes s$, then $\Gamma = \Gamma_1, \Gamma_2, \Xi$, with
      $\Xi, \Gamma_1 \vdash r : \gB_1$, $\Xi, \Gamma_2 \vdash s : \gB_2$,
      $\fT(\Xi) \subseteq \bqtypes$, and $\gB_1 \times \gB_2 \preceq A$.

    \item\label{generation_12} If $t = \pim r$, then $\Gamma \vdash r : S\left(\prod_{i=1}^{n}
      \Ba_i\right)$ and $\B^m \times S\left(\prod_{i=m+1}^{n} \Ba_i\right)
      \preceq A$ for some $0 < m \leq n$.

    \item\label{generation_13} If $t = \pimx r$, then $\Gamma \vdash r : S\left(\prod_{i=1}^{n}
      \Ba_i\right)$ and $\X^m \times S\left(\prod_{i=m+1}^{n} \Ba_i\right)
      \preceq A$ for some $0 < m \leq n$.

    \item\label{generation_14} If $t = \ite{r}{s_1}{s_2}$, then $\Gamma \vdash r : C$, $\Gamma
      \vdash s_1 : C$, and $\B \Rightarrow C \preceq A$.

    \item\label{generation_15} If $t = \itex{r}{s_1}{s_2}$, then $\Gamma \vdash r : C$, $\Gamma
      \vdash s_1 : C$, and $\X \Rightarrow C \preceq A$.

    \item\label{generation_16} If $t = \Castl r$, then either:
      \begin{itemize}
	\item $\Gamma \vdash r : S(\gB \times S(\Phi))$, with $\Phi \neq
	  S(\Phi')$ and $S(\gB \times \Phi) \preceq A$, or
	\item $\Gamma \vdash r : \X$ and $S(\B) \preceq A$, or
	\item $\Gamma \vdash r : \B$ and $\B \preceq A$.
      \end{itemize}

    \item\label{generation_17} If $t = \Castr r$, then either:
      \begin{itemize}
	\item $\Gamma \vdash r : S(S(\gB) \times \Phi)$, with $\gB \neq
	  S(\gB')$ and $S(\gB \times \Phi) \preceq A$, or
	\item $\Gamma \vdash r : \X$ and $S(\B) \preceq A$, or
	\item $\Gamma \vdash r : \B$ and $\B \preceq A$.
      \end{itemize}

    \item\label{generation_18} If $t = \head r$, then $\Gamma \vdash r : \Ba \times \M$ and $\Ba
      \preceq A$.

    \item\label{generation_19} If $t = \tail r$, then $\Gamma \vdash r : \Ba \times \M$ and $\M
      \preceq A$.
  \end{enumerate}
\end{lemma}
\begin{proof}
  By structural induction on the typing derivation for $t$. The cases follow by
  inspection of the corresponding typing rules, taking into account that only the
  subtyping, weakening, and contraction rules are non-syntax-directed.
  \qed
\end{proof}

\begin{corollary}[Generalised generation lemma for sums]
  \label{generation_9_generalized}
  If $\Gamma \vdash \sum_{i=1}^{n} t_i : A$ with $n \geq 2$, then there exist contexts $\Gamma_1, \ldots, \Gamma_n$ and $\Xi$ such that $\Gamma = \Gamma_1, \ldots, \Gamma_n, \Xi$, and for all $1 \leq i \leq n$ we have $\Xi, \Gamma_i \vdash t_i : C$, $\fT(\Xi) \subseteq \bqtypes$, and $S(C) \preceq A$.
\end{corollary}
\begin{proof}
  By induction on $n$.

  By Lemma~\ref{generation}.\ref{generation_9}, the result holds for $n=2$.
  Suppose the result holds for $n-1$ terms.  
  Let $\Gamma \vdash (\sum_{i=1}^{n-1} t_i) + t_n : A$.  
  By Lemma~\ref{generation}.\ref{generation_9}, we have:
  \[
    \Gamma = \Gamma_1', \Gamma_n, \Xi,\quad
    \fT(\Xi) \subseteq \bqtypes,\quad
    \Xi, \Gamma_1' \vdash \sum_{i=1}^{n-1} t_i : C,\quad
    \Xi, \Gamma_n \vdash t_n : C,\quad
    S(C) \preceq A
  \]
  By the induction hypothesis, there exist contexts $\Gamma_1, \ldots, \Gamma_{n-1}$ and $\Xi'$ such that
  \[
    \Xi, \Gamma_1' = \Gamma_1, \ldots, \Gamma_{n-1}, \Xi',\quad
    \fT(\Xi') \subseteq \bqtypes,\quad
    \Xi', \Gamma_i \vdash t_i : D,\quad
    S(D) \preceq C
  \]
  Since $D \preceq S(D)$ and $S(D) \preceq C$, transitivity gives $D \preceq C$, so $\Xi', \Gamma_i \vdash t_i : C$ for all $1 \leq i < n$.

  We distinguish two cases:
  \begin{itemize}
    \item If $\Xi' = \Xi_1, \Xi_2$ with $\Xi = \Xi_1$ and $\Xi_2 \subseteq \Gamma_1$, then weakening gives $\Xi', \Gamma_n \vdash t_n : C$, completing the argument.
    \item If $\Xi = \Xi_1, \Xi_2$ with $\Xi' = \Xi_1$ and $\Xi_2 \subseteq \Gamma_1', \ldots, \Gamma_{n-1}'$, then weakening gives $\Xi, \Gamma_i \vdash t_i : C$ for all $i$, and the result follows.
      \qed
  \end{itemize}
\end{proof}

\begin{corollary}[Generalised generation lemma for products]
  \label{generation_11_generalized}
  If $\Gamma \vdash \bigotimes_{i=1}^{n} t_i : A$ with $n \geq 2$, then there exist contexts $\Gamma_1, \ldots, \Gamma_n$ and $\Xi$ such that $\Gamma = \Gamma_1, \ldots, \Gamma_n, \Xi$, and for all $1 \leq i \leq n$ we have $\Xi, \Gamma_i \vdash t_i : \gB_i$, $\fT(\Xi) \subseteq \bqtypes$, and $\prod_{i=1}^{n} \gB_i \preceq A$.
\end{corollary}

\begin{proof}
  By induction on $n$.

  For $n=2$, the result follows from Lemma~\ref{generation}.\ref{generation_11}.  
  Suppose it holds for $n-1$. Let $\Gamma \vdash (\bigotimes_{i=1}^{n-1} t_i) \otimes t_n : A$.  
  By Lemma~\ref{generation}.\ref{generation_11}, we have:
  \[
    \Gamma = \Gamma_1', \Gamma_n, \Xi,\quad
    \fT(\Xi) \subseteq \bqtypes,\quad
    \Xi, \Gamma_1' \vdash \bigotimes_{i=1}^{n-1} t_i : \gB',\quad
    \Xi, \Gamma_n \vdash t_n : \gB_n,\quad
    \gB' \otimes \gB_n \preceq A
  \]
  By induction, there exist $\Gamma_1, \ldots, \Gamma_{n-1}$ and $\Xi'$ such that
  \[
    \Xi, \Gamma_1' = \Gamma_1, \ldots, \Gamma_{n-1}, \Xi',\quad
    \fT(\Xi') \subseteq \bqtypes,\quad
    \Xi', \Gamma_i \vdash t_i : \gB_i,\quad
    \prod_{i=1}^{n-1} \gB_i \preceq \gB'
  \]
  By transitivity of $\preceq$, we have $\prod_{i=1}^{n} \gB_i \preceq A$.

  As in Corollary~\ref{generation_9_generalized}, the two possible splittings of $\Xi$ and $\Xi'$ can be handled via weakening to complete the result.
  \qed
\end{proof}
\begin{corollary}
  \label{b_void_context}
  If $\vdash b : \gB$, then there exists $\M \in \bqtypes$ such that $\vdash b : \M$ and $\M \preceq \gB$.
\end{corollary}
\begin{proof}
  Since the typing context is empty, $b$ cannot be a variable. Moreover, because $b$ has type $\gB$, it cannot be a lambda abstraction either.
  We proceed by structural induction on $b$:
  \begin{itemize}
    \item If $b = \ket{0}$, or $b = \ket{1}$, then $\vdash b : \B$ and by Lemma~\ref{generation}.\ref{generation_3}, $\B \preceq \gB$.
    \item If $b = \ket{+}$, or $b = \ket{-}$, then $\vdash b : \X$ and by Lemma~\ref{generation}.\ref{generation_5}, $\X \preceq \gB$.
    \item If $b = b_1 \otimes b_2$, then by Lemma~\ref{generation}.\ref{generation_11}, we have:
    \[
      \vdash b_1 : \gB_1,\quad
      \vdash b_2 : \gB_2,\quad
      \gB_1 \otimes \gB_2 \preceq \gB.
    \]
    By the induction hypothesis, there exist $\M_1, \M_2 \in \bqtypes$ such that $\vdash b_1 : \M_1$, $\M_1 \preceq \gB_1$ and $\vdash b_2 : \M_2$, $\M_2 \preceq \gB_2$. Then
    \[
      \vdash b : \M_1 \otimes \M_2,\quad
      \text{and}\quad \M_1 \otimes \M_2 \preceq \gB_1 \otimes \gB_2 \preceq \gB,
    \]
    so $\M_1 \otimes \M_2 \preceq \gB$.
    \qed
  \end{itemize}
\end{proof}

\subsection{Substitution lemma}\label{app:substitution}

\substitution*
\begin{proof}
  We proceed by induction on the derivation of $\Gamma,x^A \vdash t:C$.
  \begin{enumerate}
    \item If $t$ is a variable, then $t = x$ and $t\Substitution{r}{x} = r$.
    \begin{itemize}
      \item Case $\Gamma, x^\gB \vdash x: C$, with $\Delta \vdash r: \gB$ and $\gB \notin \bqtypes$.  
      By Lemma~\ref{generation}.\ref{generation_1}, we know that $\fT(\Gamma) \subseteq \bqtypes$ and $\gB \preceq C$.  
      We want to derive $\Gamma, \Delta \vdash r: C$, which follows by weakening and subtyping:
      \[
        \infer[W]
        {\Gamma, \Delta \vdash r: C}
        {
          \infer[\preceq]
          {\Delta \vdash r: C}
          {\Delta \vdash r: \gB}
        }
      \]
      \item Case $\Gamma, x^{\M} \vdash x: C$, with $\Delta \vdash b: \M$ and $b \in \basis$.  
      Similarly, by Lemma~\ref{generation}.\ref{generation_1}, we know $\fT(\Gamma) \subseteq \bqtypes$ and $\M \preceq C$.  
      Then:
      \[
        \infer[W]
        {\Gamma, \Delta \vdash b: C}
        {
          \infer[\preceq]
          {\Delta \vdash b: C}
          {\Delta \vdash b: \M}
        }
      \]
    \end{itemize}

    \item If $t = \z$, then $\z\Substitution{r}{x} = \z$.  
    \begin{itemize}
      \item Case $\Gamma, x^\gB \vdash \z: C$, with $\gB \notin \bqtypes$.  
      By Lemma~\ref{generation}.\ref{generation_2}, we get $\fT(\Gamma, x^\gB) \subseteq \bqtypes$, a contradiction.
      \item Case $\Gamma, x^\M \vdash \z: C$, with $\Delta \vdash b: \M$.  
      Since $\fFV(\z) = \emptyset$, the only way to obtain $\Gamma, x^\M$ is via weakening.  
      Then $\z\Substitution{b}{x} = \z$, and as before, we derive $\Gamma, \Delta \vdash \z: C$ using weakening and subtyping.
    \end{itemize}

    \item If $t$ is a base term like $\ket{0}$, $\ket{1}$, $\ket{+}$, or $\ket{-}$, all cases are similar to the previous one for $\z$: 
    the substitution has no effect, and typing is preserved using the same reasoning (i.e., weakening and subtyping after showing that 
    $b \in \basis$ and $\fT(\Gamma) \subseteq \bqtypes$).

    \item If $t = \lambda y^B. s$, then $x$ is not bound in $t$, since $x$ appears in the context.  
    By Lemma~\ref{generation}.\ref{generation_7}, we have:
    \[
      \Gamma, y^B \vdash s : D,\quad B \Rightarrow D \preceq C
    \]
    By induction hypothesis, $\Gamma, y^B, \Delta \vdash s\Substitution{r}{x} : D$, and so:
    \[
      \infer[\preceq]
      {\Gamma, \Delta \vdash (\lambda y^B.s)\Substitution{r}{x}: C}
      {
        \infer[\Rightarrow_I]
        {\Gamma, \Delta \vdash \lambda y^B.s\Substitution{r}{x} : B \Rightarrow D}
        {\Gamma, \Delta, y^B \vdash s\Substitution{r}{x} : D}
      }
    \]

    \item If $t = s_1 s_2$, use Lemma~\ref{generation}.\ref{generation_8} and proceed by distinguishing whether $x$ occurs in the context 
    of $s_1$ or $s_2$, applying the induction hypothesis in each and reconstructing the application typing using the appropriate rule 
    (standard application or scalar application).

    \item If $t = s_1 + s_2$, same structure: apply Lemma~\ref{generation}.\ref{generation_9}, identify the side where $x$ occurs, apply the induction hypothesis, 
    and reconstruct the typing via the $S^+_I$ rule, plus weakening and contraction as needed.

    \item If $t = \alpha.t_1$, use Lemma~\ref{generation}.\ref{generation_10}. By induction hypothesis we obtain typing for $t_1\Substitution{r}{x}$ and apply 
    the rule for scalar multiplication plus subtyping.

    \item If $t = s_1 \otimes s_2$, apply Lemma~\ref{generation}.\ref{generation_11}. Distinguish whether $x$ occurs in $\Gamma_1$, $\Gamma_2$, or $\Xi$, 
    and apply the induction hypothesis and weakening accordingly.

    \item If $t = \pim t_1$, apply Lemma~\ref{generation}.\ref{generation_12} and use the induction hypothesis on $t_1\Substitution{r}{x}$.

    \item If $t = \pimx t_1$, the case is analogous to the previous one.

    \item If $t = \ite{}{s_1}{s_2}$ or $t = \itex{}{s_1}{s_2}$, use Lemma~\ref{generation}.\ref{generation_14} and proceed by applying the induction hypothesis to both $s_1$ and $s_2$.

    \item If $t = \Castl t_1$ or $t = \Castr t_1$, handle the three subcases for $t_1$ described in Lemmas~\ref{generation}.\ref{generation_16} 
    and \ref{generation}.\ref{generation_17}, applying the induction hypothesis and the corresponding cast rule.

    \item If $t = \head{t_1}$ or $t = \tail{t_1}$, use Lemmas~\ref{generation}.\ref{generation_18} and \ref{generation}.\ref{generation_19}. 
    Apply the induction hypothesis to $t_1$, then reconstruct the typing via the appropriate rule and subtyping.

    \item If $t = \error$, then $t\Substitution{r}{x} = \error$, which has any type. So the result holds trivially.
      \qed
  \end{enumerate}
\end{proof}

\subsection{Properties of the subtyping relation}\label{app:preceq_properties}
In order to prove the properties of the subtyping relation, we will need the following auxiliary properties.

\begin{lemma}[More properties of the subtyping relation]
  \label{more_preceq_properties}
  The subtyping relation $\preceq$ also satisfies the following properties:
  \begin{enumerate}
    \item \label{preceq_relation_1} If $A \preceq B$ and $B \not\approx S(C)$, then for all $D$, $A \not\approx S(D)$.
    \item \label{preceq_relation_2} If $A \Rightarrow B \preceq C$ and $C \not\approx S(D)$, then there exist $E$ and $F$ such that $C \typeequiv E \Rightarrow F$ with $E \preceq A$ and $B \preceq F$.
    \item \label{preceq_relation_4} If $S(A \Rightarrow B) \preceq C$, then there exist $k > 0$, $D$ and $E$ such that $C \typeequiv S^k(D \Rightarrow E)$ with $D \preceq A$ and $B \preceq E$.
    \item \label{preceq_relation_5} If $A \Rightarrow B \preceq S(C)$ with $C \not\approx S(D)$, then there exist $E$ and $F$ such that $C \typeequiv E \Rightarrow F$ with $E \preceq A$ and $B \preceq F$.
    \item \label{preceq_relation_9} If $\gB_1 \times \gB_2 \preceq A$ and $A$ is not a superposition, then there exist $\gB_3$ and $\gB_4$ such that $A \approx \gB_3 \times \gB_4$, $\gB_1 \preceq \gB_3$ and $\gB_2 \preceq \gB_4$.
    \item \label{preceq_relation_10} If $S(\gB_1 \times \gB_2) \preceq S(A)$ and $A$ is not a superposition, then there exist $\gB_3$ and $\gB_4$ such that $A \approx \gB_3 \times \gB_4$, $S(\gB_1) \preceq S(\gB_3)$ and $S(\gB_2) \preceq S(\gB_4)$.
  \end{enumerate}
\end{lemma}
\begin{proof}~
  \begin{enumerate}
    \item[{\ref{preceq_relation_1}}.]
      By induction on the derivation tree of the subtyping judgment.
      \begin{itemize}
	\item \emph{Base case: derivation of size 0.}

	  The only possible rule is:
	  \[
	    \infer
	    {A \preceq A}
	    {}
	  \]
	  Since $A \typeequiv B$ and $B \not\approx S(C)$, we conclude that $A \not\approx S(C)$. 
	  By $C \typeequiv D$, we get $A \not\approx S(D)$ as required.

	\item \emph{Inductive case: derivation of size greater than 0.}
	  \begin{itemize}
	    \item
	      \[
		\infer
		{A \preceq B}
		{A \preceq E & E \preceq B}
	      \]
	      Since $E \preceq B$, by the induction hypothesis we have $E \not\approx S(F)$ for any $F$.
	      Then, since $A \preceq E$, again by induction we conclude $A \not\approx S(D)$.

	    \item
	      \[
		\infer
		{\gB_2 \Rightarrow E \preceq \gB_1 \Rightarrow F}
		{E \preceq F \quad \gB_1 \preceq \gB_2}
	      \]
	      We have $A \typeequiv \gB_2 \Rightarrow E$ and $B \typeequiv \gB_1 \Rightarrow F$, with $B \not\approx S(C)$.
	      Hence $A \not\approx S(D)$ holds.

	    \item
	      \[
		\infer
		{\gB_1 \times \gB_3 \preceq \gB_2 \times \gB_4}
		{\gB_1 \preceq \gB_2 \quad \gB_3 \preceq \gB_4}
	      \]
	      Here $A \typeequiv \gB_1 \times \gB_3$ and $B \typeequiv \gB_2 \times \gB_4$, with $B \not\approx S(C)$.
	      Then $A \not\approx S(D)$ as required.
	  \end{itemize}
      \end{itemize}

    \item[{\ref{preceq_relation_2}}.]
      By induction on the derivation tree of the subtyping judgment.
      \begin{itemize}
	\item \emph{Base case: derivation of size 0.}

	  The only possible rule is:
	  \[
	    \infer
	    {A \Rightarrow B \preceq A \Rightarrow B}
	    {}
	  \]
	  Then $C \typeequiv A \Rightarrow B$, and in particular $C \not\approx S(D)$.
	  Let $E \typeequiv A$ and $F \typeequiv B$. We have $E \approx A$ and $F \approx B$, hence
	  $E \preceq A$ and $B \preceq F$ as required.

	\item \emph{Inductive case: derivation of size greater than 0.}
	  \begin{itemize}
	    \item
	      \[
		\infer
		{A \Rightarrow B \preceq E \Rightarrow F}
		{A \Rightarrow B \preceq G \quad G \preceq E \Rightarrow F}
	      \]
	      We have $C \typeequiv E \Rightarrow F$ and in particular $C \not\approx S(D)$.

	      Since $G \preceq E \Rightarrow F$, by Lemma~\ref{more_preceq_properties}.\ref{preceq_relation_1}
	      we get $G \not\approx S(I)$ for any $I$.

	      As $A \Rightarrow B \preceq G$, by induction hypothesis we get $G \approx J \Rightarrow K$
	      with $J \preceq A$ and $B \preceq K$.

	      Then $J \Rightarrow K \preceq E \Rightarrow F$, so by induction we get $E \preceq J$ and $K \preceq F$.

	      By transitivity, $E \preceq A$ and $B \preceq F$.

	    \item
	      \[
		\infer
		{\gB_2 \Rightarrow B \preceq \gB_1 \Rightarrow F}
		{B \preceq F \quad \gB_1 \preceq \gB_2}
	      \]
	      Here $A \typeequiv \gB_2$ and $E \approx \gB_1$, so $E \preceq A$ and $B \preceq F$.
	  \end{itemize}
      \end{itemize}
    \item[{\ref{preceq_relation_4}}.]
      By induction on the derivation tree.
      \begin{itemize}
	\item \emph{Base case: tree of size 0.}  
	  The only possible derivations of size 0 are:
	  \begin{itemize}
	    \item
	      \[
		\infer
		{S(A \Rightarrow B) \preceq S(A \Rightarrow B)}
		{}
	      \]
	      In this case, $C \typeequiv S^1(A \Rightarrow B)$, so $k = 1$, $D \typeequiv A$ and $E \typeequiv B$.  
	      Then, since $B \approx E$, we have $B \preceq E$, and similarly $A \approx D$, so $D \preceq A$.

	    \item
	      \[
		\infer
		{S(A \Rightarrow B) \preceq S(S(A \Rightarrow B))}
		{}
	      \]
	      Here, $C \typeequiv S^2(A \Rightarrow B)$, so $k = 2$, $D \typeequiv A$ and $E \typeequiv B$.  
	      Again, $B \preceq E$ and $D \preceq A$ follow from type equivalence.
	  \end{itemize}

	\item \emph{Inductive case: tree of size greater than 0.}
	  \begin{itemize}
	    \item
	      \[
		\infer
		{S(A \Rightarrow B) \preceq C}
		{S(A \Rightarrow B) \preceq F \quad F \preceq C}
	      \]
	      By induction hypothesis, $F \typeequiv S^{k'}(G \Rightarrow H)$ with $G \preceq A$ and $B \preceq H$.  
	      Since $S^{k'}(G \Rightarrow H) \approx S(G \Rightarrow H)$, we get $S(G \Rightarrow H) \preceq C$.  
	      Then, by induction hypothesis again, $C \typeequiv S^k(I \Rightarrow J)$ with $I \preceq G$ and $H \preceq J$.  
	      By transitivity, $I \preceq A$ and $B \preceq J$. Hence the result holds with $D \typeequiv I$ and $E \typeequiv J$.

	    \item
	      \[
		\infer
		{S(A \Rightarrow B) \preceq S^k(F)}
		{A \Rightarrow B \preceq F}
	      \]
	      Then $C \typeequiv S(F)$.
	      \begin{itemize}
		\item If $k = 1$, by Lemma~\ref{more_preceq_properties}.\ref{preceq_relation_2}, $F \typeequiv D \Rightarrow E$ with $D \preceq A$ and $B \preceq E$.
		\item If $k > 1$, by induction hypothesis, $F \typeequiv S^{k-1}(D \Rightarrow E)$ with $D \preceq A$ and $B \preceq E$.
	      \end{itemize}
	      In both cases, the result follows.
	  \end{itemize}
      \end{itemize}

    \item[{\ref{preceq_relation_5}}.]
      By induction on the derivation tree.
      \begin{itemize}
	\item \emph{Base case: tree of size 0.}  
	  The only possible derivation is:
	  \[
	    \infer
	    {A \Rightarrow B \preceq S(A \Rightarrow B)}
	    {}
	  \]
	  So \(C \typeequiv A \Rightarrow B\), and we can take \(E \typeequiv A\), \(F \typeequiv B\).  
	  Since \(A \approx E\), we get \(E \preceq A\), and likewise \(B \approx F\) implies \(B \preceq F\). Hence, the result holds.

	\item \emph{Inductive case: tree of size greater than 0.}
	  \[
	    \infer
	    {A \Rightarrow B \preceq S(C)}
	    {A \Rightarrow B \preceq G \quad G \preceq S(C)}
	  \]
	  Suppose \(G \approx S^{k'}(I)\) for some \(k' > 0\), and assume \(I \not\approx S(H)\).

	  \begin{itemize}
	    \item If \(k' = 0\), then \(G \approx I\) and by Lemma~\ref{more_preceq_properties}.\ref{preceq_relation_2} we have \(G \typeequiv J \Rightarrow K\) with \(J \preceq A\) and \(B \preceq K\).  
	      Since \(J \Rightarrow K \preceq S(C)\), by induction hypothesis we get \(C \approx L \Rightarrow M\) with \(L \preceq J\) and \(K \preceq M\).  
	      Then, by transitivity, \(L \preceq A\) and \(B \preceq M\).  
	      Letting \(E \typeequiv L\) and \(F \typeequiv M\), the result follows.

	    \item If \(k' > 0\), then by subtyping \(S^{k'}(I) \approx S(I)\), hence \(G \approx S(I)\).  
	      Since \(A \Rightarrow B \preceq S(I)\), by induction hypothesis we have \(I \approx J \Rightarrow K\) with \(J \preceq A\) and \(B \preceq K\).  
	      Then \(S(J \Rightarrow K) \preceq S(C)\), and by Lemma~\ref{more_preceq_properties}.\ref{preceq_relation_4} we get \(S(C) \typeequiv S^k(L \Rightarrow M)\) with \(L \preceq J\) and \(K \preceq M\).  
	      Since \(C \not\approx S(G)\), it must be that \(k = 1\) and \(C \approx L \Rightarrow M\).  
	      By transitivity, \(L \preceq A\) and \(B \preceq M\), and letting \(E \typeequiv L\), \(F \typeequiv M\), the result follows.
	  \end{itemize}
      \end{itemize}

    \item[{\ref{preceq_relation_9}}.]
      By induction on the derivation of the subtyping relation.
      \begin{itemize}
	\item \emph{Derivation tree of size 0}

	  The only possible rule is:
	  \[
	    \infer
	    {\gB_1 \times \gB_2 \preceq \gB_1 \times \gB_2}
	    {}
	  \]
	  Taking \(\gB_3 \approx \gB_1\) and \(\gB_4 \approx \gB_2\), the result follows by reflection.

	\item \emph{Derivation tree of size greater than 0}

	  \begin{itemize}
	    \item 
	      \[
		\infer
		{\gB_1 \times \gB_2 \preceq A}
		{\gB_1 \times \gB_2 \preceq B & B \preceq A}
	      \]
	      Since \(\gB_1 \times \gB_2 \preceq B\), by the induction hypothesis there exist \(\gB_5\) and \(\gB_6\) such that \(B \approx \gB_5 \times \gB_6\), \(\gB_1 \preceq \gB_5\) and \(\gB_2 \preceq \gB_6\).Since there exist \(\gB_7\) and \(\gB_8\) such that \(A \approx \gB_7 \times \gB_8\), \(\gB_5 \preceq \gB_7\) and \(\gB_6 \preceq \gB_8\) by the induction hypothesis again, then \(\gB_1 \preceq \gB_7\) and \(\gB_2 \preceq \gB_8\) by transitivy.
		  Taking \(\gB_3 \approx \gB_6\) and \(\gB_4 \approx \gB_7\), the result follows.
	    \item 
	      \[
		\infer
		{\gB_1 \times \gB_2 \preceq \gB_3 \times \gB_4}
		{\gB_1 \preceq \gB_3 & \gB_2 \preceq \gB_4}
	      \]
	      The conclusion directly follows by the structure of the rule.
	  \end{itemize}
      \end{itemize}
    \item[{\ref{preceq_relation_10}}.]
      By induction on the derivation of the subtyping relation.
      \begin{itemize}
	\item \emph{Derivation tree of size 0}

	  The only possible rule is:
	  \[
	    \infer
	    {S(\gB_1 \times \gB_2) \preceq S(\gB_1 \times \gB_2)}
	    {}
	  \]
	  Taking \(\gB_3 \approx \gB_1\) and \(\gB_4 \approx \gB_2\). Since \(A \approx \gB_1 \times \gB_2\), we conclude \(\gB_1 \preceq S(\gB_3)\) and \(\gB_2 \preceq S(\gB_4)\).

	\item \emph{Derivation tree of size greater than 0}
	  \begin{itemize}
	    \item 
	      \[
		\infer
		{S(\gB_1 \times \gB_2) \preceq S(A)}
		{S(\gB_1 \times \gB_2) \preceq C & C \preceq S(A)}
	      \]
	      By Lemma~\ref{lem:preceq_properties}.\ref{preceq_relation_7}, we have \(C \typeequiv S(D)\) with \(\gB_1 \times \gB_2 \preceq D\).\\
	      By induction hypothesis, there exist \(\gB_5\) and \(\gB_6\) such that \(D \approx \gB_5 \times \gB_6\), \(S(\gB_1) \preceq S(\gB_5)\) and \(S(\gB_2) \preceq S(\gB_6)\).\\
	      Since \(S(\gB_5 \times \gB_6) \preceq S(A)\), we conclude there exist \(\gB_7\) and \(\gB_8\) such that \(A \approx \gB_7 \times \gB_8\), \(S(\gB_5) \preceq S(\gB_7)\) and \(S(\gB_6) \preceq S(\gB_8)\) by induction again.\\
		  Taking \(\gB_3 \approx \gB_7\) and \(\gB_4 \approx \gB_8\), we have \(S(\gB_1) \preceq S(\gB_3)\) and \(S(\gB_2) \preceq S(\gB_4)\) by transivity, and then the result follows.
	    \item 
	      \[
		\infer
		{S(\gB_1 \times \gB_2) \preceq S(A)}
		{\gB_1 \times \gB_2 \preceq A}
	      \]
	      By Lemma~\ref{more_preceq_properties}.\ref{preceq_relation_9}, we get \(A \approx \gB_5 \times \gB_6\), \(\gB_1 \preceq \gB_5\) and \(\gB_2 \preceq \gB_6\). Then \(S(\gB_1) \preceq S(\gB_5)\) and \(S(\gB_2) \preceq S(\gB_6)\).\\
	      Taking \(\gB_3 \approx \gB_5\) and \(\gB_4 \approx \gB_6\), the result follows.
	      \qed
	  \end{itemize}
      \end{itemize}
  \end{enumerate}
\end{proof}


\preceqproperties*

\begin{proof}~
  \begin{enumerate}
    \item[{\ref{preceq_relation_3}.}]
      Immediate from Lemma~\ref{more_preceq_properties}.\ref{preceq_relation_2}.

    \item[{\ref{preceq_relation_6}.}]
      Immediate from Lemma~\ref{more_preceq_properties}.\ref{preceq_relation_5}.

    \item[{\ref{preceq_relation_7}.}]
      By induction on the derivation of the subtyping relation.
      \begin{itemize}
	\item \emph{Derivation tree of size 0}

	  The only possible rules are:
	  \begin{itemize}
	    \item 
	      \[
		\infer
		{S(A) \preceq S(A)}
		{}
	      \]
	      In this case, \(C \typeequiv A\). Hence, \(A = C\) and trivially \(A \preceq C\).

	    \item 
	      \[
		\infer
		{S(A) \preceq S(S(A))}
		{}
	      \]
	      Here, \(C \typeequiv S(A)\). Then \(S(A) = C\) and thus \(S(A) \preceq C\).
	      Since \(A \preceq S(A)\), by transitivity we get \(A \preceq C\), as required.
	  \end{itemize}

	\item \emph{Derivation tree of size greater than 0}

	  \begin{itemize}
	    \item 
	      \[
		\infer
		{S(A) \preceq B}
		{S(A) \preceq D & D \preceq B}
	      \]
	      By induction hypothesis on \(S(A) \preceq D\), we have \(D \typeequiv S(E)\) and \(A \preceq E\).\\
	      Then \(D = S(E)\), so \(S(E) \preceq B\). By induction hypothesis again, \(B \typeequiv S(F)\) and \(E \preceq F\).\\
	      By transitivity, \(A \preceq F\). Taking \(C \typeequiv F\), the result follows.

	    \item 
	      \[
		\infer
		{S(A) \preceq S(C)}
		{A \preceq C}
	      \]
	      Trivial.
	  \end{itemize}
      \end{itemize}



    \item[{\ref{preceq_relation_11}.}]
      By induction on the derivation of the subtyping relation.
      \begin{itemize}
	\item \emph{Derivation tree of size 0} \\
	  The only possible rules are:
	  \begin{itemize}
	    \item 
	      \[
		\infer
		{\prod_{i = 0}^{k} \Ba_i \times \prod_{i = k + 1}^{n} \Ba_i \preceq S(\prod_{i = 0}^{k} \Ba_i^\prime \times \prod_{i = k + 1}^{n} \Ba_i^\prime)}
		{}
	      \]
	      With \(\gB_1 \approx \prod_{i = 0}^{n} \Ba_i\) and \(\gB_3 \times \gB_4 \approx \prod_{i = 0}^{n} \Ba_i^\prime\), the result follows.

	    \item 
	      \[
		\infer
		{\gB_1 \times \gB_2 \preceq \gB_1 \times \gB_2}
		{}
	      \]
	      Taking \(\gB_3 \approx \gB_1\) and \(\gB_4 \approx \gB_2\), the result follows.

	    \item 
	      \[
		\infer
		{\gB_1 \times \gB_2 \preceq S(\gB_1 \times \gB_2)}
		{}
	      \]
	      Again, taking \(\gB_3 \approx \gB_1\) and \(\gB_4 \approx \gB_2\), the result follows.
	  \end{itemize}

	\item \emph{Derivation tree of size greater than 0}
	  \begin{itemize}
	    \item 
	      \[
		\infer
		{\gB_1 \times \gB_2 \preceq A}
		{\gB_1 \times \gB_2 \preceq B & B \preceq A}
	      \]
	      By induction hypothesis on \(\gB_1 \times \gB_2 \preceq B\), we consider two cases:
	      \begin{itemize}
		\item If \(B \approx \gB_5 \times \gB_6\), then by the induction hypothesis again on \(B \preceq A\), we obtain either \(A \approx \gB_7 \times \gB_8\) or \(A \approx S(\gB_7 \times \gB_8)\).
		\item If \(B \approx S(\gB_5 \times \gB_6)\), then by Lemma~\ref{lem:preceq_properties}.\ref{preceq_relation_7}, \(A \typeequiv S(C)\), and by Lemma~\ref{more_preceq_properties}.\ref{preceq_relation_10}, \(C \approx \gB_7 \times \gB_8\).
	      \end{itemize}
	      Taking \(\gB_3 \approx \gB_7\) and \(\gB_4 \approx \gB_8\), the result follows.

	    \item 
	      \[
		\infer
		{\gB_1 \times \gB_2 \preceq \gB_5 \times \gB_6}
		{\gB_1 \preceq \gB_5 & \gB_2 \preceq \gB_6}
	      \]
	      Taking \(\gB_3 \approx \gB_5\) and \(\gB_4 \approx \gB_6\), the result follows.
	  \end{itemize}
      \end{itemize}


    \item[{\ref{preceq_relation_12}.}]
      By induction on the derivation of the subtyping relation. We write $\timessize{A}$ for the number of product constructors in $A$.
      \begin{itemize}
	\item \emph{Base case:}
	  \begin{itemize}
	    \item \[
		\infer{\prod_{i = 0}^{n} \Ba_i \preceq S(\prod_{i = 0}^{n} \Ba_i^\prime)}{}
	      \]
	      We have $\timessize{\prod_{i = 0}^{n} \Ba_i} = n - 1$ and $\timessize{S(\prod_{i = 0}^{n} \Ba_i^\prime)} = n - 1$, so the property holds.

	    \item \[
		\infer{A \preceq A}{}
	      \]
	      Trivial.

	    \item \[
		\infer{A \preceq S(A)}{}
	      \]
	      By definition, $\timessize{S(A)} = \timessize{A}$, so the property holds.

	    \item \[
		\infer{S(S(A)) \preceq S(A)}{}
	      \]
	      Again, by definition, $\timessize{S(S(A))} = \timessize{S(A)}$, so the property holds.
	  \end{itemize}

	\item \emph{Inductive case:}
	  \begin{itemize}
	    \item \[
		\infer{A \preceq C}{A \preceq B & B \preceq C}
	      \]
	      By induction hypothesis, $\timessize{A} = \timessize{B}$ and $\timessize{B} = \timessize{C}$. Hence, by transitivity, $\timessize{A} = \timessize{C}$.

	    \item \[
		\infer{S(A) \preceq S(B)}{A \preceq B}
	      \]
	      By induction hypothesis, $\timessize{A} = \timessize{B}$, and by definition of $\timessize{\cdot}$, we have $\timessize{S(A)} = \timessize{A}$ and $\timessize{S(B)} = \timessize{B}$, so $\timessize{S(A)} = \timessize{S(B)}$.

	    \item \[
		\infer{\gB_2 \Rightarrow A \preceq \gB_1 \Rightarrow B}{A \preceq B & \gB_1 \preceq \gB_2}
	      \]
	      By induction hypothesis, $\timessize{A} = \timessize{B}$ and $\timessize{\gB_1} = \timessize{\gB_2}$. Then:
	      \[
		\timessize{\gB_2 \Rightarrow A} = \timessize{\gB_2} + \timessize{A} = \timessize{\gB_1} + \timessize{B} = \timessize{\gB_1 \Rightarrow B}
	      \]
	      Hence, the property holds.

	    \item \[
		\infer{\gB_1 \times \gB_3 \preceq \gB_2 \times \gB_4}{\gB_1 \preceq \gB_2 & \gB_3 \preceq \gB_4}
	      \]
	      By induction hypothesis, $\timessize{\gB_1} = \timessize{\gB_2}$ and $\timessize{\gB_3} = \timessize{\gB_4}$. Therefore:
	      \[
		\timessize{\gB_1 \times \gB_3} = 1 + \timessize{\gB_1} + \timessize{\gB_3} = 1 + \timessize{\gB_2} + \timessize{\gB_4} = \timessize{\gB_2 \times \gB_4}
	      \]
	      So the property holds.
	  \end{itemize}
      \end{itemize}
    \item[{\ref{preceq_relation_13}}.]
      By induction on the derivation tree of the subtyping judgment.
      \begin{itemize}
	\item \emph{Base case: derivation of size 0.}

	  The only possible rule is:
	  \[
	    \infer
	    {\gB_1 \Rightarrow C \preceq \gB_1 \Rightarrow C}
	    {}
	  \]
	  With \(\gB_2 = \gB_1\) and \(D = C\) the property hold.

	\item \emph{Inductive case: derivation of size greater than 0.}
	  \begin{itemize}
	    \item
	      \[
		\infer
		{A \preceq \gB_1 \Rightarrow C}
		{A \preceq E & E \preceq \gB_1 \Rightarrow D}
