\subsection{Properties on the subtyping relation on products}\label{app:preceq_product_properties}
In order to prove Lemma~\ref{preceqproductproperties}, we define the notion of \emph{similar types}, and prove some of its properties.

\begin{definition}[Similar types]
  \label{def:similarTypes}
  Let \(A\) be a type. We define the sequence \(\Ba_1, \Ba_2, \ldots, \Ba_n\) as the atomic types occurring from left to right in \(A\), traversing its structure recursively.

  Two types \(A\) and \(B\) are said to be \emph{similar}, written \(A \sim B\), if it is possible to replace the sequence \(\Ba_1, \Ba_2, \ldots, \Ba_n\) in \(A\) by a new sequence \(\Ba_1', \Ba_2', \ldots, \Ba_n'\) such that \(A \approx B\). 
\end{definition}

\begin{example}[Similar types]
  The following are examples of similar and non-similar types:
  \begin{align*}
    S(\B \times \B) \times \X &\sim S(\X \times \B) \times \B \\
    S(\B \Rightarrow S(\X)) &\sim S(\B \Rightarrow S(\B)) \\
    S(\Ba_1) \times \gB_1 &\sim S(\Ba_2) \times \gB_2\qquad \text{iff }\gB_1 \sim \gB_2 \\
    S(\gB_1) & \sim \gB_2\qquad  \text{iff }\gB_2 \approx S(\gB_3)\text{ and }\gB_1 \sim \gB_3\\
    S(\B \times \B) \times \gB & \not\sim S(\X \times \B)\\
    S(\X) & \not\sim \B
  \end{align*}
\end{example}

We need some properties of the similarity relation, which are stated in Lemma~\ref{sim_relation}, for which, we need the following technical lemma first.
\begin{lemma}[More properties of the similarity relation]\label{moresimrelation}
  The similarity relation $\sim$ also satisfies the following properties:
  \begin{enumerate}
    \item \label{sim_relation_1} For any $\Ba_1, \Ba_2 \in \{\B, \X\}$, we have $\Ba_1 \sim \Ba_2$.
    \item \label{sim_relation_4} If $A \sim B$, then $B \sim A$.
    \item \label{sim_relation_6} If $A \sim B$ and $C \sim D$, then $A \Rightarrow C \sim B \Rightarrow D$.
  \end{enumerate}
\end{lemma}
\begin{proof}
  We prove each of the items separately:
  \begin{enumerate}
    \item[{\ref{sim_relation_1}.}]
      Let $\Ba_1, \Ba_2 \in \{\B, \X\}$. The type $\Ba_1$ has a single atomic component, and replacing it with $\Ba_2$ yields $\Ba_2$, which is definitionally equivalent. Hence, $\Ba_1 \sim \Ba_2$.
    \item[{\ref{sim_relation_4}.}]
      Suppose $A \sim B$. Then there exists a sequence $\Ba_1, \ldots, \Ba_n$ of atomic types in $A$ that can be replaced by $\Ba_1', \ldots, \Ba_n'$ to obtain $B$. Reversing this replacement yields $A$ from $B$, so $B \sim A$.
    \item[{\ref{sim_relation_6}.}]
      Suppose $A \sim B$ and $C \sim D$. Then the atomic types in $A \Rightarrow C$ can be replaced by those in $B \Rightarrow D$ to obtain a type equivalent to $B \Rightarrow D$. Hence, $A \Rightarrow C \sim B \Rightarrow D$.
      \qed
  \end{enumerate}
\end{proof}

\begin{restatable}[Properties of the similarity relation]{lemma}{simrelation}
  \label{sim_relation}
  The similarity relation $\sim$ satisfies the following properties:
  \begin{enumerate}
    \item \label{sim_relation_3} If $A \sim B$ and $B \sim C$, then $A \sim C$.
    \item \label{sim_relation_5} If $A \sim B$ and $C \sim D$, then $A \times C \sim B \times D$.
    \item \label{preceqrelation12}\label{sim_relation_7} Let $\gB_1$ and $\gB_2$ not be superpositions, then $S(\gB_1) \approx S(\gB_2)$ if and only if $\gB_1 \sim \gB_2$.
  \end{enumerate}
\end{restatable}
\begin{proof}
  We prove each of the items separately:
  \begin{enumerate}
    \item[{\ref{sim_relation_3}.}]
      Suppose $A \sim B$ and $B \sim C$. Let $\Ba_1', \ldots, \Ba_n'$ be the sequence replacing the atomic types $\Ba_1, \ldots, \Ba_n$ in $A$ to obtain $B$, and let $\Ba_1'', \ldots, \Ba_n''$ be the sequence replacing $\Ba_1', \ldots, \Ba_n'$ in $B$ to obtain $C$. Replacing $\Ba_1, \ldots, \Ba_n$ in $A$ directly by $\Ba_1'', \ldots, \Ba_n''$ gives $C$, so $A \sim C$.
    \item[{\ref{sim_relation_5}.}]
      Suppose $A \sim B$ and $C \sim D$. Then the atomic types in $A \times C$ can be replaced by those in $B \times D$ to obtain a type equivalent to $B \times D$. Hence, $A \times C \sim B \times D$.
    \item[{\ref{preceqrelation12}.}]
	  \begin{description}
	    \item[$\Longrightarrow$:]
	      By induction on $\gB_1$:
	   \begin{itemize}
	     \item With $\gB_1 \approx \Ba$, if $S(\Ba) \approx S(\gB_2)$ does not hold when $\gB_2$ is a product. However, it does hold when $\gB_2$ is $\Ba'$. Therefore, we conclude that $\Ba \sim \Ba'$.
	     \item With $\gB_1 \approx \gB_3 \times \gB_4$, if $S(\gB_3 \times \gB_4) \approx S(\gB_2)$.
	       We apply Lemma~\ref{more_preceq_properties}.\ref{preceq_relation_10} twice to obtain $\gB_5$ and $\gB_6$ such that $\gB_2 \approx \gB_5 \times \gB_6$, $S(\gB_3) \approx S(\gB_5)$ and $S(\gB_4) \approx S(\gB_6)$. Since superposition is idempotent, we can considere $\gB_3'$, $\gB_4'$, $\gB_5'$ and $\gB_6'$ are not superpositions such that $S(\gB_3) \approx S(\gB_3')$, $S(\gB_4) \approx S(\gB_4')$, $S(\gB_5) \approx S(\gB_5')$ and $S(\gB_6) \approx S(\gB_6')$. Then $S(\gB_3') \approx S(\gB_5')$ imples $\gB_3' \sim \gB_5'$ by induction hypothesis. We have $S(\gB_4') \approx S(\gB_6')$ imples $\gB_4' \sim \gB_6'$ by induction again. We can see that, regardless of whether $\gB_3$ is a superposition or not, we have $\gB_3^\prime \sim \gB_3$ by definition. We can proceed in the same way for $\gB_4$, $\gB_5$, and $\gB_6$. Since $\gB_3 \sim \gB_5$ and $\gB_4 \sim \gB_6$ by transitivity, we have $\gB_3 \times \gB_4 \sim \gB_5 \times \gB_6$ by Lemma~\ref{sim_relation}.\ref{sim_relation_5}.
	       Therefore, we conclude that $\gB_1 \sim \gB_2$.
	   \end{itemize}

    \item[$\Longleftarrow$:]
      By inducion on $\gB_1$.
      \begin{itemize}
	\item If $\gB_1=\Ba$, then $\gB_2=\Ba'$ thus $S(\gB_1) \approx S(\gB_2)$.
	\item If $\gB_1=\gB_{11}\times\gB_{12}$, then $\gB_2=\gB_{21}\times \gB_{22}$ with $\gB_{11}\sim\gB_{21}$ and $\gB_{12}\sim\gB_{22}$.
	  By the induction hypothesis, $S(\gB_{11}) \approx S(\gB_{21})$ and $S(\gB_{12}) \approx S(\gB_{22})$.
	  Therefore, $S(\gB_1) = S(\gB_{11} \times \gB_{12}) \approx S(\gB_{21} \times \gB_{22}) = S(\gB_2)$.
	  \qed
      \end{itemize}
      \end{description}
   \end{enumerate}
\end{proof}

In particular, property~\ref{sim_relation_7} tells us that similar
types span the same vector space. For example, since $\B \sim \X$, we have
$S(\B) \approx S(\X)$. More generally, if $\gB_1$ and $\gB_2$ are similar qubit
types, then $S(\gB_1) \approx S(\gB_2)$, meaning that they represent the same
subspace. 

We distinguish between the relations $\sim$, $\approx$, and $\typeequiv$ in our
type system. For instance, we have $\B \sim \X$ and $\B \not\approx \X$, but
$S(\B) \approx S(\X)$ holds.

To formalise the idea that repeated applications of the superposition operator
do not introduce new subspaces, we define a function $\fMinS$ that collapses
nested occurrences of $S$ into a single application.

\begin{definition}
  The function $\fMinS$ is defined recursively as follows:
  \begin{align*}
    \fMinS(\M) & \approx \M \\
    \fMinS(\gB \Rightarrow A) & \approx \fMinS(\gB) \Rightarrow \fMinS(A) \\
    \fMinS(\gB_1 \times \gB_2) & \approx \fMinS(\gB_1) \times \fMinS(\gB_2) \\
    \textnormal{If } A \approx S(B), \quad \fMinS(S(A)) & \approx \fMinS(A) \\
    \textnormal{If } A \not\approx S(B), \quad \fMinS(S(A)) & \approx S(\fMinS(A))
  \end{align*}
\end{definition}

This definition is closely related to the equivalence class induced by $\sim$. 
To make this connection precise, we state the following property.

\begin{restatable}[Property of $\fMinS$]{lemma}{minSproperties}
  \label{equals_to_min} For all types $A$, we have $A \approx \fMinS(A)$.
\end{restatable}
\begin{proof}
  The function $\fMinS$ rewrites a type by collapsing nested occurrences of the
  $S$ constructor. In the critical case, if $A \approx S(B)$, then by
  definition $\fMinS(S(A)) \approx \fMinS(A)$. Since $S(S(B)) \approx S(B)$,
  the rewriting is consistent with type equivalence. All other cases are direct
  by structural induction. Therefore, $A \approx \fMinS(A)$ holds in all cases.
  \qed
\end{proof}


We begin by introducing a notion of distance between types that captures the
number of non-transitive subtyping steps required to relate them. This notion
will be instrumental in proving several technical lemmas involving nested
superpositions and product types.

Let \(\eqclass{\gB}\) denote the equivalence class of \(\gB\) under the
equivalence relation \(\sim\).  We also write \(\preceq_{NT}\) to refer to the
non-transitive fragment of the subtyping relation~\(\preceq\), that is, the
relation obtained by omitting the transitivity rule.

We now define a measure of subtyping distance between equivalence classes of
qubit types under \(\sim\).

\begin{definition}
  Let \(\precsim\) be the relation over \(\types / \sim\) defined as:
  \[
    \eqclass{\gB_1} \precsim \eqclass{\gB_2} \quad\text{if and only if}\quad \forall \gB_1' \in \eqclass{\gB_1},\; \forall \gB_2' \in \eqclass{\gB_2},\; S(\gB_1') \preceq S(\gB_2').
  \]
  Similarly, we define the non-transitive subtyping relation \(\precsim_{NT}\) as:
  \[
    \eqclass{\gB_1} \precsim_{NT} \eqclass{\gB_2} \quad\text{if and only if}\quad \forall \gB_1' \in \eqclass{\gB_1},\; \forall \gB_2' \in \eqclass{\gB_2},\; S(\gB_1') \preceq_{NT} S(\gB_2').
  \]
\end{definition}

\begin{lemma}
  \label{precsim_lemma}
  If \(\gB_1 \preceq \gB_2\), then \(\eqclass{\gB_1} \precsim \eqclass{\gB_2}\).
\end{lemma}
\begin{proof}
  We can see an equivalence on the definition of $\eqclass{\gB}$ and the set of all $\gB^\prime$ such that \(S(\gB) \approx S(\gB^\prime)\) by Lemmas~\ref{sim_relation}.\ref{preceqrelation12}. 
  Then, for all \(\gB_1' \in \eqclass{\gB_1}\) and \(\gB_2' \in \eqclass{\gB_2}\) we have \(S(\gB_1) \approx S(\gB_1')\) and \(S(\gB_2) \approx S(\gB_2')\). Therefore we have $S(\gB_1') \preceq S(\gB_2')$ by transitivity and the property hold.
  \qed
\end{proof}

\begin{definition}[Subtyping distance]
  Let \(\eqclass{\gB_1} \precsim \eqclass{\gB_2}\). The subtyping distance between \(\eqclass{\gB_1}\) and \(\eqclass{\gB_2}\), denoted \(\simplesize{ \eqclass{\gB_1}, \eqclass{\gB_2} }\), is defined recursively as follows:
  \[
    \simplesize{ \eqclass{\gB_1}, \eqclass{\gB_2} } = 
    \begin{cases}
      0 & \text{if } \eqclass{\gB_1} = \eqclass{\gB_2}, \\
      1 + \min\left\{ \simplesize{ \eqclass{\gB'}, \eqclass{\gB_2} } \;\middle|\; \eqclass{\gB_1} \precsim_{NT} \eqclass{\gB'} \precsim \eqclass{\gB_2} \right\} & \text{otherwise.}
    \end{cases}
  \]
\end{definition}

\begin{example}
  \begin{align*}
    &\simplesize{ \eqclass{\B \times \X},\; \eqclass{\X \times \X} }  = 0\\
    &\simplesize{ \eqclass{S(\B) \times S(\X)},\; \eqclass{S(S(\X) \times S(\X))} }  = 1\\
    &\simplesize{ \eqclass{\B \times \X \times S(\B \times \B)},\; \eqclass{S(S(\B) \times \X \times S(\B \times \B))} }  = 2
  \end{align*}
\end{example}

Before proving the lemma, we need the following technical results.
\begin{lemma}
  ~
  \label{preceqproductpropertiesaux}
  \begin{enumerate}
    \item \label{aux_lemma_rneutrallup_01}
      Let \(\Phi \not\approx S(\Phi')\). If \(\Phi \preceq S(\gB_1 \times S(\gB_2))\), then
      \(
	\Phi \preceq \gB_1' \times S(\gB_2')
      \)
      for some \(\gB_1' \sim \fMinS(\gB_1)\) and \(\gB_2' \sim \fMinS(\gB_2)\). 

    \item \label{aux_lemma_rneutrallup_02}
      If \(\varphi \times \M \preceq \gB_1 \times S(\gB_2)\), with \(m \geq 1\),
      \(\gB_1 \typeequiv \fMinS(\gB_1)\) and \(S(\gB_2) \typeequiv \fMinS(S(\gB_2))\), then
      \(
	\varphi \times \M \preceq \gB_1' \times \gB_2'
      \)
      for some \(\gB_1' \sim \gB_1\) and \(\gB_2' \sim \gB_2\).

    \item \label{aux_lemma_rneutralrup_01}
      Let \(\Phi \not\approx S(\Phi')\). If \(\Phi \preceq S(S(\gB_1) \times \gB_2)\), then
      \(
	\Phi \preceq S(\gB_1') \times \gB_2'
      \)
      for some \(\gB_1' \sim \fMinS(\gB_1)\) and \(\gB_2' \sim \fMinS(\gB_2)\).

    \item \label{aux_lemma_rneutralrup_02}
      If \(\M \times \varphi \preceq S(\gB_1) \times \gB_2\), with \(m \geq 1\),
      \(S(\gB_1) \typeequiv \fMinS(S(\gB_1))\) and \(\gB_2 \typeequiv \fMinS(\gB_2)\), then
      \(
	\M \times \varphi \preceq \gB_1' \times \gB_2'
      \)
      for some \(\gB_1' \sim \gB_1\) and \(\gB_2' \sim \gB_2\).
  \end{enumerate}
\end{lemma}
\begin{proof}
    \item[{\ref{aux_lemma_rneutrallup_01}}.]
      By Lemma~\ref{equals_to_min}, we have $\Phi \approx \fMinS(\Phi)$.\\
      Also, $S(\gB_1 \times S(\gB_2)) \approx \fMinS(S(\gB_1 \times S(\gB_2)))$.\\
      Since $\fMinS(S(\gB_1 \times S(\gB_2)))$ is a superposition and $\fMinS(\Phi)$ is not, we get by Lemma~\ref{precsim_lemma} that
      \[
        \delta( \eqclass{\fMinS(\Phi)}, \eqclass{\fMinS(S(\gB_1 \times S(\gB_2)))} ) \geq 1.
      \]
      So there exists $A$ such that $A \typeequiv \fMinS(A) \not\approx S(B)$ and
      \[
        \delta( \eqclass{\fMinS(\Phi)}, \eqclass{A} ) \geq 0 \quad\text{and}\quad \delta( \eqclass{A}, \eqclass{\fMinS(S(\gB_1 \times S(\gB_2)))} ) = 1.
      \]
      Then $S(A) \approx \fMinS(S(\gB_1 \times S(\gB_2)))$, and by Lemma~\ref{sim_relation}.\ref{preceqrelation12}, we have
      \[
        A \sim \fMinS(\gB_1 \times S(\gB_2)) \typeequiv \fMinS(\gB_1) \times \fMinS(S(\gB_2)).
      \]
      Thus $A \approx \gB_1' \times S(\gB_2')$ with $\gB_1' \sim \fMinS(\gB_1)$ and $\gB_2' \sim \fMinS(\gB_2)$.

    \item[{\ref{aux_lemma_rneutrallup_02}}.]
      Write $\varphi \approx \prod_{i = 1}^n \varphi_i$ with $n \geq 1$.\\
      Then $\prod_{i = 1}^n \varphi_i \times \M \preceq \gB_1 \times S(\gB_2)$.\\
      By Lemma~\ref{equals_to_min}, we have:
      \[
        \prod_{i = 1}^n \varphi_i \times \M \approx \fMinS\left( \prod_{i = 1}^n \varphi_i \times \M \right).
      \]
      Since the product ends in a non-superposed type and the right-hand side ends in a superposition, we again apply Lemma~\ref{precsim_lemma} and obtain:
      \[
        \delta( \eqclass{\fMinS(\prod_{i = 1}^n \varphi_i \times \M)}, \eqclass{\fMinS(\gB_1 \times S(\gB_2))} ) \geq 1.
      \]
      Hence, there exists $A$ such that $A \typeequiv \fMinS(A) \not\approx S(B)$ and
      \[
        \delta( \eqclass{\fMinS(\prod_{i = 1}^n \varphi_i \times \M)}, \eqclass{A} ) \geq 0, \quad \delta( \eqclass{A}, \eqclass{\fMinS(\gB_1 \times S(\gB_2))} ) = 1.
      \]
      By Lemma~\ref{lem:preceq_properties}.\ref{preceq_relation_12}, we have $A \approx \gB_1' \times \gB_2'$ with $\gB_1' \sim \gB_1$ and $\gB_2' \sim \gB_2$, and one of the following holds:
      \begin{itemize}
        \item $\prod_{i = 1}^k \varphi_i \preceq \gB_1'$ and $\prod_{i = k+1}^n \varphi_i \times \M \preceq \gB_2'$
        \item $\prod_{i = 1}^n \varphi_i \times \prod_{i = 1}^k \Ba_i \preceq \gB_1'$, $\prod_{i = k+1}^{m} \Ba_i \preceq \gB_2'$
      \end{itemize}
      In either case, we conclude $\prod_{i = 1}^n \varphi_i \times \M \preceq \gB_1' \times \gB_2'$.

    \item[{\ref{aux_lemma_rneutralrup_01}}.]
      Similar to case \ref{aux_lemma_rneutrallup_01}, applying the same sequence of lemmas with symmetry:
      \[
        \Phi \preceq S(\gB_1') \times \gB_2' \quad\text{with}\quad \gB_1' \sim \fMinS(\gB_1),\; \gB_2' \sim \fMinS(\gB_2).
      \]

    \item[{\ref{aux_lemma_rneutralrup_02}}.]
      Proceed as in case \ref{aux_lemma_rneutrallup_02}, replacing $\varphi \times \M$ by $\M \times \varphi$ and adjusting order. The same conclusion holds:
      \[
        \M \times \varphi \preceq \gB_1' \times \gB_2'.
	\tag*{\qed}
      \]
\end{proof}

Finally, with all these definitions and properties, we can prove the Lemma~\ref{preceqproductproperties}.

\preceqproductproperties*
\begin{proof}~
  \begin{enumerate}

    \item[{\ref{aux_lemma_rneutrallup}}.]
      By Lemma~\ref{preceqproductpropertiesaux}.\ref{aux_lemma_rneutrallup_01} and \ref{preceqproductpropertiesaux}.\ref{aux_lemma_rneutrallup_02}, and using Lemmas~\ref{sim_relation}.\ref{sim_relation_3}, \ref{sim_relation}.\ref{sim_relation_5}, and \ref{sim_relation}.\ref{sim_relation_7}, we derive:
      \[
        \varphi \times \M \preceq S(\gB_1 \times \gB_2).
      \]

    \item[{\ref{aux_lemma_rneutralrup}}.]
      Follows by combining Lemma~\ref{preceqproductpropertiesaux}.\ref{aux_lemma_rneutralrup_01} and \ref{preceqproductpropertiesaux}.\ref{aux_lemma_rneutralrup_02}, and applying the same reasoning as in \ref{aux_lemma_rneutrallup}.
      \[
        \M \times \varphi \preceq S(\gB_1 \times \gB_2).
	\tag*{\qed}
      \]
  \end{enumerate}
\end{proof}

