\begin{proof}
  We proceed by structural induction on the derivation of \( \Gamma \vdash t : A \):
  \begin{itemize}
    \item Rule \(\tax\): 
      If \( \theta \vDash x^\gB \), then \( \theta(x) \in \den{\gB} \) by definition.

    \item Rule \(\tax_{\vec 0}\): 
      Since \( \theta(\z) = \z \), and \( \z \in \den{S(A)} \) by Lemma~\ref{reducibility_properties}.HAB, the result follows.

    \item Rule \(\tax_{\ket 0}\): 
      Since \( \theta(\ket{0}) = \ket{0} \in \SN \), and \( \ket{0} : \B \preceq S(\B) \), we have \( \ket{0} \in \den{\B} \).

    \item Rules \(\tax_{\ket 1}, \tax_{\ket +}, \tax_{\ket -}\): analogous.

    \item Rule \(\Rightarrow_I\): 
      Let \( \theta' \vDash \Gamma \). We must show \( \lambda x^\gB. \theta'(t) \in \den{\gB \Rightarrow A} \), i.e., it has type \( S(\gB \Rightarrow A) \) and for all \( r \in \den{\gB} \), \( (\lambda x^\gB. \theta'(t))\,r \in \den{A} \). By induction hypothesis, for any \( \theta \vDash \Gamma, x^\gB \), we have \( \theta(t) \in \den{A} \), so \( \lambda x^\gB. \theta'(t) : \gB \Rightarrow A \preceq S(\gB \Rightarrow A) \). Let \( r \in \den{\gB} \), then \( r : S(\gB) \), hence \( (\lambda x^\gB. \theta'(t))\,r : S(A) \). Since the application is neutral, by Lemma~\ref{reducibility_properties}.CR3, it suffices to show all reducts lie in \( \den{A} \). We proceed by secondary induction on the lexicographic pair \( (\steps{\theta'(t)} + \steps{r}, \size{(\lambda x^\gB. \theta'(t))\,r}) \):
      \begin{itemize}
	\item \( (\lambda x^\gB. \theta'(t))\,r \rightarrow \theta'(t)[r/x] = \theta(t) \in \den{A} \) by the induction hypothesis.
	\item If \( r \lrap r' \), then \( (\lambda x^\gB. \theta'(t))\,r \lrap (\lambda x^\gB. \theta'(t))\,r' \in \den{A} \) by the induction hypothesis.
	\item If \( r = r_1 + r_2 \), the reduction yields a sum of two applications, both in \( \den{A} \) by the induction hypothesis, so the sum is in \( \den{A} \) by Lemma~\ref{reducibility_properties}.LIN1.
	\item If \( r = \alpha \cdot r_1 \), the reduction yields \( \alpha \cdot (\lambda x^\gB. \theta'(t))\,r_1 \), which lies in \( \den{A} \) by the induction hypothesis and Lemma~\ref{reducibility_properties}.LIN2.
	\item If \( r = \z \) or \( r = \error \), then the reduct is \( \z \) or \( \error \), which belong to \( \den{A} \) by Lemma~\ref{reducibility_properties}.HAB.
      \end{itemize}

    \item Rule \(\Rightarrow_E\): 
      By induction hypothesis, if \( \theta_1 \vDash \Gamma \) and \( \theta_2 \vDash \Delta \), then \( \theta_1(t) \in \den{\gB \Rightarrow A} \) and \( \theta_2(r) \in \den{\gB} \). Let \( \theta = \theta_1 \cup \theta_2 \), so \( \theta(tr) = \theta_1(t) \theta_2(r) \in \den{A} \) by definition.

    \item Rule \(\Rightarrow_{ES}\): 
      By induction hypothesis, we have \( \theta_1(t) \in \den{S(\gB \Rightarrow A)} \) and \( \theta_2(r) \in \den{S(\gB)} \), with \( \theta = \theta_1 \cup \theta_2 \). Since \( \theta_1(t) \theta_2(r) : S(A) \), it suffices, by Lemma~\ref{reducibility_properties}.CR3, to show that all reducts lie in \( \den{S(A)} \). As both arguments normalise and Lemma~\ref{reducibility_properties}.CR1, we proceed by secondary induction on \( (\steps{\theta_1(t)} + \steps{\theta_2(r)}, \size{\theta_1(t)\theta_2(r)}) \). Consider the possible reducts:

      \begin{itemize}
	\item \( \theta_1(t) \theta_2(r) \lrap t' \theta_2(r) \) where \( \theta_1(t) \lrap t' \): by the induction hypothesis, \( t' \theta_2(r) \in \den{S(A)} \).
	\item \( \theta_1(t) \theta_2(r) \lrap \theta_1(t) r' \) where \( \theta_2(r) \lrap r' \): analogous.
	\item \( \theta_1(t) \theta_2(r) = (\lambda x^{S(\gB)}. t_1)\, \theta_2(r) \rightarrow t_1[r/x] \): by Lemma~\ref{generation}.\ref{generation_7} and subtyping, \( t_1 : A \), hence \( t_1[r/x] \in \den{S(A)} \).
	\item \( (\lambda x^{\M}. t_1)\, \theta_2(r) \rightarrow t_1[r/x] \): analogous.
	\item \( \ite{\ket{1}}{t_1}{t_2} \rightarrow t_1 \): by Lemma~\ref{generation}.\ref{generation_8}, \( t_1 \in \den{S(A)} \).
	\item \( \ite{\ket{0}}{t_1}{t_2} \rightarrow t_2 \), \( \itex{\ket{+}}{t_1}{t_2} \rightarrow t_1 \), \( \itex{\ket{-}}{t_1}{t_2} \rightarrow t_2 \): analogous.
	\item \( \theta_1(t)(r_1 + r_2) \rightarrow \theta_1(t) r_1 + \theta_1(t) r_2 \): both terms in \( \den{S(A)} \) by the induction hypothesis, so the sum is too by Lemma~\ref{reducibility_properties}.LIN1.
	\item \( (t_1 + t_2)\, \theta_2(r) \rightarrow t_1 \theta_2(r) + t_2 \theta_2(r) \): analogous.
	\item \( \theta_1(t)(\alpha . r_1) \rightarrow \alpha . \theta_1(t) r_1 \): \( \theta_1(t) r_1 \in \den{S(A)} \), so the scaled term is too by Lemma~\ref{reducibility_properties}.LIN2.
	\item \( (\alpha . t_1)\, \theta_2(r) \rightarrow \alpha . t_1 \theta_2(r) \): analogous.
	\item \( \theta_1(t)\, \z \rightarrow \z \), \( \z\, \theta_2(r) \rightarrow \z \): \( \z \in \den{S(A)} \) by Lemma~\ref{reducibility_properties}.HAB.
	\item \( \theta_1(t)\, \error \rightarrow \error \), \( \error\, \theta_2(r) \rightarrow \error \): \( \error \in \den{S(A)} \) by Lemma~\ref{reducibility_properties}.HAB.
      \end{itemize}

    \item Rule \(S_I^+\): 
      By induction hypothesis, \( \theta_1(t) \in \den{A} \) and \( \theta_2(r) \in \den{A} \). Then \( \theta_1(t) + \theta_2(r) \in \den{S(A)} \) by Lemma~\ref{reducibility_properties}.LIN1.

    \item Rule \(S_I^\alpha\): 
      By induction hypothesis, \( \theta(t) \in \den{A} \). Then \( \alpha.\theta(t) \in \den{S(A)} \) by Lemma~\ref{reducibility_properties}.LIN2.

    \item Rule \(\times_I\): 
      By induction hypothesis, \( \theta_1(t) \in \den{\gB} \) and \( \theta_2(r) \in \den{\Phi} \), so both normalise (CR1). Thus \( \theta_1(t) \otimes \theta_2(r) \in \SN \), and has type \( \gB \times \Phi \preceq S(\gB \times \Phi) \), hence \( \theta_1(t) \otimes \theta_2(r) \in \den{\gB \times \Phi} \).

    \item Rule \(S_E\): 
      By induction hypothesis, \( \theta(t) \in \den{S(\prod_{i = 1}^{n} \Ba_i)} \), hence \( \theta(t) \in \SN \) and has type \( S(\prod_{i = 1}^{n} \Ba_i) \). Then \( \pim \theta(t) \in \SN \) and \( \pim \theta(t) : \B^m \times S(\prod_{i = m + 1}^{n} \Ba_i) \preceq S(\B^m \times S(\prod_{i = m + 1}^{n} \Ba_i)) \), thus \( \pim \theta(t) \in \den{\B^m \times S(\prod_{i = m + 1}^{n} \Ba_i)} \).

    \item Rule \(S_{E_\X}\): 
      Analogous to the previous case.

    \item Rule \(\tif\): 
      By induction hypothesis, \(\theta \vDash \Gamma\) implies \(\theta(t), \theta(r) \in \den{A}\). We must show that if \(\theta \vDash \Gamma\), then \(\ite{}{\theta(t)}{\theta(r)} \in \den{\B \Rightarrow A}\). By definition, it suffices to prove that \(\ite{}{\theta(t)}{\theta(r)}: S(\B \Rightarrow A)\) and that for all \(s \in \den{\B}\), \(\ite{s}{\theta(t)}{\theta(r)} \in \den{A}\). Since \(s: S(\B)\), we have \(\ite{s}{\theta(t)}{\theta(r)} : S(A)\), and as this is neutral, by Lemma~\ref{reducibility_properties}.CR3, it suffices to prove \(\fRed(\ite{s}{\theta(t)}{\theta(r)}) \subseteq \den{S(A)}\). We proceed by the induction hypothesis (2) on \((\steps{s}, \size{\ite{s}{\theta(t)}{\theta(r)}})\):
      \begin{itemize}
	\item \(\ite{s}{\theta(t)}{\theta(r)} \lrap \ite{s_1}{\theta(t)}{\theta(r)}\) with \(s \lrap s_1\): by the induction hypothesis, \(\ite{s_1}{\theta(t)}{\theta(r)} \in \den{A}\).
	\item If \(s = \ket{1}\), then \(\ite{s}{\theta(t)}{\theta(r)} \lra[1] \theta(t)\): by the induction hypothesis, \(\theta(t) \in \den{A}\).
	\item If \(s = \ket{0}\), then \(\ite{s}{\theta(t)}{\theta(r)} \lra[1] \theta(r)\): by the induction hypothesis, \(\theta(r) \in \den{A}\).
	\item If \(s = s_1 + s_2\), then \(\ite{s}{\theta(t)}{\theta(r)} \lra[1] \ite{s_1}{\theta(t)}{\theta(r)} + \ite{s_2}{\theta(t)}{\theta(r)}\): by the induction hypothesis, both terms are in \(\den{A}\); hence by Lemma~\ref{reducibility_properties}.LIN1, their sum is as well.
	\item If \(s = \alpha.s_1\), then \(\ite{s}{\theta(t)}{\theta(r)} \lra[1] \alpha.\ite{s_1}{\theta(t)}{\theta(r)}\): by the induction hypothesis, \(\ite{s_1}{\theta(t)}{\theta(r)} \in \den{A}\), and then by Lemma~\ref{reducibility_properties}.LIN2, the result is in \(\den{A}\).
	\item If \(s = \z\), then \(\ite{s}{\theta(t)}{\theta(r)} \lra[1] \z\): by Lemma~\ref{reducibility_properties}.HAB, \(\z \in \den{A}\).
	\item If \(s = \error\), then \(\ite{s}{\theta(t)}{\theta(r)} \lra[1] \error\): same as above.
      \end{itemize}

    \item Rule \(\tif_{\X}\): 
      Analogous to the previous case.

    \item Rule \(\Castl\):
      By induction hypothesis, \(\theta \vDash \Gamma\) implies \(\theta(t) \in \den{S(\gB \times S(\Phi))}\). We want to show that \(\Castl \theta(t) \in \den{S(\gB \times \Phi)}\). We proceed by cases:
      \begin{itemize}
	\item \(\theta(t) = \sum_{i = 1}^n \brackets{\alpha_i .} r_i \in \den{S(\gB \times S(\Phi))}\). We want \(\Castl \sum_{i = 1}^n \brackets{\alpha_i .} r_i \in \den{S(\gB \times \Phi)}\). It suffices to show \(\fRed(\Castl \sum_{i = 1}^n \brackets{\alpha_i .} r_i) \subseteq \den{S(\gB \times \Phi)}\). We proceed by the induction hypothesis (2) on \((\steps{\sum_i \brackets{\alpha_i .} r_i}, \size{\sum_i \brackets{\alpha_i .} r_i})\). We analyse each reduct:
	  \begin{itemize}
	    \item \(\Castl \sum_i \brackets{\alpha_i .} r_i \lrap \Castl s\), where \(\sum_i \brackets{\alpha_i .} r_i \lrap s\): by the induction hypothesis, \(\Castl s \in \den{S(\gB \times \Phi)}\).
	    \item \(\Castl \error \lra[1] \error\): by Lemma~\ref{reducibility_properties}.HAB.
	    \item \(\Castl(r_1 \otimes (r_2 + r_3)) \lra[1] \Castl(r_1 \otimes r_2) + \Castl(r_1 \otimes r_3)\): both summands are in \(\den{S(\gB \times \Phi)}\) by the induction hypothesis, so their sum is by Lemma~\ref{reducibility_properties}.LIN1.
	    \item \(\Castl(r_1 \otimes (\alpha . r_2)) \lra[1] \alpha . (\Castl(r_1 \otimes r_2))\): by the induction hypothesis and Lemma~\ref{reducibility_properties}.LIN2.
	    \item \(\Castl(r_1 \otimes \z) \lra[1] \z\), when \(r_1\) has type \(\gB\): by Lemma~\ref{reducibility_properties}.HAB.
	    \item \(\Castl(r_1 + r_2) \lra[1] \Castl r_1 + \Castl r_2\): since \(\theta(t) = r_1 + r_2 \in \den{S(\gB \times S(\Phi))}\), we get \(r_1, r_2 \in \den{S(\gB \times S(\Phi))}\) by Lemma~\ref{Span_sub_term_SN}, so \(\Castl r_1, \Castl r_2 \in \den{S(\gB \times \Phi)}\) by the induction hypothesis, and the sum is by Lemma~\ref{reducibility_properties}.LIN1.
	    \item \(\Castl(\alpha . r_1) \lra[1] \alpha . \Castl r_1\): same as above, using Lemma~\ref{reducibility_properties}.LIN2.
	    \item \(\Castl \z \lra[1] \z\): by Lemma~\ref{reducibility_properties}.HAB.
	    \item \(\Castl(u \otimes v) \lra[1] u \otimes v\), with \(u \in \basis\): since \(u \otimes v \in \den{S(\gB \times S(\Phi))}\), it reduces to \(u \otimes v'\) with \(v' \in \den{S(\Phi)}\) and \(u \otimes v' \in \den{\gB \times S(\Phi)}\). By Lemma~\ref{reducibility_properties}.CR1, \(u \otimes v' \in \SN\). By subject reduction, \(u \otimes v' : S(\gB \times \Phi)\), hence \(u \otimes v \in \den{S(\gB \times \Phi)}\).
	  \end{itemize}

	\item \(\fRed(\theta(t)) \subseteq \den{S(\gB \times S(\Phi))}\). We want \(\fRed(\Castl \theta(t)) \subseteq \den{S(\gB \times \Phi)}\). We proceed by the induction hypothesis (2) on \((\steps{\theta(t)}, \size{\theta(t)})\). The cases are analogous to the previous ones.
      \end{itemize}

    \item Rule \(\Castr\): Analogous to the previous case.

    \item Rule \(\Cast_{\B}\): 
      By Lemma~\ref{substitution}, \(\theta(\Cast t) = \Cast \theta(t): \B\). By induction hypothesis, \(\theta(t) \in \den{\B}\), and by Lemma~\ref{reducibility_properties}.HAB, \(\theta(t) \in \SN\). Then, by Lemma~\ref{Cast_SN}, \(\Cast \theta(t) \in \SN\), and since \(\Cast \theta(t): \B \preceq S(\B)\), we get \(\Cast \theta(t) \in \den{\B}\).

    \item Rule \(\Cast_{\X}\): 
      By Lemma~\ref{substitution}, \(\theta(\Cast t) = \Cast \theta(t): S(\B)\). By induction hypothesis, \(\theta(t) \in \den{\X}\), and by Lemma~\ref{reducibility_properties}.HAB, \(\theta(t) \in \SN\). Then, by Lemma~\ref{Cast_SN}, \(\Cast \theta(t) \in \SN\), and since \(\Cast \theta(t): S(\B) \preceq S(\X)\), we get \(\Cast \theta(t) \in \den{\X}\), and finally by Lemma~\ref{compatibility}, \(\Cast \theta(t) \in \den{S(\B)}\).

    \item Rule \(\times_{Er_\M}\): 
      By Lemma~\ref{substitution}, \(\theta(\head t) = \head \theta(t): \Ba\). By induction hypothesis, \(\theta(t) \in \den{\Ba \times \M}\), and by Lemma~\ref{reducibility_properties}.HAB, \(\theta(t) \in \SN\), so \(\head \theta(t) \in \SN\). Since \(\head \theta(t): \Ba \preceq S(\Ba)\), we have \(\head \theta(t) \in \den{\Ba}\).

    \item Rule \(\times_{El_\M}\): 
      By Lemma~\ref{substitution}, \(\theta(\tail t) = \tail \theta(t): \M\). By induction hypothesis, \(\theta(t) \in \den{\Ba \times \M}\), and by Lemma~\ref{reducibility_properties}.HAB, \(\theta(t) \in \SN\), so \(\tail \theta(t) \in \SN\). Since \(\tail \theta(t): \M \preceq S(\M)\), we have \(\tail \theta(t) \in \den{\M}\).

    \item Rule \(\textrm{err}\): 
      By definition, \(\theta(\error) = \error\), and by Lemma~\ref{reducibility_properties}.HAB, \(\error \in \den{A}\).

    \item Rule \(\preceq\): 
      By induction hypothesis, \(\theta(t) \in \den{A}\), and by Lemma~\ref{compatibility}, \(\den{A} \subseteq \den{B}\). Hence, \(\theta(t) \in \den{B}\).

    \item Rule \(W\): 
      By induction hypothesis, if \(\theta \vDash \Gamma\), then \(\theta(t) \in \den{A}\). If \(\theta \vDash \Gamma, x^{\M}\), then by definition \(\theta \vDash \Gamma\), so again \(\theta(t) \in \den{A}\).

    \item Rule \(C\): 
      By induction hypothesis, if \(\theta \vDash \Gamma, x^{\M}, y^{\M}\), then \(\theta(t) \in \den{A}\). Let \(\theta' \vDash \Gamma, x^{\M}\); then \(\theta'(t[y/x]) = \theta(t)\), so \(\theta'(t[y/x]) \in \den{A}\).
      \qed
  \end{itemize}
\end{proof}

