		\end{figure}
		\medskip
		Let $H$ be the graph of order $n'$ obtained from $G$ by deleting the vertices $v_4$ and $v_5$. Since $n \ge 6$, we have $n' = n - 2 \ge 4$. We note that $H$ is also a mop. Then by the induction hypothesis, let $[D'_1,D'_2]$ be an LD-partition of $H$. Since $\deg_{H}(v_3)=2$, each $D'_i$ contains at least one vertex from the set $\{v_1,v_2,v_3\}$ for $i\in\{1,2\}$. In the following, we consider three cases and in each case, we prove that $G$ admits an LD-partition.

    \medskip	
		\noindent\textbf{Case 1:} $v_1,v_2\in D'_1$ and $v_3\in D'_2$.

        \medskip 
		Let $D_1=D'_1\cup\{v_3\}$ and $D_2=(D'_2\setminus\{v_3\})\cup\{v_4,v_5\}$. Now we show that each $D_i$ is an LD-set of $G$ for $i\in\{1,2\}$. Since $N_G(v_4)\cap D_1=\{v_1,v_3\}$ and $N_G(v_5)\cap D_1=\{v_2,v_3\}$, $D_1$ is an LD-set of $G$. Note that $N_G(v_1)\cap\{v_4,v_5\}=\{v_4\}$, $N_G(v_2)\cap\{v_4,v_5\}=\{v_5\}$, and $N_G(v_3)\cap\{v_4,v_5\}=\{v_4,v_5\}$. Moreover, $\{v_4,v_5\}\subset D_2$. Therefore, $D_2$ is an LD-set of $G$.

    \medskip			
	   \noindent\textbf{Case 2:} $v_1,v_3\in D'_1$ and $v_2\in D'_2$.

	\medskip    
	    Let $D_1=D'_1\cup\{v_5\}$ and $D_2=D'_2\cup\{v_4\}$. Now we show that each $D_i$ is an LD-set of $G$ for $i\in\{1,2\}$. Note that $N_G(v_2)\cap\{v_1,v_3,v_5\}=\{v_1,v_3,v_5\}$ and  $N_G(v_4)\cap\{v_1,v_3,v_5\}=\{v_1,v_3\}$. Moreover, $\{v_1,v_3,v_5\}\subset D_1$. Therefore, $D_1$ is an LD-set of $G$. Since $D'_2$ is an LD-set of $H$, we have $N_H(v_1)\cap D'_2\neq N_H(v_3)\cap D'_2$. Hence $N_G(v_1)\cap D_2\neq N_G(v_3)\cap D_2$. Note that $\{v_2,v_4\}\subseteq N_G(v_1)\cap D_2$, $N_G(v_3)\cap D_2= \{v_2,v_4\}$, and  $N_G(v_5)\cap D_2=\{v_2\}$. Therefore, $D_2$ is an LD-set of $G$.

     \medskip  

		\noindent\textbf{Case 3:} $v_2,v_3\in D'_1$ and $v_1\in D'_2$.

	\medskip 	
		Let $D_1=D'_1\cup\{v_4\}$ and $D_2=D'_2\cup\{v_5\}$.  We can make similar arguments as we did in Case 2.

		Hence $G$ admits an LD-partition $[D_1,D_2]$. This completes the proof of Claim~\ref{cl1}.
    \end{proof}

By Claim~\ref{cl1}, $x$ has exactly one child in $T$. Since $n\ge 6$, $|V(T)|\ge 4$. So the parent of $x$ exists in $T$. Let $x'$ be the parent of $x$ in $T$. Recall that $x$ is the parent of $y$ in  $T$. Let $R_{x'}$ be the triangle in $G$ corresponding to the vertex $x'$. Let $V(R_{x'}) = \{v_1,v_2,v_3\}$. Let $R_x$ and $R_y$ be the triangles in $G$ corresponding to the vertices $x$ and $y$, respectively.  Further, due to symmetry, without loss of generality, assume that $V(R_x) = \{v_1,v_2,v_4\}$ and $V(R_y) = \{v_2,v_4,v_5\}$. Thus, $G$ contains the subgraph illustrated in Figure~\ref{fig:paras_2}(b), where the shaded triangle corresponds to the vertex $x'$ in~$T_{x'}$. Since $y$ is a leaf and $x$ has exactly one child in $T$, we have $\deg_G(v_5) = 2$ and $\deg_G(v_4) =3$.

