Let $H$ be the graph of order $n'$ obtained from $G$ by deleting the vertices $v_4$ and $v_5$. Since $n \ge 6$, we have $n' = n - 2 \ge 4$. We note that $H$ is also a mop. Then by the induction hypothesis, let $[D'_1,D'_2]$ be an LD-partition of $H$. In the following, we consider four cases and in each case, we prove that $G$ admits an LD-partition.

\medskip
\noindent\textbf{Case 1:} $v_1,v_2\in D'_1$ and $v_3\in D'_2$.

Let $D_1=D'_1\cup\{v_5\}$ and $D_2=D'_2\cup\{v_4\}$. Now we show that each $D_i$ is an LD-set of $G$ for $i\in\{1,2\}$. Note that $N_G(v_3)\cap\{v_1,v_2,v_5\}=\{v_1,v_2\}$ and $N_G(v_4)\cap\{v_1,v_2,v_5\}=\{v_1,v_2,v_5\}$. Moreover, $\{v_1,v_2,v_5\}\subset D_1$. Therefore, $D_1$ is an LD-set of $G$. Since $D'_2$ is an LD-set of $H$, we have $N_H(v_1)\cap D'_2\neq N_H(v_2)\cap D'_2$. Hence $N_G(v_1)\cap D_2\neq N_G(v_2)\cap D_2$. Note that $\{v_3,v_4\}\subseteq N_G(v_1)\cap D_2$, $\{v_3,v_4\}\subseteq N_G(v_2)\cap D_2$, and $N_G(v_5)\cap D_2=\{v_4\}$. Therefore, $D_2$ is an LD-set of $G$.

\medskip
\noindent\textbf{Case 2:} $v_1,v_3\in D'_1$ and $v_2\in D'_2$.

\medskip
Let $D_1=D'_1\cup\{v_4\}$ and $D_2=D'_2\cup\{v_5\}$. Now we show that each $D_i$ is an LD-set of $G$ for $i\in\{1,2\}$. Note that $N_G(v_2)\cap\{v_1,v_3,v_4\}=\{v_1,v_3,v_4\}$ and $N_G(v_5)\cap\{v_1,v_3,v_4\}=\{v_4\}$. Moreover, $\{v_1,v_3,v_4\}\subset D_1$. Therefore, $D_1$ is an LD-set of $G$. Since $D'_2$ is an LD-set of $H$, we have $N_H(v_1)\cap D'_2\neq N_H(v_3)\cap D'_2$. Hence $N_G(v_1)\cap D_2\neq N_G(v_3)\cap D_2$. Note that $v_5\notin N_G(v_1)\cap D_2$, $v_5\notin N_G(v_2)\cap D_2$, and $N_G(v_4)\cap D_2=\{v_2, v_5\}$. Therefore, $D_2$ is an LD-set of $G$.

\medskip
\noindent\textbf{Case 3:} $v_2,v_3\in D'_1$ and $v_1\in D'_2$. 

\medskip
Let $D_1=D'_1\cup\{v_5\}$ and $D_2=D'_2\cup\{v_4\}$.  We can make similar arguments as we did in Case 2.

\medskip
\noindent\textbf{Case 4:} $v_1,v_2,v_3\in D'_1$ and $v_1,v_2,v_3\notin D'_2$.

\medskip 
Let $D_1=D'_1\cup\{v_4\}$ and $D_2=D'_2\cup\{v_5\}$. Clearly, $D_1$ is an LD-set of $G$. Now we show that $D_2$ is an LD-set of $G$. Since $D'_2$ is an LD-set of $H$, $N_H(v_1)\cap D'_2$, $ N_H(v_2)\cap D'_2$, and $N_H(v_3)\cap D'_2$ are distinct and nonempty sets. Hence $N_G(v_1)\cap D_2$, $N_G(v_2)\cap D_2$, and $N_G(v_3)\cap D_2$ are distinct and nonempty sets. Note that $N_G(v_4)\cap D_2=\{v_5\}$. Moreover, we have $N_G(v_i)\cap D_2\neq N_G(v_4)\cap D_2$ for all $i\in\{1,2,3\}$ since $D'_2$ is an LD-set of $H$. Therefore, $D_2$ is an LD-set of $G$.
\end{proof}

\section{Split graphs and co-bipartite graphs}\label{sec:spco}

In this section, we show that every isolate-free and twin-free split graph and co-bipartite graph admit LD-partitions. In \cite{Foucaud16-2}, it has been proved that if $G$ is a twin-free and isolate-free split graph or co-bipartite graph, then  $\gamma_{LD}(G)\leq \frac{n}{2}$. Our proofs are an extension of the ones from~\cite{Foucaud16-2} used to prove Conjecture~\ref{conj} for split and co-bipartite graphs, but the key arguments are similar. 

\begin{theorem}
	If $G$ is an isolate-free and  twin-free split graph, then $G$ admits an LD-partition.
\end{theorem}
\begin{proof}
	Assume that $G$ is an  isolate-free and twin-free split graph. Let $X$ be  a clique of $G$  and $Y$ be an independent set of $G$ such that $X\cap Y=\emptyset$ and $X\cup Y=V(G)$. Note that every vertex in $Y$ has at least one neighbor in $X$. Moreover, for every $a,b\in X$, we have $N_G(a)\cap Y\neq N_G(b)\cap Y$ since $G$ is twin-free. Further, for every $c,d\in Y$, we have $N_G(c)\cap X\neq N_G(d)\cap X$.

    Let $S=\{a\in X| N_G(a)\cap Y=\emptyset\}$. Since $G$ is twin-free, $|S|\leq 1$. If $S=\emptyset$, then $N_G(a)\cap Y\neq \emptyset$ for every $a\in X$. Hence $[X,Y]$ is an LD-partition of $G$. So we assume that $S\neq \emptyset$. Let $X'=X\setminus S$ and $Y'=Y\cup S$. Now we show that $X'$ and $Y'$ are LD-sets of $G$. Since $G$ is twin-free, there is no vertex $c\in Y$ such that $N_G(c)\cap X= X\setminus S$, where $S=\{a\}$. So for every $x,y\in X'$, we have $N_G(x)\cap Y'\neq \emptyset$ and $N_G(x)\cap Y'\neq N_G(y)\cap Y'$. Further, for every $c,d\in Y'$, we have $N_G(c)\cap X'\neq \emptyset$ and $N_G(c)\cap X'\neq N_G(d)\cap X'$. Hence $X'$ and $Y'$ are LD-sets of $G$. Thus $G$ admits an LD-partition.
	% First we assume that there does not exist a vertex $a\in X$ such that $N_G(a)\cap Y=\emptyset$. Then for every $a\in X$ and $c\in Y$, we have $N_G(a)\cap Y\neq \emptyset$ and $N_G(c)\cap X\neq \emptyset$. So $[X,Y]$ is an LD-partition of $G$. Hence we assume that there exists a vertex $a\in X$ such that $N_G(a)\cap Y=\emptyset$. Let $X'=X\setminus\{a\}$ and $Y'=Y\cup \{a\}$. Now we show that $X'$ and $Y'$ are LD-sets of $G$. Note that there does not exist  vertex $b\in X$ other than $a$ such that $N_G(b)\cap Y=\emptyset$; otherwise, $G$ contains twins. Similarly, there does not exists a vertex $c\in Y$ such that $N_G(c)\cap X= X\setminus\{a\}$. So for every $x,y\in X'$, we have $N_G(x)\cap Y'\neq \emptyset$ and $N_G(x)\cap Y'\neq N_G(y)\cap Y'$. Further, for every $c,d\in Y'$, we have $N_G(c)\cap X'\neq \emptyset$ and $N_G(c)\cap X'\neq N_G(d)\cap X'$. Hence $X'$ and $Y'$ are LD-sets of $G$. Thus $G$ admits an LD-partition.
\end{proof}

\begin{theorem}
	If $G$ is an isolate-free and  twin-free co-bipartite graph, then $G$ admits an LD-partition.
\end{theorem}
\begin{proof}
	Assume that $G$ is an isolate-free and twin-free co-bipartite graph. Let $X$ and $Y$ be the two cliques of $G$ such that $X\cap Y=\emptyset$ and $X\cup Y=V(G)$. Let $S_1=\{a\in X| N_G(a)\cap Y=\emptyset\}$ and $S_2=\{c\in Y| N_G(c)\cap X=\emptyset\}$. Since $G$ is twin-free, we have $N_G(a)\cap Y\neq N_G(b)\cap Y$ and $N_G(c)\cap X\neq N_G(d)\cap X$ for every $a,b\in X$ and $c,d\in Y$. So $|S_1|\le 1$ and $|S_2|\le 1$.

	If $S_1=\emptyset$ and $S_2=\emptyset$, then $X$ and $Y$ are LD-sets of $G$ and so $G$ admits an LD-partition. Hence at least one of sets from $S_1$ and $S_2$ is nonempty. First suppose that $|S_1|=1$ and $|S_2|=1$. Let $X'=(X\setminus S_1)\cup S_2$ and $Y'=(Y\setminus S_2)\cup S_1$. Now we show that $X'$ and $Y'$ are LD-sets of $G$. It is easy to observe that $X'$ is a dominating set of $G$. Since $N_G(c)\cap X\neq N_G(d)\cap X$ for every $c,d\in Y$, $N_G(c)\cap X'\neq N_G(d)\cap X'$ for every $c,d\in Y\setminus\{S_2\}$. Since $|S_2|=1$, we have $N_G(x)\cap X'\neq N_G(y)\cap X'$ for $x\in S_1$ and every $y\in Y\setminus\{S_2\}$. Hence $X'$ is an LD-set of $G$. Similarly, $Y'$ is also an LD-set of $G$ and so $G$ admits an LD-partition. Hence we assume that either $S_1=\emptyset$ or $S_2=\emptyset$. Without loss of generality, assume that $|S_1|=1$ and $S_2=\emptyset$. Let $S_1=\{x\}$. If there is no vertex $y\in Y$ such that $N_G(y)\cap X\setminus\{x\}= X\setminus\{x\}$, then let $X'=X\setminus\{x\}$ and $Y'=Y\cup \{x\}$. Then $X'$ and $Y'$ are LD-sets of $G$ and so $G$ admits an LD-partition. Hence there exists a vertex $y\in Y$ such that $N_G(y)\cap X\setminus\{x\}= X\setminus\{x\}$. Note that there is no vertex $y'\in Y$ other than $y$ such that $N_G(y')\cap X\setminus\{x\}= X\setminus\{x\}$; otherwise, $G$ contains twins. Let $X'=(X\setminus\{x\})\cup \{y\}$ and $Y'=(Y\setminus\{y\})\cup \{x\}$. Clearly, $X'$ is an LD-set of $G$. Now we show that $Y'$ is an LD-set of $G$. Note that $N_G(y)\cap Y'=Y'\setminus\{x\}$ and $N_G(v)\cap Y'\neq \emptyset$ for all $v\in X\setminus\{x\}$. Moreover, every vertex in  $X\setminus\{x\}$ has distinct neighborhood in $Y'$ since $G$ is twin-free and $x\in Y'$. Hence $Y'$ is also an LD-set of $G$. Thus $G$ admits an LD-partition.
\end{proof}

\section{Conclusion}\label{sec:con}

Conjecture~\ref{conj} is already known to hold for several important graph classes, including bipartite graphs, split graphs, co-bipartite graphs, line graphs, maximal outerplanar graphs, subcubic graphs, and block graphs. In this work, we addressed Question~\ref{motivation} and provided a positive answer for well-structured graph classes, namely distance-hereditary graphs, maximal outerplanar graphs, split graphs, and co-bipartite graphs.



This work contributes to a deeper structural understanding of locating-dominating sets and their properties within well-defined graph classes. As a natural direction for future research, it would be worthwhile to investigate whether Conjecture~\ref{conj} holds for the class of chordal graphs.


