%     \]
% \end{itemize}

The complete workflow of the proposed (CPINN-ABPI) approach is detailed in~\cref{alg:cpinn-abpi} and~\cref{alg:nsga2}.

\begin{algorithm}[tb]
\caption{CPINN-ABPI}
\label{alg:cpinn-abpi}
\begin{algorithmic}[1]
\Require Temperature sequences $\{T(k)\}_{k=1}^K \in \mathbb{R}^{N_c}$, power data $\{P_{\text{est}}(k), P_{\text{act}}(k)\}$
\Ensure Trained CPINN-ABPI model

\Statex \textbf{Phase 1: Initialization}
\State Load thermal matrices $\mathbf{A}, \mathbf{B} \in \mathbb{R}^{N_c \times N_c}$ from empirical ABPI
\State Initialize trainable parameters: $\mathbf{A}' \leftarrow \mathbf{A}$, $\mathbf{B}' \leftarrow \mathbf{B}$
\State Initialize neural network $f_\theta$ with given architecture

\Statex \textbf{Phase 2: Training Loop}
\For{epoch $e = 1$ to $E_{\max}$}
    \State $\text{total\_loss} \leftarrow 0$
    \For{each batch $b$ in training data}
        \For{each sample $(T_{\text{prev}}, T_{\text{curr}}, P_{\text{est}}, P_{\text{act}})$ in batch $b$}

            \Statex \quad \textit{Physics-informed forward pass}
            \State $\hat{T} \leftarrow \mathbf{A}'^T \cdot T_{\text{prev}}$
            \State $\Delta T \leftarrow T_{\text{curr}} - \hat{T}$
            \State $P_{\text{physics}} \leftarrow \Delta T \cdot (\mathbf{B}'^{-1})^T$

            \Statex \quad \textit{Neural network correction}
            \State $x \leftarrow [T_{\text{prev}}; T_{\text{curr}}; P_{\text{est}}]$
            \State $\Delta P \leftarrow f_\theta(x)$
            \State $P_{\text{final}} \leftarrow P_{\text{physics}} + \Delta P$

            \Statex \quad \textit{Loss computation}
            \State $\mathcal{L}_{\text{data}} \leftarrow \|P_{\text{final}} - P_{\text{act}}\|^2$
            \State $\mathcal{L}_{\text{physics}} \leftarrow \|\mathbf{A}'^T T_{\text{prev}} + \mathbf{B}'^T P_{\text{final}} - T_{\text{curr}}\|^2$
            \State $\mathcal{L}_{\text{guide}} \leftarrow \|P_{\text{final}} - P_{\text{physics}}\|^2$
            \State $\mathcal{L}_{\text{batch}} \leftarrow \mathcal{L}_{\text{data}} + \lambda_{\text{phys}} \mathcal{L}_{\text{physics}} + \lambda_{\text{guide}} \mathcal{L}_{\text{guide}}$
            \State $\text{total\_loss} \leftarrow \text{total\_loss} + \mathcal{L}_{\text{batch}}$
        \EndFor
    \EndFor

    \Statex \quad \textit{Backward pass and optimization}
    \State Compute gradients: $\nabla_\theta \text{total\_loss}$, $\nabla_{\mathbf{A}'} \text{total\_loss}$, $\nabla_{\mathbf{B}'} \text{total\_loss}$
    \State Update parameters: $\theta, \mathbf{A}', \mathbf{B}'$ using optimizer

    \Statex \quad \textit{Convergence check}
    \If{validation loss converged}
        \State \textbf{break}
    \EndIf
\EndFor

\State \Return Optimized model $(\theta^*, \mathbf{A}'^*, \mathbf{B}'^*)$
\end{algorithmic}
\end{algorithm}


\begin{algorithm}[tb]
\caption{NSGA-II for CPINN-ABPI Architecture Optimization}
\label{alg:nsga2}
\begin{algorithmic}[1]
\Require Training dataset $\mathcal{D}$, population size $N_{\text{pop}}$, generations $G_{\text{max}}$
\Ensure Pareto-optimal architectures $\mathcal{P}^*$

\Statex \textbf{Phase 1: Population Initialization}
\State Initialize population $P_0 \leftarrow \{\}$
\For{$i = 1$ to $N_{\text{pop}}$}
    \State Generate random individual $\mathbf{h}_i \leftarrow (\text{layers}, \text{widths}, \text{activation}, \lambda_{\text{phys}}, \lambda_{\text{guide}})$
    \State $P_0 \leftarrow P_0 \cup \{\mathbf{h}_i\}$
\EndFor

\Statex \textbf{Phase 2: Evolution Loop}
\For{generation $g = 0$ to $G_{\max} - 1$}

    \Statex \quad \textit{Objective evaluation}
    \For{each individual $\mathbf{h}_i \in P_g$}
        \State Train CPINN-ABPI model using Algorithm 1 with hyperparameters $\mathbf{h}_i$
        \State Evaluate MAE: $f_1(\mathbf{h}_i) \leftarrow \frac{1}{|\mathcal{D}_{\text{test}}|} \sum \|P_{\text{pred}} - P_{\text{true}}\|_1$
        \State Evaluate computational cost: $f_2(\mathbf{h}_i) \leftarrow \text{MACs}(\mathbf{h}_i)$
        \State Assign objectives: $\mathbf{f}(\mathbf{h}_i) \leftarrow [f_1(\mathbf{h}_i), f_2(\mathbf{h}_i)]$
    \EndFor

    \Statex \quad \textit{Non-dominated sorting}
    \State Compute domination relationships for all individuals in $P_g$
    \State Partition $P_g$ into fronts: $\mathcal{F}_1, \mathcal{F}_2, \ldots, \mathcal{F}_k$
    \State Compute crowding distance for each individual

    \Statex \quad \textit{Selection and reproduction}
    \If{$g < G_{\max} - 1$}
        \State Generate offspring $Q_g$ through tournament selection, crossover, and mutation
        \State Combine populations: $R_g \leftarrow P_g \cup Q_g$
        \State Apply elitist selection to form $P_{g+1}$ of size $N_{\text{pop}}$
    \EndIf
\EndFor

\Statex \textbf{Phase 3: Pareto Front Extraction}
\State Extract final Pareto front: $\mathcal{P}^* \leftarrow \mathcal{F}_1$ from $P_{G_{\max}}$
\State Apply the 10-Fold Cross-Validation on the Pareto solution.
\State \Return $\mathcal{P}^*$
\end{algorithmic}
\end{algorithm}


