\title[]{Howe duality over finite fields II: explicit stable computation}
\author{Sophie Kriz}
\thanks{The author was supported by a 2023 National Science Foundation
Graduate Research Fellowship, no. 2023350430}


\begin{document}


\maketitle

\begin{abstract}
In this second paper of a series dedicated to type I Howe duality for finite fields,
we explicitly decompose the restriction of an oscillator representation of a finite symplectic group
to the product of a symplectic and an orthogonal subgroup which are
each other's centralizers in terms of G. Lusztig's
classification of irreducible representations of finite groups of Lie type
in the two so-called stable ranges.

\end{abstract}

\section{Introduction}


\vspace{5mm}


This is the second paper of a series dedicated to type I Howe duality for finite fields.
We recall that over a finite field, the oscillator representation is a representation
of a finite symplectic group, in which a type I reductive dual pair consists of a
symplectic and an orthogonal subgroup which are each other's centralizers.
In \cite{TotalHoweI}, we constructed explicit correspondences between the sets of 
representations on the symplectic and orthogonal side in the two 
stable ranges. In this paper, we shall describe these correspondences
explicitly in terms of G. Lusztig's classification of representations of finite groups of Lie type
(see, for example, \cite{Lusztig}).


Consider an oscillator representation $\omega [V\otimes W]$
of a symplecitc group $Sp(V\otimes W)$
restricted to such a reductive dual pair, consisting
of a symplectic group $Sp(V)$ and an orthogonal group $O(W,B)$. In the first
part of this series \cite{TotalHoweI}, we proved the existence of a {\em symplectic} and an
{\em orthogonal stable range}, where the restriction of the oscillator representation
to the product $Sp(V) \times O(W,B)$ decomposes in terms of (twisted) parabolic inductions
and a system of injections with mutually disjoint images
\beg{EtaCorrIntro}{\eta^V_{W,B}: \widehat{O(W,B)} \hookrightarrow \widehat{Sp(V)}}
(where $\widehat{G}$ denotes the set of isomorphism classes of irreducible complex representations
of a group $G$)
for $(Sp(V), O(W,B))$ a symplectic stable reductive dual pair (where symplectic stability
means that $dim (W) \leq dim (V)/2$), and 
\beg{ZetaCorrIntro}{\zeta^{W,B}_V: \widehat{Sp(V)} \hookrightarrow \widehat{O(W,B)}}
for $(Sp(V), O(W,B))$ an orthogonal stable reductive dual pair
(where $dim (V)$ is less than or equal to the dimension of the maximal isotropic subspace
of $W$). We omit subcripts from the notation
of \rref{EtaCorrIntro}, \rref{ZetaCorrIntro} when the source is already established. 


\vspace{3mm}

The main result of \cite{TotalHoweI} is

\begin{theorem}\label{TotalHoweITheorem}
Let $V$ be a $2N$-dimensional symplectic space and let $W$ be an $n$-dimensional
space with symmetric bilinear form $B$. Write $h_W$ for the maximal dimension of an isotropic subspace
of $W$.

\begin{enumerate}

\item If $(Sp(V), O(W,B))$ is a reductive dual pair in $Sp(V \otimes W)$
in the symplectic stable range, then
for a system of mutually disjoint injections $\eta^V_{W,B}$ as in \rref{EtaCorrIntro}, 
the restriction of $\omega [ V\otimes W]$ to $Sp(V) \times O(W,B)$ decomposes as
\beg{EtaCorrThmDecomp}{
\bigoplus_{k=0}^{h_W}
\bigoplus_{\rho \in \widehat{O(W[-k], B[-k])}} \eta^V (\rho) \otimes Ind^{P_k^B} (\rho \otimes \epsilon (det))
}
where $Ind^{P_k^B}$ denotes parabolic induction from the maximal parabolic $P_k^B$
in $O(W,B)$ whose Levi factor is $O(W[-k], B[-k]) \times GL_k (\F_q)$, which we consider
$\rho \otimes \epsilon (det)$ a representation of by considering $\epsilon (det)$ as
a representation of $GL_k(\F_q)$.


\vspace{2mm}

\item If $(Sp(V), O(W,B))$ is a reductive dual pair in $Sp(V \otimes W)$
in the orthogonal stable range, then for a system
of mutually disjoint injections $\zeta^{W,B}_V$ as in \rref{ZetaCorrIntro},
the restriction of $\omega [ V\otimes W]$ to $Sp(V) \times O(W,B)$ decomposes as
\beg{ZetaCorrThmDecomp}{
\bigoplus_{k=0}^{h_W}
\bigoplus_{\rho \in \widehat{Sp(V[-k])}}  Ind^{P_k^V} (\rho \otimes \epsilon (det)) \otimes \zeta^{W,B} (\rho)
}
where $Ind^{P_k^V}$ denotes parabolic induction from the maximal parabolic $P_k^V$
in $Sp(V)$ with Levi factor $Sp(V[-k]) \times GL_k (\F_q)$, which we consider
$\rho \otimes \epsilon (det)$ a representation of by considering $\epsilon (det)$ as
a representation of $GL_k(\F_q)$.

\end{enumerate}
\end{theorem}

\vspace{5mm}

Now to state the main result of this paper, we must briefly recall Lusztig's classification
of irreducible representations of finite groups of Lie type $G$.
Most generally, we consider the data of 
\begin{itemize}
\item The conjugacy class of a semisimple element $s$ in the dual group $G^D$.

\vspace{3mm}

\item A unipotent representation $u$ of the dual $(Z_{G^D} (s))^D$ of the centralizer of $s$ in $G^D$.

\end{itemize}
We associate to the data $[(s), u]$ a representation of $G$
we denote by $\rho_{(s), u}$ of dimension equal to the dimension
of $u$ multiplied by the prime to $q$ part of the quotient order
$|G^D/ Z_{G^D} (s)|$. Intuitively, $\rho_{(s),u}$ can be thought of
as a ``faked parabolic induction" of $u$, with the realization that over a finite field,
there are many cases of $s$ (specifically, when it only can live in a torus
with a non-split factor $SO_2^+$) where there is no actual
maximal parabolic with Levi factor
$Z_{G^D} (s)$. However, $\rho_{(s),u}$ will sit in the the induction from the torus character
corresponding to $s$ to $G$.

In all cases of $G$, for every irreducible representation $\rho \in \widehat{G}$, there exists
a unique choice of data $[(s), u]$ as described above, such that $\rho \subseteq \rho_{(s),u}$.
On the one hand, if $G$ has a connected center,
for example, in the case of the odd special orthogonal groups
$G = SO_{2m+1} (\F_q)$, the representations $\rho_{(s), u}$ are irreducible, and therefore
they precisely describe irreducible
representations of $G$. In this case, we call the data $[(s), u]$ the {\em Lusztig classification data}
corresponding to an irreducible representation $\rho = \rho_{(s),u}$.

On the other hand, if $G$ has a disconnected center, $\rho_{(s), u}$ may split further.
For example, in the case of symplectic groups $G= Sp_{2N} (\F_q)$ which have center $\Z/2$,
a representation $\rho_{(s),u}$ splits if and only
if $s$ has $-1$ eigenvalues. If $s$ has $-1$ eigenvalues, then $\rho_{(s), u}$ splits into two irreducible
non-isomorphic pieces
$$\rho_{(s), u} = \rho_{(s), u , +1} \oplus \rho_{(s), u , -1},$$
both of dimension equal to exactly half of the dimension of $\rho_{(s), u}$.
In this case, we call the
data $[(s), u, \pm 1]$ the {\em Lusztig classification data} corresponding
to an irreducible representation $\rho = \rho_{(s), u, \pm 1}$
and call the sign $\pm 1$ its {\em central sign}.
If $s$ has no $-1$ eigenvalues,
then as before, we call $[(s), u]$ the {\em Lusztig classification data} corresponding to
the irreducible representation $\rho = \rho_{(s), u}$.
A similar but slightly more complicated effect occurs for even orthogonal groups
$G= O_{2m}^\pm (\F_q)$, with $\rho_{(s),u}$ consisting of one, two, or four
distinct irreducible summands, depending on the eigenvalues of $s$. This effect can also be
interpreted according to certain ``sign data",
and we use similar terminology,
calling the collection of data of $(s), u$ and this extra sign data (when needed)
the Lusztig classification data associated to an irreducible representation.
We discuss this in Section \ref{BackgroundSect}.

\vspace{3mm}

Using this description, we describe injections
$$\phi^V_{W,B} : \widehat{O(W,B)} \hookrightarrow \widehat{Sp(V)}$$
$$\psi^{W,B}_V : \widehat{Sp(V)} \hookrightarrow \widehat{O(W,B)}$$
roughly defined by altering the semisimple part of the input representation's
Lusztig classification data by
adding $-1$ eigenvalues if $W$ is odd dimensional
and adding $1$ eigenvalues if $W$ is even dimensional, and by changing
the unipotent part by adding a coordinate to the symbol of the factor
of $u$ corresponding to the altered eigenvalues to achieve
the needed new rank and defect (the choice of how to
add eigenvalues and where to, if there is one, is determined by the central action
of the input irreducible representation). This construction
is described in more detail in Section \ref{LusztigClaimSect} below.


\vspace{3mm}

\begin{theorem}\label{EtaExplicitIntro}
Assume the notation of Theorem \ref{TotalHoweITheorem}.

\begin{enumerate}
\item\label{SympStabSide}
Suppose we have a reductive dual pair
$(Sp(V), O(W,B))$ in $Sp(V\otimes W)$ in the symplectic
stable range. Then
$$\eta^V_{W,B} = \phi^V_{W,B}.$$

\vspace{1mm}

\item\label{OrthoStabSide}
Suppose we have a reductive dual pair
$(Sp(V), O(W,B))$ in $Sp(V\otimes W)$ in the orthogonal
stable range.Then
$$\zeta^{W,B}_V = \psi^{W,B}_V.$$

\end{enumerate}

\end{theorem}

\vspace{3mm}

The main tool used to prove Theorems \ref{EtaExplicitIntro} is
actually dimension. We state here a key result, which, combined with some combinatorics,
will prove that the dimensions of the $Sp(V)$-representations
$\eta^V_{W,B}(\rho)$ and $\phi^V_{W,B} (\rho)$ (resp. the $O(W,B)$-representations
$\zeta^{W,B}_V(\rho)$ and $\psi^{W,B}_V (\rho)$) always match
for $\rho \in \widehat{O(W,B)}$ (resp. $\rho \in \widehat{Sp(V)}$) for
$N>>n$ (resp. $n>>N$). 
We can derive then that they must always match, since for a fixed $\rho$, the dimensions
of $\eta^V_{W,B} (\rho)$ and $\phi^V_{W,B} (\rho)$ both form polynomials of $q^{N}$ (resp. the
dimensions of $\zeta^{W,B}_V (\rho)$ and $\psi^{W,B}_V (\rho)$ both form
polynomials of $q^n$). Since the semisimple part and the sign data of $\eta^V_{W,B} (\rho)$
or $\zeta^{W,B}_V( \rho)$
are already determined
by considering the restriction of the oscillator
representation to the general linear group, this suffices to prove the representations themselves match.

We define, for $\rho$ an irreducible representation of $Sp_{2N} (\F_q)$, its {\em $N$-rank} to be
$$rk_N (\rho) = \lceil \frac{deg_q (dim (\rho))}{N} \rceil .$$
Similarly, for $\rho$ an irreducible representation of $O (W,B)$ with $dim (W) = n$, define
its {\em $n$-rank} to be
$$rk_n (\rho)= \lceil \frac{deg_q (dim (\rho))}{n} \rceil .$$

\vspace{3mm}


\begin{proposition}\label{NnRank}
Assume the notation of Theorem \ref{TotalHoweITheorem}.

\begin{enumerate}
\item \label{N>>nPartOfRankProp} Consider $N>>n$. Then the
disjoint union of the images of the eta correspondences
$$\eta^V_{W,B}: \widehat{O(W,B)} \hookrightarrow \widehat{Sp(V)}$$
for the symplectic space $V$ of dimension $2N$ and
the two choices of orthogonal space $(W,B)$ of dimension $n$
is precisely the set of irreducible representations of $Sp(V)$ of $N$-rank $n$.

\item \label{n>>NPartOfRankProp} Consider $n>>N$. Then the
disjoint union of the images of the zeta correspondences
$$\zeta^V_{W,B}: \widehat{O(W,B)} \hookrightarrow \widehat{Sp(V)}$$
for the symplectic space $V$ of dimension $2N$ and
the two choices of orthogonal space $(W,B)$ of dimension $n$
is precisely the set of irreducible representations of $Sp(V)$ of $N$-rank $n$.



\end{enumerate}
\end{proposition}

\vspace{3mm}



The present paper is organized as follows: In Section \ref{BackgroundSect},
we describe Lusztig's classification of irreducible representations.
In Section \ref{LusztigClaimSect}, we describe our proposed constructions of the eta and
zeta correspondences in more detail. In Section \ref{CombinatoricsSect}, we prove
combinatorial identities proving our claimed constructions can be plugged into 
the decompositions in Theorem \ref{TotalHoweITheorem} and add up to the correct dimension.
In Section \ref{InductiveProof}, we use an inductive argument to prove Proposition \ref{NnRank}
and conclude Theorem \ref{EtaExplicitIntro}.
In Section \ref{SL2Sect}, we write down the zeta correspondence in the example
where $dim (V) = 2$.

