\name performs well with perfect workloads. However, since we developed it based on the challenges of real-world scenarios, we focus on evaluating its performance under those conditions to highlight the \emph{practical utility} of \name.

\smallskip
\noindent \textbf{Data updates/shifts.} In production environments, we observe that user data typically remains static throughout a week, and production systems often accumulate a significant number of queries weekly. For example, businesses we can access in ByteDance generates, on average, over 2 million queries per workload (each corresponding to a database instance) each week.
Therefore, we adopt a pragmatic approach to manage data distribution shifts: we retrain \name weekly using the queries collected during that period.

\section{PRELIMINARIES}
This section first introduces notations and concepts, and then summarizes real-world production workloads we collected at ByteDance.

\vspace{-0.5em}
\subsection{Definitions\label{section:definition}}

\begin{definition}[\textit{Database Instance}] A database instance \(\mathcal{DB}\) comprises a set of base relations/tables \(\{T_j\}_{j=1}^m\), where \(m\) denotes the number of tables in \(\mathcal{DB}\). Each table \(T_j\) includes a set of columns or attributes \(\{A_i\}_{i=1}^n\), where \(n\) represents the number of attributes per table. We define the cardinality $|T_j|$ of each table $T_j$ as the number of total tuples in $T_j$. 
We also define the domain of an attribute \(A\), denoted as \(\text{dom}(A)\), as the set of all distinct values in \(A\). 
% Additionally, the schema of \(\mathcal{DB}\) specifies how these base relations are interconnected through join keys.

\end{definition}

{\color{black}
\begin{definition}
[\textit{Query}]  \label{def:query} A query is a structured request to retrieve data from a database based on specified operations and conditions. This paper focuses on SPJ queries with \emph{inner equi-joins}, following most  learned CardEst work~\cite{wu2023factorjoin, kim2024asm, deepdb, yang2020neurocard}. \name is capable of handling chain joins, star joins, and self-joins, all of which we evaluate in the paper. While \name can also be extended to handle cyclic joins under the join key independence assumption (as in~\cite{wu2023factorjoin}), we did not evaluate cyclic joins, as most benchmarks focus on acyclic joins. For supported predicates, we focus on equality ($=$), range ($<, \leq, >, \geq$), string matching (\texttt{LIKE}), containment  (\texttt{IN}), and null-checking  (\texttt{NULL}) predicates. These supported predicates are consistent with most existing learned CardEst work and are included in the benchmarks we evaluate in this paper. 

Other features (\textit{e.g.,} \texttt{Group-By}, \texttt{Distinct}) also impacts query cardinalities. While existing techniques~\cite{kipf2019estimating} could be integrated with \name to address additional features, they fall outside the scope of this work. Moreover, these features are not prevalent in the real-world queries we collected from ByteDance: 82\% of queries we collected fit within the scope of this paper.
% This indicates the practical importance of focusing on the types of queries primarily considered in this paper.

\end{definition}
}

\begin{definition}[\textit{Join Template/Join Graph}] \label{def:join_template} A join template, also referred to as a join graph, connects base relations through their join keys. It consists of nodes and edges, where each node represents a base relation and each edge represents a join operation between two relations based on join keys. {\color{black} Here, a {join key} is defined as a pair of attributes from two relations that are used to establish a condition for joining tuples from those relations. This paper considers both foreign key-primary key (FK-PK) and FK-FK equi-joins}. 
\end{definition}

% {\color{black} Note that the definition of join template specifically defines how tables are interconnected through joins \emph{without} considering the specificities of other predicates outside of the joining conditions. 
%  }

\begin{definition}[\textit{Query Template}] \label{def:query_template} 
% {\color{black}A query template is a  parameterized form of a database query that abstracts specific literals or values to placeholders, allowing for the reuse of the query structure with different inputs. This template serves as a blueprint for constructing SQL queries and is particularly useful in preparing and optimizing queries in applications where similar queries are executed repeatedly with varying parameters. It aids in query optimization by allowing database engines to cache execution plans and understand query patterns more effectively.
% }
A query template is a {\color{black}parameterized} query pattern that maintains consistent {\color{black}or fixed} join template {\color{black}\emph{as well as other predicates outside of the joining conditions}, varying \emph{only} in the values or literals specified within non-join predicates. This paper does not consider nested queries, following most of learned CardEst work~\cite{wu2023factorjoin, kim2024asm, deepdb, yang2020neurocard}.}
\end{definition}


\begin{definition}[\textit{Cardinality Estimation}] \label{definition:cardest}
    Given a database instance $\mathcal{DB}$ and query $q$ over $\mathcal{DB}$, the goal of cardinality estimation is to predict the cardinality $c(q)$, \textit{i.e.,} the number of tuples that satisfy $q$. Another equivalent term, selectivity, is the ratio $c(q)/|T|$, where $|T|$ is the table cardinality or the join size if $q$ is a join query. {\color{black} In query optimization, the optimizer needs to estimate the cardinality for each subquery of $q$, as each subquery can be considered a query.}
\end{definition}
{ \color{black}

 % Then we introduce notations needed to formally define the properties of imperfect workloads we consider in the paper (\S~\ref{section.problem_formulation}).

\begin{definition}[\textit{Template Coverage Ratio}] \label{def:tcr} 
 Let $\mathcal{T}$ be the set of all possible join templates of a schema, and 
$\mathcal{T}_{\text{train}} \subset \mathcal{T}$ be the set of templates observed during training. We define \textbf{Template Coverage Ratio (TCR)} as $
        \mathrm{TCR} = \frac{\lvert \mathcal{T}_{\text{train}} \rvert}{\lvert \mathcal{T} \rvert}.$
    A lower TCR indicates that more join templates are missing from the training workload.
\end{definition}


\begin{definition}[\textit{Class Imbalance Ratio}]\label{def:cir}   
 Let $n_t$ be the number of training queries for a join template 
$t \in \mathcal{T}_{\text{train}}$. We define  \textbf{Class Imbalance Ratio (CIR):} $ \mathrm{CIR} = \frac{\max_{t \in \mathcal{T}_{\text{train}}} n_t} {\min_{t \in \mathcal{T}_{\text{train}}} n_t}.$
 A higher CIR indicates a greater imbalance between join templates.
\end{definition}

\begin{definition}[\textit{Granularity}]\label{def:granularity} 
We define \textbf{Granularity} as the \emph{range size} for a query $q$ on a specific \emph{numerical} attribute $A_i$ that supports \emph{range predicates/filters}. For example, let $\ell_i$ and $r_i$ be the lower and upper bounds of $q$'s filter over $A_i$. Then: $\mathrm{Granularity}(q) = r_i - \ell_i$. \label{definition.granularity}
% $
% G(q) \;=\; \prod_{i=1}^d \bigl(r_i - \ell_i\bigr),
% $ (one can extend the definition to equality operator by following~\cite{dutt2019selectivity}).
\end{definition}

}

