\end{figure}



The likelihood of a certain trajectory $\textbf{y}_{1:T}$, given the latent states $z_{1:T}$ and all model parameters, can be written in two different formulations:

\begin{equation}
\begin{aligned}
    P(\textbf{y}_{1:T}|z_{1:T}, \{\hat{A}_k\}, \{Q_k\}, M) & = \prod_{t=1}^{T-1} (2\pi)^{-\frac{N}{2}} |Q_{z_{t+1}}|^{-\frac{1}{2}}
    \cdot \exp{\left[-\frac{1}{2} (\textbf{y}_{t+1} - \hat{A}_{z_{t+1}} \hat{\textbf{y}}_t)^T Q_{z_{t+1}}^{-1} (\textbf{y}_{t+1} - \hat{A}_{z_{t+1}} \hat{\textbf{y}}_t) \right]} \\ & = \prod_{k=1}^{K} (2\pi)^{-\frac{N \cdot N_k}{2}} |Q_{k}|^{-\frac{N_k}{2}}
    \cdot \exp{\left[-\frac{1}{2} \sum_{t_i \in k}^{N_k} (\textbf{y}_{t_i} - \hat{A}_{k} \hat{\textbf{y}}_{t_i-1})^T Q_{k}^{-1} (\textbf{y}_{t_i} - \hat{A}_{k} \hat{\textbf{y}}_{t_i-1}) \right]}
\end{aligned}
\end{equation}

where $t_i$ is an instant in time in which $z_{t_i} = k$ and $N_k$ corresponds to the number of occurrences of state $k$.

The joint probability distribution for all the variables can be written as

\begin{equation}
\begin{aligned}
    P(\textbf{y}_{1:T}, z_{1:T}, \{\hat{A}_k\}, \{Q_k\}, M) =
    P(\textbf{y}_{1:T}|z_{1:T}, \{\hat{A}_k\}, \{Q_k\}, M) \cdot P(z_{1:T}|M) \cdot P(M) \cdot P(\{\hat{A}_k\}, \{Q_k\}) ,
\end{aligned}
\end{equation}

where choosing an uninformative prior on the state $z_1$ the probability of observing a given latent history is

\begin{equation}
    P(z_{1:T}| M) = P(z_1) \cdot \prod_{t=1}^{T-1} M_{z_t, z_{t+1}} = \frac{1}{K} \cdot \prod_{t=1}^{T-1} M_{z_t, z_{t+1}}. 
\end{equation}


Conjugate priors for the model parameters can be chosen, in order to simplify the inference task. Specifically, the Dirichlet distribution is the conjugate prior of the categorical distribution, and the Inverse Wishart ($\mathcal{IW}$) distribution is the conjugate prior for the covariance matrix of a Multivariate Normal ($\mathcal{MN}$) distribution.

\begin{equation}
    P(M) = \prod_{k=1}^{K} P(\textbf{M}_k|\boldsymbol\alpha_k) = \prod_{k=1}^{K} \frac{1}{B(\boldsymbol\alpha_k)} \prod_{l=1}^{K} M_{kl}^{\alpha_{kl} - 1} , 
\end{equation}
\begin{equation}
\begin{aligned}
    P(\{\hat{A}_k\}, \{Q_k\}) & = \prod_{k=1}^{K} P(\hat{A}_k, Q_k) = \prod_{k=1}^{K} \mathcal{MNIW} (\hat{A}_k, Q_k; C, V, S, \nu) \\ & = \prod_{k=1}^{K} \mathcal{MN}(\hat{A}_k| C, Q_k, V) \cdot \mathcal{IW}(Q_k; S, \nu) .
\end{aligned}
\end{equation}

The model hyperparameters choice has to reflect the knowledge about the system. We use hence uninformative priors. The concentration parameters of the Dirichlet distribution are uniformly set as \(\boldsymbol\alpha_k = [1, ..., 1]\ \ \forall k = 1, ..., K\),  while the mean matrix $ C $ takes the form $[\vec{\mathbf{0}}, \mathbb{I}_N]$.  The inverse covariance matrix along columns, $ V $, is assigned the structure $\mathbb{I}_{N+1} $.  and the scale matrix $ S = \mbox{diag}(\lambda_1, ..., \lambda_N)$ associated with the Inverse Wishart ($\mathcal{IW}$) distribution, defines the expected scale of the data variability. The degrees of freedom for the $\mathcal{IW}$ distribution are set to $\nu = N$, matching the data dimensionality. Collectively, the hyperparameters consist of the  matrices $\alpha$, $C$, $V$, $S$ and the scalar number of degrees of freedom $\nu$.


The objective is then to perform Gibbs sampling for this kind of AR-HMM. We have to compute the conditional probabilities of each random variable, keeping fixed all the others.

\subsubsection{Message passing algorithm on $z_{1:T}$}
Following \citep{fox_nonparametric_2008}, one can develop a message passing algorithm to sample the hidden history $z_{1:T}$. First, we observe that the joint probability $P(z_{1:T}| \{\hat{A}_k\}, \{Q_k\}, M, \textbf{y}_{1:T})$ factorizes as

\begin{equation}
    P(z_{1:T}| \{\hat{A}_k\}, \{Q_k\}, M, \textbf{y}_{1:T}) = P(z_1| \{\hat{A}_k\}, \{Q_k\}, M, \textbf{y}_{1:T}) \cdot \prod_{t = 2}^{T} P(z_t|z_{t-1}, \{\hat{A}_k\}, \{Q_k\}, M, \textbf{y}_{1:T}).
\end{equation}

Starting from sampling $z_1$ then one can sample $z_2|z_1$, and so on.
Single terms of such product can be iteratively computed from the message vector $\mathbf{m}_{t, t-1}$, whose $k$-th component is $m_{t, t-1}(z_{t-1} = k)$ defined as

\begin{equation}
    m_{t, t-1}(z_{t-1} = k) \propto
    \begin{cases}
        \sum_{j=1}^{K} M_{k, j} \cdot \mathcal{N}(\textbf{y}_{t} - \hat{A}_{j} \hat{\textbf{y}}_{t-1}, Q_{j}) \cdot m_{t+1, t}(z_{t} = j) \ \ \ t \leq T , \\
        1 \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ t = T+1 .
    \end{cases}
\end{equation}

The conditional distribution of $z_1$ corresponds to

\begin{equation}
    P(z_{1}| \{\hat{A}_k\}, \{Q_k\}, M, \textbf{y}_{1:T}) \propto P(z_1) P( \textbf{y}_1| \{\hat{A}_k\}, \{Q_k\}) \sum_{z_{2:T}} \prod_{t} P(z_t| M_{z_{t-1}})P( \textbf{y}_t| \{\hat{A}_k\}, \{Q_k\}, \textbf{y}_{t-1}) \, .
\end{equation}

Supposing to sample $z_1$ from a uniform categorical distribution, all the others $z_{t}$ can be sampled categorically from

\begin{equation}
    P(z_t = k|\{\hat{A}_k\}, \{Q_k\}, M, \textbf{y}_{1:T}) \propto M_{z_{t-1}, k} \cdot \mathcal{N}(\textbf{y}_{t} - \hat{A}_{k} \hat{\textbf{y}}_{t-1}, Q_{k}) \cdot m_{t+1, t}(z_{t} = k) .
\end{equation}

\subsubsection{Conditional distributions on $M$, $\{\hat{A}_k\}, \{Q_k\}$}

In order to sample the model parameters $M$, $\{\hat{A}_{k}\}$, $\{Q_{k}\}$, conditional distribution are found to follow the given proportionalities \citep{fox_nonparametric_2008}.

\begin{equation}
\begin{aligned}
    P(\textbf{M}_{k} | z_{1:T}, \{\hat{A}_k\}, \{Q_k\}, \textbf{y}_{1:T}) & \propto \prod_{t=1}^{T-1} \chi(z_t = k) \cdot M_{k, z_{t+1}} \cdot \prod_{l=1}^K M_{kl}^{\alpha_{kl} - 1} \\ & \propto \prod_{l=1}^K M_{kl}^{\alpha_{kl} + \sum_t^{T-1} \chi(z_t = k) \chi(z_{t+1} = l)\ - 1} \\ & \propto \mbox{Dir}(\textbf{M}_{k} | \boldsymbol \alpha_k + \boldsymbol \chi_k) 
\end{aligned}
\label{eq:meq}
\end{equation}

Following \citep{fox_nonparametric_2008} we also write the likelihood in matrix normal form. We build the matrices $Y^{(k)} = [\textbf{y}_{t_1}, ..., \textbf{y}_{t_{N_k}}] \in \mathbb{R}^{N \times N_k}$ and $\bar{Y}^{(k)} = [\hat{\textbf{y}}_{t_1 - 1}, ..., \hat{\textbf{y}}_{t_{N_k} - 1}] \in \mathbb{R}^{(N+1) \times N_k}$ for this goal. We obtain then

\begin{equation}
\begin{aligned}
    P(\textbf{y}_{1:T}|z_{1:T}, \{\hat{A}_k\}, \{Q_k\}, M) & = \prod_{k=1}^{K} (2\pi)^{-\frac{N \cdot N_k}{2}} |Q_{z_{t+1}}|^{-\frac{N_k}{2}} \\ & \cdot \exp{\left[-\frac{1}{2} \mbox{tr}\left( (Y^{(k)} - \hat{A}_{k} \bar{Y}^{(k)})^T Q_{k}^{-1} (Y^{(k)} - \hat{A}_{k} \bar{Y}^{(k)}) \mathbb{I}_{N_k} \right) \right]} \\ & = \prod_{k=1}^{K} \mathcal{MN}(Y^{(k)}; \hat{A}_{k} \bar{Y}^{(k)}, Q_k, \mathbb{I}_{N_k})
\end{aligned}
\end{equation}

Since the prior for $\hat{A}_{k}$ follows a matrix normal distribution, its conditional posterior also remains a matrix normal distribution, but with updated parameters. Defining the following quantities

\begin{equation}
    S_{\bar{y} \bar{y}}^{(k)} = \bar{Y}^{(k)} \bar{Y}^{(k) T} + V, \quad
    S_{y \bar{y}}^{(k)} = Y^{(k)} \bar{Y}^{(k) T} + CV,
\end{equation}
\begin{equation}
    S_{y y}^{(k)} = Y^{(k)} Y^{(k) T} + CVC^T, \quad
    S_{y | \bar{y}}^{(k)} = S_{y y}^{(k)} - S_{y \bar{y}}^{(k)} S_{\bar{y} \bar{y}}^{(k) -1} S_{y \bar{y}}^{(k) T}
\end{equation}

the conditional probabilities for the linear dynamics parameters are

\begin{equation}
    P(Q_k | z_{1:T}, \hat{A}_k, M, \textbf{y}_{1:T}) \propto \mathcal{IW}(Q_k| S + S_{y | \bar{y}}^{(k)}, \nu + N_k)
\label{eq:qeq}
\end{equation}
\begin{equation}
    P(\hat{A}_k | z_{1:T}, Q_k, M, \textbf{y}_{1:T}) \propto \mathcal{MN}(\hat{A}_k | S_{y \bar{y}}^{(k)} S_{\bar{y} \bar{y}}^{(k) -1}, Q_k, S_{\bar{y} \bar{y}}^{(k) -1})
\label{eq:aeq}
\end{equation}

Equations \eqref{eq:meq}, \eqref{eq:qeq}, \eqref{eq:aeq} allow then to sample the model parameters $M$, $\{\hat{A}_{k}\}$, $\{Q_{k}\}$.

\subsubsection{Specifics of the experiments}

Following the literature for animal movement modeling \cite{erdtmann_behavioural_2020, Clontz2021Mar, Laguna2021Nov, saldanhaAnimalBehaviourMove2023}, we set the number of hidden states to $K = 5$. We analyze each boar individually, defining its configuration at time $t$ as a two-dimensional vector $\textbf{y}_t \in \mathbb{R}^2 = \{ x_t, y_t \}$ representing its spatial coordinates. For each boar, the complete trajectory is then given by the sequence of all its subsequent states across all observed timesteps.

To improve computational efficiency while preserving essential movement patterns, we downsample the raw trajectory data (Figure~\ref{fig:trajectory}) by keeping every fifth observation (downsampling factor = $5$). Additionally, we discard the initial burn-in portion of the Markov chain to ensure convergence, retaining only samples from the stationary distribution for inference.


