\section{Algorithms}\label{appendix:algos}

\begin{algorithm}[H]\label{alg:normalization}
\caption{Normalization Pipeline}
\begin{algorithmic}[1]
    \STATE \textbf{Input:} Data tensor $x_t$ and model $M_\theta$
    \STATE \textbf{Output:} Predicted tensor $y$
    \FOR{each variable $v$}
        \STATE $\mu_v = \frac{1}{h \times w}\sum_{i=1}^{h}\sum_{j=1}^{w} x_{t,v,i,j}$ 
        \STATE $\sigma_v = \sqrt{\frac{1}{h \times w}\sum_{i=1}^{h}\sum_{j=1}^{w} (x_{t,v,i,j} - \mu_v)^2}$ 
        \STATE $\hat{x}_{t,v} = \frac{x_{t,v} - \mu_v}{\sigma_v + \epsilon}$ 
    \ENDFOR
    \STATE $\hat{y} = M_\theta(\hat{x}_t)$ 
    \FOR{each variable $v$}
        \STATE $y= \hat{y} \times \sigma_v + \mu_v$ 
    \ENDFOR
    \STATE \textbf{Return:} $y$
\end{algorithmic}
\end{algorithm}


\begin{algorithm}[H]\label{alg:d_perturb}
\caption{Diffusion-based Perturbation Model: Inference}
\begin{algorithmic}[1]
    \STATE \textbf{Input:} Initial state $x_0$, Perturbation model $\epsilon_\phi$, Deterministic model $G_\theta$, number of samples $N$, number of trajectory steps $T$, guidance scale $\omega$
    \STATE \textbf{Output:} Trajectories $\{x_t^{(i)}\}_{t=1}^T, \, i = 1, \dots, N$
    \STATE Repeat input: $\{x_0^{(i)} = x_0\}_{i=1}^N$
    \FOR{$t = 1$ to $T$}
        \FOR{$i = 1$ to $N$}
            \STATE $z_S^{(i)} \sim \mathcal{N}(0, I)$
            \STATE Run DPM++ solver to sample perturbed state $\tilde{x}_t^{(i)}$ from $z_S^{(i)}$ using CFG:
            \FOR{reverse diffusion step $s = S, S{-}1, \dots, 1$}
                \STATE  $\hat{\epsilon}_u = \epsilon_\phi(z_s^{(i)}, \emptyset)$
                \STATE  $\hat{\epsilon}_c = \epsilon_\phi(z_s^{(i)}, x_{t-1}^{(i)})$
                \STATE $\hat{\epsilon} = (1 + \omega)\hat{\epsilon}_c - \omega \hat{\epsilon}_u$
                \STATE Update $z_{s-1}^{(i)}$ using DPM++ update rule with $\hat{\epsilon}$
            \ENDFOR
            \STATE $\tilde{x}_t^{(i)} \gets z_0^{(i)}$
            \STATE $x_{t+1}^{(i)} \gets G_\theta(\tilde{x}_t^{(i)})$
        \ENDFOR
    \ENDFOR
    \STATE \textbf{Return:} $\{x_t^{(i)}\}_{t=1}^T, \, i = 1, \dots, N$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[H]\label{alg:d_training}
\caption{Diffusion-based Perturbation Model: Training over Dataset}
\begin{algorithmic}[1]
    \STATE \textbf{Input:} Dataset $\mathcal{D} = \{x_0^{(i)}\}_{i=1}^N$, Diffusion model $\epsilon_\phi$, Deterministic model $G_\theta$
    \STATE \textbf{Output:} Trained perturbation model $\epsilon_\phi$
    \FOR{each sample $x_0 \in \mathcal{D}$}
        \STATE $s \sim \text{Bernoulli}(0.5)$
        \IF{$s = 1$}
            \STATE $x_0 \gets G_\theta(x_0)$ \COMMENT{Advance sample through time}
        \ENDIF
        \STATE $t \sim \mathcal{U}\{1, \dots, T\}$
        \STATE  $\epsilon \sim \mathcal{N}(0, I)$
        \STATE $x_t = \sqrt{\bar{\alpha}_t} x_0 + \sqrt{1 - \bar{\alpha}_t} \epsilon$
        \STATE $g \sim \text{Bernoulli}(\lambda)$
        \IF{$g = 1$}
            \STATE $\hat{\epsilon} = \epsilon_\phi(x_t, c)$ \COMMENT{Use conditional input $c$}
        \ELSE
            \STATE $\hat{\epsilon} = \epsilon_\phi(x_t, \emptyset)$ \COMMENT{Use unconditional input}
        \ENDIF
        \STATE $\mathcal{L} = \|\hat{\epsilon} - \epsilon\|^2$
        \STATE $g \gets \nabla_\phi \mathcal{L}$
        \STATE $g \gets \frac{g}{\max(1, \|g\|_2 / \tau)}$ \COMMENT{Gradient norming with threshold $\tau$}
        \STATE $\phi \gets \phi - \eta \cdot g$
    \ENDFOR
\end{algorithmic}
\end{algorithm}


