\subsection{Numerical integration of the multi-dimensional PDE} \label{sec:amfr-w}
%\red{Anteriormente empleé el subindice $k$ para $k=1,\ldots,N$, y los subíndices $i,j$ para derivas y mixed terms, sería mejor mantener eso.}
In this section we design an appropriate and efficient numerical scheme for solving the PDE stated in Section \ref{sec:PDEsFMM}, when considering the lognormal model for volatilities. 

Taking into account the notation of the tenor structure for the swap, let us focus on the pricing of the swaption $T_1\times (T_N-T_1)$,
with payoff function
$$\varphi(R_1,\dots,R_N)= \max\left\{ \ds\sum_{k=2}^N P(T_1,T_k) \tau_k(R_k(T_1)-K), \,0\right\},$$
so the relative price $\Pi(t,R_1,\dots,R_N)$ satisfies the PDE \eqref{eq:PDEFMM} for $t\in [T_0,T_1]$ and the final condition
$$\Pi(T_1,R_1,\dots,R_N) = \dfrac{1}{P(T_1,T_0)}  \max\left\{ \ds\sum_{k=2}^N P(T_1,T_k) \tau_k(R_k-K), \,0\right\}.$$
%
In order to solve numerically this PDE problem, for simplicity we consider the following change of time variable and notations:
\begin{equation}\label{change1}
u(t,x_1,\dots,x_N)= \Pi(T_1-t,R_1,\dots,R_N),\quad t\in [0,T_1-T_0]=[0,\tau_1],\,x_k=R_k\ge 0.    
\end{equation}

Note that we are allowing a certain abuse of notation: we maintain the notation $t$, which initially represented physical time and hereafter represents the remaining time up to $T_1$. In this way the final condition at physical time $T_1$ becomes an initial condition in the PDE formulation in the new time variable. Numerical results in the next section will always refer to the physical time.
%

After the previously indicated change of time variable and notations, the PDE problem can be expressed as follows, find the function $u$, such that:
\begin{equation}\label{edpdimN}
\begin{array}{rl}
\dfrac{\partial u}{\partial t} =& \ds\sum_{k=1}^N \mu_k(t,x_1,\dots,x_k)\dfrac{\partial u}{\partial x_k}  + \ds\sum_{k=1}^N \delta_k(t,x_k)  \dfrac{\partial^2 u}{\partial x_k^2} \\[0.8pc]
 +& \ds\sum_{k=1}^{N-1} \ds\sum_{l=k+1}^N \varrho_{kl}(t,x_k,x_l) 
\dfrac{\partial^2 u}{\partial x_k\,\partial x_l}  ,
\end{array}
\end{equation}
for all $x_k>0$, where
%
\begin{equation}\label{coeff_edp}
\begin{array}{l}
 \mu_k(t,x_1,\dots,x_k)= \lambda_k(t) x_k \,\ds\sum_{j=1}^k \rho_{kj} \lambda_j(t) \dfrac{\tau_j}{1+\tau_j x_j} x_j,  \\[0.5pc]
 \delta_k(t,x_k)= \frac12 \lambda_k^2(t) x_k^2,\\[0.5pc]
 \varrho_{kl}(t,x_k,x_l) =\rho_{kl} \lambda_k(t) \lambda_l(t) x_k x_l,\\[0.5pc]
 \lambda_k(t)= \sigma_k(T_1-t) \gamma_k(T_1-t)=\left\{\begin{array}{ll}
 \sigma_1(T_1-t) \dfrac{t}{\tau_1}, & \hbox{ if } k=1 \\[0.5pc]
  \sigma_k(T_1-t), & \hbox{ if } k\ge 2, 
 \end{array}\right. ,\quad t\in [0,\tau_1],
\end{array}
\end{equation}
%
with initial condition
\begin{equation}\label{ini_N}
\begin{array}{l}
u(0,x_1,\dots,x_N)=u_0(x_1,\dots,x_N):=\max \{g(x_1,\dots,x_N),0\}, \\[0.5pc]
g(x_1,\dots,x_N)=\ds\sum_{k=2}^N \left( \ds\prod_{l=1}^k \dfrac{1}{1+\tau_l x_l} \right) \tau_k (x_k-K).
%\cancel{g(x_1,\dots,x_N)=\ds\sum_{j=2}^N \dfrac{1}{P(T_j,T_0)} \tau_j (x_j-K)} \\[0.5pc] 
%g(x_1,\dots,x_N)=\ds\dfrac{1}{P(T_1,T_0)}\sum_{j=2}^N P(T_1,T_j) \tau_j (x_j-K) .
\end{array}
\end{equation}
%

Note that the expression of $\lambda_k$ in (\ref{coeff_edp}) is valid for $t\in [0,\tau_1]$.

As usual, in financial problems initially posed in unbounded spatial domains, for the numerical integration of this PDE, the spatial domain must be restricted to a rectangle 
$(x_1,\dots,x_N)\in \Omega=(0,R_1^{max})\times \dots \times (0,R_N^{max})$, by selecting the values $\{R_k^{max}\}_{k=1}^N$  large enough. On the upper boundaries, a linear behavior of the solution is assumed by considering the conditions
\begin{equation}\label{bc_N}
\dfrac{\partial^2 u}{\partial x_k^2}(t,x_1,\dots,x_N) = 0 \quad \hbox{if } x_k=R_k^{max},\quad k=1,\dots,N,
\end{equation}
while, due to the degeneracy of the PDE at the boundaries $x_k=0$, no conditions are required at these boundaries.

Next, we propose a finite difference method to approximate the solution of the PDE problem \eqref{edpdimN}-\eqref{coeff_edp}-\eqref{ini_N}-\eqref{bc_N}. 
%
Firstly, a discretization of the spatial derivatives $u_{x_k},u_{x_k x_k},u_{x_k x_j}$ must be done. In order to build a spatial mesh, it must be taken into account that the payoff \eqref{ini_N} lacks differentiability at the points of $\Omega$ such that
\begin{equation}\label{areaint}
\tilde{g}(x_2,\dots,x_N):=\ds\sum_{k=2}^N \left( \ds\prod_{l=2}^k \dfrac{1}{1+\tau_l x_l} \right) \tau_k (x_k-K)=0,
\end{equation} 
%
so, as it is recommended in \cite[Chap. 4]{KarelintHout17} and the references therein, a non-uniform spatial mesh on each $x_k-$direction, for $k\ge 2$, results more convenient. Therefore, given $N$ positive integers $\{M_1,\dots,M_N\}$ we consider the spatial grid
\begin{equation}\label{mesh1}
\hspace{-2em}\begin{array}{rl}
\hbox{for } x_1:&   x_{1,j_1}=j_1 h_1,\quad 0\le j_1\le M_1, \quad h_1=\dfrac{R_1^{max}}{M_1},\\[0.5pc]
%
\hbox{for } x_k,\,k\ge 2:& x_{k,j_k}=K+L_k \sinh \xi_{k,j_k},\, 0\le j_k\le M_k, \,h_{k,j_k}= x_{k,j_k}-x_{k,j_k-1},  \\[0.5pc]
& \xi_{k,j_k}=\xi_k^{min} + j_k \Delta \xi_k,\quad \Delta \xi_k=\dfrac{\xi_k^{max}-\xi_k^{min}}{M_k}, \\[0.5pc]
 & \xi_k^{min} = \sinh^{-1} (-K/L_k), \quad \xi_k^{max}=\sinh^{-1} \left((R_k^{max}-K)/L_k\right),
\end{array}
\end{equation}
%
where the parameters $L_k$ measure the fraction of grid points that are closer to $K$. In this case, we will consider $L_k=K/10,\,\forall k\ge 2.$

In addition, a cell averaging technique is applied to smooth the payoff at the grid points close to the hyperplane defined by \eqref{areaint}, by adapting the technique proposed in \cite[Chap. 4]{KarelintHout17} for 1D-PDEs. In this case, for each subset of indices $(j_3,\dots,j_N)$, $0\le j_k\le M_k,\,k\ge 3,$ we compute the value
%$$\tilde{x}_2:= K-\dfrac{1}{\tau_2} S_3(x_{3,j_3},\dots,x_{N,j_N}),\quad S_3(x_3,\dots,x_N)= \ds\sum_{j=3}^N \left( \ds\prod_{k=3}^j  \dfrac{1}{1+\tau_k x_k}\right) \,\tau_j(x_j-K),$$
%
$$\tilde{x}_2:= K-\dfrac{1}{\tau_2} \ds\sum_{k=3}^N \left( \ds\prod_{l=3}^k  \dfrac{1}{1+\tau_l x_{l,j_l}}\right) \,\tau_k(x_{k,j_k}-K),$$
%
($\tilde{x}_2=K$ for $N=2$)  and look for the index $j_{ind}$, with $0\le j_{ind} \le M_2$, such that
$|x_{2,j_{ind}}-\tilde{x}_2| = \min_{0\le j_2\le M_2} |x_{2,j_2}-\tilde{x}_2|.$ Then, the cell $[x_2^-,x_2^+]$ is considered, where
$$x_2^-=\dfrac{x_{2,j_{ind}-1}+x_{2,j_{ind}}}{2},\quad x_2^+=\dfrac{x_{2,j_{ind}}+x_{2,j_{ind}+1}}{2},\quad \tilde{h}_2=x_2^+ -x_2^- ,
$$
and the initial condition at the points $(x_{1,j_1},x_{2,j_{ind}},x_{3,j_3},\dots,x_{N,j_N})$, for all $j_1=0,\dots,M_1$, is taken as the average over this cell $[x_2^-,x_2^+]$, that is,
$$\begin{array}{l}
u(0,x_{1,j_1},x_{2,j_{ind}},x_{3,j_3},\dots,x_{N,j_N})=\dfrac{1}{\tilde{h}_2} \ds\int_{x_2^-}^{x_2^+} u_0(x_{1,j_1},x_{2},x_{3,j_3},\dots,x_{N,j_N})\,dx_2 \\[0.8pc] 
\hspace{5em} =\dfrac{1}{\tilde{h}_2 (1+\tau_1 x_{1,j_1})} \left(  x_2^+ -\tilde{x}_2  - \left( K+ \dfrac{1-H_3}{\tau_2} \right)  \log \left( \dfrac{1+\tau_2 x_2^+}{1+\tau_2 \tilde{x}_2} \right) \right),
\end{array}$$
with
$$H_3 = \left\{ \begin{array}{ll}
0, & \hbox{ if } N=2, \\
%
\ds\sum_{k=3}^N \left( \ds\prod_{l=3}^k \dfrac{1}{1+\tau_l x_{l,j_l}} \right) \tau_k (x_{k,j_k}-K)  & \hbox{ if } N\ge 3. 
\end{array}\right. $$
%
%
%With this value, the cell $[x_2^-,x_2^+]$ is built with
%$$$$
%and 
%where
%$$\begin{array}{rl}
%\Gamma_{j_3,\dots,j_N}=&\dfrac{1}{\tilde{h}_2} \ds\int_{\tilde{x}_2}^{x_2^+} \dfrac{\tau_2 (x_2-K)}{1+\tau_2x_2} \,dx_2 + \dfrac{1}{\tilde{h}_2} S_3(x_{3,j_3},\dots,x_{N,j_N}) \ds\int_{\tilde{x}_2}^{x_2^+} \dfrac{dx_2}{1+\tau_2x_2}\\[0.8pc] 
%=&  \dfrac{1}{\tilde{h}_2} \left( x_2^+ -\tilde{x}_2 + \dfrac{1}{\tau_2} ( S_3(x_{3,j_3},\dots,x_{N,j_N}) -1-\tau_2K) \log\left(  \dfrac{1+\tau_2 x_2^+}{1+\tau_2 \tilde{x}_2} \right)  \right)
%\end{array}$$
%
On the other mesh points, the payoff function given in \eqref{ini_N} is applied.

Following the notation given in \cite[Sec. 3]{LopezPerezVazquez:sisc}, the grid points are rearranged as
$$\overline{\Omega}_h=\{ \vec{x}_J=(x_{1,j_1},\dots,x_{N,j_N}) \,:\, J=\vartheta_0(j_1,\dots,j_N),\,0\le j_k\le M_k, \,1\le k\le N\},$$ 
where the bijection $\vartheta_0: \, {\cal I}_N^{(0)} \rightarrow \{0,1,\dots,M-1\}$, with $M=\ds\prod_{k=1}^N (M_k+1)$ is defined as
$$\vartheta_0(x_{1,j_1},\dots,x_{N,j_N})= \ds\sum_{k=1}^N j_k E_k,\quad \mbox{with} \quad E_1=1,\,\,E_k=\ds\prod_{l=1}^{k-1} (M_l+1),\,k\ge 2 .$$
%
%
Because of the boundary conditions, the solution of the PDE on all the nodes (including the boundary points) of the spatial grid is unknown. 
Then, by approxi\-ma\-ting the spatial derivatives in the PDE by second-order central finite differen\-ces schemes on all the nodes of the spatial grid, for each $J=0,1,\dots,M-1$, $(j_1,\dots,j_N)=\vartheta_0^{-1}(J)$, we get
\begin{equation}\label{discret1}
\begin{array}{rl}
Y_J'=& \ds\sum_{k=1}^N \mu_k(t,x_{1,j_1},\dots,x_{k,j_k}) \nabla_J^{(k)} 
+ \ds\sum_{k=1}^N \delta_k(t,x_{k,j_k}) \Delta_J^{(k)}  \\[0.5pc]
&+ 
\ds\sum_{k=1}^{N-1} \ds\sum_{l=k+1}^N \varrho_{kl}(t,x_{k,j_k},x_{l,j_l}) \Delta_J^{(kl)}, 
\end{array}
\end{equation}
%
where the involved discrete operators are 
\begin{equation}\label{discret2}
\begin{array}{l}
\nabla_J^{(1)}=\dfrac{Y_{J+E_1}-Y_{J-E_1}}{2h_1},\quad \nabla_J^{(k)}=\beta_{j_k,-1}^{(k)} Y_{J-E_k}+\beta_{j_k,0}^{(k)} Y_J+ \beta_{j_k,1}^{(k)} Y_{J+E_k},\,\, k\ge 2, \\[0.5pc]
\Delta_J^{(1)}=\dfrac{Y_{J+E_1}-2Y_J+Y_{J-E_1}}{h_1^2} ,\\[0.5pc]
\Delta_J^{(k)}=\eta_{j_k,-1}^{(k)} Y_{J-E_k}+\eta_{j_k,0}^{(k)} Y_J+ \eta_{j_k,1}^{(k)} Y_{J+E_k},\, k\ge 2,\\[0.5pc]
\Delta_J^{(kl)}=\beta_{j_l,-1}^{(l)} \nabla^{(k)}_{J-E_l}+\beta_{j_l,0}^{(l)} \nabla^{(k)}_J+ \beta_{j_l,1}^{(l)} \nabla^{(k)}_{J+E_l},\,  l\ge k+1,
\end{array}
\end{equation}
%
%
with
\begin{equation}\label{diff_coef}
\begin{array}{ll}
\beta_{j_k,-1}^{(k)}=\dfrac{-h_{k,j_k+1}}{h_{k,j_k}(h_{k,j_k}+h_{k,j_k+1})}, &
\eta_{j_k,-1}^{(k)}=\dfrac{2}{h_{k,j_k}(h_{k,j_k}+h_{k,j_k+1})}, \\[0.5pc]
\beta_{j_k,0}^{(k)}=\dfrac{h_{k,j_k+1}-h_{k,j_k}}{h_{k,j_k}h_{k,j_k+1}}, &
\eta_{j_k,0}^{(k)}=\dfrac{-2}{h_{k,j_k}h_{k,j_k+1}}, \\[0.5pc]
\beta_{j_k,1}^{(k)}=\dfrac{h_{k,j_k}}{h_{k,j_k+1}(h_{k,j_k}+h_{k,j_k+1})}, &
\eta_{j_k,1}^{(k)}=\dfrac{2}{h_{k,j_k+1}(h_{k,j_k}+h_{k,j_k+1})}.
\end{array}
\end{equation}
%
%
%
It must be observed that, with this procedure, the spatial discretization is expanded to the borders. On the one hand, at the points of the ``right" borders the conditions \eqref{bc_N} have to be involved, so when $j_k=M_k$,  $\Delta_J^{(k)}=0$ is imposed. Therefore, virtual points $Y_{J+E_k}$ must be defined when $j_k=M_k$,
$$Y_{J+E_1}=2Y_J -Y_{J-E_1},\quad  Y_{J+E_k}= -\dfrac{\eta_{j_k,-1}^{(k)}}{\eta_{j_k,1}^{(k)}}  Y_{J-E_k} - 
\dfrac{\eta_{j_k,0}^{(k)}}{\eta_{j_k,1}^{(k)}}  Y_J,\,k\ge 2.
$$
%%
%
On the other hand, for each $k=1,\dots,N,$ on the boundary $x_k=0$, we get $\mu_k=\delta_k=0,\, \forall k,$ $\varrho_{kl}=0,\,\forall l\ge k+1$. As a consequence, $\nabla_J^{(k)}=\Delta_J^{(k)}=0,\, \forall k,$ $\Delta_J^{(kl)}=0,\,l\ge k+1,$ when $j_k=0$.

%
By grouping all the approximations in a vector $Y=(Y_J)_{J=0}^{M-1}$, these equations can be written as the initial value problem with a directional splitting
\begin{equation}\label{ivp2d}
\begin{array}{c}
Y'={\cal F}(t,Y)=\ds\sum_{k=0}^N {\cal F}_k(t,Y), \quad Y(0)=Y_0,\\
{\cal F}_k(t,Y)={\cal A}_k(t) Y,\quad k=0,1,\dots,N,\\
{\cal A}_1(t)= \lambda_1^2(t) \tilde{{\cal A}}_1 ,\quad {\cal A}_k(t) =\lambda_k^2(t) \tilde{{\cal A}}_k^{(1)}+\lambda_k(t) {\cal D}_k(t) \tilde{{\cal A}}_k^{(2)},\,\,k=2,\dots,N,\\
\end{array}
\end{equation}
%
where each $\F_k(t,Y)$ stores the components of the discretization of the advection and diffusion terms in the $x_k-$direction, for $k=1,\dots,N,$ and $\F_0(t,Y)$ stores those of the discretization of the mixed derivatives. In this case, $\tilde{{\cal A}}_1$, $\{\tilde{{\cal A}}_k^{(1)},\tilde{{\cal A}}_k^{(2)}\}_{k=2}^N$ are block tridiagonal constant matrices and ${\cal D}_k(t)$ is diagonal. For the sake of simplicity, the coefficients of these matrices are given in \ref{ap:matrixCoefs}.
%

Due to the increasing stiffness of \eqref{ivp2d} as the resolution of the spatial grid increases, explicit methods are not suitable for its time integration. On the other hand, fully implicit methods requiring the computation of the exact Jacobian of the derivative function are also unsuitable because of the complicated structure of the matrix ${\cal A}_0(t)$. Therefore, for the time integration of \eqref{ivp2d} a method from the class of AMFR-W-methods (\cite[Sec. 4]{GlezHairerHdezPerez18}, \cite{GlezHdezPerez21}) is applied. In particular, we have selected the one-stage AMFR-W1 method. More precisely, given an approximation $Y_n$ to the solution of \eqref{ivp2d} at the time $t=t_n$, this method approximates the solution at $t=t_{n+1}=t_n+\Delta t$ (with $\Delta t$ being the constant step of the time discretization) by 
\begin{equation}\label{amfrw1}
\begin{array}{rl}
K^{(0)}=& \Delta t \, {\cal F}(t_n,Y_n), \\
(I-\nu \Delta t \,  {\cal A}_k(t_n))K^{(k)}=& K^{(k-1)}+\nu (\Delta t )^2 \alpha_{k,n},\quad k=1,\dots,N, \\
\tilde{K}^{(0)}=& 2K^{(0)}+\theta (\Delta t)^2 G_n- (I-\theta \Delta t \, {\cal A}(t_n))K^{(N)}, \\
(I-\nu \Delta t \, {\cal A}_k(t_n))\tilde{K}^{(k)}=& \tilde{K}^{(k-1)}+\nu (\Delta t )^2 \alpha_{k,n},\quad k=1,\dots,N, \\
Y_{n+1}=& Y_n+ \tilde{K}^{(N)},
\end{array}
\end{equation}
where
$$\begin{array}{l}
{\cal A}(t_n)=\dfrac{\partial {\cal F}}{\partial Y}(t_n,Y_n)=\ds\sum_{k=0}^N {\cal A}_k(t_n),\\[0.8pc]
 \alpha_{k,n}=\dfrac{\partial {\cal F}_k}{\partial t}(t_n,Y_n), \,k=1, \dots, N, \quad G_{n}=\dfrac{\partial {\cal F}}{\partial t}(t_n,Y_n) ,
\end{array}
$$
%
with parameters $\theta=1/2$ and $\nu=\theta$ for $N=2,3$ and $\nu= \kappa_N N \,\theta$ for $N\ge 4$, where the values of $\kappa_N$ are given in \cite[Table 2]{GlezHairerHdezPerez18} and guarantee that the AMFR-W1 method is unconditionally stable on multi-dimensional linear constant coefficient PDEs with mixed derivatives. 

It must be observed that, due to the block tridiagonal structure of the matrices $\A_k(t),\,k=1,\dots,N$, the linear systems with coefficient matrix $(I- \nu \Delta t \, {\cal A}_k(t_n))$ of dimension $M$ in the method are decoupled in tridiagonal systems of dimension $M_k+1$, which drastically reduces their computational cost (see details in \ref{ap:matrixCoefs}). In addition, it is not necessary to compute the full Jacobian ${\cal A}(t_n)$ in \eqref{amfrw1}, which does not have a block structure that can reduce its computational cost, due to the presence of the discretization of the mixed derivatives. The product ${\cal A}(t_n) K^{(N)}$ in the right-hand side in the definition of $\tilde{K}^{(0)}$ in \eqref{amfrw1} is obtained by an additional evaluation of the derivative function, since
$${\cal A}(t_n) K^{(N)}= \left(\ds\sum_{k=0}^N \A_k(t_n) \right) K^{(N)} =\F(t_n,K^{(N)}).$$


\section{Numerical experiments} \label{sec:numericalExperiments}

In this section, we present some numerical results that correspond to several RFR swaptions to assess the correctness of the proposed numerical methods and the performance of the models. The selected swaptions aim to illustrate the behavior of the methodology when increasing the number of involved RFRs.

