\begin{theorem}[Bieberbach\cspace II]\label{thm - bieberbach II}
	Two abstract crystallographic groups are isomorphic if and only if there is an Euclidean space $E$ such that their affine realizations in $\aff(E)$ are conjugated by some affine motion in $E$.
\end{theorem}
