\begin{lemma}\label{lemma_the_prop_def_transla_crysp} 
	Let $W$ be a crystallographic group with translation group $T$ and point group $W_0$. Then $T$ is $\emptyset$-definable in $W$. More precisely, if $W_0$ has order $k$, then $T$ is definable by the first-order formula $\phi(x)\equiv \forall y ([x,y^k]=e)$.
\end{lemma}
\begin{proof}
	Let $p: W \rightarrow W_0$ be the canonical projection as in \ref{def - abstract crysp group}, and let $\phi(x)$ be as in the statement of the lemma. Denote by $\phi(W)$ the set of realizations of $\phi(x)$ in $W$. We claim that $T=\phi(W)$. The inclusion $[\subseteq]$ follows directly from the fact that $T$ is abelian, and $W/T\cong W_0$ has finite order $k$. Indeed, for each $w\in W$, in $W/T$ we have $w^kT=(wT)^k=T$, showing that $w^k \in T$.

	\smallskip\noindent
	Conversely, for the inclusion $[\supseteq]$, we argue by contradiction. Suppose there exists some $w \in W\setminus T$ such that $W\models \phi(w)$. Then, for each $t\in T$, we have:
	\begin{equation*}
		w(kt)w^{-1}(kt)^{-1}=[w,kt]=e.
	\end{equation*}
	\noindent
	It follows that:
	\begin{equation*}
		(kt)^w = kt.
	\end{equation*}
	Since $T$ is torsion-free, this implies that $t^w=t$, for all $t\in T$. In particular, by the definition of the action $\alpha:W_0\rightarrow\mathrm{Aut}(T)$, we have:
	\begin{equation*}
		\alpha(p(w))(t)=t^w=t,
	\end{equation*}
	\noindent
	for all $t\in T$. However, by the faithfulness of $\alpha$, $\alpha(p(w))$ is the identity on $T$ if and only if $p(w)= 1_{W_0}$, i.e., if $w\in T$. This contradicts the assumption $w\in W\setminus T$, completing the proof.
\end{proof}

We briefly recall a few notions and facts concerning $\mathbb{Z}[W_0]$-lattices, which we will need below. For further details, see \cite{plesken-holt}.

\begin{definition}[{\cite[Definition\cspace4.1.6, p.\cspace94]{plesken-holt}}]\label{same_genus}
	\begin{enumerate}[(i)]
		\item Let $W$ and $W'$ be crystallographic groups with translations subgroups $T(W)$, and $T(W')$, respectively. Then, we say that $W$ and $W'$ belong to the \emph{same genus} if $W/mT(W)\cong W'/mT(W')$ for all $m\in\N$.
		\item Let $W_0$ be a finite group and $L, L'$ be two $\mathbb{Z}[W_0]$-lattices. We say that $L$ and $L'$ belong to the \emph{same genus} (as $\mathbb{Z}[W_0]$-modules) if for every prime number $p$ and $k \in \mathbb{N}$ we have that $L/p^kL \cong L'/p^kL'$ as $\mathbb{Z}[W_0]$-modules.
	\end{enumerate}
\end{definition}
\begin{fact}[{\cite[Exercise\cspace1, p.\cspace96]{plesken-holt}}]\label{Exercise1}
	Let $W$ and $W'$ be crystallographic groups belonging to the same genus. Suppose that $P(W), P(W')$ are the point groups, and $L(W), L(W')$ are the translation lattices, of $W$ and $W'$, respectively. Then, after identifying their (isomorphic) point groups with a group $W_0$, $L(W)$ and $L(W')$ lie in the same genus as $\Z[W_0]$-lattices.     
\end{fact}
\begin{fact}[{\cite[Theorem\cspace4.1.8]{plesken-holt}}]\label{plesken_fact} Let $W_0$ be a finite group and $L, L'$ be two $\Z[W_0]$-lattices belonging to the same genus. Then, for every $m \in \mathbb{N}$ there is an injective $\mathbb{Z}[W_0]$-module homomorphism $\sigma: L' \rightarrow L$ such that the index $[L : \sigma\,( L')]$ is coprime~to~$m$.
\end{fact}
\begin{lemma}\label{lemma - every f.g. group el. equivalent to a crysp gp is crysp}
	Let $W$ be a crystallographic group, and $W'$ be a finitely generated group elementarily equivalent to $W$. Then, $W'$ is a crystallographic group with translation subgroup $\tranwone$ and point group $\pointwone$ such that the following hold:
	\begin{enumerate}[(1)]
	\item $\tranw\cong\tranwone$;
	\item $\pointw\cong\pointwone$;
	\item after identifying the (isomorphic) point groups with a group $W_0$, $L(W)$ and $L(W')$ lie in the same genus as $\Z[W_0]$-lattices.
\end{enumerate}	
\end{lemma}
\begin{proof}
	By Lemma\cspace\ref{lemma_the_prop_def_transla_crysp}, $\tranw$ is $\emptyset$-definable in $W$ by a first-order formula $\phi(x)$. Since $W\equiv W'$, it follows that $\phi(W')$ is normal in $W'$, and $W'/\phi(W') \cong P(W)$. Moreover, $\phi(W')$ is finitely generated, as it is normal of finite index in $W'$, which is finitely generated by assumption. Finally, $\phi(W) $ and $\phi(W')$ are elementarily equivalent, and hence $\phi(W) \cong \phi(W')$, since finitely generated free abelian groups are well known to be first-order rigid.
