	\end{equation*} 
	\noindent
	It follows that $\alpha':W'/\tranwone\rightarrow \mathrm{Aut}(\tranwone)$ is injective, since $W'$ is elementarily equivalent to $W$ by assumption. Therefore, by Definition\cspace\ref{def - abstract crysp group}, $W'$ is crystallographic with translation subgroup $\tranwone=\phi(W')$ and point group $\pointwone=W'/\tranwone\cong \pointw$. This completes the proof of (1) and (2).

	\smallskip\noindent
	Concerning (3), let $T,L$ and $T',L'$ denote the translation subgroups and translation lattices of $W$ and $W'$, respectively. Identifying their isomorphic point groups with a finite group $W_0$, $L$ and $L'$ are naturally $\Z[W_0]$-lattices (cf. item (2) of this lemma). We claim that $L$ and $L'$ belong to the same genus as $\Z[W_0]$-lattices. Indeed, by Lemma~\ref{lemma_the_prop_def_transla_crysp}, there exists a $\emptyset$-definable formula whose solution set in $W$ (respectively $W'$) is the translation lattice $L$ (respectively $L'$). Thus, the conditions $W/mL\cong W'/mL'$, for $m\in\N$, are first-order expressible. Since $W'\equiv W$, it follows that $W$ and $W'$ belong to the same genus. Therefore, by Fact \ref{Exercise1}, $L, L'$ belong to the same genus as $\mathbb{Z}[W_0]$-lattices.
\end{proof}
\begin{theorem}\label{thm - finitely many centerings -> split profinite rigidity}
	Let $W$ be a crystallographic group with translation subgroup $\tranw$ and point group $\pointw$, and let $W'$ be a finitely generated group elementarily equivalent to $W$. Suppose that there are finitely many subgroups $N_0,\ldots,N_{k-1}$ {of $\tranw$ such that:}
	\begin{enumerate}[(a)]
		\item $N_i\trianglelefteq W$, and $[\tranw:N_i]<\infty$ for all $i<k$;
		\item every subgroup $N$ of $\tranw$ that is normal in $W$ is a multiple $\ell N_i$ of $N_i$, for some $i<k$ and $\ell\in\N$.
	\end{enumerate}
	\noindent
	Then, the following holds:
	\begin{enumerate}[(1)]
		\item identifying $\pointw$ and $\pointw'$ with $W_0$, $\lattw\cong\lattwone$ as $\Z[W_0]$-lattices;
		\item if in addition $W$ is split, then $W \cong W'$ (so $W$ is profinitely rigid).
	\end{enumerate}
\end{theorem}
\begin{proof}
	Item (2) follows from (1) and a direct argument, see e.g. \cite[Section~3]{paolini-sklinos}. We prove item (1): the argument is essentially as in \cite[Theorem~3.17]{paolini-sklinos}. By Lemma\cspace\ref{lemma - every f.g. group el. equivalent to a crysp gp is crysp}, $W'$ is also crystallographic, with $\tranw\cong\tranwone$ and $\pointw\cong\pointwone$. For ease of notation, let $T,L$ and $T',L'$ the translation subgroups and translation lattices of $W$ and $W'$, respectively. Identifying $P(W)$ and $P(W')$ with a common finite group $W_0$, again by \ref{lemma - every f.g. group el. equivalent to a crysp gp is crysp}, we have that $L, L'$ belong to the same genus \mbox{as $\mathbb{Z}[W_0]$-lattices.}

	\smallskip\noindent
	We now show that, under the additional assumptions of the present theorem, $L$ and $L'$ are isomorphic as $\mathbb{Z}[W_0]$-lattices. By assumption ($a$), the order $m_i\vcentcolon=[T:N_i]$ is finite, for all $i<k$. Hence, there exists a non-negative integer $m$ such that:
	\begin{equation*}
		m=\prod_{1<k}m_i.
	\end{equation*}
	\noindent
	Since $L$ and $L'$ belong to the same genus as $\Z[W_0]$-lattices, it follows from Fact\cspace\ref{plesken_fact} that there exists an injective $\Z[W_0]$-module homomorphism $\sigma: L' \rightarrow L$ such that the index $[T: \sigma (T')]$ is coprime to $m$. In particular, $\sigma(L')$ is a submodule of $L$, i.e., $\sigma(T')$ is stable under the action of the point group of $W$. Therefore, $\sigma(T')$ is a normal subgroup of $W$. By assumption ($b$), this implies that there are some $\ell\in\N$ and $j<k$ such that $\sigma(T') = \ell N_j$. We distinguish two cases.
	\begin{itemize}
		\item[\underline{Case 1}:] If $N_j=T$, then $\sigma(T')=\ell T$ and $\sigma:L'\rightarrow \ell L$ is an isomorphism of $\Z[W_0]$-lattices. Observe that if $\ell=0$ the thesis is immediate, as both $L$ and $L'$ are trivial. Otherwise, for $\ell\neq 0$, the function:
		\begin{equation*}
			\tau_\ell:L\rightarrow \ell L, \quad x\mapsto \ell x,
		\end{equation*}
		\noindent
		is naturally an isomorphism of $\Z[W_0]$-lattices, since $T$ is supposed to be torsion-free and the action of $W_0$ on $T$ is linear. Therefore, the composition $\sigma^{-1}\circ\tau_\ell$ witnesses that $L$ and $L'$ are isomorphic $\Z[W_0]$-lattices. 

		\item[\underline{Case 2}:] If $N_j\neq L$, then $[T:N_j] = m_j>1$. However, since:
		\begin{equation*}
			[T:\sigma(T')]=[T:\ell N_j]=[T:N_j]\cdot [N_j:\ell N_j]=m_j\ell^n,
		\end{equation*}
		\noindent
		this leads to a contradiction, as $[T:\sigma(T')]$ was supposed to be \mbox{coprime to $m$.}
	\end{itemize}
\end{proof}

\section{Centering conditions}\label{sec4}
%In this section, we will show that assumption ($a$) and ($b$) of Theorem\cspace\ref{thm - finitely many centerings -> split profinite rigidity} have a natural reformulation in terms of $\Z[W_0]$-lattices.
In this section, we follow \cite{plesken-pohst} and show how to adapt it to our context.
\begin{definition}\label{def - centering of a Z[G]-repr module}
	Let $W_0$ be a finite group and $L$ be a $\Z[W_0]$-lattice. Then, a \emph{centering} of $L$ is a submodule $C$ of $L$ of finite index.
\end{definition}
A subgroup $C$ of a free abelian group $T$ of finite rank $n$ is itself free abelian of rank $m\leq n$, with the equality $m=n$ realized if and only if $C$ has finite index in $T$. Therefore, for any finite group $W_0$, we can equivalently characterize the centerings of a $\Z[W_0]$-lattice $L$ as the sublattices of maximal rank in $L$.

\smallskip 
Let $W_0$ be a finite group. There is a canonical correspondence assigning to each $\Z[W_0]$-lattice $L$ an integral representation $\alpha_L : W_0 \to \mathrm{GL}_n(\Z)$, where $n = \mathrm{rank}_\mathbb{Z}(L)$. Under this correspondence, two $\Z[W_0]$-lattices $L$ and $L'$ are isomorphic if and only if the associated representations $\alpha_L$ and $\alpha_{L'}$ are equivalent, i.e., if they are conjugate in $\mrm{GL}_n(\mathbb{Z})$. Moreover, $W_0$ acts faithfully on $L$ if and only if the corresponding representation $\alpha_L$ is faithful. We will often pass from one perspective to the other.

\smallskip 
Any integral representation $\alpha_L: W_0 \to \mathrm{GL}_n(\Z)$ naturally extends to a rational representation via the inclusion of $\mathrm{GL}_n(\Z)$ in $\mathrm{GL}_n(\Q)$. It is thus natural to associate to the $\Z[W_0]$-lattice $L$ a $\Q[W_0]$-module $\Q L$ that extends $L$ by allowing $\Q$-scalar multiplications. The rational representation associated to $L$ can then be viewed as arising from the action of $W_0$ on $\Q L$. Formally, we define:
\begin{definition}{\cite[\S\phantom{.}73, Ch.\phantom{.}XI]{representation_theory_book}}\label{def.-QL}
	%p.\cspace495
	Let $W_0$ be a finite group and $L$ be a $\Z[W_0]$-lattice. Suppose $W_0=\{w_i:i<k\}$ is an enumeration without repetition of $W_0$. Then, $\Q L$ is the $\Q[W_0]$-module with domain $\Q\otimes_\Z L$, and $\Q[W_0]$-scalar multiplication:
	\begin{equation*}
		r.(h\otimes x)=\sum_{i < k}q_ih\otimes w_i.x,
	\end{equation*}
	\noindent
	for all $r\in \Q [W_0]$, $x\in L$, and $h,q_0,\ldots,q_{k-1}\in\Q$ such that $r=\sum_{i<k}q_iw_i$.
\end{definition}
\begin{fact}{\cite[\S\phantom{.}73, Ch.\phantom{.}XI]{representation_theory_book}}\label{remark - QL}
	In the context of Definition\cspace\ref{def.-QL}, the $\Q[W_0]$-module $\Q L$ naturally inherits the structure of a $\Q$-vector space, where the $\Q$-scalar multiplication is defined by:
	\begin{equation*}
		q.(h\otimes x)=q1.(h\otimes x)=q h\otimes x,
	\end{equation*}
	\noindent
	for all $q,h\in\Q$, and $x\in L$. If $\{x_i:i<n\}$ is a free abelian basis of $L$, then $\{1\otimes x_i:i<n\}$ forms a basis of $\Q L$ as a $\Q$-vector space. In particular, the dimension of $\Q L$ over $\Q$ equals the rank of $L$ as a free abelian group.
	%\item In the context of \emph{Definition\cspace\ref{def. QM}}, let $M_{\Q L}$ be the $\Z[W_0]$-module structure on $(\Z^\times\times L)/_\sim$ induced by $\Q L$ (i.e., in model-theoretic terms $M_{\Q L}$ is the reduct of $\Q L$ to the language of $\Z[W_0]$-modules). Then, $L$ naturally embeds in $\Q L$ via the homomorphism:
	%\begin{equation*}
	%	\mu: L\rightarrowtail \Q L, \quad\text{s.t.}\quad x\mapsto[1,x],
	%\end{equation*}
	%\noindent
	%called \emph{canonical embedding} of $L$.
	%\end{enumerate}.
\end{fact}
%Notice that also $\Q M$ is a lattice, as if $\{m_0,\ldots,m_{n-1}\}$ is a basis of $M$, then $\{1\otimes m_0,\ldots,1\otimes m_{n-1}\}$ is a basis of $\Q M$.
%One of the first useful features that we might notice of a $\Q$-expansion $\Q L$ as above is that it is still \say{comparable} in dimension with the original module $L$. Moreover, $L$ canonically embeds in $\Q L$ as a $\Z[W_0]$-submodule. Conversely, any $\Q[W_0]$-module is essentially of this form, i.e., the $\Q$-expansion of some $\Z[W_0]$-submodule. The next remark formalizes these observations.
\begin{definition}{\cite[Section\phantom{.}2]{plesken-pohst}}\label{def. Z/Q-equivalence}
		% pg.\cspace537	
	Let $W_0$ be a finite group, and $L,L'$ be $\Z[W_0]$-lattices. Then, we say that $L$ and $L'$ are:
	\begin{enumerate}[(1)]
		\item $\Z$\emph{-equivalent}, and we write $L\sim_\Z L'$, if\, $L\cong L'$ (as $\Z[W_0]$-lattices);
		\item $\Q$\emph{-equivalent}, and we write $L\sim_\Q L'$, if\, $\Q L \cong \Q L'$ (as $\Q[W_0]$-modules).
	\end{enumerate}
\end{definition}
As mentioned above, in the language of representation theory, item\cspace$(1)$ in \ref{def. Z/Q-equivalence} corresponds to saying that the associated integral representations $\alpha_L$ and $\alpha_{L'}$ are equivalent, i.e., that there exists an invertible \mbox{matrix $A\in\mathrm{GL}_n(\Z)$ such that:}
\begin{equation*}
	\alpha_L(w)=A\alpha_{L'}(w)A^{-1},
\end{equation*}
\noindent
for all $w\in W_0$ (cf.\cspace\cite[Definition\cspace73.2, Ch.\phantom{.}XI]{representation_theory_book}). Similarly, item\cspace$(2)$ in \ref{def. Z/Q-equivalence} is equivalent to the representations $\alpha_L$ and $\alpha_{L'}$ being conjugate in $\mathrm{GL}_n(\Q)$ (cf. \cite[Definition\cspace73.1, Ch.\phantom{.}XI]{representation_theory_book}).

\smallskip
Clearly, $\Z$-equivalence implies $\Q$-equivalence, but the converse does not generally hold (cf. \cite[\S\phantom{.}73, Ch.\phantom{.}XI]{representation_theory_book}).
%p.\cspace494-495
For example, consider the case where $W_0=\Z_2 = \mathbb{Z}/2\mathbb{Z}$, and let $L,L'$ be the $\Z[W_0]$-lattices on $\Z^2$ induced by the representations:
\begin{equation*}
	\alpha:\bar{1}\mapsto\begin{pmatrix}
		1&0\\
		0&-1
	\end{pmatrix}\quad\text{and}\quad \alpha':\bar{1}\mapsto \begin{pmatrix}
		1 & 1\\
		0 & -1
	\end{pmatrix},
\end{equation*}
\noindent
respectively. Then $L\sim_\Q L'$, but $L\not\sim_\Z L'$, as the matrices $\alpha(\bar{1})$ and $\alpha'(\bar{1})$ are conjugate in $\mathrm{GL}_2(\Q)$, yet not in $\mathrm{GL}_2(\Z)$.
\begin{lemma}{\cite[Section\phantom{.}2]{plesken-pohst}}\label{lemma every centering is Q-equivalent to the ambient module}
	%p.\cspace537
	Let $W_0$ be a finite group and $L$ be a $\Z[W_0]$-lattice. Then, every centering $C$ of $L$ is $\Q$-equivalent to $L$.
\end{lemma}
\begin{proof}
	Since $C$ is a submodule of $L$, the inclusion $C \subseteq L$ induces a natural embedding of $\Q[W_0]$-modules $\delta: \Q C \rightarrowtail \Q L$. We claim that this embedding is in fact an isomorphism.

	\smallskip\noindent
	By assumption, $C$ has finite index in $L$, and hence it is a free abelian group of the same rank as $L$. Consequently, by Remark\cspace\ref{remark - QL}, the $\Q$-vector spaces on $\Q C$ and $\Q L$ have the same finite dimension. Since the map $\delta$ is clearly $\Q$-linear and injective, it follows that $\delta$ is also surjective. We conclude that $\Q C \cong \Q L$, and therefore 
	$C \sim_\Q L$, as required.
\end{proof}
By the preceding discussion, for a fixed finite group $W_0$, each $\Q$-equivalence class of $\Z[W_0]$-lattices decomposes into a disjoint union of $\Z$-equivalence classes. Lemma\cspace\ref{lemma-there are only finitely many Z-equivalence classes}, which is an instantiation of the Jordan-Zassenhaus Theorem (cf.\cspace\cite[Theorem~79.1, Ch.\phantom{.}XI]{representation_theory_book}) in the context of $\Z[W_0]$-lattices, guarantees that this decomposition yields only finitely many distinct $\Z$-equivalence classes. We will need the following basic fact from \cite{plesken-pohst}.
\begin{fact}{\cite[Section\phantom{.}2]{plesken-pohst}}\label{fact-every_Q-equivalent_lattice_is_Z-equivalent_to_a_center}
	%p.\cspace537
	Let $W_0$ be a finite group, and $L,L'$ be $\Z[W_0]$-lattices. If $L\sim_\Q L'$, then there exists a centering $C$ of $L$ such that $C\sim_\Z L'$.
\end{fact}
\begin{lemma}\label{lemma-there are only finitely many Z-equivalence classes}
	Let $W_0$ be a finite group, and $L$ be a $\Z[W_0]$-lattice. Then, the $\Q$-equivalence class of $L$ splits into finitely many disjoint $\Z$-equivalence classes.
\end{lemma}
\begin{proof}
	By the Jordan-Zassenhaus Theorem (see~\cite[\S\phantom{.}79,\phantom{.}Ch.\phantom{.}XI]{representation_theory_book}), \mbox{the set of all} $\Z[W_0]$-lattices $L'$ such that $L' \subseteq \Q L$ and $L' \sim_\Q L$ decomposes into finitely many $\Z$-equivalence classes. Thus, it suffices to observe that, by Fact\cspace\ref{fact-every_Q-equivalent_lattice_is_Z-equivalent_to_a_center}, every $\Z[W_0]$-lattice $\Q$-equivalent to $L$ is isomorphic to some centering $C$ of $L$. Since, by Lemma\cspace\ref{lemma every centering is Q-equivalent to the ambient module}, every such centering is itself $\Q$-equivalent to $L$, the claim follows immediately.
\end{proof}

A $\Z[W_0]$-lattice $L$ always admits infinitely many centerings. Indeed, if $C$ is a centering of $L$, then the infinite descending chain
\begin{equation*}
	C\geq 2C\geq 3C\geq\cdots
\end{equation*}
\noindent
consists entirely of centerings of $L$, since, for every $k\in\N^+$, the map $x\mapsto kx$ defines an isomorphism $C\rightarrow kC$. This observation implicitly suggests the following notion, already considered in \cite[Section\phantom{.}2]{plesken-pohst}.
\begin{definition}\label{def. - order centerings}
	Let $W_0$ be a finite group, and let $L$ be a $\Z[W_0]$-lattice. We define:
	\begin{enumerate}[(1)]
		\item $\mathcal{C}(L)$ to be the set of all centerings of $L$;
		\item a partial order $\prec$ on $\mathcal{C}(L)$, given by
		\begin{equation*}
			C\prec C' \quad\text{if and only if}\quad \exists \lambda\in\Z\quad\text{such that}\quad C=\lambda C',
		\end{equation*}
		\noindent
		for all $C,C'\in\mathcal{C}(L)$.
	\end{enumerate}
\end{definition} 
%It shows that the $\Z$-equivalence is preserved under the relation $\prec$, so that any $\prec$-chain in $\mathcal{C}(L)$ entirely lays in the same $\Z$-equivalence class. Moreover, any $\prec$-chain has a maximum, and these maxima can be explicitly characterized in terms of the free abelian bases of $A_L$. Hence, we can use them as natural representatives for the $\Z$-equivalence classes. 
\begin{fact}{\cite[Section\phantom{.}2]{plesken-pohst}}\label{lemma - properties order centerings}
	%p.\cspace537
	Let $W_0$ be a finite group and $L$ be a $\Z[W_0]$-lattice. Then, the following hold:
	\begin{enumerate}[(1)]
		\item for all $C,C'\in\mathcal{C}(L)$, $C\sim_\Z C'$ whenever $C\prec C'$;
		\item for each $C\in\mathcal{C}(L)$, there exists a unique $\prec$-maximal centering $\overline{C}\in\mathcal{C}(L)$ such that $C\prec \overline{C}$.
	\end{enumerate}
\end{fact}

	It may happen that two distinct $\prec$-maximal centerings $C$ and $C'$ in $\mathcal{C}(L)$ are $\Z$-equivalent while remaining $\prec$-incomparable. Consequently, the number of $\Z$-equivalence classes (which is finite by \ref{lemma-there are only finitely many Z-equivalence classes}) does not necessarily bound the number of $\prec$-maximal centerings of a given $\Z[W_0]$-lattice. We will see that this phenomenon does not occur when the $\Z[W_0]$-lattice $L$ is in addition an \emph{absolutely irreducible} module. %, where stronger structural constraints ensure comparability within $(\mathcal{C}(L),\prec)$.
%For instance, this is the case of lattices of the cyclic group $C_p$ of prime order $p\geq 23$\todo{Give more details.}
\smallskip\noindent
First, we fix some module-theoretic terminology.
\begin{definition}
	Let $Q$ be a ring (with unity). \mbox{Then a $Q$-module $M$ is said to be:}
	\begin{enumerate}[(1)]
		\item \emph{irreducible} $($or \emph{simple}$)$, if $M$ admits only trivial submodules, i.e., for every submodule $N$ of $M$ either $N=\{0\}$ or $N=M$;
		\item \emph{decomposable} if there exist two non-trivial submodules $N_0$ and $N_1$ of $M$ such that $M=N_0\oplus N_1$;
		\item \emph{indecomposable} if it is not decomposable.
	\end{enumerate}
\end{definition}

Clearly, if a $Q$-module is irreducible, then it is also indecomposable. In the case of $Q$ being the group algebra $K[W_0]$ of a finite group $W_0$ over a field $K$ of characteristic $0$, the converse is also true, as a consequence of a classic result by Maschke (cf. \cite[Proposition\phantom{.}2, Ch.\phantom{.}V, Annexe]{bourbaki} or \cite[Theorem\phantom{.}10.8, Ch.\phantom{.}II]{representation_theory_book}).

\begin{definition}{\cite[\S\phantom{.}29, Ch.\phantom{.}IV]{representation_theory_book}}\label{def - absolutely irreducible module}
	Let $W_0$ be a finite group and $M$ be a $\Q[W_0]$-module. Suppose that $W_0=\{w_i:i<k\}$ is an enumeration {without repetition of $W_0$.} %Then,
	\begin{enumerate}[(1)]
		\item For every field extension $K$ of $\Q$, we define the $K[W_0]$-module $K M$ as follows\footnote{Various notations are used in the literature: this $K[W_0]$-module is denoted $M^K$ in \cite[\S\phantom{.}29, Ch.\phantom{.}IV]{representation_theory_book}, and $M_{(K)}$ in \cite[\S\phantom{.}8.1, Ch.\phantom{.}II]{bourbaki algèbre}. Here,
		%for the ease of reading, 
		we adopt $K M$ to preserve consistency with Definition\cspace\ref{def.-QL}.}:
		\begin{enumerate}[(i)]
			\item the underlying abelian group is $K\otimes_\Q M$, where the tensor product is computed with respect to the natural $\Q$-vector space structure on $M$;
			\item the $K[W_0]$-scalar multiplication is given by
			\begin{equation*}
				r.\left(\sum_{j<m}b_j\otimes x_j\right)=\sum_{\overset{i<k}{j<m}}a_ib_j\otimes w_i.x_j,
			\end{equation*}
			\noindent
			for all $r\in K [W_0]$, $x_0,\ldots,x_{m-1}\in M$, and $a_0,\ldots,a_{k-1},b_0,\ldots,b_{m-1}\in K$ such that $r=\sum_{i<n}a_iw_i$.
		\end{enumerate}
		\item The module $M$ is said to be \emph{absolutely irreducible} if $K M$ is irreducible for every field extension $K$ of $\Q$.
		%\item $L$ is said to be \emph{absolutely irreducible} if $K L$ is irreducible, for every field extension $K$ of $\Q$.
	\end{enumerate} 
\end{definition}
\begin{definition}\label{def - absolutely irreducible lattice}
	Let $W_0$ be a finite group. A $\Z[W_0]$-lattice $L$ is said to be \emph{absolutely irreducible} if $\Q L$ is absolutely irreducible as a $\Q[W_0]$-module. In particular, for every field extension $K$ of $\Q$, the tensor product defining $K L$ is computed with respect to the $\Q$-vector space structure on $\Q L$ from Fact\cspace\ref{remark - QL}. A crystallographic group $W$ with point group $W_0$ and translation lattice $L$ is said to be \emph{absolutely irreducible} if $L$ is absolutely irreducible (as a $\Z[W_0]$-lattice).
\end{definition}
\noindent 
%The main advantage of considering absolutely irreducible modules is that in this case we have a deep comprehension of the endormorphism group, which is actually the simplest possible: $\mathrm{End}(M)\cong \Q$. More precisely, the following equivalence holds.
%\begin{fact}{\cite[Theorem\cspace29.13, pg.\cspace202]{representation_theory_book}}\label{fact. - absolutely irreducible iff every endomorphism is an homothety}
%Let $W_0$ be a finite group. Then, an irreducible $\Q[W_0]$-module $M$ is absolutely irreducible if and only if every endomorphism of $M$ is a left% multiplication by an element of $\Q$. 
%\end{fact}
%\noindent
%This property allows to prove the next fundamental result.
\begin{lemma}\label{thm. - absolutely irreducible -> there are only finitely many maximal centerings}
	Let $W_0$ be a finite group and $L$ be an absolutely irreducible $\Z[W_0]$-lattice. Then there are only finitely many maximal centerings of $L$.
\end{lemma}
\begin{proof}
	 By \cite[Theorem\cspace2.1]{plesken-pohst}, the $\prec$-maximal centerings of $L$ form a complete set of representatives for the $\Z$-equivalence classes contained in the $\Q$-equivalence class of $L$. Moreover, by Lemma\cspace\ref{lemma-there are only finitely many Z-equivalence classes}, there are only finitely many such $\Z$-equivalence classes. Therefore, it suffices to show that any two distinct $\prec$-maximal centerings $\overline{C}$ and $\overline{C}'$ of $L$ cannot be $\Z$-equivalent. The case $L=\{0\}$ is trivial. If $L\neq\{0\}$, suppose for contradiction that there exists an isomorphism of $\Z[W_0]$-modules $\sigma:\overline{C}\rightarrow\overline{C}'$. Identifying $\Q\overline{C}$ and $\Q\overline{C}'$ with $\Q L$ via the isomorphisms induced by the inclusions $\overline{C},\overline{C}'\leq L$, this map linearly extends to a $\Q[W_0]$-module endomorphism $\bar{\sigma}$ of $\Q L$.

 	\smallskip\noindent
 	Since $\Q L$ is absolutely irreducible, it follows from \cite[Theorem\cspace29.13, Ch.\phantom{.}IV]{representation_theory_book} that $\bar{\sigma}$ is a scalar multiplication by some rational number. In particular, this means that there exist $\alpha\in\Z$ and $\beta\in\Z^\times$ such that $\beta\sigma(x)=\alpha x$ for all $x\in \overline{C}$. Hence:
	\begin{equation*}
		\alpha \overline{C}=\beta\sigma(\overline{C})=\beta\overline{C}'.
	\end{equation*}
	\noindent
	Let $C\vcentcolon=\beta\overline{C}'$. Clearly, $C$ is a centering satisfying $C\prec\overline{C}'$, by definition. Since $C$ has maximal rank, we must have $\alpha\neq0$, as otherwise $L$ would be trivial. Therefore, the identity $C=\alpha\overline{C}$ witnesses that $C\prec\overline{C}$. However, this contradicts Fact\cspace\ref{lemma - properties order centerings}{(2)}, as $C\prec \overline{C}'$ and $\overline{C},\overline{C}'$ are assumed to be distinct.
\end{proof}
We can now restate Theorem\cspace\ref{thm - finitely many centerings -> split profinite rigidity} in this terminology as follows:
\begin{theorem}\label{theorem}
	Let $W$ be a crystallographic group with translation subgroup $\tranw$ and point group $\pointw$. Suppose that $W'$ is a finitely generated group elementarily equivalent to $W$. If $\lattw$ admits only finitely many $\prec$-maximal centerings, then:
	\begin{enumerate}[(1)]
		\item after identifying $\pointw$ and $\pointw'$ with a common finite group $W_0$, $\lattw\cong\lattwone$ as $\Z[W_0]$-lattices;
		\item if, in addition, $W$ is split, then $W \cong W'$. In particular, $W$ is profinitely rigid.
	\end{enumerate}
\end{theorem}

    \begin{corollary}\label{cor_asb_irr_rigid}  Absolutely irreducible split crystallographic groups are profinitely rigid (equiv. first-order rigid).
\end{corollary}

    \begin{proof} This is by \ref{thm. - absolutely irreducible -> there are only finitely many maximal centerings} and \ref{theorem}.
    \end{proof}
%Theorem\cspace\ref{theorem} clarifies the relevance of the following notion for the problem of profinite rigidity.
%\begin{remark}
%	Let $\{W_i:i<m\}$ be a finite set of absolutely irreducible crystallographic groups with point group $P(W_i)$ and translation lattice $L(W_i)$ for all $i<m$. Then, the direct product $W=\prod_{i<m}W_i$ is a crystallographic group with:
