\begin{fact}{\cite[Theorem\cspace2.2]{oger-lasserre}}\label{fact - lasserre}
	Let $G$ and $H$ be elementarily equivalent polycyclic-by-finite groups. If $G$ admits a decomposition of the form $G\cong \prod_{i\in[1,k]}G_{i}$, then there exists a decomposition $H\cong \prod_{i\in[1,k]}H_i$ of $H$ \mbox{such that $H_i\equiv G_i$ for all $i\in[1,k]$.}
\end{fact}
\begin{lemma}\label{lemma_direct_products}
	Suppose that $G\cong \prod_{i\in[1,k]}G_i$ is a finitely generated abelian-by-finite group. If, for every $i\in[1,k]$, $G_i$ is first-order rigid, then $G$ is first-order rigid.
\end{lemma}
\begin{proof}
	Let $H$ be a finitely generated group elementarily equivalent to $G$. Then $H$ is also abelian-by-finite. In particular, both $G$ and $H$ are polycyclic-by-finite. By Fact\cspace\ref{fact - lasserre}, there exists a decomposition $H\cong\prod_{i\in[1,k]}H_i$, with $H_i\equiv G_i$ for all $i\in[1,k]$. Each factor $H_i$ is finitely generated, and hence $H_i\cong G_i$ for all $i\in[1,k]$. Consequently, $G\cong H$.
\end{proof}
\begin{theorem1.1}
	\emph{Finite direct products of absolutely irreducible split crystallographic groups are profinitely rigid (equiv. first-order rigid).}
\end{theorem1.1}
\begin{proof}
