\section{Root systems and Weyl groups}
%Root systems and Weyl groups are arguably some of the most important tools in modern Lie Theory. Several fundamental problems in this subject\todo{such as the classification of semi-simple Lie algebras}, and the related areas of Mathematics, reduce to computations on these objects and their interaction.
In this section, we present some basic notions on root systems and their symmetries that we will need in the following. Detailed introductions to the subject can be found in \cite{bourbaki, humphreys_1}.

In Section\cspace\ref{sec6}, we will employ some computations from \cite{martinais}, where Bourbaki's framework from \cite{bourbaki} is adopted. So, for the reader's convenience, we will maintain consistency with \cite{martinais} and
%mainly refer to
primarily follow \cite{bourbaki}.

\smallskip
Throughout this section, we adopt the following notational conventions.
\begin{notation}\label{notation - root systems}
	Let $K$ be a field extending $\Q$, and $V$ be a finite-dimensional vector space over $K$. Then:
	%, we adopt the following notational conventions:
	\begin{enumerate}[(1)]
		%\item $K$ denotes a field of characteristic $0$ such that $\Z\subseteq K$;
		%\item $V$ denotes a $K$-vector space of finite dimension $l$;
		\item $V^*$ denotes the dual space of $V$, i.e., the $K$-vector space consisting of all $K$-linear maps from $V$ to $K$;
		\item given a subring $Q$ of $K$ and a subset $X\subseteq V$, we write $\langle X\rangle_Q$ for the $Q$-span of $X$ in $V$, i.e., the smallest $Q$-submodule of $V$ containing $X$.
	\end{enumerate}
\end{notation}
\begin{definition}\label{def - reflection}
	Let $V$ be a vector space of dimension $l$ over a field $K$ extending $\Q$. Then, a \emph{reflection} in $V$ is an automorphism $s\in\mathrm{GL}(V)$ which is both:
	\begin{enumerate}[(1)]
		\item a \emph{pseudo-reflection}, i.e., the subspace $\mathrm{ker}(1-s)$ has dimension $l-1$;
		\item an \emph{involution}, i.e., $s^2=1$.
	\end{enumerate}
We sometimes say {\em affine reflection}, to stress that we are considering $s \in \mathrm{GL}(V)$.
\end{definition}

Notice that any choice of a non-zero vector $a\in V$ and a non-trivial $K$-linear form $\alpha^*\in V^*$ yields a pseudo-reflection $s_{a,\alpha^*}$ of the following form:
\begin{equation*}
	s_{a,\alpha^*}(x)\vcentcolon=x-\alpha^*(x).a,
\end{equation*}
\noindent
for all $x\in V$ (cf. \cite[\S\phantom{.}2.1, Ch.\phantom{.}V]{bourbaki}). Moreover, if $\alpha^*(a)=2$, then $s_{a,\alpha^*}$ is a reflection (in the sense of \ref{def - reflection}) and it satisfies $s_{a,\alpha^*}(a)=-a$.
\begin{fact}\label{fact - every involution induces a decomposition of V in ker(1-s)+ker(1+s)}
	Let $V$ be a finitely generated real vector space. Then, every involution $s\in \gl(V)$ induces a decomposition of $V$ as a direct sum of subspaces of the form:
	\begin{equation}\tag{$\star_1$}\label{eq.1 - decomposition V induced by involutions}
		V=\mathrm{ker}(1-s)\oplus\mathrm{ker}(1+s).
	\end{equation}
	\noindent
	When $V$ is Euclidean with inner product $(\,\cdot\,,\,\cdot\,)$ and $s\in O(V)$ is a reflection of the form $s=s_{a,\alpha^*}$, for some $a\in V$ and $\alpha^*\in V^*$, then $s$ admits explicit description as:
	\begin{equation*}
		s(x)=x-2\frac{(x,a)}{(a,a)}a,
	\end{equation*}
	for all $x\in V$ (cf. \cite[\S\phantom{.}2.3, Ch.\phantom{.}V]{bourbaki}, \cite[\S\phantom{.}9.1, Ch.\phantom{.}III]{humphreys_1}), and the decomposition \eqref{eq.1 - decomposition V induced by involutions} simply reduces to:
	\begin{equation*}
		V=H_a\oplus\langle a\rangle_\R,
	\end{equation*}
	\noindent
	with $H_a$ being the hyperplane orthogonal to $a$ in $V$.	
	%When $V$ is euclidean and $s\in O(V)$ is a reflection of the form $s=s_{a,\alpha^*}$, for some $a\in V$ and $\alpha^*\in V^*$, the decomposition \eqref{eq.1 - decomposition V induced by involutions} simply reduces to:
	%\begin{equation*}
	%	V=H_a\oplus\langle a\rangle_\R,
	%\end{equation*}
	%\noindent
	%with $H_a$ being the hyperplane orthogonal to $a$ in $V$.
\end{fact}
\begin{definition}{\cite[D\'efinition\cspace1, \S\phantom{.}1.1, Ch.\phantom{.}VI]{bourbaki}}\label{def - root system}
	Let $V$ be a vector space over a field $K$ extending $\Q$. Then, a subset $R\subseteq V$ is said to be a \emph{root system in $V$} if the following conditions are satisfied:
	\begin{enumerate}[(1)]
		\item $R$ is finite, does not contain $0$, and $\langle R\rangle_K=V$;
		\item for all $\alpha\in R$, there is a $K$-linear form $\coalpha\in V^*$ such that:
		\begin{enumerate}[(a)]
			\item $\coalpha(\alpha)=2$;
			\item $R$ is stable under the reflection $s_{\alpha,\coalpha}$, i.e., $s_{\alpha,\coalpha}(R)\subseteq R$;
			\item $\coalpha(R)\subseteq \Z$.
		\end{enumerate}
	\end{enumerate}
	\noindent
	The elements $\alpha\in R$ are called the \emph{roots} of $R$, and the corresponding $K$-linear maps $\coalpha\in V^*$ are called the \emph{coroots} of $R$.
\end{definition}
\begin{notation}\label{s_a_notation}
	By \cite[Lemme\cspace1, \S\phantom{.}1.1, Ch.\phantom{.}VI]{bourbaki}, each root $\alpha\in R$ uniquely determines $\coalpha\in V^*$ and $s_{\alpha,\coalpha}\in \mathrm{GL}(V)$ through the axioms (2)(a),(b) above. Hence, the reflection $s_{\alpha,\coalpha}$ is simply denoted by $s_\alpha$ (cf. \cite[\S\phantom{.}1.1, Ch.\phantom{.}VI]{bourbaki}).
\end{notation}
In this paper, we are primarily concerned with root systems $R$ in real vector spaces. However, in Theorem\cspace\ref{thm. - R irreducible iff modules are (abs) irreducible} it will be necessary to regard $R$ as a root system in the $\Q$-vector space generated by its roots. The following notion provides a precise mean of translating between these two settings.
\begin{definition}{\cite[Proposition\cspace1, \S\phantom{.}8.1, Ch.\phantom{.}II]{bourbaki algèbre}}\label{prop. - characterization Q-structures}
	Let $V$ be a real vector space, and $U$ be a subspace of the $\Q$-vector space structure on $V$. Then, $U$ is a $\Q$\emph{-structure on }$V$ if it satisfies one of the following equivalent conditions:
	\begin{enumerate}[(1)]
		\item there exists a basis of $U$ (over $\Q$) which is also a basis of $V$ over $\R$;
		\item every basis of $U$ (over $\Q$) is also a basis of $V$ over $\R$;
		\item $V=\langle\, U\rangle_\R$ and every $\Q$-linearly independent subset of $U$ is $\R$-linearly independent;
		\item for every $\R$-vector space $V$, each $\Q$-linear function $f:U\rightarrow V'$ uniquely extends to an $\R$-linear map $\bar{f}:V\rightarrow V'$.
	\end{enumerate}
\end{definition}
