The following fact will be crucial in Section\cspace\ref{sec6}.
\begin{fact}\label{fact - Q(R) is always a Q-structure in V}
	Every root system $R$ in a real vector space $V$ yields a $\Q$-structure $\langle R\rangle_\Q$ on $V$ (see \cite[Proposition\cspace1, \S\phantom{.}1.1, Ch.\phantom{.}VI]{bourbaki}, or \ref{fact - basis of a root system}).
\end{fact}
%As a result, we are enabled to use the following useful property.
As a consequence of Fact\cspace\ref{fact - Q(R) is always a Q-structure in V}, a set $R$ of generators of a finite-dimensional real vector space $V$ is a root system in $V$ if and only if it is a root system in the $\Q$-vector space $\langle R\rangle_\Q$. Indeed, by Definition\cspace\ref{def - root system}(2)(c), each coroot $\coalpha$ of $R$ in $V$ only takes rational values on $\langle R\rangle_\Q$, and thus restricts canonically to a coroot in the rational span of $R$. Conversely, by Definition\cspace\ref{prop. - characterization Q-structures}(4), each coroot of $R$ in $\langle R\rangle_\Q$ extends uniquely to a coroot in $V$.
\begin{fact}\label{fact - Q(R^vee) is a Q-structure}
	Let $R$ be a root system in a real vector space $V$. Then, the following conditions hold:
	\begin{enumerate}[(1)]
		\item the set of coroots $R^\vee\vcentcolon=\{\coalpha:\alpha\in R\}$ is a root system in $V^*$ (cf. \cite[Proposition\cspace2, \S\phantom{.}1.1, Ch.\phantom{.}VI]{bourbaki});
		\item $\langle R^\vee\rangle_\Q$ is a $\Q$-structure on $V^*$ (cf. \cite[Proposition\cspace1, \S\phantom{.}1.1]{bourbaki}, or Fact\cspace\ref{fact - Q(R) is always a Q-structure in V}).
	\end{enumerate}
\end{fact}
\begin{definition}{\cite[\S\phantom{.}1.2, Ch.\phantom{.}VI]{bourbaki}}\label{def. - irreducible root system}
	Let $R$ be root system in a vector space $V$ over a field $K$ extending $\Q$. Then, $R$ is said to be \emph{reducible} if there are two non-empty subsets $R_0,R_1\subseteq R$ such that:
	\begin{enumerate}[(i)]
		\item $R=R_0\sqcup R_1$ (where $\sqcup$ denotes disjoint union);
		\item $V$ is the direct sum of the $K$-vector spaces $\langle R_0\rangle_K$ and $\langle R_1\rangle_K$;
		\item $R_i$ is a root system in $\langle R_i\rangle_K$, for $i = 0, 1$.
	\end{enumerate}
	In this case, we also say that $R$ is the \emph{direct sum} of the root systems $R_0$ and $R_1$.
	Finally, we say that $R$ is \emph{irreducible} if $R$ is not reducible and $R\neq\emptyset$.
\end{definition}
Any root system $R$ in $V$ admits a decomposition as a direct sum of the form:
\begin{equation*}
	\quad R=\bigsqcup_{i<m} R_i,
\end{equation*}
where $m\in\N$, and each $R_i$ is an irreducible root system in its span $\langle R_i\rangle_K$. Moreover, this decomposition is unique up to permutation of the factors (see \cite[Proposition\cspace6, \S\phantom{.}1.2, Ch.\phantom{.}VI]{bourbaki}).
\begin{definition}{\cite[\S\phantom{.}1.1, Ch.\phantom{.}VI]{bourbaki}}\label{def. - Weyl group of a root system}
	Let $R$ be a root system in a vector space $V$ over a field $K$ extending $\Q$. Then, the \emph{Weyl group} of $R$ is the subgroup $W_0(R)$ of $\mathrm{GL}(V)$ generated by the reflections $s_\alpha$, for all $\alpha\in R$ (cf. \ref{s_a_notation}).
\end{definition}
Notice that a Weyl group $W_0(R)$ is always finite, since by {(2)(b)} of Definition\cspace\ref{def - root system} we have an identification of $W_0(R)$ with a subgroup of the symmetric group on $R$.

\begin{fact}{\cite[Proposition, \S\cspace1.14, Ch.{\cspace}I]{humphreys}}\label{fact - every reflection in a Weyl group is induced by a root}
	Let $R$ be a root system in a real Euclidean vector space $V$, and $W_0(R)\leq O(V)$ its Weyl group. Then, every reflection $s\in W_0(R)$ (in the sense of \ref{def - reflection}) is of the form $s=s_\alpha$, for some $\alpha\in R$.

\end{fact}
Several structural properties of a Weyl group $W_0(R)$ can be deduced from the combinatorics of the root system $R$. For instance, if $R$ admits a direct sum decomposition $R=\bigsqcup_{i<m}R_i$, where each $R_i$ is irreducible with respect to its linear span $\langle R_i\rangle_K$, then, by \cite[\S\phantom{.}1.2, Ch.VI]{bourbaki}), we have:
\begin{equation*}
	W_0(R)\cong\prod_{i<m}W_0(R_i),
\end{equation*}
\noindent
where $W_0(R_i)$ denotes the Weyl group associated with $R_i$ in $\langle R_i\rangle_K$, for all $i<m$.
\begin{definition}[Coxeter groups]\label{def_Coxeter_groups} Let $S$ be a set. A matrix $m: S \times S \rightarrow \{1, 2, . . . , \infty \}$ is called a {\em Coxeter matrix} if it satisfies:
	\begin{enumerate}[(1)]
		\item $m(s, s') = m(s' , s)$;
		\item $m(s, s') = 1 \Leftrightarrow s = s'$.
	\end{enumerate}
	%$$m(s, s') = m(s' , s);$$
	%$$m(s, s') = 1 \Leftrightarrow s = s'.$$
	For such a matrix, let $S^2_{*} = \{(s, s') \in S^2 : m(s, s' ) < \infty \}$. A Coxeter matrix $m$ determines
	a group $W_0$ with presentation:
	$$
	\begin{cases} \text{Generators:} \; \;  S \\
		\text{Relations:} \; \;   (ss')^{m(s,s')} = e, \text{ for all } (s, s' ) \in S^2_{*}.
	\end{cases} $$
	A group with a presentations as above is called a \emph{Coxeter group}, and the pair $(W_0, S)$ is a called a \emph{Coxeter system}. The \emph{rank} of the Coxeter system $(W_0, S)$ is $|S|$.
\end{definition}
\begin{definition}\label{def_Coxeter_graph}
	In the context of Definition~\ref{def_Coxeter_groups}, the Coxeter matrix $m$ can be equivalently represented by a labeled graph $\Delta$, known as the \emph{Coxeter diagram} of the system $(W_0,S)$. The vertex set of $\Delta$ is $S$, and its edge set $E_\Delta$ consists of unordered pairs $\{s, s' \}\subseteq S$ such that $3\leq m(s, s') < \infty$. Each edge $\{s,s'\}$ is labeled by the integer $m(s,s')$. By convention, labels corresponding to $m(s,s')=3$ are typically omitted.
\end{definition}
An automorphism $\sigma$ of a Coxeter diagram $\Delta$ is a bijection of the set of nodes of $\Delta$ such that two nodes $s,s'\in\Delta$ are connected by an edge labeled $m(s,s')$ if and only if $\sigma(s),\sigma(s')$ are connected by an edge with the same label. Each such automorphism $\sigma$ of the Coxeter diagram $\Delta$ of a Coxeter group $W_0$ extends uniquely to an automorphism $f_\sigma$ of $W_0$.

