	\label{fact - basis of a root system}
	Let $R$ be a root system in a real vector space $V$. Then, a subset $B\subseteq R$ is a \emph{basis} (or \emph{simple system}) of $R$ if the following conditions are satisfied:
	\begin{enumerate}[(1)]
		\item $B$ is a basis of $V$;
		\item $B$ consists entirely of indivisible roots;
		\item each $\alpha\in R$ can be written as a $\Z$-linear combination of elements from $B$ with coefficients all of the same sign (either all non-negative, or all non-positive).
	\end{enumerate}
	The elements $\alpha$ belonging to some basis of $R$ are called \emph{simple roots} of $R$, and the corresponding reflections $s_\alpha$ are the \emph{simple reflections} of $R$.
\end{definition}
\begin{remark}\label{remark - humphreys}
	In \cite{bourbaki}, bases of root systems are introduced through a constructive method that also ensures the existence of a basis $B$ for any root system $R$ (see \cite[Théorème\cspace2, \S\phantom{.}1.5, Ch.\phantom{.}VI]{bourbaki}). Definition\cspace\ref{fact - basis of a root system} provides an equivalent characterization, as stated in \cite[Corollaire\cspace3, \S\phantom{.}1.7, Ch.\phantom{.}VI]{bourbaki}. This formulation is also adopted as the definition of a simple system in \cite{humphreys_1, humphreys}, where only reduced systems are considered (cf. \cite[\S\phantom{.}9.2,\phantom{.}10.1, Ch.\phantom{.}III]{humphreys_1}).
\end{remark}
\begin{fact}{\cite[Théorème\cspace2(vii), \S{\phantom{.}}1.5, Ch.VI]{bourbaki}}\label{fact - simple reflections form a Coxeter system of the Weyl gp}
	Let $R$ be a root system in a real vector space $V$, and $W_0(R)$ its Weyl group. If $B$ is a basis of $R$ and $S\vcentcolon=\{s_\alpha\in W_0(R):\alpha\in B\}$ is the set of simple reflections of $B$, then $(W_0(R), S)$ is a (finite) Coxeter system. %In particular, every Weyl group is a finite Coxeter group.
\end{fact}
\begin{fact}\label{fact - the Weyl group acts simply transitively on the set of bases of a root system}
	Let $R$ be a root system in a real vector space $V$, and $W_0(R)$ its Weyl group. If $B$ is a basis of $R$, then, for each $w\in W_0(R)$, $w(B)$ is also a basis of $R$ (see \cite[\S\phantom{.}1.5, Ch.\phantom{.}VI]{bourbaki} and \cite[\S\phantom{.}10.1, Ch.\phantom{.}III]{humphreys_1}). The resulting action of $W_0(R)$ on the sets of bases of $R$ is simply transitive (cf. \cite[Remarques(4), \S\phantom{.}1.5, Ch.\phantom{.}VI]{bourbaki}).
\end{fact}
\begin{fact}{\cite[Proposition\cspace15, \S\phantom{.}1.5]{bourbaki}}\label{fact - every root in a reduced root system is the image of a root of the basis through an element of the Weyl group}
	Let $R$ be a reduced root system in a real vector space $V$, and $W_0(R)$ be the Weyl group of $R$. If $B$ is a basis of $R$ (cf. \ref{fact - basis of a root system}), then, for every root $\alpha'\in R$, there exist some $w\in W_0(R)$ and $\alpha\in B$ such that $\alpha'=w(\alpha)$.
\end{fact}
\begin{fact}{\cite[Corollaire, \S\phantom{.}1.6, Ch.\phantom{.}VI]{bourbaki}}\label{fact - every vector in Q(R) l.d. from an indivisible root alpha, is Z-proposrtional to alpha}
	Let $R$ be a root system in a real vector space, and $\alpha$ be an indivisible root in $R$. Then, for every $x\in \langle R\rangle_\Z\cap\langle\alpha\rangle_\R$, $x$ belongs to $\langle\alpha\rangle_\Z$.
\end{fact}
\begin{fact}
	The reduced irreducible root systems have been classified (see \cite[Planche{\cspace}I to IX]{bourbaki}). A list of the Coxeter diagrams of the corresponding Weyl groups can be found in Table~\ref{table - Coxeter diagrams of irreducible root systems} from the Appendix (i.e., Section~\ref{app_sec}).
\end{fact}
The following result is folklore, we will need it in the \mbox{next section (cf. \ref{remark - we can consider reduced root systems}).}
\begin{fact}\label{fact - R reduced root system is irreducible iff the coxeter diagram is connected}
	Let $R$ be a reduced root system in a real vector space $V$, and $W_0(R)$ be its Weyl group. Then, $R$ is irreducible if and only if the Coxeter diagram of $W_0(R)$ is connected.
\end{fact}
\begin{fact}\label{fact - w s_alpha w^-1 = s_w(alpha)}
	Let $R$ be a root system in a real Euclidean vector space $V$, and $W_0(R)\leq O(V)$ be its Weyl group. Then,
	\begin{enumerate}[(1)]
		\item for every basis $B$ of $R$, and every $w\in W_0(R)$, $w(B)$ is a basis of $R$ (cf. \cite[\S\phantom{.}1.4, Ch.\phantom{.}1]{humphreys});
		\item for every $\alpha\in R$ and every $w\in W_0(R)$, $(s_\alpha)^w=s_{w(\alpha)}$ (cf. \cite[Proposition, \S\phantom{.}1.2, Ch.\phantom{.}1]{humphreys}).
	\end{enumerate}
	In particular, inner automorphisms of $W_0(R)$ map Coxeter systems of simple reflections into Coxeter systems of simple reflections.
\end{fact}

