\begin{definition}{\cite[Definition\cspace1.36, \S\phantom{.}1.4, Ch.{\cspace}1]{franzsen}}\label{def - inner-by-graph automorphism}
	Let $R$ be a root system in a real vector space $V$ with Weyl group $W_0(R)$. Suppose that $B$ is a basis of $R$ and $S=\{s_\alpha:\alpha\in B\}$ is a system of simple reflections. Then, an automorphism $f\in\mathrm{Aut}(W_0(R))$ is said to be \emph{inner-by-graph} if it belongs to the subgroup of $\mathrm{Aut}(W_0(R))$ generated by the subgroup of inner automorphisms and the subgroup of graph automorphisms of $(W_0(R), S)$, i.e., the permutations of $S$ inducing an automorphism of the Coxeter diagram $\Delta$ of $(W_0(R),S)$ (cf. \ref{def_Coxeter_graph} and \ref{fact - simple reflections form a Coxeter system of the Weyl gp}).
\end{definition}
Since the subgroup of inner automorphisms of $W_0(R)$ is normal, any inner-by-graph automorphism $f$ of $W_0(R)$ is a composition of the form:
\begin{equation*}
	f=(\,\cdot\,)^w\circ f_\sigma,
\end{equation*}
\noindent
for some graph automorphism $\sigma$ and some $w\in W_0(R)$ (cf. \cite[\S\phantom{.}1.4, Ch.\phantom{.}1]{franzsen}).
\begin{fact}{\cite[Proposition\cspace1.44, \S\phantom{.}1.4, Ch\phantom{.}1]{franzsen}}\label{fact - every automorphism of a Weyl group of an irreducible root system is inner-by-grapph} Let $R$ be an irreducible reduced root system in a real vector space $V$ with Weyl group $W_0(R)$. If $B$ is a basis of $R$, then every automorphism $f\in\mathrm{Aut}(W_0(R))$ preserving the set $S^{W_0(R)}=\{ws_\alpha w^{-1}:\alpha\in B\}$ is inner-by-graph.
\end{fact}
In Section\cspace\ref{sec6} we will see that, for any choice of a basis $B$ for a root system $R$ in $V$, the set $S^{W_0(R)}=\{ws_\alpha w^{-1}:\alpha\in B\}$ actually consists of all the affine reflections in $W_0(R)$. This will be crucial for the proof of Theorem\cspace\ref{main_th2}.

\begin{definition}{\cite[$\S\phantom{.}1.9$, Ch.\phantom{.}VI]{bourbaki}}\label{def - Q(R) and P(R)}
	Let $V$ be a finite-dimensional real vector space. If $R$ is a root system in $V$ and $W_0(R)$ is the Weyl group of $R$, then we define:
	\begin{enumerate}[(1)]
		\item $P(R)\vcentcolon=\{x\in V:\forall \alpha\in R(\coalpha(x)\in\Z)\}$, the group of \emph{weights} of $R$.
		\item $Q(R)\vcentcolon=\langle R\rangle_\Z$, the group of \emph{radical weights} of $R$;
	\end{enumerate}
\end{definition}
Clearly, by Definition\cspace\ref{def - root system}(2)(c), every radical weight is also a weight, and hence the inclusion $Q(R)\leq P(R)$ holds for any root system $R$. Both $Q(R)$ and $P(R)$ are known to be free abelian of the same rank (see \cite[Proposition\cspace26, \S\phantom{.}1.9, Ch.\phantom{.}VI]{bourbaki}), and the finite index $[P(R):Q(R)]$ is called the \emph{index of connection} of $R$ (cf.\cspace\cite[$\S${\phantom{.}}1.9, Ch.{\phantom{.}}VI]{bourbaki}). Since $P(R)$ and $Q(R)$ are stable under the action of the Weyl group $W_0$ of $R$, they are also endowed with a natural structure of $\Z[W_0]$-lattice (cf. \cite{martinais, maxwell}).

\smallskip
If $V$ is a finite-dimensional real vector space, any choice of a basis $B=\{v_j:1\leq j\leq l\}$ of $V$ determines a \emph{dual basis} $B^*=\{\delta_i:1\leq i\leq l\}$ in $V^*$ (cf. \ref{notation - root systems}) whose elements are the $\R$-linear maps $\delta_i:V\rightarrow \R$ such that $\delta_i(v_j)=1$ if $i=j$, and $0$ otherwise. The correspondence $v_i\mapsto\delta_i$, for $1\leq i\leq l$, naturally yields and isomorphism of $V$ and $V^*$.


If $R$ is a root system in $V$, then the identity $(\coalpha)^\vee=\alpha$ holds for each root $\alpha\in R$ (cf. \cite[Proposition\cspace2, \S\phantom{.}1.1, Ch.\phantom{.}VI]{bourbaki}). As a result, one has that the assignment $\alpha\mapsto\coalpha$ is a 1-1 correspondence, called \emph{canonical bijection}. This map usually does not extend to an isomorphism of $\langle R\rangle_\Z$ and $\langle R^\vee\rangle_\Z$, as it does not preserve sums of roots (see \cite[\S\phantom{.}1.1, Ch.\phantom{.}VI]{bourbaki}). Nevertheless, if the system $R$ is reduced, then every basis $B$ of $R$ yields a basis of $R^\vee$ of the form $B^\vee\vcentcolon=\{\coalpha:\alpha\in B\}$  (cf. \cite[Remarques(5), \S\phantom{.}1.5, Ch.\phantom{.}VI]{bourbaki}). 


The weight group $P(R)$, as defined in  Definition\cspace\ref{def - Q(R) and P(R)}, is the free abelian group generated by the dual basis $(B^\vee)^*=\{\overline{\omega}_i:1\leq i\leq l\}$ of $B^\vee\subset V^*$ in $V$. The generators $\overline{\omega}_i$ are known as the \emph{fundamental weights} of the root system $R$ (cf. \cite[\S\phantom{.}1.10, Ch.\phantom{.}VI]{bourbaki}).  By Fact\cspace\ref{fact - Q(R^vee) is a Q-structure}, the natural isomorphism $V\cong V^*$ induced by the identification of $B^\vee$ and $(B^\vee)^*$ witnesses the following fundamental property.
\begin{fact}\label{fact - P(R) is a Q-structure on V}
	Let $R$ be a reduced root system in a real vector space $V$, and $P(R)$ be the group of weights of $R$. Then, $\langle P(R)\rangle_\Q$ is a $\Q$-structure on $V$.
\end{fact}
\begin{theorem}\label{thm. - R irreducible iff modules are (abs) irreducible}
	Let $R$ be a root system in a real vector space $V$ with Weyl group $W_0$. Then, the following conditions are equivalent:
	\begin{enumerate}[(1)]
		\item $R$ is irreducible in $V$;
		%\item the Coxeter diagram of $R$ is connected;
		\item $R$ is irreducible as a root system in $\langle R\rangle_\Q$;
		\item $V$ is irreducible $($or indecomposable$)$ as an $\R[W_0]$-module;
		\item $V$ is absolutely irreducible as an $\R[W_0]$-module;
		\item $\langle R\rangle_\Q$ is irreducible $($or indecomposable$)$ as a $\Q[W_0]$-module;
		\item $\langle R\rangle_\Q$ is absolutely irreducible as a $\Q[W_0]$-module;
		%\item $Q(R)$ is irreducible as a $\Z[W_0]$-lattice;
		\item $Q(R)$ is absolutely irreducible as a $\Z[W_0]$-lattice.
	\end{enumerate}
\end{theorem}
\begin{proof}
	Equivalence $[6\Leftrightarrow 7]$ follows directly from Definition\cspace\ref{def - absolutely irreducible lattice} and the fact that $\langle R\rangle_\Q$ and $\Q Q(R)$ are isomorphic as $\Q[W_0]$-modules. Equivalences $[1\Leftrightarrow3\Leftrightarrow4]$ and $[2\Leftrightarrow5\Leftrightarrow6]$ are established in \cite[Corollaire, \S\phantom{.}1.2, Ch.\phantom{.}VI]{bourbaki}. It remains to prove the equivalence $[1\Leftrightarrow2]$. The implication $[2\Rightarrow1]$ is immediate, as any decomposition of $R=R_0\sqcup R_1$ satisfying
	\begin{enumerate}[(a)]
		\item $R_0,R_1\neq\emptyset$;
		\item $V=\langle R_0\rangle_\R\oplus\langle R_1\rangle_\R$;
		\item each $R_i$ is a root system in $\langle R_i\rangle_\R$;
	\end{enumerate}
	\noindent
	naturally induces a decomposition of $\langle R\rangle_\Q$ as a direct sum of $\Q$-vector spaces $\langle R\rangle_\Q=\langle R_0\rangle_\Q\oplus\langle R_1\rangle_\Q$, in which each $R_i$ remains a root system in $\langle R\rangle_\Q$, by Definition\cspace\ref{def - root system}(2)(c).

	\smallskip\noindent
	For implication $[1\Rightarrow2]$, assume, towards a contradiction, that there exist two non-empty subsets $R'_0,R_1'\subseteq R$ such that:
	\begin{enumerate}[(a')]
		\item $R=R'_0\sqcup R'_1$;
		\item $\langle R\rangle_\Q=\langle R'_0\rangle_\Q\oplus\langle R'_1\rangle_\Q$;
		\item each $R'_i$ is a root system in the $\Q$-vector space $\langle R'_i\rangle_\Q$.
	\end{enumerate}
	\noindent
	Then, by (c'), $R_0$ and $R_1$ are also root systems in $\langle R_0\rangle_\R$ and $\langle R_1\rangle_\R$, respectively (cf. Fact\cspace\ref{fact - Q(R) is always a Q-structure in V} and the related discussion). Since the rational spans of $R_0,R_1$ are $\Q$-structures in $\langle R_0\rangle_\R$ and $\langle R_1\rangle_\R$, Definition\cspace\ref{prop. - characterization Q-structures}(2) implies that each basis $B_i$ of $\langle R_i\rangle_\Q$ is also a basis of $\langle R_i\rangle_\R$ as a real vector space. Moreover, by (b'), $B_0\sqcup B_1$ is a basis of $\langle R\rangle_\Q$, which is a $\Q$-structure on $V$, since $R\subseteq V$ is a root system. Hence, applying Definition\cspace\ref{prop. - characterization Q-structures}(2) once more, we conclude that $B_0\sqcup B_1$ is a basis of $V$ yielding the decomposition $V=\langle R_0\rangle_\R\oplus\langle R_1\rangle_\R$. This contradicts the irreducibility of $R$ in $V$, completing the proof.
	%\smallskip\noindent
	%By \cite[Theorem\cspace73.9, \S\phantom{.}73, Ch.XI]{representation_theory_book}, $L$ is irreducible as $\Z[W_0]$-lattice if and only if $\Q L$ is irreducible as a $\Q[W_0]$-module.
\end{proof}
\section{Crystallography of Coxeter groups}\label{sec6}

In this section, we consider crystallographic groups admitting an affine realization as groups of isometries of a finite-dimensional real Euclidean vector space $V$, whose point group is generated by reflections and essential. A subgroup $W_0\leq O(V)$ is called \emph{essential} if its fixed-point subspace is trivial; that is, if we have:
\begin{equation*}
    V^{W_0}\vcentcolon=\{x\in V:w(x)=x\quad\text{for all}\quad w\in W_0\}=\{0\}.
\end{equation*}
\begin{fact}[{\cite[Proposition\cspace9, \S\phantom{.}2.5]{bourbaki}}]\label{fact - property of finite groups of isometries essential and generated by reflections} If $V$ is a real Euclidean vector space of finite dimension $l$, and $W_0$ is a finite subgroup of $O(V)$ that is essential and generated by reflections, then the following conditions are equivalent:
\begin{enumerate}[(1)]
	\item there exists a lattice of rank $l$ in $V$ stable under $W_0$;
	\item there exists a root system $R$ in $V$ whose Weyl group is $W_0$.
\end{enumerate}
\end{fact}
In \cite{martinais, maxwell}, crystallographic groups with point groups satisfying the above conditions were analyzed. Building on \cite{martinais}, we consider the following notion.
\begin{definition}\label{def - crystallographic group arising from a root system}
	We say that an (abstract) crystallographic group $W$ \emph{arises from a root system} if it admits an affine realization as a discrete subgroup of the isometry group of an $l$-dimensional Euclidean vector space $V$, with $l$ being the rank of the translation subgroup, such that the associated point group $W_0\leq O(V)$ is essential and generated by reflections $($in the sense of the ambient space $V)$. By Fact\cspace\ref{fact - property of finite groups of isometries essential and generated by reflections}, $W_0$ is the Weyl group of some root system $R$ in $V$. If, in addition, $R$ can be chosen to be irreducible, we say that $W$ \emph{arises from an irreducible root system}.
\end{definition}
%In this case, the translation lattice satisfies item (1) above, and hence ensure the existence of a root system inducing the point group. Do you agree? (see Theorem\cspace\ref{thm - zassenhaus}) 
%
\begin{fact}{\cite[Theorem\cspace1.10]{martinais}}\label{fact - existence reduced root system and sandwich condition}
	If $R$ is a root system in a real Euclidean vector space $V$ whose Weyl group $W_0(R)\leq O(V)$ is essential and generated by reflections, then for every lattice $L$ in $V$ invariant under $W_0(R)$ there exists a reduced root system $R'$ in $V$ such that the following conditions are satisfied:
	\begin{enumerate}[(1)]
		\item $W_0(R)$ is the Weyl group of $R'$ (i.e., $W_0(R)=W_0(R')$);
		\item $Q(R')\leq L\leq P(R')$.
	\end{enumerate}
\end{fact}
\begin{remark}\label{remark - we can consider reduced root systems}
	%If $R$ is an irreducible root system of rank $l\geq3$ in a real vector space $V$, then the subset $R'\subseteq R$ of indivisible roots is an irreducible \emph{reduced} root system in $V$ with Weyl group $W_0(R')=W_0(R)$ (cf. \cite[Proposition\cspace13\phantom{.}(i), \S\phantom{.}1.4]{bourbaki}).
	Let $W'$ be a crystallographic group arising from an irreducible root system, and let $V$ be a finite-dimensional real Euclidean vector space. Suppose that ${W}$ is an affine realization of $W'$ in $V$, whose point group $W_0\leq O(V)$ is the Weyl group of an irreducible root system $R$ in $V$. Then, in light of Fact\cspace\ref{fact - existence reduced root system and sandwich condition}, it is always possible to find a reduced root system $R'$ in $V$ with Weyl group $W_0(R')=W_0$ such that the translation lattice $L$ of $W$ satisfies the inclusions:
	\begin{equation*}
		Q(R')\leq L\leq P(R').
	\end{equation*}
	\noindent
	Since $R$ is irreducible, the Coxeter diagram of $W_0$ is connected, and hence $R'$ is also irreducible, by Fact\cspace\ref{fact - R reduced root system is irreducible iff the coxeter diagram is connected}.
	For this reason, in the remainder of the paper, we will adopt a standard convention (cf. \cite{martinais, maxwell}) and simply say \emph{irreducible} root system in place of \emph{irreducible reduced} root system. In fact, since all our results only depend on the point group $W_0(R)$ and the translation lattice $L$ (considered as a $\mathbb{Z}[W_0(R)]$-module), they remain valid in the general non-reduced context. %This convention \mbox{is also used in~\ref{main_th2}.}
\end{remark}


In \cite[Table I]{maxwell} (also reproduced in Table\cspace\ref{table all inequivalent lattices} below), Maxwell classified the isomorphism classes of lattices in a finite-dimensional real Euclidean vector space $V$ that are invariant under the action of the Weyl group $W_0(R)$ associated with an irreducible root system $R$ in $V$. These classes are represented by lattices $L$ satisfying:
\begin{equation*}
	Q(R)\leq L\leq P(R)
\end{equation*}
\noindent
(see also \cite[Tables I, II]{martinais}). Building on the techniques developed in Section~\ref{sec4}, we establish in the following lemma that all these lattices are absolutely irreducible.

\begin{lemma}\label{lemma-every_lattice_L_s.t._Q(R)<L<P(R)_is_absolutely_irreducible}
	Let $R$ be a root system in a real vector space $V$. If $W_0(R)$ is the Weyl group of $R$ in $V$, then the following conditions are equivalent:
	\begin{enumerate}[(1)]
		\item $R$ is irreducible in $V$;
		\item any $\Z[W_0(R)]$-lattice $L$ fitting into the chain of inclusions:
		\begin{equation*}
			Q(R)\leq L\leq P(R)
		\end{equation*}
		\noindent
		is absolutely irreducible.
	\end{enumerate}
\end{lemma}
\begin{proof}
	Direction $[2\Rightarrow1]$ is trivial: it follows directly from instantiating implication $[7\Rightarrow1]$ of Theorem\cspace\ref{thm. - R irreducible iff modules are (abs) irreducible} to the case $L= Q(R)$.

	\smallskip\noindent
	For the converse direction $[1\Rightarrow2]$, observe that $Q(R)$ is absolutely irreducible, by Theorem\cspace\ref{thm. - R irreducible iff modules are (abs) irreducible}. According to Definition\cspace\ref{def - absolutely irreducible module}, this means that $\Q Q(R)$ is absolutely irreducible as a $\Q[W_0(R)]$-module. Furthermore, by Definition\cspace\ref{def - Q(R) and P(R)} and the subsequent discussion, $Q(R)$ has finite index in $P(R)$. Since
	\begin{equation*}
		[P(R):Q(R)]=[P(R):L]\,\cdot\,[L:Q(R)],
	\end{equation*}
	\noindent
	it follows that $Q(R)$ has finite index in $L$. Hence, by Definition\cspace\ref{def - centering of a Z[G]-repr module}, $Q(R)$ is a centering of $L$. Therefore, by applying Lemma\cspace\ref{lemma every centering is Q-equivalent to the ambient module}, we conclude that $\Q Q(R)\cong\Q L$, and so that $L$ is absolutely irreducible, completing the proof. 
\end{proof}

Maxwell's inequivalent lattices from \cite[Table I]{maxwell} were explicitly computed by Martinais in \cite[Tables I, II, III]{martinais}, employing Bourbaki's classical framework \cite[Planche~I to IX]{bourbaki}. These lattices fall into a few families, parametrized by the rank $l$ of the root system $R$. For completeness, these lattices are presented in \mbox{Table\cspace\ref{table - martinais nomenclature} below.}

\medskip
By Bieberbach's First Theorem, every crystallographic group $W$ has an affine realization as a subgroup of the group of isometries of a finite-dimensional real Euclidean vector space $V$. In this context, the point group of $W$ is a finite subgroup $W_0$ of the orthogonal group $O(V)$ and its translation lattice $L$ is a discrete cocompact subgroup of $V$ stable under the action of $W_0$ (cf. Section\cspace\ref{prel_sec}). It follows from a general theory (cf. \cite{hiller, martinais, maxwell}) that the group extensions of $W_0$ by $L$, regarded as a $\Z[W_0]$-lattice, correspond to cohomology classes in $H^1(W_0,V/L)$. Moreover, this correspondence is such that two crystallographic groups are isomorphic if and only if their cohomology classes lie in the same orbit under the natural action of the normalizer of $W_0$ in $\mathrm{Aut}(L)$ (see \cite[Sectiom\phantom{.}1]{martinais} and \cite[Theorem\cspace5.2]{hiller}).

\smallskip
Working within this framework, Martinais \cite{martinais} also computed, for every irreducible root system $R$ and $\Z[W_0(R)]$-lattice $L$ from Table~\ref{table - martinais nomenclature}, the number $n(W_0(R), L)$ of these orbits, and hence of isomorphism classes, of crystallographic groups extending $W_0(R)$ by $L$ (cf. the relevant column of Table~\ref{table all inequivalent lattices}). Finally, he provided explicit representatives for each of these isomorphism classes (cf. \cite[Table{\cspace}V]{martinais}), that we list in Table\cspace\ref{table - explicit crystallographic groups} for convenience of the reader. The following remark explains some conventions used by Martinais.

\smallskip
\begin{remark}\label{remark_for_star2}
	Every crystallographic group $W$ in Martinais's classification from \cite{martinais} is defined by a presentation of the form:
	\begin{equation}\tag{$\star_2$}\label{eq.1 - martinais' groups presentation}
		W=\langle (x,1), (t_1,s_1),\ldots,(t_l,s_l): x\in L'\rangle_{\iso(V)},
	\end{equation}
	\noindent
	where:
	\begin{enumerate}[(1)]
		\item $V$ is the real Euclidean vector space underlying the irreducible root system $R$;
		\item $L'$ is one of the $\Z[W_0]$-lattices in Table\cspace\ref{table - martinais nomenclature}, and $L=\{(x,1):x\in L'\}$ is the translation lattice of $W$;
		\item $l$ is the rank of $R$ (equivalently, the dimension of $V$);
		\item $t_1,\ldots,t_l$ are translations in $V$ (but generally not in $L'$);
		\item $s_1,\ldots,s_l$ is the (Coxeter) system of simple reflections associated with the basis $B=\{\alpha_i:1\leq i\leq l\}$ of $R$ from Bourbaki's standard realization \cite[Planche{\cspace}I to IX]{bourbaki}.
        %\smallskip
        %In the proof of Theorem\cspace\ref{main_th2}, the main result of this section, we will only need an explicit description of $B$ and the $s_i$'s for the case of $R$ of type $B_l, C_l$ or $D_l$ with $l\geq 3$. For convenience of the reader, we present them in Table\cspace\ref{table - root systems, bases and reflections} in the Appendix (Section\cspace\ref{app_sec}).
	\end{enumerate}
\end{remark}
In particular, for any irreducible root system $R$ and $\Z[W_0]$-lattice
there exists a split crystallographic group:
\begin{equation*}
	W=\langle (x,1),(0,s_j):1\leq j\leq l,x\in L'\rangle_{\iso(V)}\cong L\rtimes W_0(R).
\end{equation*}

By Theorem~\ref{theorem}, if $W$ is a crystallographic group of the form \eqref{eq.1 - martinais' groups presentation} from \ref{remark_for_star2}, then every finitely generated $H$ that is elementarily equivalent to $W$ necessarily extends $W_0(R)$ by $L$, and hence falls into one of the isomorphism classes of Martinais's analysis \cite{martinais}. Lemma\cspace\ref{lemma-split extensions are definable} below shows that the isomorphism $H\cong W$ is immediate when $n(W_0(R),L)\leq 2$, since in these cases there are only two possible non-isomorphic extensions: one split, and one non-split. As a result, in the proof of Theorem\cspace\ref{main_th2} we will only need an explicit description of these crystallographic groups in the case $n(W_0(R),L)\geq 3$. So, we briefly recall them in Table\cspace\ref{table - explicit crystallographic groups} below.
\begin{lemma}\label{lemma-split extensions are definable}
	Let $W$ be a crystallographic group with point group $W_0$ and translation subgroup $T$. Then there exists a first-order sentence $\psi$ (depending only on $W_0$, and not on $W$ or $T$) such that $W\models\psi$ if and only if $W$ is split.
\end{lemma}
\begin{proof}
	Let $p:W\rightarrow W_0$ denote the canonical projection of $W$ onto $W_0$, and let $\{w_i:i<k\}$ be an enumeration without repetition of $W_0$. By definition (see \cite[Proposition\phantom{.}2.1, Ch.\phantom{.}IV]{brown}), $W$ is split if and only if there exists an embedding $j:W_0\rightarrow W$ such that $p\circ j=\mathrm{id}_{W_0}$. Since $W_0\cong W/T$, this amounts to saying that there is an embedding of $W_0$ in $W$ whose elements belong to pairwise \mbox{distinct cosets.}

	\smallskip\noindent
	By Lemma\cspace\ref{lemma_the_prop_def_transla_crysp}, the translation subgroup $T$ is $\emptyset$-definable in $W$ by a formula depending only on the order $k$ of $W_0$. Thus, since $W_0$ is finite, it suffices to consider the formula $\psi$ stating the existence of $k$ elements $x_0,\ldots,x_{k-1}$ such that $\{x_0,\ldots,x_{k-1}\}$ is a group isomorphic to $W_0$, and $x_ix_j^{-1}\in T$ if and only if $i=j$.
\end{proof}
\begin{lemma}\label{lemma - abstract reflections and affine reflections cohincide}
	Let $R$ be a reduced root system in a real Euclidean vector space $V$, and let $B$ be a basis of $R$. If $S$ is the system of simple reflections in the Weyl group $W_0(R)$ of $R$ associated to $B$, then, for every $s\in W_0(R)$, the following conditions are equivalent:
	\begin{enumerate}[(1)]
		\item $s$ is an affine reflection of $V$ (cf. Definition\cspace\ref{def - reflection});
		\item $s$ belongs to the set $S^{W_0(R)}\vcentcolon=\{ws_\alpha w^{-1}:\alpha\in B, w\in W_0(R)\}$.
	\end{enumerate}
\end{lemma}
\begin{proof}
	For implication $[1\Rightarrow2]$, suppose that $s\in W_0(R)$ is an affine reflection in $V$ (in the sense of Definition~\ref{def - reflection})). Then, by Fact\cspace\ref{fact - every reflection in a Weyl group is induced by a root}, there exists a root $\alpha'\in R$ such that $s=s_{\alpha'}$. Since $R$ is reduced, Fact\cspace\ref{fact - every root in a reduced root system is the image of a root of the basis through an element of the Weyl group} ensures that any such $\alpha'$ is of the form $\alpha'=w(\alpha)$ for some $\alpha\in B$ and $w\in W_0(R)$. By Fact\cspace\ref{fact - w s_alpha w^-1 = s_w(alpha)}(2), we have:
	\begin{equation*}
		s=s_{w(\alpha)}=ws_\alpha w^{-1},
	\end{equation*}
	\noindent
	and hence $s\in S^{W_0(R)}$.

	\smallskip\noindent
	Similarly, implication $[2\Rightarrow1]$ is an straightforward consequence of Fact\cspace\ref{fact - w s_alpha w^-1 = s_w(alpha)}(2): if $s=ws_\alpha w^{-1}$ for some $\alpha\in B$ and $w\in W_0(R)$, then $s=s_{w(\alpha)}$ (recall that, by Fact\cspace\ref{fact - w s_alpha w^-1 = s_w(alpha)}(1), $w(\alpha) \in R$, and thus  $s_{w(\alpha)}$ is trivially an affine reflection~of~$V$).
\end{proof}
