\begin{remark}\label{remark - all lattices with n>2 is of type Q(R) or P(R)}
	Let $R$ be an irreducible root system in a real vector space $V$ with Weyl group $W_0(R)$. If $L'$ is a $\Z[W_0]$-lattice in $V$ from Table\cspace\ref{table all inequivalent lattices} such that $n(W_0,L')\geq3$, then $L'$ is of type $Q(R)$ or $P(R)$.
\end{remark}
\begin{lemma}\label{lemma - reflections can be detected on the translation subgroup}\label{lemma - logic characterization of reflections}
	Let $V$ be a real Euclidean vector space, and $R$ be a root system of rank $l$ in $V$ with Weyl group $W_0(R) \leq O(V)$. Suppose that $L'$ is a $\Z[W_0(R)]$-lattice from \emph{Table\cspace\ref{table all inequivalent lattices}} such that $n(W_0(R),L')\geq3$, and $T'$ is the abelian group structure on $L'$. Then, for every involution $s\in W_0(R)$ the following conditions are equivalent:
	\begin{enumerate}[(1)]
		\item $s$ is an affine reflection in $V$ (cf. Definition\cspace\ref{def - reflection});
		\item $T'\cap\mathrm{ker}(1-s)$ and $T'\cap\mathrm{ker}(1+s)$ are free abelian of rank $l-1$ and $1$, respectively.
	\end{enumerate}
	Furthermore, if $W$ is a crystallographic group of the form \eqref{eq.1 - martinais' groups presentation} from \ref{remark_for_star2}, with translation subgroup $T=\{(t,1):t\in T'\}$,
	% and $s$ is an involution in $W_0(R)$,
	then, for each $u\in W$ such that $u=(t,s)$, with $t\in V$, (1) and (2) are equivalent to:
	\begin{enumerate}[(3)]
		\item the subgroups $T^u=\{(x,1)\in T:(x,1)^u=(x,1)\}$ and $T_u=\{(x,1)\in T: (x,1)^u=(-x,1)\}$ have rank $l-1$ and $1$, respectively.
	\end{enumerate}
\end{lemma}
\begin{proof}
	For implication $[1\Rightarrow2]$, suppose that $s\in W_0(R)$ is an affine reflection. Then, by Fact\cspace\ref{fact - every reflection in a Weyl group is induced by a root}, there exists some root $\alpha\in R$ such that $s=s_\alpha$. Since $V$ is Euclidean, by Fact\cspace\ref{fact - every involution induces a decomposition of V in ker(1-s)+ker(1+s)} the subspaces $\mathrm{ker}(1-s)$ and $\mathrm{ker}(1+s)$ of $V$ correspond to $H_\alpha$ and $\langle \alpha\rangle_\R$, with $H_\alpha=\{x\in V:(\alpha,x)=0\}$ denoting the hyperplane orthogonal to $\alpha$. We show that $\langle\alpha\rangle_\R\cap T'$ and $H_\alpha\cap T'$ have rank $1$ and $l-1$, respectively.
	%To this extent, one can proceed by a direct case-by-case analysis starting from Bourbaki's explicit descriptions of root systems of types $B_l,C_l$, and $D_l$ in \cite[Planches{\cspace}II to IV]{bourbaki}.

	\smallskip\noindent
	Since $R$ is reduced, Fact\cspace\ref{fact - every root in a reduced root system is the image of a root of the basis through an element of the Weyl group} ensures that each $\alpha$ as above is actually the image of an element $\alpha'$ in some basis $B'$ of $R$ through a map $w\in W_0(R)$. Any such $w$ is an orthogonal map, i.e., an automorphism of $V$ preserving inner products, and hence it maps $H_{\alpha'}$ into $H_\alpha$ and $\langle\alpha'\rangle_\R$ into $\langle\alpha\rangle_\R$. In particular, $w$ transforms the decomposition $V=H_{\alpha'}\oplus\langle \alpha'\rangle_\R$ into $V=H_{\alpha}\oplus\langle \alpha\rangle_\R$. Therefore, since $T'$ is stable under the action of $W_0(R)$, this means that $w$ restricts to an isomorphism between $H_{\alpha'}\cap T'$ and $H_{\alpha}\cap T'$, and an isomorphism between $\langle \alpha'\rangle_\R\cap T'$ and $\langle \alpha\rangle_\R\cap T'$, respectively.

	\smallskip\noindent
	By Fact\cspace\ref{fact - the Weyl group acts simply transitively on the set of bases of a root system}, $W_0(R)$ acts simply transitively on the set of bases of $R$. Hence, without loss of generality, we can assume that $\alpha$ belongs to one of the bases $B$ of $R$ listed in Table\cspace\ref{table - root systems, bases and reflections} in terms of the canonical basis $\{\epsilon_i:1\leq i\leq l\}$ of $V$. According to the root system and lattice types realizing $n(W_0(R),L')\geq 3$, we distinguish the following cases.

	\smallskip\noindent
	\underline{{\bf Case 1}}. $R=B_l$ and $T'=Q(B_l)=CL_l$, with $l\geq3$.

	\smallskip\noindent
	In this case, $T'$ is the $\Z$-linear span of the basis $B=\{\alpha_i:1\leq i\leq l\}$ of $R$ such that:
	\begin{equation}\label{eq.1 - case B_l lemma logical characterization of affine reflections}\tag{$\star_3$}
		\alpha_i=\epsilon_i-\epsilon_{i+1},\quad\text{and}\quad\alpha_l=\epsilon_l,\quad\text{for all}\quad i\in[1,l-1].
	\end{equation} 
	\noindent
	By \ref{fact - basis of a root system}, $B$ is also a basis of $V$, and each element of $T'$ has a unique expression as a $\Z$-linear combination of the $\alpha_i$'s. {Therefore, $\langle \alpha\rangle_\R\cap T'$ is clearly a subgroup of $T'$ of} rank $1$, with free abelian basis $\{\alpha\}$ (alternatively, one can use  {Fact\cspace\ref{fact - every vector in Q(R) l.d. from an indivisible root alpha, is Z-proposrtional to alpha}). To establish} that $H_\alpha\cap T'$ has rank $l-1$, we use the explicit description of $CL_l$ from Table\cspace\ref{table all inequivalent lattices}, {together with the fact that $\{\epsilon_i:1\leq i\leq l\}\subseteq B_l\subseteq T'$. By \eqref{eq.1 - case B_l lemma logical characterization of affine reflections}, we discuss two cases.}

	\smallskip\noindent
	\underline{{\bf Case 1.1}}. $\alpha=\alpha_i=\epsilon_i-\epsilon_{i+1}$, for some $i\in[1,l-1]$.

	\smallskip\noindent
	In this case, the subset $\{\epsilon_j:j\neq i,i+1\}$ of the canonical basis clearly consists of $\R$-linearly independent vectors lying in the intersection $H_\alpha\cap T'$. Since $H_\alpha$ is an $(l-1)$-dimensional subspace, it suffices to complete this set to an $\R$-basis of $H_\alpha$ by adding a suitable $\beta\in H_\alpha\cap T'$ that is $\R$-linear independent from all the $\epsilon_j$'s such that $j\neq i, i+1$. The root $\beta\vcentcolon=\epsilon_i+\epsilon_{i+1}\in B_l$ satisfies these requirements: it lies in $H_\alpha$, since it is orthogonal to $\alpha=\epsilon_i-\epsilon_{i+1}$, and it is clearly $\R$-linearly independent from $\{\epsilon_j:j\neq i, i+1\}$. Consequently, $\{\beta,\epsilon_j:j\neq i, i+1\}$ is a free abelian basis of $H_\alpha\cap T'$ of size $l-1$.

	%Observe that the roots $\alpha_3,\ldots,\alpha_l$ are linearly independent over $\R$ and lie in the intersection $H_\alpha\cap R$. Since $H_\alpha$ is an $(l-1)$-dimensional subspace, it suffices to complete the set $\{\alpha_3,\ldots,\alpha_l\}$ to an $\R$-basis of $H_\alpha$ by adding a suitable $\beta_1\in H_\alpha\cap T'$ that is $\R$-linear independent form $\alpha_3,\ldots,\alpha_l$. The root $\beta_1\vcentcolon=\epsilon_1+\epsilon_2\in B_l$ satisfies these requirements: it lies in $H_\alpha$, since it is orthogonal to $\alpha=\epsilon_1-\epsilon_2$, and it is clearly $\R$-linear independent from $\alpha_3,\ldots,\alpha_l$. Consequently, $\{\beta_1,\alpha_3, \ldots,\alpha_l\}$ is a free abelian basis of $H_\alpha\cap T'$ of size $l-1$.

	\smallskip\noindent
	\underline{{\bf Case 1.2}}. $\alpha=\alpha_l=\epsilon_l$.

	\smallskip\noindent
	This case is trivial: $\{\epsilon_j:1\leq j<l\}$ is a basis of $H_\alpha$ lying entirely in $T'$. Hence, it is a free abelian basis of $H_\alpha\cap T'$.

	\smallskip\noindent
	\underline{{\bf Case 2}}. $R=B_4$, and $T'=P(B_4)=CCL_4$.

	\smallskip\noindent
	In this case, by the explicit description of $CCL_4$ in Table\cspace\ref{table - martinais nomenclature}, each element $x\in T'$ has a unique expression as a $\Z$-linear combination of the form:
	\begin{equation}\tag{$\star_4$}\label{eq.1 - reflections of type B_4 and CCL_4}
		x=\sum_{j=1}^3a_i\epsilon_j+b\left(\frac{1}{2}(\epsilon_1+\ldots+\epsilon_4)\right)=\sum_{j=1}^3\left(a_j+\frac{b}{2}\right)\epsilon_j+\frac{b}{2}\epsilon_4,
	\end{equation}
	\noindent
	for some $a_1,a_2,a_3,b\in\Z$. 

	\smallskip\noindent
	By Table\cspace\ref{table - root systems, bases and reflections}, we can consider the basis $B=\{\alpha_i:1\leq l\leq4\}$ for $B_4$ such that:
	\begin{equation}\label{eq.2 - case B_4 lemma logical characterization of affine reflections}\tag{$\star_5$}
		\alpha_i=\epsilon_i-\epsilon_{i+1},\quad\text{and}\quad\alpha_4=\epsilon_4,\quad\text{for all}\quad i\in[1,3].
	\end{equation}
	\noindent
	Since $T'=P(B_4)$ strictly contains the group $Q(B_4)$ of radical weights of $B_4$, the set $B$ does not form a free abelian basis of $T'$. As a consequence, for each $\alpha\in B$, we cannot directly conclude that $\langle \alpha\rangle_\R\cap T'$ coincides with the $\Z$-linear span of $\alpha$, and we must verify, case by case, both that $\langle \alpha\rangle_\R\cap T'$ has rank $1$ and that $H_\alpha\cap T'$ has rank $l-1$. In particular, from \eqref{eq.2 - case B_4 lemma logical characterization of affine reflections} we distinguish three possibilities.

	\smallskip\noindent
	\underline{{\bf Case 2.1}} $\alpha=\alpha_i=\epsilon_i-\epsilon_{i+1}$, with $i\in[1,2]$.

	\smallskip\noindent
	To prove that $H_\alpha\cap T'$ has rank $3$, we study the set of solutions $(a_1,a_2,a_3,b)\in\Z^4$ of the equation $(\alpha,x)=0$, for $x\in T'$ as in \eqref{eq.1 - reflections of type B_4 and CCL_4}. This is the set of tuples satisfying the identity $a_i=a_{i+1}$. Hence, each $x\in H_\alpha\cap T'$ is expressible a as linear a combination:
	\begin{equation*}
		x=a_k\epsilon_k+a_i(\epsilon_i+\epsilon_{i+1})+b\left(\frac{1}{2}(\epsilon_1+\ldots+\epsilon_4)\right),
	\end{equation*}
	\noindent
	such that $a_i,a_k,b\in\Z$ and $k\in\{1,2,3\}\setminus\{i,i+1\}$. This shows that \mbox{$\{\epsilon_k,\epsilon_i+\epsilon_{i+1},$}\\{$\frac{1}{2}(\epsilon_1+\ldots+\epsilon_4)\}$} is a set of generators for $H_\alpha\cap T'$. The $\Z$-linear independence follows\\directly from that of the free abelian basis \mbox{$\{\epsilon_1,\epsilon_2,\epsilon_3,\frac{1}{2}(\epsilon_1+\ldots+\epsilon_4)\}$ of $T'=CCL_4$.}
	%\todog{It follows from a general theory (see \cite[Planches I to VIII]{bourbaki}) that a free abelian basis for $CCL_4=P(B_4)$ is the system of fundamental weights:
	%	\begin{equation*}
	%		\overline{\omega}_1=\epsilon_1,\quad \overline{\omega}_2=\epsilon_1+\epsilon_2, \quad\overline{\omega}_3=\epsilon_1+\epsilon_2+\epsilon_3,
			%=\sum_{j=1}^i\epsilon_j,
	%		\quad\text{and}\quad\overline{\omega}_4=\frac{1}{2}\left(\sum_{j=1}^4\epsilon_i\right).
	%	\end{equation*}
	%	\noindent
	%From here, you take the map:
	%\begin{equation*}
	%\overline{\omega}_1\mapsto\overline{\omega}_1=\epsilon_1, \quad \overline{\omega}_2\mapsto \epsilon_2,\quad \overline{\omega}_3\mapsto\epsilon_3,\quad \overline{\omega}_4\mapsto\overline{\omega}_4.
	%\end{equation*}
	%\noindent
	%This is clearly surjective, and hence an isomorphism by Hopfianity.	I tried to stay as contained as possible, but if you think that is better not to just cite Martinais, I'll implement this fact.}

	\smallskip\noindent
	Similarly, it is straightforward to verify that any $x\in \langle\alpha\rangle_\R\cap T'$ as in \eqref{eq.1 - reflections of type B_4 and CCL_4} is uniquely determined by a tuple $(a_1,a_2,a_3,b)\in\Z^4$ such that:
	\begin{equation*}
		b=0,\quad a_i=-a_{i+1},\quad \text{and}\quad a_k=0,\quad \text{for} \quad k\in\{1,2,3\}\setminus\{i,i+1\}.
	\end{equation*}
	\noindent
	Therefore, $\alpha=\epsilon_i-\epsilon_{i+1}$ itself is a free generator of $\langle \alpha\rangle_\R\cap T'$, as \mbox{$\alpha\in B_4\subseteq P(B_4)=T'$.}

	\smallskip\noindent
	\underline{{\bf Case 2.2}} $\alpha=\alpha_3=\epsilon_3-\epsilon_4$.

	\smallskip\noindent
	By imposing the condition $(\alpha,x)=0$ on the elements $x\in T'$ as in \eqref{eq.1 - reflections of type B_4 and CCL_4}, we deduce that each $x\in H_\alpha\cap T'$ corresponds uniquely to a tuple $(a_1,a_2,a_3,b)\in \Z^4$ satisfying $a_3=0$. It follows that $\{\epsilon_1,\epsilon_2,\frac{1}{2}(\epsilon_1+\ldots+\epsilon_4)\}$ is a free abelian basis of \mbox{$H_\alpha \cap T'$.}

	\smallskip\noindent
	Similarly, each tuple $(a_1,a_2,a_3,b)\in \Z^4$ identifying some $x\in \langle \alpha\rangle_\R\cap T'$ must satisfy the identities:	
	\begin{equation*}
		a_1=a_2=-\frac{b}{2},\quad\text{and}\quad a_3=-b.
	\end{equation*}
	\noindent
	Thus, any such $x$ has an expression of the form:
	\begin{equation*}
		x=a \epsilon_1+a\epsilon_2+2a\epsilon_3-2a\left(\frac{1}{2}(\epsilon_1+\ldots+\epsilon_4)\right)=a\left(\epsilon_3-\epsilon_4\right),
	\end{equation*}
	\noindent
	for some $a\in\Z$. Hence, $\alpha=\epsilon_3-\epsilon_4$ itself is a free generator of $\langle\alpha\rangle_\R\cap T'$.

	\smallskip\noindent
	\underline{{\bf Case 2.3}} $\alpha=\alpha_4=\epsilon_4$.

	\smallskip\noindent
	In this case, \eqref{eq.2 - case B_4 lemma logical characterization of affine reflections} directly witnesses that $\{\epsilon_1,\epsilon_2,\epsilon_3\}\subseteq CCL_4=T'$ is a free abelian basis of $H_\alpha\cap T'$. Moreover, each $x\in\langle\alpha\rangle_\R\cap T'$ as in \eqref{eq.1 - reflections of type B_4 and CCL_4} is uniquely determined by a tuple $(a_1,a_2,a_3,b)\in\Z^4$ such that:
	\begin{equation*}
		a_1=a_2=a_3=-\frac{b}{2}
	\end{equation*}
	\noindent
	Therefore, any such $x$ is of the form:
	\begin{equation*}
		x=a\epsilon_1+a\epsilon_2+a\epsilon_3-2a\left(\frac{1}{2}(\epsilon_1+\ldots+\epsilon_4)\right)=a\epsilon_4,
	\end{equation*}
	\noindent
	for some $a\in\Z$. Therefore, also in this case $\alpha$ is a free generator of $\langle\alpha\rangle_\R\cap T'$.

	\smallskip\noindent
	\underline{{\bf Case 3}}. $C_l$, and $T'=Q(C_l)=FL_l$, with $l\geq3$ odd.

	\smallskip\noindent
	In this case, $T'$ is the free $\Z$-linear span of the basis $B=\{\alpha_i:1\leq i\leq l\,\}$ of $C_l$ such that:
	\begin{equation}\label{eq.3 - case C_l lemma logical characterization of affine reflections}\tag{$\star_6$}
		\alpha_i=\epsilon_i-\epsilon_{i+1},\quad\text{and}\quad\alpha_l=2\epsilon_l,\quad\text{for all}\quad i\in[1,l-1]
	\end{equation} 
	\noindent
	(see Table\cspace\ref{table - root systems, bases and reflections}). Since we assumed $\alpha\in B$, it follows that $\langle \alpha\rangle_\R\cap T'$ is necessarily a rank-$1$ subgroup of $T'$ freely generated by $\alpha$ (cf. Fact\cspace\ref{fact - every vector in Q(R) l.d. from an indivisible root alpha, is Z-proposrtional to alpha}). Moreover, each $x\in T'$ admits a unique expression as a linear combination:
	\begin{equation}\label{eq.4 - case C_l lemma logical characterization of affine reflections}\tag{$\star_7$}
		x=\sum_{i=1}^la_i\alpha_i
		%=\sum_{i=1}^la_i(\epsilon_i-\epsilon_{i+1})+2a_l\epsilon_l
		=a_1\epsilon_1+\sum_{j=2}^{l-1}(a_j-a_{j-1})\epsilon_j+(2a_l-a_{l-1})\epsilon_l,
	\end{equation}
	\noindent
	for some $a_1,\ldots,a_l\in\Z$. To compute the rank of $H_\alpha\cap T'$, we refer to \eqref{eq.3 - case C_l lemma logical characterization of affine reflections} and distinguish four cases.

	\smallskip\noindent
	\underline{{\bf Case 3.1}}. $\alpha=\alpha_1=\epsilon_1-\epsilon_2$.

	\smallskip\noindent
	By imposing the condition $(\alpha,x)=0$ on the elements $x\in T'$ as in \eqref{eq.4 - case C_l lemma logical characterization of affine reflections}, we obtain that each $x\in H_\alpha\cap T'$ is uniquely determined by a tuple $(a_1,\ldots,a_l)\in\Z^l$ such that $2a_1-a_2=0$. Hence, any such $x$ is of the form:
	\begin{equation*}
		x=\sum_{j\neq 1,2}a_j\alpha_j+a_1\alpha_1+2a_1\alpha_2= \sum_{j\neq 1,2}a_j\alpha_j+a_1(\alpha_1+2\alpha_2).
	\end{equation*}
	\noindent
	It follows that $\{\alpha_j,\alpha_1+2\alpha_2:j\neq 1,2\}\subseteq Q(C_l)=T'$ is a generating set of $H_\alpha\cap T'$. We claim that this is actually a free abelian basis of $H_\alpha\cap T'$.

	\smallskip\noindent
	Adding $\alpha_2$ to $\{\alpha_j,\alpha_1+2\alpha_2:j\neq 1,2\}$ yields a generating set for $T'$ of cardinality $l$. Since free abelian groups of finite rank are Hopfian, it follows that $\{\alpha_2,\alpha_j,\alpha_1+2\alpha_2:j\neq 1,2\}$ is a free abelian basis of $T'$. In particular, the set $\{\alpha_j,\alpha_1+2\alpha_2:j\neq 1,2\}$ consists of $\Z$-linearly independent vectors, and thus forms a free abelian basis of $H_\alpha\cap T'$.	

	\smallskip\noindent
	\underline{{\bf Case 3.2}}. $\alpha=\alpha_i=\epsilon_i-\epsilon_{i+1}$, for some $i\in[2,l-2]$.

	\smallskip\noindent
	As above, by imposing the condition $(\alpha,x)=0$ on the elements $x\in T'$ as in \eqref{eq.4 - case C_l lemma logical characterization of affine reflections}, one derives that each $x\in H_\alpha\cap T'$ uniquely corresponds to a tuple $(a_1,\ldots,a_l)\in\Z^l$ satisfying $2a_i-a_{i-1}-a_{i+1}=0$. Hence, any such $x$ is of the form:
	\begin{equation*}
		\begin{split}
			x&=\sum_{j\neq i,i+1}a_j\alpha_j+a_i\alpha_i+(2a_i-a_{i-1})\alpha_{i+1}\\
			&= \sum_{j\neq i-1,i,i+1}a_j\alpha_j+a_{i-1}(\alpha_{i-1}-\alpha_{i+1})+a_i(\alpha_i+2\alpha_{i+1}).
		\end{split}
	\end{equation*}
	\noindent
	Therefore, the subset $\{\alpha_j,\alpha_{i-1}-\alpha_{i+1}, \alpha_i+2\alpha_{i+1}:j\neq i-1,i,i+1\}\subseteq Q(C_l)=T'$ generates $H_\alpha\cap T'$. Extending this set by including $\alpha_{i-1}$ yields a generating set for $T'$ of cardinality $l$. Consequently, by Hopfianity,
    %Fact\cspace\ref{fact - free abelian groups of finite rank are Hopfian}(3)
    the set $\{\alpha_j,\alpha_{i-1}-\alpha_{i+1}, \alpha_i+2\alpha_{i+1}:j\neq i-1,i,i+1\}$ consists of $\Z$-linearly independent vectors, and hence forms a free abelian basis of $H_\alpha\cap T'$.

	\smallskip\noindent
	\underline{{\bf Case 3.3}}. $\alpha=\alpha_{l-1}=\epsilon_{l-1}-\epsilon_{l}$.

	\smallskip\noindent
	By studying the set of solutions of the equation $(\alpha,x)=0$, for $x\in T'$ as in \eqref{eq.4 - case C_l lemma logical characterization of affine reflections}, one derives that each $x\in H_\alpha\cap T'$ uniquely corresponds to a tuple $(a_1,\ldots,a_l)\in\Z^l$ satisfying \mbox{$-a_{l-2}+2a_{l-1}-2a_{l}=0$.} Thus, any such $x$ is of the form:
	\begin{equation*}
		\begin{split}
			x&=\sum_{j\neq l-2}a_j\alpha_j+(2a_{l-1}-2a_{l})\alpha_{l-2}\\
			&= \sum_{j\neq l-2,l-1,l}a_j\alpha_j+a_{l-1}(\alpha_{l-1}+2\alpha_{l-2})+a_l(\alpha_l-2\alpha_{l-2}).
		\end{split}
	\end{equation*}
	\noindent
	This proves that the subset $\{\alpha_j,\alpha_{l-1}+2\alpha_{l-2}, \alpha_l-2\alpha_{l-2}:j\neq l-2,l-1,l\}\subseteq Q(C_l)=T'$ generates $H_\alpha\cap T'$. Extending it by including $\alpha_{l-2}$ gives a generating set for $T'$ of cardinality $l$. By Hopfianity, it follows that the vectors in $\{\alpha_j,\alpha_{l-1}+2\alpha_{l-2}, \alpha_l-2\alpha_{l-2}:j\neq l-2,l-1,l\}$ are also $\Z$-linearly independent, and hence form a free abelian basis of $H_\alpha\cap T'$ of size $l-1$.

	\smallskip\noindent
	\underline{{\bf Case 3.4}}. $\alpha=\alpha_l=2\epsilon_l$.

	\smallskip\noindent
	As in the previous cases, the analysis of the equation $(\alpha,x)=0$, for $x\in T'$ as in \eqref{eq.4 - case C_l lemma logical characterization of affine reflections}, shows that each $x\in H_\alpha\cap T'$ is uniquely determined by a tuple $(a_1,\ldots,a_l)\in\Z^l$ satisfying the relation $2a_{l}-a_{l-1}=0$. Hence, any such $x$ is of the form:
	\begin{equation*}
			x=\sum_{j\neq l-1,l}a_j\alpha_j+2a_{l}\alpha_{l-1}+a_l\alpha_l= \sum_{j\neq l-1,l}a_j\alpha_j+a_{l}(2\alpha_{l-1}+\alpha_l).
	\end{equation*}
	\noindent
	It follows that the subset $\{\alpha_j,2\alpha_{l-1}+\alpha_l:j\neq l-1,l\}\subseteq Q(C_l)=T'$ generates $H_\alpha\cap T'$. Extending it by including $\alpha_{l-1}$ yields a generating set for $T'$ of cardinality $l$. Since free abelian groups of finite rank are Hopfian, the original set $\{\alpha_j,2\alpha_{l-1}+\alpha_l:j\neq l-1,l\}$ must consist of $\Z$-linearly independent vectors. Therefore, it is a free abelian basis of $H_\alpha\cap T'$ of size $l-1$.

	\smallskip\noindent
	\underline{{\bf Case 4}}. $R=D_l$, and $T'=Q(D_l)=FL_l$, with $l\geq6$ even.

