    \begin{equation}\label{eq.1 - direction 2->1 lemma characterization of reflections}\tag{$\star_{8}$}
        \frac{a_1}{b_1}x_1+\frac{a_2}{b_2}x_2+\ldots+\frac{a_{l-1}}{b_{l-1}}x_{l-1}=0.
    \end{equation}
