We now introduce a notation that will simplify the proof of Theorem\cspace\ref{lemma - all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}.
\begin{notation}\label{notation - lemma all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}
	Let $V,R,S,\Delta_S,L'$ be as follows:
	\begin{enumerate}[$\bullet$]
		\item $V$ is a real Euclidean vector space of finite dimension $l$;
		\item $R$ is an irreducible root system in $V$, with Weyl group $W_0(R)\leq O(V)$;
		\item $S=\{s_1,\ldots,s_l\}$ is a system of simple reflections in $W_0(R)$ induced by a basis $B=\{\alpha_1,\ldots,\alpha_l\}$ of $R$;
		\item $\Delta_S$ is the Coxeter diagram of the system $(W_0(R),S)$ (cf.\cspace\ref{fact - simple reflections form a Coxeter system of the Weyl gp});
		\item $L'$ is a ($\Z[W_0(R)]$-)lattice from Table\cspace\ref{table - martinais nomenclature} such that $n(W_0(R),L')\geq 3$ (cf. Table\cspace\ref{table all inequivalent lattices}).
	\end{enumerate}
	\noindent
	Then, by Lemma\cspace\ref{lemma_the_prop_def_transla_crysp}, the translation subgroup of any crystallographic group extending $W_0(R)$ by $L'$ is $\emptyset$-definable by a first-order formula (in the language of groups) 
	depending only on the order of $W_0(R)$. For the ease of reading, we denote by $T$ the set of realizations of such formula.

	\smallskip\noindent
	For each $g\in W_0(R)$ we fix a group word $w_g(x_1,\ldots,x_l)$ such that $g=w_g(s_1,\ldots,s_l)$.
	%Let $\mathrm{Word}=\{w_g(x_1,\ldots,x_l):g\in W_0(R)\}$ be the set of such words. 
	Then, we let $\eta_{\Delta_S}(x_1,\ldots,x_l)$ be the first-order formula (in the language of groups) asserting that:
	\begin{enumerate}[(1)]
		\item $\langle x_1T,\ldots,x_lT\rangle\cong W_0(R)$ via the map $s_i\mapsto x_iT$, for $i\in[1,l\,]$;
		\item for each $g\in W_0(R)$, $g$ belongs to $S^{W_0(R)}=\{ws_iw^{-1}:1\leq i\leq l, w\in W_0(R)\}$ if and only if the following conditions are simultaneously satisfied by some (or, equivalently, any) $x\in w_g(x_1,\ldots,x_l)T$:
		\begin{enumerate}[(a)]
			%\item $xT$ is an involution (i.e., $x^2T=T$); 
			\item $T^{x}\vcentcolon=\{t\in T:(t)^{x}=t\}$ has quotient $T^{x}/2T^{x}$ of cardinality $2^{\,l-1}$;
			\item $T_{x}\vcentcolon=\{t\in T:(t)^{x}=-t\}$ has quotient $T_{x}/2T_{x}$ of cardinality $2$.
		\end{enumerate}
	\end{enumerate}
	\noindent
	Since $W_0(R)$ is finite and the set of words $w_g(x_1,\ldots,x_l)$ is fixed, these conditions are clearly first-order expressible.	
\end{notation}
\begin{remark}\label{notation_2 - lemma all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}
	In the setting of Notation\cspace\ref{notation - lemma all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}, let $W$ be a subgroup of $\iso(V)$ with presentation \eqref{eq.1 - martinais' groups presentation}, and $(u'_1,\ldots,u'_l)$ be a tuple realizing $\eta_{\Delta_S}(x_1,\ldots,x_l)$ in $W$ such that $u_i'=(t'_i,s_i')$ for all $i\in[1,l\,]$. Then, by Lemma\cspace\ref{lemma - affine projection and quotient projection coincide}, item $(1)$ in the definition of $\eta_{\Delta_S}(x_1,\ldots,x_l)$ just states that the assignment $s_i\mapsto s'_i$ extends to an automorphism $f$ of $W_0(R)$. This automorphism maps each involution $g=w_g(s_1,\ldots,s_l)\in S^{W_0(R)}$ into a term $g'=w_g(s'_1,\ldots,s_l')$. Then, denoting by $\theta:W/T\rightarrow W_0(R)$ the isomorphism in \eqref{eq.1 - isomorphism theta:W/T->W_0(R)}, items $(2)(a)(b)$ in the definition of $\eta_{\Delta_S}(x_1,\ldots,x_l)$ are equivalent to saying that the conjugation by each $u\in \theta^{-1}(g')$ stabilizes two free abelian subgroups $T^u=\{x\in T:x^u=x\}$ and $T_u=\{x\in T:x^u=-x\}$ of rank $l-1$ and $1$, respectively. By Lemma\cspace\ref{lemma - logic characterization of reflections}, this means that $g'\in W_0(R)$ is an affine reflection, and hence $g'\in S^{W_0(R)}$, by Lemma\cspace\ref{lemma - abstract reflections and affine reflections cohincide}. Consequently, by Fact\cspace\ref{fact - every automorphism of a Weyl group of an irreducible root system is inner-by-grapph}, $f\in \mathrm{Aut}(W_0(R))$ is inner-by-graph.

	\smallskip\noindent
	In particular, the corresponding automorphism $f_T\in \mathrm{Aut}(W/T)$ induced by $f$ via the identification $\theta^{-1}:W_0(R)\rightarrow W/T$ of Lemma\cspace\ref{lemma - affine projection and quotient projection coincide} is a coset permutation such that:
	\begin{enumerate}[(1)]
		\item $f_T((t_i,s_i)T)=u'_iT$ for each $i\in[1,l\,]$;
		\item $f=(\,\cdot\,)^{u'T}\circ f_\sigma$, for some $u'\in W$ and some graph automorphism $f_\sigma$ of the system $(W/T,\{(t_1,s_1)T,\ldots,(t_l,s_l)T\})$ (where $(t_1,s_1),\ldots,(t_l,s_l)$ are the generators of $W$ from the presentation \eqref{eq.1 - martinais' groups presentation}).
	\end{enumerate}
