	%\end{equation*}
	%\noindent
	%such that $\eta_{\Delta_S}(x_1,\ldots,x_l)$ is as in \ref{notation - lemma all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}, depending only on $(W_0(R),S)$ (and the fixed set of group words $w_g(x_1,\ldots,x_l)$), and $\chi(x_1,\ldots,x_l)$ is a formula, depending on $W$, that involves only bounded quantifications over $x_1T,\ldots,x_lT$ (i.e., of type $\forall y\in x_iT$ and $\exists y\in x_iT$) and whose truth is preserved under the action of the graph automorphisms of the system $(W/T,\{(t_1,s_1),\ldots,(t_l,s_l)\})$.
\end{remark}

\medskip
The last ingredient that we need towards the proof of Theorem\cspace\ref{main_th2} is a straightforward observation on some of the Coxeter diagrams in Table\cspace\ref{table - Coxeter diagrams of irreducible root systems}.
\begin{fact}\label{fact - form of inner-by-graph automorphisms in the case B_l,C_l,D_l}
	Let $R$ be an irreducible reduced root system of rank $l\geq3$ with Coxeter diagram $\Delta=\{s_1,\ldots,s_l\}$ as in Table\cspace\ref{table - Coxeter diagrams of irreducible root systems}. Then,
	\begin{enumerate}[(1)]
		\item if $R=B_l$, the only automorphism of $\Delta$ is the identity;
		\item if $R=D_l$, the only automorphisms of $\Delta$ are the identity and the transposition of the nodes $s_{l-1}$ and $s_l$. 
	\end{enumerate}
\end{fact}
\begin{theorem}\label{lemma - all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}
	Every crystallographic group arising from an irreducible root system is profinitely rigid (equivalently, first-order rigid).
\end{theorem}
\begin{proof}
	In light of Fact\cspace\ref{Oger}, it suffices to show that every crystallographic group $W$ arising from an irreducible root system is first-order rigid. 

	\smallskip\noindent
	By Fact\cspace\ref{fact - existence reduced root system and sandwich condition}, $W$ admits an affine realization as a group of isometries of a real Euclidean vector space $V$, with point group the Weyl group $W_0(R)$ of an irreducible root system $R$ in $V$, and translation lattice of the form $L=\{(t,1):t\in L'\}$, where $L'$ is a lattice in $V$ satisfying:
	\begin{equation*}
		Q(R)\leq L'\leq P(R).
	\end{equation*}
	\noindent
	By Lemma\cspace\ref{lemma-every_lattice_L_s.t._Q(R)<L<P(R)_is_absolutely_irreducible}, $L'$ and $L$ are absolutely irreducible. Therefore, if $H$ is a finitely generated group elementarily equivalent to $W$, it follows from Lemma\cspace\ref{thm. - absolutely irreducible -> there are only finitely many maximal centerings} and Theorem\cspace\ref{theorem} that $H$ is crystallographic with point group $P(H)\cong W_0(R)$ and translation lattice $L(H)\cong L$. In other words, both $W$ and $H$ are extensions of $W_0(R)$ by $L$. According to the number $n(W_0(R),L)$ of isomorphism classes of such extensions, we distinguish the following cases.	

	\smallskip\noindent
	\underline{{\bf Case 1}}. $n(W_0(R),L)=1$.
	\newline In this case both $W$ and $H$ are split and the result follows immediately.

	\smallskip\noindent
	\underline{{\bf Case 2}}. $n(W_0(R),L)=2$.
	\newline In this case there are just two non-isomorphic extensions of $W_0(R)$ by $L$: one split and the other non-split. By Lemma\cspace\ref{lemma-split extensions are definable}, there is a sentence $\psi_R$ (depending only on $R$) that is satisfied only by those extensions of $W_0(R)$ by $L$ that are split. So, since $W$ and $H$ are elementarily equivalent, either they both satisfy $\psi_R$ (and they are split), or they satisfy $\neg\psi_R$ (and they are non-split). In both cases they are isomorphic.

	\smallskip\noindent
	From the standard classification of wallpaper groups (cf. \cite[Table\cspace2]{hiller}), it is known that for any Weyl group $W_0(R)$ associated to an irreducible root system $R$ of rank $2$ there are at most two isomorphism classes of $2$-dimensional crystallographic groups having $W_0(R)$ as point group. Hence, in the remaining cases we may assume that the rank $l$ of $R$ is at least $3$. In this setting, both $W$ and $H$ are isomorphic to certain representatives of Martinais's classification (see Table\cspace\ref{table - explicit crystallographic groups}). Consequently, for fixed $R$ and $L$, it suffices to prove that no two such representatives are elementarily equivalent. In particular, in each case we will distinguish the non-split extensions $W_n$ listed in Table\cspace\ref{table - explicit crystallographic groups} by means of sentences of the form:
	\begin{equation}\label{eq.0 - lemma - all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}\tag{$\star_{10}$}
		\zeta_m\equiv \forall x_1,\ldots,x_l(\eta_{\Delta_S}(x_1,\ldots,x_l)\rightarrow \chi_m(x_1,\ldots,x_l)),
	\end{equation}
	\noindent
	such that:
	\begin{enumerate}[$\bullet$]
		\item $W_n\models\zeta_m$ if and only if $n=m$;
		\item $\eta_{\Delta_S}(x_1,\ldots,x_l)$ is a formula as in Notation\cspace\ref{notation - lemma all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}, depending only on the Coxeter system $(W_0(R),S)$ given by the simple reflections $S=\{s_1,\ldots,s_l\}$ of Table\cspace\ref{table - root systems, bases and reflections}, and a fixed set of group words $w_g(x_1,\ldots,x_l)$;
		\item $\chi_m(x_1,\ldots,x_l)$ is a formula consisting of a quantifier free formula $\tau_m(z_1,\ldots,z_l)$ 
		%depending on $W_n$
		preceded by quantifications bounded over the cosets $x_1T,\ldots,x_lT$, that is, quantifications of type $\forall z_i\in x_iT$ and $\exists z_i\in x_iT$. In particular, the truth value of $\chi_m(x_1,\ldots,x_l)$ depends only on the cosets $x_1T,\ldots,x_lT$, and not strictly on $x_1,\ldots,x_l$ themselves.
		% and whose truth is preserved under the action of the graph automorphisms of the system $(W_n/T,\{(t_1,s_1)T,\ldots,(t_l,s_l)T\})$;
	\end{enumerate}
	\noindent 
	By Remark\cspace\ref{notation_2 - lemma all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}, if $(u'_1,\ldots,u'_l)$ is a tuple realizing $\eta_{\Delta_S}(x_1,\ldots,x_l)$ in $W_n$ and $u_1=(t_1,s_1),\ldots,u_l=(t_l,s_l)$ are the generators in the presentation of $W_n$ in Table\cspace\ref{table - explicit crystallographic groups} corresponding to the simple reflections $s_1,\ldots,s_l$, then there exist some $u\in W_n$ and a graph automorphism $f_\sigma$ of $(W_n/T,\{u_1T,\ldots,u_lT\})$ such that, for every $i\in[1,l\,]$:
	\begin{equation}\label{eq.1 - lemma - all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}\tag{$\star_{11}$}
		u'_iT=(f_\sigma(u_iT))^{uT}.
	\end{equation}
	\noindent
	Since $f_\sigma$ acts as a permutation of $\{u_1T,\ldots,u_lT\}$, it can be identified with the corresponding index permutation $\sigma$ such that $f_\sigma(u_iT)=u_{\sigma(i)}T$ for each $i\in[1,l\,]$. Consequently, \eqref{eq.1 - lemma - all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid} reduces to the following coset identity:
	\begin{equation}\label{eq.2 - lemma - all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}\tag{$\star_{12}$}
		u'_iT=(u_{\sigma(i)}T)^{uT}=uu_{\sigma(i)}u^{-1}T=(u_{\sigma(i)})^uT.
	\end{equation}
	\noindent
	By construction, the truth value of $\chi_m(x_1,\ldots,x_l)$ only depends on the cosets $x_1T,\ldots,x_lT$ and not on $x_1,\ldots,x_l$ themselves. Hence, \eqref{eq.2 - lemma - all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid} and the fact that  $(\,\cdot\,)^u\in\mathrm{Aut}(W_n)$ witness that:
	\begin{equation*}
		\begin{split}
			W_n\models\chi_m(u_1',\ldots,u_l') \quad&\iff\quad W_n\models\chi_m((u_{\sigma(1)})^u,\ldots,(u_{\sigma(l)})^u)\\
			&\iff\quad W_n\models\chi_m(u_{\sigma(1)},\ldots,u_{\sigma(l)}).
		\end{split}
	\end{equation*}
	\noindent
	In all but one of the cases considered below, the root system $R$ is of type $B_l$ or $C_l$ (cf. Table\cspace\ref{table all inequivalent lattices}), and by Fact\cspace\ref{fact - form of inner-by-graph automorphisms in the case B_l,C_l,D_l} the permutation $\sigma$ is trivial. In the remaining case, $R$ is of type $D_l$, and the only non-trivial graph automorphism corresponds to the transposition of the indices $l-1$ and $l$. In this instance, we select the formulas $\chi_m(x_1,\ldots,x_l)$ to be symmetric in the variables $x_{l-1}$ and $x_l$, and hence invariant under the action of $\sigma$. In both cases, we have:
	\begin{equation*}
		W_n\models\chi_m(u_{\sigma(1)},\ldots,u_{\sigma(l)})\quad\iff\quad W_n\models\chi_m(u_1,\ldots,u_l). 
	\end{equation*}
	\noindent	
	This procedure allows to verify the truth value of a universal statement by a direct analysis of the cosets of the generators $u_1=(t_1,s_1),\ldots,u_l=(t_l,s_l)$. We will use this fact freely in what follows.
	%{Alternatively, we can say:
	%\say{In each of the following cases we will select $\chi_m(x_1,\ldots,x_l)$ so that  $W_n\models\chi_m(u_{\sigma(1)},\ldots,u_{\sigma(l)})$ if and only if $W_n\models\chi_m(u_1,\ldots,u_l)$. This procedure allows to verify the truth value of a universal statement by a direct analysis of the cosets of the generators $u_1=(t_1,s_1),\ldots,u_l=(t_l,s_l)$. We will use this fact freely in the following.}}

	\noindent\smallskip
	\underline{{\bf Case 3}}. $n(W_0(R),L)=3$.
	\newline In this case, according to Tables\cspace\ref{table all inequivalent lattices} and \ref{table - explicit crystallographic groups}, we must have $R=D_l$ and $L=FL_l$, for some even $l\geq 6$. A complete system of representatives of the isomorphism classes of crystallographic groups extending $W_0(R)$ by $L$ is the following:
	\begin{enumerate}[$\bullet$]
		\item $W_1=\langle (\sum_{i=1}^la_i\epsilon_i,1),(0,s_j):1\leq j\leq l, a_i\in\Z, \sum_{i=1}^la_i\in2\Z\rangle_{\iso(V)}$;
		\item $W_2=\langle (\sum_{i=1}^la_i\epsilon_i,1),(\epsilon_1,s_j):1\leq j\leq l, a_i\in\Z, \sum_{i=1}^la_i\in2\Z\rangle_{\iso(V)}$;
		\item \mbox{$W_3=\langle (\sum_{i=1}^la_i\epsilon_i,1),(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_j):1\leq j\leq l, a_i\in\Z, \sum_{i=1}^la_i\in2\Z\rangle_{\iso(V)}$.}
	\end{enumerate}
	\noindent
	Note that $W_1$ is split. Hence, by Lemma\cspace\ref{lemma-split extensions are definable}, $W_1\models \psi_{D_l}$ and $W_2,W_3\models\neg\psi_{D_l}$.

	\smallskip\noindent
	%Let $W_0(D_l)=(w_i:i<k)$ be an enumeration without repetitions of $W_0(D_l)$ such that $w_0=e$ and $w_i=s_i$, for $1 \leq i \leq l$. For any $j<k$, we fix a finite tuple $(i^j_1,\ldots,i^j_m)\in \{1, ..., l\}^{<\omega}$ (with $m$ depending on $j$) such that $w_j=w_{i_1^j}\cdot\ldots\cdot w_{i_m^j}$, and denote by $\mathrm{Ref}$ the subset of $k$ consisting of those $j$ indexing an affine reflection $w_j$ in $V$, or equivalently, recalling \ref{lemma - abstract reflections and affine reflections cohincide}, an element of $S^{W_0(R)}$, where $S$ is the Coxeter basis of $W_0(R)$ corresponding to a fixed basis $B$ or $R$.
	Let $\zeta_2,\zeta_3$ be sentences of the form \eqref{eq.0 - lemma - all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}, and $\chi_2(x_1,\ldots,x_l),\chi_3(x_1,\ldots,x_l)$ be the first-order formulas defined as follows: 
	\begin{enumerate}[$\bullet$]
		\item $\chi_2(x_1,\ldots,x_l)$ states that there exist $z_{l-1}\in x_{l-1}T$ and $z_l\in x_lT$ such that $z_{l-1}^2= z_l^2$;
		\item $\chi_3(x_1,\ldots,x_l)$ states that $z_{l-1}^2\neq z_l^2$ for all $z_{l-1}\in x_{l-1}T$ and $z_l\in x_lT$.
	\end{enumerate}

	\begin{claim}
		For each $n,m\in\{2,3\}$, $W_n\models\zeta_m$ if and only if $n=m$.
	\end{claim}

	\smallskip\noindent
	\begin{claimproof}
	Note that both $\chi_2(x_1,\ldots,x_l)$ and $\chi_3(x_1,\ldots,x_l)$ are symmetric in the variables $x_{l-1}$ and $x_l$. Hence, in light of the discussion above, it suffices to show that $((\epsilon_1,s_j):1\leq j\leq l)$ realizes $\chi_2(x_1,\ldots,x_l)$ in $W_2$, while $((\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_j):1\leq j\leq l)$ realizes its negation in $W_3$.

	\smallskip\noindent
	The first claim is immediate. It follows from the fact that, in this case, the reflection $s_{l-1}$ acts on the canonical basis $\{\epsilon_1,\ldots,\epsilon_l\}$ by transposing $\epsilon_{l-1}$ and $\epsilon_l$, and $s_l$ maps $\epsilon_{l-1}$ to $-\epsilon_l$ and $\epsilon_l$ to $-\epsilon_{l-1}$, while leaving the other $\epsilon_i$'s unchanged (cf. Table\cspace\ref{table - root systems, bases and reflections}). From this, one readily derives the following identities:
	\begin{equation*}
		(\epsilon_1,s_{l-1})^2=(2\epsilon_1,1)=(\epsilon_1,s_l)^2.
	\end{equation*}
	\noindent
	This proves that $W_2\models\zeta_2$, and hence $W_2\not\models\zeta_3$. It only remains to show that in $W_3$ there are no $z_{l-1}\in(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_{l-1})T$ and $z_l\in(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_l)T$ with the same square. 

	\smallskip\noindent
	By Remark\cspace\ref{remark- canonical expression of elements in cosets} and the explicit description of $FL_l$ in Table\cspace\ref{table - martinais nomenclature}, each $z_{l-1}\in(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_{l-1})T$ and $z_{l}\in(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_{l})T$ is of the form:
		\begin{equation*}
			z_{l-1}=\left(\sum_{i=1}^l\left(a^{l-1}_i+\frac{1}{2}\right)\epsilon_i,s_j\right)\quad\text{and}\quad z_l=\left(\sum_{i=1}^l\left(a^l_i+\frac{1}{2}\right)\epsilon_i,s_j\right),
		\end{equation*}
		\noindent
		for some $a_1^{l-1},\ldots,a_l^{l-1},a_1^l,\ldots,a_l^l\in\Z$ such that $\sum_{i=1}^la_i^{l-1},\sum_{i=1}^la_i^l\in 2\Z$. Consequently, one derives the following expressions for the squares:
		\begin{equation*}
			\begin{split}
				z_{l-1}^2&=\left(\sum_{i\neq l-1,l}(2a^{l-1}_i + 1)\epsilon_i+(a^{l-1}_{l-1}+a_l^{l-1} + 1)\epsilon_{l-1}+(a^{l-1}_{l-1}+a_l^{l-1} + 1)\epsilon_{l},1\right),\\
				z_{l}^2&=\left(\sum_{i\neq l-1,l}(2a^{l}_i + 1)\epsilon_i+(a^{l}_{l-1}-a_l^{l})\epsilon_{l-1}+(a^{l}_{l} -a_{l-1}^{l})\epsilon_{l},1\right).
			\end{split}
		\end{equation*}
		\noindent
		Assume, for a contradiction, that $z_{l-1}^2=z_l^2$. Then, by equating the coefficients of the expressions above with respect to the canonical basis $\{\epsilon_1,\ldots,\epsilon_l\}$, we obtain a compatible system over $\Z$:
		\begin{equation*}
			\begin{cases}
				&a_i^l=a_i^{l-1}\phantom{a_l^{l-1}+a_{l-1}^{l-1}+1}\quad\quad\forall i\neq l-1,l\\
				&a^l_{l-1}-a_l^l=a_l^{l-1}+a_{l-1}^{l-1}+1\\
				&a_l^l-a_{l-1}^l=a_l^{l-1}+a_{l-1}^{l-1}+1.
			\end{cases}
		\end{equation*}
		\noindent
		From this, by summing the last two equations, one readily derives the equivalent system:
		\begin{equation}\tag{$\star_{13}$}\label{eq.1 - case D_l}
			\begin{cases}
				&a_i^l=a^{l-1}_i\phantom{a^l_l+a^{l-1}_{l-1}+a^l_{l-1}+1}\forall i\neq l-1,l\\
				&a^{l-1}_{l-1}=-a^{l-1}_l-1\\
				&a^l_l=a^{l-1}_l+a^{l-1}_{l-1}+a^l_{l-1}+1.
			\end{cases}
		\end{equation}
		\noindent
		It follows from the second equation in \eqref{eq.1 - case D_l} that $a^{l-1}_{l-1}+a^{l-1}_l\in 2\Z+1$. Since by assumption, $\sum_{i=1}^{l}a^{l-1}_i\in 2\Z$, the first equation in \eqref{eq.1 - case D_l} then forces:
		\begin{equation}\tag{$\star_{14}$}\label{eq.2 - case D_l}
			\sum_{i\neq l-1,l}a_i^l=\sum_{i\neq l-1,l}a_i^{l-1}\in2\Z+1.
		\end{equation}
		\noindent
		%since $\sum_{i=1}^la^{l-1}_i$ is even, by assumption.
		Similarly, substituting $a^{l-1}_{l-1}=-a^{l-1}_l-1$ into the third equation of \eqref{eq.1 - case D_l} yields $a^l_l=a^l_{l-1}$, and thus:
		\begin{equation*}
			a^l_{l-1}+a^l_l=2a^l_{l-1}\in2\Z.
		\end{equation*} 
		\noindent
		By \eqref{eq.2 - case D_l}, this entails that $\sum_{i=1}^la_i^l\in2\Z+1$, contradicting the definition of $z_l$. This concludes the proof of the claim.
	\end{claimproof}

	\noindent\smallskip
	\underline{{\bf Case 4}}. $n(W_0(R),L)=4$.
	\newline In this case, according to Table\cspace\ref{table - explicit crystallographic groups}, exactly one of the following occurs:
	%\newline \underline{{\bf Case 2.1}}. $R=B_l$, with $l\geq3$, and $L=CL_l$;
	%\newline \underline{{\bf Case 2.2}}. $R=B_4$ and $L=CCL_4$;
	%\newline \underline{{\bf Case 2.3}}. $R=C_l$, with $l\geq3$ odd, and $L=FL_l$.
	\begin{enumerate}[(1)]
		\item $R=B_l$, with $l\geq3$, and $L=CL_l$;
		\item $R=B_4$ and $L=CCL_4$;
		\item $R=C_l$, with $l\geq3$ odd, and $L=FL_l$.
	\end{enumerate}

	\noindent
	We show that in each of these cases it is possible to find first-order sentences distinguishing the crystallographic groups extending $W_0(R)$ by $L$.

	\noindent\smallskip
    \underline{{\bf Case 4.1}}. $R=B_l$, with $l\geq3$, and $L=CL_l$;
    \newline In this case, by Table\cspace\ref{table - explicit crystallographic groups}, a complete system of representatives of the isomorphism classes of crystallographic groups extending $W_0(R)$ by $L$ is the following:
	\begin{enumerate}[$\bullet$]
		\item $W_1=\langle(\sum_{i=1}^lx_i\epsilon_i,1),(0,s_j):1\leq j\leq l, x_i\in \Z \rangle_{\iso(V)}$;
		\item $W_2=\langle(\sum_{i=1}^lx_i\epsilon_i,1),(0,s_j),(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_l):1\leq j< l, x_i\in \Z \rangle_{\iso(V)}$;
		\item $W_3=\langle(\sum_{i=1}^lx_i\epsilon_i,1),(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_j),(0,s_l):1\leq j< l, x_i\in \Z \rangle_{\iso(V)}$;
		\item $W_4=\langle(\sum_{i=1}^lx_i\epsilon_i,1),(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_j):1\leq j\leq l, x_i\in \Z \rangle_{\iso(V)}$.
	\end{enumerate}
	\noindent
	Since $W_1$ is split, by Lemma\cspace\ref{lemma-split extensions are definable} there exists a first-order sentence $\psi_{B_l}$ such that $W_1\models\psi_{B_l}$, while $W_n\models\neg\psi_{B_l}$ for all $n\in\{2,3,4\}$.

	\smallskip\noindent
	Let $\zeta_2,\zeta_3,\zeta_4$ be sentences of the form \eqref{eq.0 - lemma - all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}, and $\chi_2(x_1,\ldots,x_l),\chi_3(x_1,\ldots,x_l),\chi_4\\(x_1,\ldots,x_l)$ be the first-order formulas defined as follows: 
	\begin{enumerate}[$\bullet$]
		\item $\chi_2(x_1,\ldots,x_l)$ states that there exists an involution in each $x_iT$, for $i\in[1,l-1]$, but there are no involutions in $x_lT$;
		\item $\chi_3(x_1,\ldots,x_l)$ states that there exists an involution in $x_lT$, but there are no involutions in $x_iT$, for all $i\in[1,l-1]$;
		\item $\chi_4(x_1,\ldots,x_l)$ states that there are no involutions in any of the cosets $x_1T,\ldots,x_lT$.
	\end{enumerate}

	\begin{claim}
		For every $n,m\in\{2,3,4\}$, $W_n\models\zeta_m$ if and only if $n=m$.
	\end{claim}

    \smallskip\noindent
	\begin{claimproof}
	    For ease of reading, for each $n\in\{2,3,4\}$, we denote by $(t_1^n,s_1),\ldots,(t_l^n,s_l)$ the generators in the presentation of $W_n$ above, so that, for example, $(t_1^2,s_1)=(0,s_1)$, while $(t^3_1,s_1)=(t^4_1,s_1)=(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_1)$.

        \smallskip\noindent
        Since the $\chi_m(x_1,\ldots,x_l)$'s are mutually inconsistent, it suffices to show that for each $n\in\{2,3,4\}$, $W_n\models\chi_n((t^n_1,s_1),\ldots,(t^n_l,s_l))$. This is immediate for $W_2$, where we have:
        \begin{equation*}
        	(t^2_j,s_j)^2=(0,s_j)^2=(0,1)\quad \forall j\in[1,l-1].
        \end{equation*}

        \smallskip\noindent
        For the remaining cases, note that, by Remark\cspace\ref{remark- canonical expression of elements in cosets} and the explicit description of $CL_l$ in Table\cspace\ref{table - martinais nomenclature}, each element $z_{j}\in(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_{j})T$ for $j\in[1,l]$ has the form:
        \begin{equation}\label{eq.1 - main theorem - case B_l, CL_l}\tag{$\star_{15}$}
            z_j=\left(\,\sum_{i=1}^la_i^j\epsilon_j+\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_j\right)=\left(\,\sum_{i=1}^l\left(a_i^j+\frac{1}{2}\right)\epsilon_i,s_j\right),
        \end{equation}
        for some $a_1^j,\ldots,a_l^j\in\Z$. As indicated in Table\cspace\ref{table - root systems, bases and reflections}, in this context, for each $j\in[1,l-1]$, the reflection $s_j$ acts on the canonical basis $\{\epsilon_1,\ldots,\epsilon_l\}$ as the transposition of $\epsilon_j$ and $\epsilon_{j+1}$; while $s_l$ maps $\epsilon_l$ to $-\epsilon_l$, leaving the other $\epsilon_i$'s unchanged. Consequently, \eqref{eq.1 - main theorem - case B_l, CL_l} yields the following expressions for the squares:
        \begin{equation*}
            \begin{split}
                z_l^2&=\left(\,\sum_{i=1}^{l-1}(2a_i^l+1)\epsilon_i,1\right),\quad\text{and}\\
                z_j^2&=\left(\sum_{i\neq j, j+1}(2a_i^j+1)\epsilon_i+(a_j^j+a_{j+1}^j+1)\epsilon_j+(a_j^j+a_{j+1}^j+1)\epsilon_{j+1},1\right),               
            \end{split}
        \end{equation*}
        \noindent
        for all $j\in[1,l-1]$. In both cases, none of the terms $2a_i^l+1$ or $2a_i^j+1$, for $i\in[1,l-2]$, can be zero, since the $a^l_j$'s and $a_i^j$'s are integers. Because $l\geq3$, for each $j\in[1,l\,]$ no element $z_{j}\in(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_{j})T$ can be an involution. Since $(t^4_j,s_j)=(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_{j})$ for all $j\in[1,l]$, it follows that $W_4\models\chi_4((t^4_1,s_1),\ldots,(t^4_l,s_l))$. Likewise, from $(t^3_l,s_l)=(0,s_l)$ and $(t^3_j,s_j)=(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_{j})$ for all $j\in[1,l-1]$, we obtain that $W_3\models\chi_3((t^3_1,s_1),\ldots,(t^3_l,s_l))$, as required. 
	\end{claimproof}

	\smallskip\noindent
	\underline{{\bf Case 4.2}}. $R=B_4$, and $L=CCL_4$;
    \newline In this case, by Table\cspace\ref{table - explicit crystallographic groups}, a complete system of representatives of the isomorphism classes of crystallographic groups extending $W_0(R)$ by $L$ is the following:
	\begin{enumerate}[$\bullet$]
		\item $W_1=\langle(\sum_{i=1}^3(x_i+\frac{y}{2})\epsilon_i+\frac{y}{2}\epsilon_4,1), (0,s_j):1\leq j\leq 4, x_i,y\in\Z\rangle_{\iso(V)}$;
		\item $W_2=\langle(\sum_{i=1}^3(x_i+\frac{y}{2})\epsilon_i+\frac{y}{2}\epsilon_4,1), (\frac{1}{4}\sum_{i=1}^4\epsilon_i,s_j),(0,s_4):1\leq j\leq 3,\\
		\phantom{W_2=\langle (} x_i,y\in\Z\rangle_{\iso(V)}$;
		\item $W_3=\langle(\sum_{i=1}^3(x_i+\frac{y}{2})\epsilon_i+\frac{y}{2}\epsilon_4,1), (\frac{1}{2}\epsilon_3,s_1),(\frac{1}{2}\epsilon_1,s_2),(\frac{1}{2}\epsilon_2,s_3),(0,s_4):\\
		\phantom{W_3=\langle (}x_i,y\in\Z\rangle_{\iso(V)}$;
		\item $W_4=\langle(\sum_{i=1}^3(x_i+\frac{y}{2})\epsilon_i+\frac{y}{2}\epsilon_4,1), (\frac{1}{2}\epsilon_3+\frac{1}{4}\sum_{i=1}^4\epsilon_i,s_1),(\frac{1}{2}\epsilon_1+\frac{1}{4}\sum_{i=1}^4\epsilon_i,s_2),\\\phantom{W_4=\langle\,}(\frac{1}{2}\epsilon_2+\frac{1}{4}\sum_{i=1}^4\epsilon_i,s_3),(0,s_4):x_i,y\in\Z\rangle_{\iso(V)}$.
	\end{enumerate}
	\noindent
	Since $W_1$ is split, by Lemma\cspace\ref{lemma-split extensions are definable} there exists a first-order sentence $\psi_{B_4}$ such that $W_1\models\psi_{B_4}$, while $W_n\models\neg\psi_{B_4}$ for all $n\in\{2,3,4\}$.

	\smallskip\noindent
	Let $\zeta_2,\zeta_3,\zeta_4$ be sentences of the form \eqref{eq.0 - lemma - all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}, with $\chi_2(x_1,\ldots,x_4),\chi_3(x_1,\ldots,x_4),\\\chi_4(x_1,\ldots,x_4)$ being the first-order formulas defined as follows:
	\begin{enumerate}[$\bullet$]
		\item $\chi_2(x_1,\ldots,x_4)$ states that there exist $z_1\in x_1T$, $z_2\in x_2T$ and $z_3\in x_3 T$ such that $z_1^2=z_2^2=z_3^2$;
		\item $\chi_3(x_1,\ldots,x_4)$ states that no elements in the cosets $x_1T,x_2T$ and $x_3T$ share the same square, and that there exists an element $z_1\in x_1 T$ commuting with an involution in $x_4T$;
        \item $\chi_4(x_1,\ldots,x_4)$ states that no elements in the cosets $x_1T,x_2T$ and $x_3T$ share the same square, and there is no $z_1\in x_1 T$ commuting with some involution in $x_4T$.
	\end{enumerate}    

	\begin{claim}
		For every $n,m\in\{2,3,4\}$, $W_n\models\zeta_m$ if and only if $n=m$.
	\end{claim}

    \smallskip\noindent
    \begin{claimproof}
    	As above, for each $n\in\{2,3,4\}$ we denote by $(t_1^n,s_1),\ldots,(t_4^n,s_4)$ the generators of $W_n$ in the presentation above. By construction, $\chi_2(x_1,\ldots,x_l),\chi_3(x_1,\ldots,x_l)$ and $\chi_4(x_1,\ldots,x_l)$ are mutually inconsistent. Thus, it suffices to verify that $W_n\models((t^n_1,s_1),\ldots,(t^n_4,s_4))$ for all $n\in\{2,3,4\}$.

        \smallskip\noindent
        First, we show that $W_2\models\chi_2((t^2_1,s_1),\ldots,(t^2_4,s_4))$. Recall that for each $j\in[1,3]$, $s_j$ acts on the canonical basis $\{\epsilon_1,\ldots,\epsilon_4\}$ as the transposition of $\epsilon_j$ and $\epsilon_{j+1}$, while $s_4$ maps $\epsilon_4$ to $-\epsilon_4$ and leaves $\epsilon_1,\epsilon_2,\epsilon_3$ fixed (cf. Table\cspace\ref{table - root systems, bases and reflections}). Since $(t^2_1,s_1),(t^2_2,s_2)$ and $(t_3^2,s_3)$ have translation component $t^2_1=t^2_2=t^2_3=\frac{1}{4}\sum_{i=1}^{4}\epsilon_i$, it follows that their squares coincide:
        \begin{equation*}
        	(t_1^2,s_1)^2=(t_2^2,s_2)^2=(t_3^2,s_3)^2=\left(\frac{1}{2}\sum_{i=1}^4\epsilon_i,1\right).
        \end{equation*}
    	\noindent
    	This proves that $W_2\models\chi_2((t^2_1,s_1),\ldots,(t^2_4,s_4))$, and hence $W_2\models\zeta_2$.

    	\smallskip\noindent
    	We now show that $W_3\not\models\chi_2((t^3_1,s_1),\ldots,(t^3_4,s_4))$. By Remark\cspace\ref{remark- canonical expression of elements in cosets} and the explicit description of $CCL_4$ in Table\cspace\ref{table - martinais nomenclature}, every $z_1\in (t^3_1,s_1)T$, $z_2\in(t^3_2,s_2)T$ and $z_3\in(t^3_3,s_3)T$ is of the form:
    	\begin{equation*}
    		\begin{split}
    			z_1&=\left(\left(a^1_1+\frac{b^1}{2}\right)\epsilon_1+\left(a^1_2+\frac{b^1}{2}\right)\epsilon_2+\left(a^1_3+\frac{b^1}{2}+\frac{1}{2}\right)\epsilon_3+\frac{b^1}{2}\epsilon_4,s_1\right),\\
    			z_2&=\left(\left(a^2_1+\frac{b^2}{2}+\frac{1}{2}\right)\epsilon_1+\left(a^2_2+\frac{b^2}{2}\right)\epsilon_2+\left(a^2_3+\frac{b^2}{2}\right)\epsilon_3+\frac{b^2}{2}\epsilon_4,s_2\right),\\
    			z_3&=\left(\left(a^3_1+\frac{b^3}{2}\right)\epsilon_1+\left(a^3_2+\frac{b^3}{2}+\frac{1}{2}\right)\epsilon_2+\left(a^3_3+\frac{b^3}{2}\right)\epsilon_3+\frac{b^3}{2}\epsilon_4,s_3\right).
    		\end{split}
    	\end{equation*}
        \noindent
        for some $a^i_j,b^i\in\Z$, with $i,j\in[1,3]$. Consequently, we derive the following expression for the squares:
        \begin{equation*}
        	\begin{split}
        		z_1^2&=\left((a^1_1+a^1_2+b^1)(\epsilon_1+\epsilon_2)+(2a^1_3+b^1+1)\epsilon_3+b^1\epsilon_4,1\right),\\
        		z_2^2&=\left((2a^2_1+b^2+1)\epsilon_1+(a^2_2+a_3^2+b^2)(\epsilon_2+\epsilon_3)+b^2\epsilon_4,1\right),\\
        		z_3^2&=\left((2a^3_1+b^3)\epsilon_1+(2a^3_2+b^3+1)\epsilon_2+(a^3_3+b^3)(\epsilon_3+\epsilon_4),1\right).
        	\end{split}
        \end{equation*}
    	\noindent
    	If the identity $z_1^2=z_2^2=z_3^2$ holds, then equating the coefficients of these expressions with respect to the canonical basis yields the following compatible system of equations over $\Z$:
    	\begin{equation}\label{eq.2 - case B_4 - main_th_2}\tag{$\star_{16}$}
    		%\begin{table}[h!]
    			\begin{tabular}{cccccc}
    				$\epsilon_1:$&$a^1_1+a^1_2+b^1$&$=$&$2a^2_1+b^2+1$&$=$&$2a^3_1+b^3$\\ \addlinespace
    				& \verteq &&&&\\
    				$\epsilon_2:$& $a^1_1+a^1_2+b^1$ & $=$ & $a^2_2+a_3^2+b^2$ & $=$ & $2a^3_2+b^3+1.$
    				%\\ \addlinespace
    				%&&& \verteq &&\\
    				%$\epsilon_3:$ &  $a^1_3+\frac{b^1}{2}+\frac{1}{2}$ & $=$ & $a^2_2+a_3^2+b^2$ & $=$ & $a^3_3+b^3$\\ \addlinespace
    				%&&&&& \verteq \\
    				%$\epsilon_4:$ & $b^1$ & $=$ & $b^2$ & $=$ & $a^3_3+b^3$
    			\end{tabular}
    		%\end{table}
    	\end{equation}
    	\noindent
    	In particular the identity $2a^3_1+b^3=2a^3_2+b^3+1$ holds, which simplifies to $2a^3_1=2a^3_2+1$. This equation admits no integer solutions, as it equates an even and an odd value, leading to a contradiction. It follows that $W_3\not\models\chi_2((t^3_1,s_1),\ldots,(t^3_4,s_4))$. 

    	\smallskip\noindent
    	Furthermore, since the nodes with labels $1$ and $4$ in the Coxeter diagram of $(W_0(B_4),\\\{s_1,\ldots,s_4\})$ are not linked (cf. Table\cspace\ref{table - Coxeter diagrams of irreducible root systems}), $s_1$ and $s_4$ commute. Hence, using that $s_4$ fixes $\epsilon_3$ (cf. Table\cspace\ref{table - root systems, bases and reflections}), one readily verifies that:
    	%\begin{table}[h!]
    	\begin{equation*}
    	 	\begin{tabular}{ccccc}
    	 		$(t^3_1,s_1)\cdot(t^3_4,s_4)$ & $=$ & $\left(\frac{1}{2}\epsilon_3,s_1\right)\cdot(0,s_4)$ & $=$ & $\left(\frac{1}{2}\epsilon_3,s_1s_4\right)$\\ \addlinespace
    	 		&&&& \verteq \\
    	 		$(t^3_4,s_4)\cdot(t^3_1,s_1)$ & $=$ & $(0,s_4)\cdot\left(\frac{1}{2}\epsilon_3,s_1\right)$ & $=$ & $\left(\frac{1}{2}\epsilon_3,s_4s_1\right)$.
    	 	\end{tabular}
     	\end{equation*}
     	%\end{table}
     	\noindent
     	Therefore, we have $W_3\models \chi_3((t^3_1,s_1),\ldots,(t^3_4,s_4))$. It only remains to prove that $W_4\models \chi_4((t^4_1,s_1),\ldots,(t^4_4,s_4))$.

     	\smallskip\noindent
     	As above, by Remark\cspace\ref{remark- canonical expression of elements in cosets} and the explicit description of $CCL_4$ in Table\cspace\ref{table - martinais nomenclature}, each $z_1\in (t^4_1,s_1)T$, $z_2\in(t^4_2,s_2)T$, $z_3\in(t^4_3,s_3)T$ and $z_4\in(t^4_4,s_4)T$ is of the form:
    	\begin{equation*}
    		\begin{split}
    			z_1&=\left(\left(a^1_1+\frac{b^1}{2}+\frac{1}{4}\right)\epsilon_1+\left(a^1_2+\frac{b^1}{2}+\frac{1}{4}\right)\epsilon_2+\left(a^1_3+\frac{b^1}{2}+\frac{3}{4}\right)\epsilon_3+\left(\frac{b^1}{2}+\frac{1}{4}\right)\epsilon_4,s_1\right),\\
    			z_2&=\left(\left(a^2_1+\frac{b^2}{2}+\frac{3}{4}\right)\epsilon_1+\left(a^2_2+\frac{b^2}{2}+\frac{1}{4}\right)\epsilon_2+\left(a^2_3+\frac{b^2}{2}+\frac{1}{4}\right)\epsilon_3+\left(\frac{b^2}{2}+\frac{1}{4}\right)\epsilon_4,s_2\right),\\
    			z_3&=\left(\left(a^3_1+\frac{b^3}{2}+\frac{1}{4}\right)\epsilon_1+\left(a^3_2+\frac{b^3}{2}+\frac{3}{4}\right)\epsilon_2+\left(a^3_3+\frac{b^3}{2}+\frac{1}{4}\right)\epsilon_3+\left(\frac{b^3}{2}+\frac{1}{4}\right)\epsilon_4,s_3\right),\\
    			z_4&=\left(\sum_{i=1}^3\left(a^4_i+\frac{b^4}{2}\right)\epsilon_i+\frac{b^4}{2}\epsilon_4,s_4\right).
    		\end{split}
    	\end{equation*}
    	\noindent
    	for some $a^i_j,b^i\in\Z$. The corresponding squares
    	%, computed according to Table\cspace\ref{table - root systems, bases and reflections},
    	have expressions:
    	\begin{equation*}
    		\begin{split}
    			z_1^2&=\left(\left(a^1_1+a_2^1+b^1+\frac{1}{2}\right)(\epsilon_1+\epsilon_2)+\left(2a^1_3+b^1+\frac{3}{2}\right)\epsilon_3+\left(b^1+\frac{1}{2}\right)\epsilon_4,1\right),\\
    			z_2^2&=\left(\left(2a^2_1+b^2+\frac{3}{2}\right)\epsilon_1+\left(a^2_2+a^2_3+b^2+\frac{1}{2}\right)(\epsilon_2+\epsilon_3)+\left(b^2+\frac{1}{2}\right)\epsilon_4,1\right),\\
    			z_3^2&=\left(\left(2a^3_1+b^3+\frac{1}{2}\right)\epsilon_1+\left(2a^3_2+b^3+\frac{3}{2}\right)\epsilon_2+\left(a^3_3+b^3+\frac{1}{2}\right)(\epsilon_3+\epsilon_4),1\right).
    			%z_4^2&=\left(\sum_{i=1}^3(2a_i^4+b^4)\epsilon_i,1\right).
    		\end{split}
    	\end{equation*}
    	\noindent
    	Assume that the identity $z_1^2=z_2^2=z_3^2$ holds for some $z_1,z_2,z_3$. Then, equating the coefficients of the expressions above with respect to the canonical basis returns the same system as \eqref{eq.2 - case B_4 - main_th_2}, thus yielding a contradiction. It follows that $W_4\not\models\chi_2((t^4_1,s_1),\ldots,(t^4_4,s_4))$.

    	\smallskip\noindent
    	Finally, we prove that no $z_1$ and $z_4$ as above commute. This clearly implies the weaker statement that no element in the coset $(t^4_1,s_1)T$ commutes with an involution in $(t^4_4,s_4)T$. Recall that $s_1$ acts on the basis $\{\epsilon_1,\ldots,\epsilon_4\}$ by transposing $\epsilon_1$ and $\epsilon_2$, while $s_4$ fixes $\epsilon_1,\epsilon_2,\epsilon_3$ and maps $\epsilon_4$ to $-\epsilon_4$. Consequently, one derives the following identities:
    	\begin{equation*}
    		\begin{split}
    			z_1\cdot z_4 & =\bigg(\left(a^1_1+a_2^4+\frac{b^1+b^4}{2}+\frac{1}{4}\right)\epsilon_1+\left(a^1_2+a^4_1+\frac{b^1+b^4}{2}+\frac{1}{4}\right)\epsilon_2\\
    			&+\left(a^1_3+a_3^4+\frac{b^1+b^4}{2}+\frac{3}{4}\right)\epsilon_3+\left(\frac{b^1+b^4}{2}+\frac{1}{4}\right)\epsilon_4,s_1s_4\bigg),\\
    			z_4\cdot z_1 & = \bigg(\left(a^1_1+a_1^4+\frac{b^1+b^4}{2}+\frac{1}{4}\right)\epsilon_1+\left(a^1_2+a_2^4+\frac{b^1+b^4}{2}+\frac{1}{4}\right)\epsilon_2\\
    			%+\frac{1}{4}\right)\epsilon_1+\left(a^1_2+a_2^4+\frac{b^1+b^4}{2}+\frac{1}{4}\right)\epsilon_2
    			&+\left(a^1_3+a_3^4+\frac{b^1+b^4}{2}+\frac{3}{4}\right)\epsilon_3+\left(\frac{b^4}{2}-\frac{b^1}{2}-\frac{1}{4}\right)\epsilon_4,s_4s_1\bigg).
    		\end{split}
    	\end{equation*}
    	\noindent
    	If $z_1\cdot z_4=z_4\cdot z_1$ were to hold, then equating the coefficients of $z_1\cdot z_4$ and $z_4\cdot z_1$ with respect to the element $\epsilon_4$ of the canonical basis would determine the compatible integral equation:
    	\begin{equation*}
    		%\label{eq.2 - case B_4 - main_th_2}\tag{$\ast_{20}$}
    		%\begin{cases}
    		%&a^1_1+a_2^4+\frac{b^1+b^4}{2}+\frac{1}{4}=a^1_1+a_1^4+\frac{b^1+b^4}{2}+\frac{1}{4}\\
    		%&a^1_2+a^4_1+\frac{b^1+b^4}{2}+\frac{1}{4}=a^1_2+a_2^4+\frac{b^1+b^4}{2}+\frac{1}{4}\\
    		%&a^1_3+a_3^4+\frac{b^1+b^4}{2}+\frac{3}{4}=a^1_3+a_3^4+\frac{b^1+b^4}{2}+\frac{3}{4}\\
    		%&
    		\frac{b^1+b^4}{2}+\frac{1}{4}=\frac{b^4}{2}-\frac{b^1}{2}-\frac{1}{4}
    		%\end{cases}
    		\quad\Rightarrow\quad
    		%\begin{cases}
    		%&a^1_1+a_2^4=a^1_1+a_1^4\\
    		%&a^1_2+a^4_1=a^1_2+a_2^4\\
    		%&a^1_3+a_3^4=a^1_3+a_3^4\\
    		%&
    		b^1=-\frac{1}{2}.
    		%\end{cases}
    	\end{equation*}
    	\noindent
    	Since $b^1$ is supposed to be an integer, this leads to a contradiction. It follows that $W_4\models \chi_4((t^4_1,s_1),\ldots,(t^4_4,s_4))$, completing the proof.
    	\end{claimproof}

    	\smallskip\noindent
    	\underline{{\bf Case 4.3}}. $R=C_l$, with $l\geq3$ odd, and $L=FL_l$;
    	\newline In this case, by Table\cspace\ref{table - explicit crystallographic groups} a complete system of representatives of the isomorphism classes of crystallographic groups extending $W_0(R)$ by $L$ is the following:
    	\begin{enumerate}[$\bullet$] 
    		\item $W_1=\langle(\sum_{i=1}^lx_i\epsilon_i,1),(0,s_j):1\leq j\leq l,x_i\in \Z, \sum_{i=1}^lx_i\in2\Z \rangle_{\iso(V)}$;
    		\item $W_2=\langle(\sum_{i=1}^lx_i\epsilon_i,1),(0,s_j),(\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_l):1\leq j< l,x_i\in \Z,\\
    		\phantom{W_e=\langle\,}\sum_{i=1}^lx_i\in2\Z \rangle_{\iso(V)}$;
    		\item $W_3=\langle(\sum_{i=1}^lx_i\epsilon_i,1),(\epsilon_1,s_j):1\leq j\leq l,x_i\in \Z, \sum_{i=1}^lx_i\in2\Z \rangle_{\iso(V)}$;
    		\item $W_4=\langle(\sum_{i=1}^lx_i\epsilon_i,1),(\epsilon_1,s_j),(\epsilon_1+\frac{1}{2}\sum_{i=1}^l\epsilon_i,s_l):1\leq j< l,x_i\in \Z,\\
    		\phantom{W_4=\langle\,} \sum_{i=1}^lx_i\in2\Z \rangle_{\iso(V)}$.
    	\end{enumerate}
    	\noindent
    	%(where, $\{\epsilon_1,\ldots,\epsilon_l\}$ denotes the canonical basis of $V$).
    	Since $W_1$ is split, by Lemma\cspace\ref{lemma-split extensions are definable} there exists a first-order sentence $\psi_{C_l}$ such that $W_1\models\psi_{C_l}$, while $W_n\models\neg\psi_{C_l}$ for all $n\in\{2,3,4\}$.

    	\smallskip\noindent
    	Let $\zeta_2,\zeta_3,\zeta_4$ be sentences of the form \eqref{eq.0 - lemma - all crystallographic groups arising from irreducible root systems are f.o. rigid and profinitely rigid}, with $\chi_2(x_1,\ldots,x_4),\chi_3(x_1,\ldots,x_4),\\\chi_4(x_1,\ldots,x_4)$ being the first-order formulas defined as follows:  
    	\begin{enumerate}[$\bullet$]
    		\item $\chi_2(x_1,\ldots,x_l)$ states that there exists an involution in $x_iT$ for all $i\in[1,l-1]$;
    		%, but there are no involutions in $x_lT$;
    		\item $\chi_3(x_1,\ldots,x_l)$ states that there are no involutions in $x_2T$, and there exist $z_2\in x_2T$ and $z_l\in x_l T$ such that $z_2^2=z_l^2$;
    		\item $\chi_4(x_1,\ldots,x_l)$ states that there are no involutions in $x_2T$,
    		%the negation of $\chi_2(x_1,\ldots,x_l)$ holds,
    		and no element in $x_2T$ has the same square of an element in $x_lT$.
    	\end{enumerate}    
    	\smallskip\noindent
    	\begin{claim}
    		For every $n,m\in\{2,3,4\}$, $W_n\models\zeta_m$ if and only if $n=m$.
    	\end{claim}

    	\smallskip\noindent
    	\begin{claimproof}
    		For each $n\in\{2,3,4\}$, denote by $(t_1^n,s_1),\ldots,(t_l^n,s_l)$ the generators of $W_n$ in the presentation above. As in the preceding cases, $\chi_2(x_1,\ldots,x_l),\chi_3(x_1,\ldots,x_l)$ and $\chi_4(x_1,\ldots,x_l)$ are mutually inconsistent, thus it suffices to establish that $W_n\models\chi_n((t^n_1,s_1),\ldots,(t^n_l,s_l))$ for all $n\in\{2,3,4\}$.

    		\smallskip\noindent
    		Clearly, $W_2\models\chi_2((t^2_1,s_1),\ldots,(t^2_l,s_l))$, since for each $j\in[1,l-1]$ we have $(t^2_j,s_j)=(0,s_j)$. We prove that $W_3\models\chi_3((t^3_1,s_1),\ldots,(t^3_l,s_l))$.

    		\smallskip\noindent
    		The second claim of the formula follows directly from the fact that $s_2$ acts on $\{\epsilon_1,\ldots,\epsilon_l\}$ as the transposition of $\epsilon_2$ and $\epsilon_3$, while $s_l$ maps $\epsilon_l$ to $-\epsilon_l$ and leaves the other elements of the canonical basis fixed (cf.\cspace Table\cspace\ref{table - root systems, bases and reflections}). Therefore, since $(t^3_2,s_2)=(\epsilon_1,s_2)$ and $(t^3_l,s_l)=(\epsilon_1,s_l)$, we have:
    		\begin{equation*}
    			(t^3_2,s_2)^2=(\epsilon_1,s_2)^2=(2\epsilon_1,1)=(\epsilon_1,s_l)^2=(t^3_l,s_l)^2.
       		\end{equation*}
    		\noindent
    		We now prove that there are no involutions in the coset $(t^3_2,s_2)T$. By Remark\cspace\ref{remark_for_star2} and the explicit description of $FL_l$ in Table\cspace\ref{table all inequivalent lattices}, each $z_2\in (t^3_2,s_2)T$ has the form:
    		\begin{equation}\label{eq.2 - case C_l main thm}\tag{$\star_{17}$}
    				z_2=\left((a^2_1+1)\epsilon_1+\sum_{j=2}^la_j^2\epsilon_j,s_2\right),
    				%\quad\text{and}\quad  				z_l=\left((a_1^l+1)\epsilon_1+\sum_{i=2}^la_j^l\epsilon_j,s_l\right),
    		\end{equation}
    		\noindent
    		for some $a_1^2,\ldots,a_l^2\in\Z$ such that $\sum_{i=1}^la_i^2\in2\Z$.
    		%,a_1^l,\ldots,a_l^l\in\Z$ such that:
    		%\begin{equation}
    		%	\sum_{i=1}^la_i^2\in2\Z\quad\text{and}\quad\sum_{i=1}^la^l_i\in2\Z.
    		%\end{equation}
    		%\noindent
    		Consequently, using again that $s_2$ acts on $\{\epsilon_1,\ldots,\epsilon_l\}$ by transposing $\epsilon_2$ and $\epsilon_3$ (cf. Table\cspace\ref{table - root systems, bases and reflections}), one readily computes the following expression for the square:
    		\begin{equation}\label{eq.3 - case C_l main thm}\tag{$\star_{18}$}
    			\begin{split}
    				z_2^2&=\left((2a^2_1+2)\epsilon_1+(a^2_2+a^2_3)\epsilon_2+(a^2_2+a^2_3)\epsilon_3+\sum_{i\neq1,2,3}2a_i^2\epsilon_i,1\right).
    				%z_l^2&=\left((2a_1^l+2)\epsilon_1+\sum_{i\neq1,l}2a_j^l\epsilon_j,1\right).
    			\end{split}
    		\end{equation}
    		\noindent
    		If $z_2$ were an involution, the identity $z_2^2=(0,1)$ would yield the following compatible system of equations over $\Z$:
    		\begin{equation*}
    			\begin{cases}
    				&a^2_1+1=0\\
    				&a^2_2+a^2_3=0\\
    				&a^2_i=0\quad\text{for all }i\neq1,2,3.
    			\end{cases}
    		\end{equation*}
    		\noindent
    		This leads to a contradiction, since each tuple $a^2_1,\ldots,a^2_l\in\Z$ realizing the system above satisfies the identity:
    		\begin{equation*}
    			\sum_{i=1}^la^2_i=a^2_1+(a^2_2+a^2_3)+\sum_{i\neq1,2,3}a^2_i=-1+0+0=-1\notin2\Z,
    		\end{equation*}
    		\noindent
    		against the assumption $\sum_{i=1}a^2_i\in2\Z$. This proves that there are no involutions in the coset $(t^3_2,s_2)T$, and thus that $W_3\not\models\chi_2((t^3_1,s_1),\ldots,(t^3_l,s_l))$.

    		\smallskip\noindent
    		It only remains to prove that $W_4\models\chi_4((t^4_1s_1),\ldots,(t^4_l,s_l))$. In this case, we have $(t^4_j,s_j)=(t^3,s_j)$ for all $j\in[1,l-1]$. Thus, each $z_2\in(t^4_2,s_2)T$ is of the form \eqref{eq.2 - case C_l main thm} and the preceding argument shows that this is not an involution.

    		\smallskip\noindent
    		By Remark\cspace\ref{remark- canonical expression of elements in cosets} and the explicit description of $FL_l$ in Table\cspace\ref{table - martinais nomenclature}, each $z_l\in(t^4_l,s_l)T$ is admits expression:    		
    		\begin{equation*}
    			z_l=\left(\left(a^4_1+\frac{3}{2}\right)\epsilon_1+\sum_{i=2}^l\left(a^4_i+\frac{1}{2}\right)\epsilon_i,s_l\right),
    		\end{equation*}
    		\noindent
    		for some $a^4_1,\ldots,a^4_l\in\Z$ such that $\sum_{i=1}^la^4_i\in2\Z$. Hence, it has square:
    		\begin{equation}\label{eq.4 - case C_l main thm}\tag{$\star_{19}$}
    			z_l^2=\left((2a^4_1+3)\epsilon_1+\sum_{i=2}^{l-1}(2a^4_i+1)\epsilon_i,1\right).
    		\end{equation}
    		\noindent
    		If the identity $z_2^2=z_l^2$ were to hold, then comparing the terms of \eqref{eq.3 - case C_l main thm} and \eqref{eq.4 - case C_l main thm} with respect to the canonical basis would yield the following system of equations:
    		\begin{equation*}
    			\begin{cases}
    				&2a^2_1+2=2a^4_1+3\\
    				&a^2_2+a^2_3=2a^4_2+1\\
    				&a^2_2+a^2_3=a^4_3+1\\
    				&2a_i^2=2a^4_i+1\quad\text{for all}\quad i\neq1,2,3.			
    			\end{cases}
    		\end{equation*}
    		\noindent
    		However, this system is clearly inconsistent, since it contains the identity $2a_i^2=2a^4_i+1$ of an even and an odd number. It follows that no $z_2\in(t^4_2,s_2)T$ and $z_l\in(t^4_l,s_l)T$ have the same square, and hence that $W_4\models\chi_4((t^4_1,s_1),\ldots,(t^4_l,s_l))$.

    	\end{claimproof}

    	\noindent
    	Since in each case we have found a first-order sentence separating the representatives from Martinais's classification, this concludes the proof.
\end{proof}
