\section{Technical proofs}\label{app: proofs}

In this section, we provide the complete proofs of Propositions~\ref{prop:Borel-f_kN} and~\ref{prop:Borel-g_kN} and Lemma~\ref{lemma:summability-f-kN} on the resurgence and summability of the asymptotic expansions for $y\to 0$ with $\Im(y)>0$ of the $q$-Pochhammer symbols $f_{k,N}(y)$, $ g_{k,N}(y)$, $y \in \IH$, defined in Eq.~\eqref{eq:f_kN} after fixing $N\in\IZ_{\geq 2}$ and $k\in\IZ_N$.

\begin{proof}[Proof of Prop.~\ref{prop:Borel-f_kN}]
The Borel transform of the asymptotic series $\psi_k(y)$ in Eq.~\eqref{eq: tilde-psi} can be decomposed as
\be
\begin{aligned}
    \borel\left[\psi_k\right](\zeta)&=\sum_{n=1}^\infty (2\pi \ri)^{2n-1}\frac{B_{2n}}{(2n)!}\mathrm{Li}_{2-2n}(\zeta_N^k)\frac{\zeta^{2n-2}}{(2n-2)!}\\
    &=\left(\sum_{n=1}^\infty \frac{B_{2n}}{(2n)!}\zeta^{2n-2} \right) \diamond \left(\sum_{n=1}^\infty (2\pi \ri)^{2n-1}\frac{\mathrm{Li}_{2-2n}(\zeta_N^k)}{(2n-2)!} \zeta^{2n-2} \right)=:\tilde{g}(\zeta)\diamond \tilde{f}(\zeta)\,,
\end{aligned}
\ee
where $\zeta$ is the formal variable conjugate to $y$ and $\diamond$ denotes the Hadamard product~\cite{Hadamard}. The formal power series $\tilde{g}(\zeta)$, $\tilde{f}(\zeta)$ have finite radius of convergence at $\zeta=0$ and can be resummed explicitly into the functions\footnote{We impose that $g(0)=1/12$ to eliminate the removable singularity of $g(\zeta)$ at the origin.}
\begin{subequations}
    \begin{align}
        g(\zeta)&=-\frac{1}{\zeta^2}+\frac{1}{2 \zeta}\coth\left(\frac{\zeta}{2}\right) \, , \quad |\zeta|<2\pi \, , \\
    f(\zeta)&=-\pi \ri\left(\frac{1}{1-\zeta_N^{-k}\re^{-2\pi \ri \zeta}}+\frac{1}{1-\zeta_N^{-k}\re^{2\pi \ri \zeta}}\right) \, , \quad |\zeta|<\frac{k}{N} \, , 
    \end{align}
\end{subequations}
respectively.
After being analytically continued to the whole complex $\zeta$-plane, the function $g(\zeta)$ has simple poles along the imaginary axis at
\be
\mu_m = 2 \pi \ri m \, , \quad m \in \IZ_{\ne 0} \, ,
\ee
while the function $f(\zeta)$ has simple poles along the real axis at 
\be
\nu_\ell^{\pm}=\pm\frac{k}{N}+\ell \, , \quad \ell \in \IZ \, .
\ee
Let us now consider a circle $\gamma$ in the complex $s$-plane with center $s=0$ and radius $0 < r < 2 \pi$ and apply Hadamard's multiplication theorem~\cite{Hadamard, Hadamard2}. The Borel transform of $\psi_k(y)$ can be written as the integral
\be \label{eq: intBorelinfty}
\begin{aligned}
    \borel \left[\psi_k\right](\zeta) &=\frac{1}{2\pi \ri}\int_\gamma g(s)\, f\left(\frac{\zeta}{s}\right) \frac{ds}{s} \\
    &= \frac{1}{2}\int_\gamma \left(\frac{1}{s}-\frac{1}{2}\coth\left(\frac{s}{2}\right) \right)\left(\frac{1}{1-\zeta_N^{-k}\re^{-2\pi \ri \zeta/s}}+\frac{1}{1-\zeta_N^{-k}\re^{2\pi \ri \zeta/s}}\right) \frac{ds}{s^2} \, ,
\end{aligned}
\ee
for $|\zeta|<rk/N$. Here, the function $s \mapsto f(\zeta/s)$ is singular at $s = \zeta/\nu^{\pm}_\ell$, $\ell \in \IZ$, which sit inside the contour of integration $\gamma$ and accumulate at the origin, and regular for $|s| > r$. Meanwhile, the function $g(s)$ has simple poles at $s= \mu_m$ with residues
\be
\underset{s= 2 \pi \ri m}{\text{Res}} g(s) = \frac{1}{2 \pi \ri m} \, , \quad m \in \IZ_{\ne 0} \, . 
\ee
By Cauchy's residue theorem, the integral in Eq.~\eqref{eq: intBorelinfty} can be evaluated by summing the residues at the poles of the integrand which lie outside $\gamma$. More precisely, we have that
\be \label{eq: intBorel2infty-proof-A}
\begin{aligned}
    \borel \left[\psi_k\right](\zeta)&=-\sum_{m\in\IZ_{\neq 0}} \underset{s=2 \pi \ri m}{\text{Res}} \left[ g(s) f\left(\frac{\zeta}{s}\right)\frac{1}{s}\right] \\
    &=\sum_{m\in\IZ_{\neq 0}}\frac{1}{4 \pi \ri m^2}\left(\frac{1}{1-\zeta_N^{-k}\re^{-\frac{\zeta}{m}}}+\frac{1}{1-\zeta_N^{-k}\re^{\frac{\zeta}{m}}}\right)\\
    &=\frac{1}{2 \pi \ri} \sum_{m=1}^{\infty}\frac{1}{m^2}\left(\frac{1}{1-\zeta_N^{-k}\re^{-\frac{\zeta}{m}}}+\frac{1}{1-\zeta_N^{-k}\re^{\frac{\zeta}{m}}}\right) \, ,
\end{aligned}
\ee
which is manifestly Gevrey-1 and simple resurgent.
\end{proof}

\begin{proof}[Proof of Prop.~\ref{prop:Borel-g_kN}]
The Borel transform of the asymptotic series $\varphi_k(y)$ in Eq.~\eqref{eq: tilde-phi} can be decomposed as
\be
\begin{aligned}
    \borel\big[\varphi_k\big](\zeta)&=\sum_{n=1}^\infty (2\pi \ri)^{2n}\frac{B_{2n}B_{2n+1}\left(\tfrac{k}{N}\right)}{2n (2n+1)!}\frac{\zeta^{2n-1}}{(2n-1)!}\\
    &=\left(\sum_{n=1}^\infty \frac{B_{2n}}{(2n)!}\zeta^{2n-1} \right) \diamond \left(\sum_{n=1}^\infty (2\pi\ri)^{2n}\frac{B_{2n+1}\left(\tfrac{k}{N}\right)}{(2n+1)!}\zeta^{2n-1} \right)=:\tilde{g}(\zeta)\diamond \tilde{f}(\zeta)\,,
\end{aligned}
\ee
where $\zeta$ is the formal variable conjugate to $y$ and $\diamond$ denotes the Hadamard product~\cite{Hadamard}. The formal power series $\tilde{g}(\zeta)$, $\tilde{f}(\zeta)$ have finite radius of convergence at $\zeta=0$ and can be resummed explicitly into the functions\footnote{We impose that $g(0)=0$ and $f(0)=0$ to eliminate the removable singularities of $g(\zeta)$ and $f(\zeta)$ at the origin.}
\begin{subequations}
    \begin{align}
        g(\zeta)&=-\frac{1}{\zeta}+\frac{1}{2 }\coth\left(\frac{\zeta}{2}\right) \, , \quad |\zeta|<2\pi \, , \\
        f(\zeta)&=-\frac{B_1\left(\tfrac{k}{N}\right)}{\zeta} +\frac{\sin\left(\left(\tfrac{2k}{N}-1\right)\pi\zeta\right)}{2\zeta\sin(\pi\zeta)} \, , \quad |\zeta|<1 \, , 
    \end{align}
\end{subequations}
respectively. 
After being analytically continued to the whole complex $\zeta$-plane, the function $g(\zeta)$ has simple poles along the imaginary axis at
\be
\mu_m = 2 \pi \ri m \, , \quad m \in \IZ_{\ne 0} \, ,
\ee
while the function $f(\zeta)$ has simple poles along the real axis at 
\be
\nu_\ell=\ell \, , \quad  \ell\in\IZ_{\ne 0}\, .
\ee
Let us now consider a circle $\gamma$ in the complex $s$-plane with center $s=0$ and radius $0 < r < 2 \pi$ and apply Hadamard's multiplication theorem~\cite{Hadamard, Hadamard2}. The Borel transform of $\varphi_k(y)$ can be written as the integral
\be \label{eq: intBorel0}
\begin{aligned}
    \borel [\varphi_k](\zeta) &=\frac{1}{2\pi \ri}\int_\gamma f(s)\, g\left(\frac{\zeta}{s}\right) \frac{ds}{s} \\
    &= \frac{1}{2\pi\ri}\int_\gamma  \left(-\frac{B_1\big(\tfrac{k}{N}\big)}{s} +\frac{\sin\big(\big(\tfrac{2k}{N}-1\big)\pi s\big)}{2s\sin\big(\pi s\big)}\right)\left(-\frac{s}{\zeta}+\frac{1}{2}\coth\left(\frac{\zeta}{2s}\right)\right) \frac{ds}{s} \\
\end{aligned}
\ee
for $|\zeta|<r$. Here, the function $s \mapsto g(\zeta/s)$ is singular at $s = \zeta/\mu_m$, $m \in \IZ_{\ne 0}$, which sit inside the contour of integration $\gamma$ and accumulate at the origin, and regular for $|s| > r$. 
Meanwhile, the function $f(s)$ has simple poles at $s= \nu_\ell$ with residues
\be
\underset{s= \ell}{\text{Res}}\, f(s) = \frac{\sin\big(\tfrac{2 \pi k \ell}{N} \big)}{2\pi\ell} \, , \quad \ell\in\IZ_{\ne 0} \,.
\ee
By Cauchy's residue theorem, the integral in Eq.~\eqref{eq: intBorel0} can be evaluated by summing the residues at the poles of the integrand which lie outside $\gamma$. More precisely, we have that
\be \label{eq: intBorel20-proof-A}
\begin{aligned}
    \borel [\varphi_k](\zeta)&=-\sum_{\ell \in \IZ_{\ne 0}} \underset{s=\ell}{\text{Res}} \left[ f(s) g\left(\frac{\zeta}{s}\right)\frac{1}{s}\right] \\
    &={-}\sum_{\ell \in \IZ_{\ne 0}}\frac{\sin\big(\tfrac{2 \pi k \ell}{N}\big)}{2\pi\ell}\left(-\frac{1}{\zeta}+\frac{1}{2\ell}\coth\left(\frac{\zeta}{2\ell}\right)\right)\\
    &={-}\sum_{\ell =1}^{\infty}\frac{\sin\big(\tfrac{2 \pi k \ell}{N}\big)}{\pi\ell}\left(-\frac{1}{\zeta}+\frac{1}{2\ell}\coth\left(\frac{\zeta}{2\ell}\right)\right) \, ,
\end{aligned}
\ee
which is manifestly Gevrey-1 and simple resurgent. 
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lemma:summability-f-kN}]
We can now compute the Laplace transform of $\borel \left[\psi_k\right](\zeta)$ in Eq.~\eqref{eq: intBorel2infty-proof-A} along the positive and negative real axes. When $\Re (y)>0$, we have that
\be
\begin{aligned}
    s_0(\psi_k)(y)&=\frac{1}{2\pi \ri}\int_0^\infty \re^{-\zeta/y} \left[\sum_{m=1}^{\infty}\frac{1}{m^2}\left(\frac{1}{1-\zeta_N^{-k}\re^{-\frac{\zeta}{m}}}+\frac{1}{1-\zeta_N^{-k}\re^{\frac{\zeta}{m}}}\right)\right] d\zeta\\
    &=\frac{1}{2\pi \ri}\int_0^\infty \left(\sum_{m=1}^{\infty}\frac{\re^{-mt/y}}{m} \right) \left(\frac{1 }{1-\zeta_N^{-k}\re^{-t}}+\frac{1}{1-\zeta_N^{-k}\re^{t}}\right) dt \, ,
\end{aligned}
\ee
where we have applied the change of variable $\zeta = m t$. Resumming the series in $m$, we find that
\be \label{eq: sum0-proof1}
\begin{aligned}
    s_0(\psi_k)(y)
    &=-\frac{1}{2\pi \ri}\int_0^\infty \log(1-\re^{-t/y})\left(\frac{1}{1-\zeta_N^{-k}\re^{-t}}+\frac{1}{1-\zeta_N^{-k}\re^{t}}\right) dt\\
    &=-\frac{1}{2\pi \ri}\int_{-\infty}^\infty \frac{\log(1-\re^{-t/y})}{1-\zeta_N^{-k}\re^{-t}} dt +\frac{1}{2\pi \ri}\int_0^{-\infty}\frac{\log(-\re^{t/y})}{1-\zeta_N^{-k}\re^{-t}} dt \, ,
\end{aligned}
\ee
where we have divided the integral into the sum of two contributions for simplicity.
Indeed, we observe that the second term in the RHS of Eq.~\eqref{eq: sum0-proof1} gives
\be \label{eq: sum0-proof1-p1}
\frac{1}{2\pi \ri}\int_0^{-\infty}\frac{\log(-\re^{t/y})}{1-\zeta_N^{-k}\re^{-t}} dt = -\frac{\mathrm{Li}_2(\zeta_N^k)}{2\pi \ri y}-\frac{1}{2}\log(1-\zeta_N^{k}) \, ,
\ee
while, after rewriting $\zeta_N^{-k}$ as $\zeta_N^{N-k}$, the first term gives
\begin{align}
    -\frac{1}{2\pi \ri}\int_{-\infty}^\infty \frac{\log(1-\re^{-t/y})}{1-\zeta_N^{N-k}\re^{-t}} dt &= \log\frac{(\zeta_N^k; \, \re^{2\pi \ri y})_\infty}{(\re^{-2\pi \ri (N-k)/(Ny)}; \, \re^{-2\pi \ri/y})_\infty} \, , \label{eq: sum0-proof1-p2a}
\end{align}
The last two formulae follow from~\cite[Thm~A-29]{wheeler-thesis}.
Therefore, substituting Eqs.~\eqref{eq: sum0-proof1-p1} and~\eqref{eq: sum0-proof1-p2a} into Eq.~\eqref{eq: sum0-proof1}, we find that 
\begin{align}
s_0(\psi_k)(y)=& -\frac{\mathrm{Li}_2(\zeta_N^k)}{2\pi \ri y}-\frac{1}{2}\log(1-\zeta_N^{k}) +\log\frac{(\zeta_N^k; \, \re^{2\pi \ri y})_\infty}{(\re^{-2\pi \ri (N-k)/(Ny)}; \, \re^{-2\pi \ri/y})_\infty} \, . \label{eq: sum0-proof1-p3a}
\end{align}
Finally, using Eqs.~\eqref{eq:f_kN},~\eqref{eq: expansion-fkN}, and~\eqref{eq: sum0-proof1-p3a}, we obtain that
\be
\begin{aligned}
    s_0(\tilde{f}_{k,N})(y)&=\log\frac{(\zeta_N^k; \, \re^{2\pi \ri y})_\infty}{(\re^{-2\pi \ri (N-k)/(Ny)}; \, \re^{-2\pi \ri/y})_\infty} \\
    &=f_{k,N}(y)-g_{\underline{k},N}\big(-\tfrac{1}{Ny}\big) \, .
\end{aligned}
\ee

Similarly, for $\Re (y)<0$, the Borel--Laplace sum of $\psi_k(y)$ along the negative real axis is
\be
\begin{aligned}
    s_\pi(\psi_k)(y)&=\frac{1}{2\pi \ri}\int_0^{-\infty} \re^{-\zeta/y} \left[\sum_{m=1}^{\infty}\frac{1}{m^2}\left(\frac{1}{1-\zeta_N^{-k}\re^{-\frac{\zeta}{m}}}+\frac{1}{1-\zeta_N^{-k}\re^{\frac{\zeta}{m}}}\right) \right] d\zeta\\
    &=\frac{1}{2\pi \ri}\int_0^{-\infty} \left(\sum_{m=1}^{\infty}\frac{\re^{-mt/y}}{m} \right) \left(\frac{1 }{1-\zeta_N^{-k}\re^{-t}}+\frac{1}{1-\zeta_N^{-k}\re^{t}}\right) dt \, ,
\end{aligned}
\ee
where we have applied the change of variable $\zeta = m t$. Resumming the series in $m$, we find that
\be \label{eq: sumpi-proof1}
\begin{aligned}
    s_\pi(\psi_k)(y)
    &=-\frac{1}{2\pi \ri}\int_0^{-\infty} \log(1-\re^{-t/y})\left(\frac{1}{1-\zeta_N^{-k}\re^{-t}}+\frac{1}{1-\zeta_N^{-k}\re^{t}}\right) dt\\
    &=\frac{1}{2\pi \ri}\int_0^{\infty} \log(1-\re^{t/y})\left(\frac{1}{1-\zeta_N^{-k}\re^{t}}+\frac{1}{1-\zeta_N^{-k}\re^{-t}}\right) dt\\
    &=\frac{1}{2\pi \ri}\int_{-\infty}^\infty \frac{\log(1-\re^{t/y})}{1-\zeta_N^{-k}\re^{-t}} dt -\frac{1}{2\pi \ri}\int_0^{-\infty}\frac{\log(-\re^{-t/y})}{1-\zeta_N^{-k}\re^{-t}} dt \, ,
\end{aligned}
\ee
where we have again divided the integral into the sum of two contributions for simplicity. 
Let us now set $x=-1/y$, so that $\Re(x)>0$ and $\Im (x)>0$, then the second term in the RHS of Eq.~\eqref{eq: sumpi-proof1} becomes
\be \label{eq: sumpi-proof1-p1}
-\frac{1}{2\pi \ri}\int_0^{-\infty}\frac{\log(-\re^{t x})}{1-\zeta_N^{-k}\re^{-t}} dt = \frac{x} {2\pi \ri}\mathrm{Li}_2(\zeta_N^k) + \frac{1}{2}\log(1-\zeta_N^k) \, ,
\ee
while the first term gives
\begin{align}
    \frac{1}{2\pi \ri}\int_{-\infty}^\infty \frac{\log(1-\re^{-tx})}{1-\zeta_N^{N-k}\re^{-t}} dt &= -\log\frac{(\zeta_N^{k}; \, \re^{2\pi \ri /x})_\infty}{(\re^{-2\pi \ri (N-k)x/N}; \, \re^{-2\pi \ri x})_\infty} \, , \label{eq: sumpi-proof1-p2a}
\end{align}
as before. 
Thus, substituting Eqs.~\eqref{eq: sumpi-proof1-p1} and~\eqref{eq: sumpi-proof1-p2a}, after changing back $x$ to $-1/y$, into the formula for the Borel--Laplace sum in Eq.~\eqref{eq: sumpi-proof1}, we find that 
\be
s_\pi(\psi_k)(y)= -\frac{\mathrm{Li}_2(\zeta_N^k)}{2\pi \ri y}+\frac{1}{2}\log(1-\zeta_N^k) -\log\frac{(\zeta_N^k; \, \re^{-2\pi \ri y})_\infty}{(\re^{2\pi \ri (N-k)/(Ny)}; \, \re^{2\pi \ri/y})_\infty} \, . \label{eq: sumpi-proof1-p3a} 
\ee
Finally, putting together Eqs.~\eqref{eq:f_kN},~\eqref{eq: expansion-fkN}, and~\eqref{eq: sumpi-proof1-p3a} yields
\be \label{eq: sumpi-proof2}
\begin{aligned}
    s_\pi(\tilde{f}_{k,N})(y)&=\log(1-\zeta_N^k)-\log\frac{(\zeta_N^k; \, \re^{-2\pi \ri y})_\infty}{(\re^{2\pi \ri (N-k)/(Ny)}; \, \re^{2\pi \ri/y})_\infty} \\
    &=f_{k,N}(y)-g_{k,N} \big(-\tfrac{1}{Ny}\big) \, ,
\end{aligned}
\ee
where we have applied the identity
\be \label{eq: qdilog-rel}
(x; \, q^{-1})_\infty = (xq; \, q)_\infty^{-1} \, .
\ee
and used that
\be
\log(\zeta_N^k \, \re^{2\pi \ri y}; \, \re^{2\pi \ri y})_\infty = \log(\zeta_N^k; \, \re^{2\pi \ri y})_\infty - \log(1-\zeta_N^k) \, .
\ee
\end{proof}

