    \subsection*{Step 6: The general case}
        The general case of Theorem \ref{thm chi2 torsion} can be deduced from the smooth case using the same \textit{dévissage} methods used in \cite{DiegoLuco2024KKp-adicFunction}; namely the following \textit{dévissage} principle can be applied in our context, see \cite[Proposition 3.15]{DiegoLuco2024KKp-adicFunction}
        \begin{prop}
        Let $F$ be a field and $r$ a positive integer. Let $(\mathrm{P})$ be a property of $F$-varieties. Suppose that for every proper $F$-variety we are given an integer $m_X$. Assume that 
        \begin{enumerate}
            \item For every morphism of proper $F$-varieties $Y\to X$, the integer $m_X$ divides $m_Y$,
            \item for every proper $F$-variety satisfying $(\mathrm{P})$, the integer $m_X$ divides $\chi_F(X,\mathcal{O}_X)^r$,
            \item for every proper integral $F$-scheme $X$ there exists a proper $F$-scheme $Y$ satisfying $(\mathrm{P})$ and an $F$-morphism $Y \to X$ with generic fibre $Y_{\eta}$ such that $m_X$ and $\chi_{F(X)}(Y_{\eta},\mathcal{O}_{Y_{\eta}})^r$ are coprime.
        \end{enumerate}
        Then for every proper $F$-variety $X$ and coherent sheaf $E$ on $X$, the integer $m_X$ divides $\chi_K(X,E)^r$. 
        \end{prop}
        \noindent This proposition is a refinement of \cite[Proposition 2.1]{Wittenberg2015KKQp}.
    \subsection*{The \texorpdfstring{$C_{d+1}^{d+1}$}{Kato Kuzumaki} property}
    As an application of Theorem \ref{thm chi2 torsion} we get the following result.
    \begin{thm}\label{thm Cd1d1}
        Let $k$ be a $d$-local $k$ field such that $k_1$ is a $p$-adic field. Then the field $K= k(x)$ has the $C_{d+1}^{d+1}$ property.
    \end{thm}
    \begin{proof}
        Let $L$ be a finite field extension of $K$ and $Z$ a hypersurface of $\mathbf{P}^n_{L}$ of degree $m$ such that $m^{d+1} \leq n$. Note that $L$ is the function field of a smooth projective geometrically integral curve $C$ over a $d$-local field $l$. Since $L^{pnr} = l^{pnr}L$ satisfies the $C_{d+1}$ property, we know that there exists a finite purely unramified extension $l'/l$ such that $Z(l') \neq \emptyset$. Set $L' := l' K$. Now we can apply Theorem \ref{thm chi2 torsion} to $Z$ and deduce that 
        \[ \mathrm{K}_{d+1}(L)  \big/  \left\langle \mathrm{N}_{d+1}(L'/L) , \mathrm{N}_{d+1}(Z/K) \right\rangle = \mathrm{K}_{d+1}(L)  \big/   \mathrm{N}_{d+1}(Z/K) \]
        is $\chi(Z, \mathcal{O}_Z)^2$-torsion. But since $m\leq n$ we can apply \cite[Theorem III 5.1]{Hartshorne1983AlgebraicGeometry} and the exact sequence
        \[0 \to \mathcal{O}_{\mathbf{P}^n_K}(-d) \to \mathcal{O}_{\mathbf{P}^n_K} \to \iota_* \mathcal{O}_Z \to 0\]
        where $\iota: Z \to \mathbf{P}^n_K$ stands for the closed immersion, to deduce that $\chi_K(Z,\mathcal{O}_Z) = 1$.
    \end{proof} 
\section{About the \texorpdfstring{$C_{j+1}^{d+1}$}{Kato Kuzumaki} property}
The setting is the same as the previous section: $k$ is a $d$-local field such that $k^{(d-1)}$ is a $p$-adic field and $K$ is the function field of a smooth projective geometrically integral curve $C$ defined over $k$. In this section we generalise the methods from \cite[Section 4]{DiegoLuco2024KKp-adicFunction} to get results in the direction of the $C_{j+1}^{d+1}$ property for some $j$ smaller than $d$. \par 
For the rest of this section, fix an integer $j \in \{1 ,\cdots , d \}$. Let $l/k$ be a finite extension totally $j$-ramified of prime degree $\ell$. We define $\mathcal{E}^0_{l/k}$ as the set of finite $j$-ramified subextensions of $l^{pnr}/k$. Set
\[ \mathcal{E}_{l/k} := \{ K'/K \, | \, K' = k'K \text{ with } k' \in \mathcal{E}_{l/k} \}.\]
In the rest of the section we use extensively the following observation: for every pair of extensions $k'$ and $k''$ in $\mathcal{E}^0_{l/k}$ such that $k' \subseteq k''$ the extension $k'' / k'$ is purely unramified.
\begin{thm}\label{thm Elk generated Ktheory}
    Assume that $i_{\leq j}(C) = 1$. Let $\ell$ be a prime number and $l/k$ a totally $j$-ramified extension of degree $\ell$. Then we have 
    \[ \mathrm{K}_{d+1}(K) = \left\langle \mathrm{N}_{d+1}(K'/K) \, | \, K' \in \mathcal{E}_{l/k} \right\rangle.\]
\end{thm}
\subsection*{Step 1: Solving the problem locally}
The following proposition is valid for any $d$-local field regardless the level where the characteristic gets mixed.
\begin{prop}\label{prop generators Ktheory dlocal}
    Let $t_1,\cdots, t_d$ be a system of parameters of $k$ and $n \in \mathbf{N}$. Then $\mathrm{K}_n(k)$ is generated by symbols of the form $\{t_1, \cdots t_m, \lambda_{m+1}, \cdots, \lambda_{d}\}$ where $m \in \{1,\cdots, m\}$, and for every $j \in \{m+1, \cdots, d\}$ the element $\lambda_j$ is in $\mathcal{O}_k^{\times}$.
\end{prop}
\begin{proof}
    This is a direct computation given the fact that $\mathcal{O}_k^{\times}$ together with $t_1, \cdots ,t_n$ generates $k^{\times}$.
\end{proof}

\begin{lemma}\label{lemma not totally j}
    Let $\ell$ be a prime number and $l/k$ a finite Galois totally $j$-ramified extension of degree $\ell$. Let $m/k$ be a finite purely ramified and $j$-ramified extension such that $ml/m$ is purely unramified. Then there exists $k' \in \mathcal{E}_{l/k}^0$ contained in $m$.
\end{lemma}
\begin{proof}
    If $ml/m$ is trivial, $l$ is contained in $m$ and there is nothing to prove. Then we may and do assume that $ml/m$ has degree $\ell$. Let $k_{\ell}$ be the purely unramified extension of $k$ of degree $\ell$ and set $l_{\ell} := lk_{\ell} $. The extension $l_{\ell}/k$ is Galois with Galois group $(\mathbf{Z}/\ell )^2$. Note that $ml$ contains $l_{\ell}$ because $ml/m$ is purely unramified of degree $\ell$.  Note that we have the following inequalities
    \[[m:k] [l_{\ell}:k] = \ell^2 [m:k] \gneq \ell [m:k] = [ml:k] = [ml_{\ell}:k].\]
    Denote by $k'$ the intersection $m \cap l_{\ell}$. The previous inequality imply that $[k:k] \gneq 1$ and as a subextension of $l_{\ell}$ its degree can only be $\ell$ or $\ell^2$, but it cannot be $\ell^2$ because that would imply $l_{\ell} \subseteq m$. Since $m/k$ is purely ramified and $j$-ramified, we conclude that $k' \in \mathcal{E}_{l/k}^0$.
\end{proof}
\begin{prop}\label{prop Elk generates locally}
    Let $\ell$ be a prime number and $l/k$ be a finite extension of degree $\ell$ totally $j$-ramified for $j \in \{1, \cdots, d\}$. Then for every $v \in C^{(1)}$ we have 
    \begin{equation}\label{eq generation K locally}
        \mathrm{K}_{d+1}(K_v) =\left\langle \mathrm{N}_{d+1} (K' \otimes_K K_v /K_v) \; |\; K' \in \mathcal{E}_{l/k} \right\rangle.
    \end{equation}
\end{prop}
\begin{proof}
    Thanks to Proposition \ref{prop generate residue implies generate} we only need to prove that $\mathrm{K}_{d}(k(v))$ is generated by the norms coming from $k' \otimes_k k(v)$ with $k' \in \mathcal{E}^0_{l/k}$. We prove this statement by induction on $d$. The case $d=1$ is treated in \cite[Proposition 4.4]{DiegoLuco2024KKp-adicFunction}.  \par
    Let us consider the case $j \neq d$. Then by the induction hypothesis, we see that 
    \[\mathrm{K}_{d-1}(k(v)^{(1)}) = \left\langle \mathrm{N}_{d-1} (m \otimes_{k^{(1)}} k(v)^{(1)} /k(v)^{(1)}) \; |\; m \in \mathcal{E}_{l^{(1)}/k^{(1)}}^0 \right\rangle. \]
    We conclude this case by applying Proposition \ref{prop generate residue implies generate} and noting that an extension $m/k_{d-1}$ is in $\mathcal{E}^0_{l^{(1)}/k^{(1)}}$ if and only if there exists an extension $k' \in \mathcal{E}^0_{l/k}$ whose first residual extension $k'^{(1)}/k^{(1)}$ is equal to $m$. \par
    Assume that $j=d$. We distinguish four cases 
    \begin{enumerate}
        \item $l$ is contained in $k(v)$,
        \item $lk(v)/k(v)$ is purely unramified of degree $\ell$,
        \item $lk(v)/k(v)$ is totally $i$-ramified of degree $\ell$ for $i\in \{1 , \cdots, d-1 \}$, or
        \item $lk(v)/k(v)$ is totally $d$-ramified of degree $\ell$.
    \end{enumerate}
    Case 1 is direct because $l \otimes k(v) \simeq k(v) \times \cdots \times k(v)$. Let us consider case 2. Note that $k(v)/k$ is $d$-ramified because otherwise $lk(v)/k(v)$ would necessarily be $d$-ramified. Let $k(v)_{pnr}/k$ be the maximal purely unramified subextension of $k(v)$. We can apply Lemma \ref{lemma not totally j} because the extension $k(v)/k(v)_{pnr}$ is a purely ramified $d$-ramified extension such that $lk(v)/k(v)_{pnr}$ is purely unramified. Then there exists a finite extension $k' \in \mathcal{E}^0_{lk(v)_{pnr}/k(v)_{pnr}} \subseteq \mathcal{E}^0_{l/k}$ contained in $k(v)$.\par 
    Let us consider case 3. As in case 2, the extension $k(v)/k$ must be $d$-ramified. Since the statement was already proved for $j\neq d$ we know that 
    \begin{equation} \label{eq Elk generates locally case 2}
        \mathrm{K}_d(k(v)) =\left\langle \mathrm{N}_{d} (k' /k(v)) \; |\; k' \in \mathcal{E}_{lk(v)/k(v)}^0 \right\rangle.
    \end{equation}
    Let $k'$ be an extension in $\mathcal{E}^0_{l k(v)/k(v)}$. Denote by $k'_{pnr}/k$ the maximal purely unramified subextension of $k'/k$. We can apply Lemma \ref{lemma not totally j} because $k'/k'_{pnr}$ is a purely ramified $d$-ramified extension such that $k'l/k'$ is purely unramified. Then we can find an extension $k'' \in \mathcal{E}^0_{lk'_{pnr}/k_{pnr}'} \subseteq \mathcal{E}_{l/k}$ contained in $k'$. Since $k''$ is contained in $k'$ we have $\mathrm{N}_d(k'/k(v)) \subseteq \mathrm{N}_d(k''k(v)/k(v))$ where $k''k(v)$ is the composite of $k''$ and $k(v)$ inside $k'$. In particular, $\mathrm{N}_d(k'/k(v)) \subseteq \mathrm{N}_d(k'' \otimes_{k(v)} k(v) /k(v))$. We conclude this case using \eqref{eq Elk generates locally case 2}. \par 
    Finally, let us consider case 4. Since $d\geq 2$ we can find a system of parameters $t_1, \cdots, t_d$ for $k(v)$ such that $t_d$ belongs to $k$ and $l = k(\sqrt[\ell]{t_d})$, see \cite[Proposition II 5.12]{Lang1994AlgebraicNumberTheory}. In particular, we have $lk(v) = k(v)(\sqrt[\ell]{t_d})$. Clearly $t_d$ belongs to $\mathrm{N}_{1}(lk(v)/ k(v))$. Note that for every $u \in \mathcal{O}^{\times}_{k(v)}$ the extension $k(\sqrt[\ell]{ut_d})/k$ belongs to $\mathcal{E}^0_{l/k}$. Then any symbol $\alpha$ in $\mathrm{K}_d(k(v))$ that has either $t_d$ or an element of $\mathcal{O}_{k(v)}^{\times}$ as an entry in 
    \[\left\langle \mathrm{N}_{d} (k' \otimes_k k(v) /k(v)) \; |\; k' \in \mathcal{E}_{l/k}^0 \right\rangle.\]
    We conclude case 4 applying Proposition \ref{prop generators Ktheory dlocal}.
\end{proof}
\subsection*{Step 2: Computation of a Tate-Shafarevich group}
In this step we compute a Tate-Shafarevich group that controls the defect of the \textit{multi-normic} principle for extensions in $\mathcal{E}_{l/k}$.
\begin{prop}
    Assume that $i_{\leq j}(C) = 1$. Let $l/k$ be a finite Galois extension totally $j$-ramified of prime degree $\ell$. Given $K_1, \cdots, K_r \in \mathcal{E}_{l/k}$ such that $K_1$ and $K_2$ are linearly disjoint over $K$, consider the Galois module $\hat{T}$ defined by the following exact sequence  
    \begin{equation}
        0 \to \mathbf{Z} \to \mathbf{Z}[E/K] \to \hat{T} \to 0,
    \end{equation}
    where $E := K_1 \times \cdots \times K_r$. Then $\Sha^2(K,\hat{T})$ is divisible. 
\end{prop}
\begin{proof}
    We have a complex 
    \[ \Sha^2(K,\hat{T}) \xrightarrow{f_0} \Sha^2(K_1,\hat{T}) \oplus \Sha^2(K_2,\hat{T}) \xrightarrow{g_0} \Sha^2(K_1K_2,\hat{T})\]
    where $f_0$ and $g_0$ are defined as follows
    \begin{align*}
        f_0(\alpha) &= (\mathrm{res}_{K_1/K}(\alpha),\mathrm{res}_{K_2/K}(\alpha)) \\
        g_0(\alpha,\beta) &= \mathrm{res}_{K_1K_2/K_1}(\alpha)-\mathrm{res}_{K_1K_2/K_2}(\beta).
    \end{align*}
    \begin{lemma}
        $f_0$ is injective.
    \end{lemma}
    \begin{proof}
        We fix an algebraic closure $\overline{K}$ of $K$ and all fields are considered inside $\overline{K}$. Let $K_I$ be the Galois closure of the composite $K_1 \cdots K_r$ and $k_I/k$ the corresponding extension. Let $S \subseteq C^{(1)}$ be a finite family of points such that 
        \[ \mathrm{gcd} \left([k(v):k]_j \, | \, v \in S \right) =1. \] 
        For every $v \in S$ denote by $G_v \leq \mathrm{Gal}(K_I/K) = \mathrm{Gal}(k_I/k)$ the decomposition group of $v$ in $K_I/K$. We have the following identification of subgroups of $\mathrm{Gal}(k_I/ k)$
        \[G_v = \mathrm{Gal}(k_I/ k_I \cap k(v))\]
        Noting that for every $i \in \{j+1, \cdots, d\}$ the extension $k_I/k$ is not $i$-ramified, we deduce that the index of $G_v$ in $\mathrm{Gal}(k_I/k)$ divides $[k(v):k]_j$. A small exercise in group theory shows that a family of subgroups with coprime index must generate the group. For each $v \in S$ we choose a place $w$ of $K_I$ above $v$ and denote by $K_{I,v}$ the completion $K_{I,w}$. Thus, the restriction map 
        \[\mathrm{H}^2(K_I/K, \hat{T}) \to \prod_{v \in S} \mathrm{H}^2(K_{I,v}/K_v, \hat{T})\]
        is injective. By inflation-restriction we have the following commutative diagram with exact row
        \begin{equation*}
        \begin{tikzcd}
            0 \ar[r] & \mathrm{H}^2(K_I/K, \hat{T}) \ar[r] \ar[d] & \mathrm{H}^2(K, \hat{T}) \ar[r] \ar[d] & \mathrm{H}^2(K_I, \hat{T}) \ar[d] \\
            0 \ar[r] & \prod_{v \in S} \mathrm{H}^2(K_{I,v}/K_v, \hat{T}) \ar[r] & \prod_{v \in S} \mathrm{H}^2(K_v, \hat{T}) \ar[r]& \prod_{v \in S} \mathrm{H}^2(K_{I,v}, \hat{T}).
        \end{tikzcd}
    \end{equation*}
    We deduce that the morphism 
    \[ \ker \left(\mathrm{H}^2(K, \hat{T}) \to  \prod_{v \in S} \mathrm{H}^2(K_v, \hat{T})\right) \to \ker \left(\mathrm{H}^2(K_I, \hat{T}) \to  \prod_{v \in S} \mathrm{H}^2(K_{I,v}, \hat{T})\right) \]
    is injective. In particular, the restriction $\Sha^2(K,\hat{T}) \to \Sha^2(K_I,\hat{T})$ is also injective. We conclude because $\Sha^2(K,\hat{T}) \to \Sha^2(K_I,\hat{T})$ factors through $\Sha^2(K,\hat{T}) \to \Sha^2(K_1,\hat{T})$ and $\Sha^2(K,\hat{T}) \to \Sha^2(K_2,\hat{T})$. 
    \end{proof}
    Now we can follow the proof of \cite[Proposition 4.5]{DiegoLuco2024KKp-adicFunction} replacing every instance of \cite[Lemma 3.12]{DiegoLuco2024KKp-adicFunction} by Lemma \ref{lemma torsion of kernel and surj shas} and noting that $i_0(C) = 1$ since $i_0(C)$ divides $i_{\leq j}(C)$.
    \end{proof}
    \subsection*{Step 3: Conclusion of the argument}
    \begin{proof}[Proof of Theorem \ref{thm Elk generated Ktheory}]
        Consider $x \in \mathrm{K}_{d+1}(K)$. For every $v \in C^{(1)}$ we have 
    \[\mathrm{K}_{d+1}(K_v) =\left\langle \mathrm{N}_{d+1} (K' \otimes_K K_v /K_v) \; |\; K' \in \mathcal{E}_{l/k} \right\rangle.\]
    Hence, we can find $K_1, \cdots, K_r \in \mathcal{E}_{l/k}$ such that the class of $x$ in 
    \[\mathrm{K}_{d+1}(K) \, \big / \, \left\langle  \mathrm{N}_{d+1} (K_i /K) \, |  \, i \in \{1, \cdots, r \} \right\rangle\]
     belongs to the kernel of the restriction map towards 
    \[ \prod_{v \in C^{(1)}} \mathrm{K}_{d+1}(K_v) \, \big / \, \left\langle  \mathrm{N}_{d+1} (K_i \otimes_K K_v /K_v) \, | \, i \in \{1, \cdots, r \} \right\rangle.\]
    Moreover, up to enlarging the family $K_i$, we may assume that $K_1$ and $K_2$ are linearly disjoint. Consider the étale algebra $E:= K_1 \times \cdots \times K_r$ and the Galois module $\hat{T}$ defined by the following exact sequence
    \[0 \to \mathbf{Z} \to \mathbf{Z}[E/K] \to \hat{T} \to 0. \]
    Set $\check{T} := \mathrm{Hom}_K \;(\hat{T}, \mathbf{Z})$ and $T:= \check{T} \otimes \mathbf{Z}(d+1)$. Then under the identifications in Lemma \ref{lemma norms Ktheory and motivic} the class of $x$ belongs to $\Sha^{d+2}(K,T)$. On the other hand, the group $\Sha^2(K,\hat{T})$ is divisible and Poitou-Tate duality \cite[Theorem 0.1]{Diego2015LGPrincipleHigherLocal} implies that $\Sha^{d+2}(K,T)$ is trivial. Then $x$ belongs to $\left\langle  \mathrm{N}_{d+1} (K_i /K) \, |  \, i \in \{1, \cdots, r \} \right\rangle$, concluding the proof of Theorem \ref{thm Elk generated Ktheory}.
    \end{proof}

    \subsection*{Application to the \texorpdfstring{$C_{j+1}^{d+1}$}{Kato Kuzumaki} property}
    Theorem \ref{thm Elk generated Ktheory} allows us to prove the following result.
    \begin{thm}\label{thm iramchi torsion}
        Let $K$ be the function field of a smooth projective curve $C$ defined over a $d$-local field $k$ such that the $1$-local residue field of $k$ is $p$-adic. Let $l/k$ be a finite Galois extension, a number $j \in \{1,\cdots , d\}$ and set $L:=lK$. Assume that $l/k$ is not $i$-ramified for every $i\in \{j+1, \cdots , d\}$. Let $Z$ be a proper $K$-variety. Set $s_{l/k}$ to be the number of (not necessarily distinct) prime factors of the total ramification index of $l/k$. Then the quotient
        \[ \mathrm{K}_{d+1}(K) \, \big/ \, \left\langle \mathrm{N}_{d+1}(L/K) , \mathrm{N}_{d+1}(Z/K)\right\rangle\]
        is $i_{\leq j}^{ram}(C) \cdot \chi_K(Z,E)^{2 s_{l/k} +4}$-torsion for every coherent sheaf $E$ over $Z$.
    \end{thm}
    \begin{proof}
        We first assume that $i_{\leq j}(C) = 1$, and prove that the quotient in the statement is $\chi_K(Z,E)^{2s_{l/k} +2 }$-torsion for every coherent sheaf $E$ over $Z$. We proceed by induction on $s_{l/k}$. The case $s_{l/k} = 0$ is the content of Theorem \ref{thm chi2 torsion}. Assume that $s_{l/k}$ is greater than zero. Denote by $l_{pnr}$ the maximal subextension of $l/k$ such that $l_{pnr}/k$ is purely unramified, and set $L_{pnr} = l_{pnr}K$. By Theorem \ref{thm chi2 torsion} the quotient
        \[ \mathrm{K}_{d+1}(K) \, \big/ \, \left\langle \mathrm{N}_{d+1}(L_{pnr}/K) , \mathrm{N}_{d+1}(Z/K)\right\rangle\] 
        is $\chi_K(E,Z)^2$-torsion. Let $j' \in\{1, \cdots, j \}$ be the smallest index such that $l/l_{pnr}$ is $j'$-ramified. Denote by $l_{\leq j'}/l_{pnr}$ the maximal subextension of $l/l_{pnr}$ that not $i$-ramified for every $i \in \{j'+1,\cdots, d\}$. Since $l_{\leq j'}/l_{pnr}$ is a solvable extension, we can extract a subextension $m/l_{pnr}$ totally $j'$-ramified of prime degree $\ell$. Set $M = mK$. In one hand Theorem \ref{thm Elk generated Ktheory} tells us that
        \[\mathrm{K}_{d+1}(L_{pnr}) = \left\langle \mathrm{N}_{d+1}(K'/K) \, | \, K' \in \mathcal{E}_{m/l_{pnr}} \right\rangle.\]
        On the other hand, for each $k' \in \mathcal{E}^0_{m/l_{pnr}}$ the total ramification degree of $lk'/k'$ strictly divides that of $l/k$. Indeed, we can see that $[mk':k'] \cdot e_{tot}(lk'/k')$ divides $e_{tot}(l/k)$. Then $e_{tot}(l/k) =e_{tot}(lk'/k')$ would imply $m=k'$ which gives a contradiction because $e_{tot}(l/k) = \ell \cdot e_{tot}(l/m)$. So we can apply our induction hypothesis to deduce that for every $K' \in \mathcal{E}_{m/l_{pnr}}$ the quotient
        \[ \mathrm{K}_{d+1}(K') \, \big/ \, \left\langle \mathrm{N}_{d+1}(K'L/K') , \mathrm{N}_{d+1}(Z \otimes_K K'/K')\right\rangle\]
        is $\chi_{K}(Z,E)^{2 s_{l/k}}$-torsion. Putting these facts together we deduce that 
        \[\mathrm{K}_{d+1}(K) \, \big/ \, \left\langle \mathrm{N}_{d+1}(L/K) , \mathrm{N}_{d+1}(Z/K) \right\rangle\]
        is $\chi_K(Z,E)^{2s_{l/k} +2 }$-torsion. \par 
        We no longer assume $i_{\leq j}(C) =1$. Let $k_1, \cdots ,k_n$ be finite extensions of $k$ such that for every $ r \in \{1, \cdots , n \}$ the curve $C$ has a $k_r$-point, and
        \[ i_{\leq j}^{ram}(C) = \mathrm{gcd}\left( e_{\leq j}(k_r/k) \, | \, r \in \{1, \cdots , n\} \right).\]
        For each index $r$, denote by $k_{r,pnr}$ the maximal subextension of $k_r/k$ such that $k_{r,pnr}/k$ is purely unramified, and set $K_{r,pnr} := k_{r,pnr} K$. Thanks to Theorem \ref{thm chi2 torsion} we know that the quotient
        \[ \mathrm{K}_{d+1}(K) \, \big/ \, \left\langle \mathrm{N}_{d+1}(K_{r,pnr}/K) , \mathrm{N}_{d+1}(Z/K)\right\rangle\]
        is $\chi_K(Z,E)^2$-torsion for every $r$. For each $r$ let $m_r/k$ be the maximal subextension of $k_r/k$ such that $m_r/k$ is $i$-unramified for every $i \in \{j+1, \cdots ,d \}$, and set $M_r := m_rK$. Note that $k_{r,pnr}$ is contained in $m_r$ and  $[m_r:k] = [k_r:k]_j$. A restriction-corestriction argument shows that 
        \[ \mathrm{K}_{d+1}(K_{r,pnr}) / \mathrm{N}_{d+1}(M_{r}/K_{r,pnr})\]
        is $[m_r :k_{r,pnr}]$-torsion. Note that $[m_r: k_{r,pnr}] = e_{\leq j}(k_r/k)$. We deduce that the quotient
        \[\mathrm{K}_{d+1}(K) \, \big/ \, \left\langle \mathrm{N}_{d+1}(M_1/K), \cdots , \mathrm{N}_{d+1}(M_n/K) , \mathrm{N}_{d+1}(Z/K)\right\rangle\]
        is $i_{\leq j}^{ram}(C) \cdot \chi_K(Z,E)^2$-torsion. Since over $m_r$ we have $i_{\leq j}(C \otimes_k m_r) =1$ we can apply the first case to see that 
        \[\mathrm{K}_{d+1}(M_r) \, \big/ \, \left\langle \mathrm{N}_{d+1}(M_r L/M_r) , \mathrm{N}_{d+1}(Z \otimes_K M_i/M_i)\right\rangle\]
        is $\chi_K(Z,E)^{2 s_{l/k} +2}$-torsion. Then 
        \[\mathrm{K}_{d+1}(K) \, \big/ \, \left\langle \mathrm{N}_{d+1}(L/K) , \mathrm{N}_{d+1}(Z/K)\right\rangle\]
        is $i_{\leq j}^{ram}(C) \cdot \chi_K(Z,E)^{2 s_{l/k} +4}$-torsion.
    \end{proof}
    \noindent As corollaries, we get the following results about the $C_{j+1}^{d+1}$ property.
    \begin{cor}
        Let $K$ be the funciton field of a smooth projective curve $C$ defined over a $d$-local field $k$ such that the $1$-local residue field of $k$ is $p$-adic and $j \in \{0, \cdots , d \}$. Then, for every $m,n \geq 1$ and hypersurface $Z$ in $\mathbf{P}^{n}_K$ of degree $m$ such that $m^{j+1} \leq n$, the quotient $\mathrm{K}_{d+1}(K) / \mathrm{N}_{d+1}(Z/K)$ is $i_{\leq d-j}^{ram}(C)$-torsion
    \end{cor}
    \begin{proof}
        Let $Z$ be a hypersurface of $\mathbf{P}^n_k$ of degree $m$ with $m^{j+1} \leq n$. Let $k^{\leq d -j}/k$ be the maximal extension of $k$ that is not $i$-ramified for any $i \in \{d-j+1, \cdots,d\}$. We can combine Tsen's Theorem \cite[Theorem 2a]{Nagata1957NotesLang} and Lang's Theorem \cite[Theorem 12]{Lan1952QAlgClosure} to deduce that the field $k^{\leq d-j}(C)$ satisfies $C_{j+1}$. Then there exists a finite Galois extension $l/k$ such that $Z(lK)\neq \emptyset$ and $l/k$ is not $i$-ramified for every $i \in \{d-j+1,\cdots, d\}$. Theorem \ref{thm iramchi torsion} ensures that the quotient
        \[\mathrm{K}_{d+1}(K) \big/ \left\langle \mathrm{N}_{d+1}(lK) , \mathrm{N}_{d+1}(Z/K) \right\rangle = \mathrm{K}_{d+1}(K) \big/ \left\langle\mathrm{N}_{d+1}(Z/K) \right\rangle\]
        is $i_{\leq d-j}^{ram}(C) \cdot \chi_K(Z,E)^{2s_{l/k}+4}$-torsion for any coherent sheaf $E$. But since $m\leq n$ we can deduce from \cite[Theorem III 5.1]{Hartshorne1983AlgebraicGeometry} and the exact sequence
        \[0 \to \mathcal{O}_{\mathbf{P}^n_K}(-d) \to \mathcal{O}_{\mathbf{P}^n_K} \to \iota_* \mathcal{O}_Z \to 0\]
        where $\iota: Z \to \mathbf{P}^n_K$ stands for the closed immersion, that $\chi_K(Z,\mathcal{O}_Z) = 1$. Thus, $\mathrm{K}_{d+1}(K) \big/ \left\langle\mathrm{N}_{d+1}(Z/K) \right\rangle$ is $i^{ram}_{\leq d-j}(C)$-torsion.
    \end{proof}
    \begin{cor}
        Let $K$ be the funciton field of a smooth projective curve $C$ defined over a $d$-local field $k$ such that the $1$-local residue field of $k$ is $p$-adic and $j \in \{0,\cdots, d\}$. Assume that $i_{\leq d-j}^{ram} (C) = 1$ Then, for every $m,n \geq 1$ and hypersurface $Z$ in $\mathbf{P}^{n}_K$ of degree $m$ such that $m^{j+1} \leq n$, we have $\mathrm{K}_{d+1}(K)  =  \mathrm{N}_{d+1}(Z/K)$.
    \end{cor}
